{
  "name": "LocateIt - Custom Map Quiz",
  "description": "A GeoGuessr-style game where you create your own quizzes by taking photos at real-world locations and challenge friends to guess them on a map.",
  "requestFramePermissions": [
    "camera",
    "geolocation"
  ]
}

export interface Location {
  lat: number;
  lng: number;
}

export interface Question {
  id: string;
  imageUrl: string;
  location: Location;
}

export interface Player {
  id: string;
  name: string;
  score: number;
  lastGuess?: Location;
  lastDistance?: number;
  hasGuessed: boolean;
}

export interface GameState {
  id: string;
  status: 'LOBBY' | 'PLAYING' | 'RESULTS' | 'FINISHED';
  questions: Question[];
  currentQuestionIndex: number;
  players: Player[];
  hostId: string;
}

export type GameAction =
  | { type: 'JOIN_LOBBY'; player: Player }
  | { type: 'START_GAME' }
  | { type: 'SUBMIT_GUESS'; playerId: string; guess: Location; distance: number }
  | { type: 'NEXT_QUESTION' }
  | { type: 'SHOW_RESULTS' }
  | { type: 'END_GAME' };

import { Location } from './types';

/**
 * Calculates distance between two coordinates in kilometers using Haversine formula.
 */
export const calculateDistance = (loc1: Location, loc2: Location): number => {
  const R = 6371; // Earth radius in km
  const dLat = (loc2.lat - loc1.lat) * Math.PI / 180;
  const dLng = (loc2.lng - loc1.lng) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(loc1.lat * Math.PI / 180) * Math.cos(loc2.lat * Math.PI / 180) * 
    Math.sin(dLng/2) * Math.sin(dLng/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
};

export const formatDistance = (km: number): string => {
  if (km < 1) return `${(km * 1000).toFixed(0)}m`;
  return `${km.toFixed(2)}km`;
};

export const generateId = () => Math.random().toString(36).substr(2, 6).toUpperCase();

import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import { Location } from '../types';

interface MapProps {
  onLocationSelect?: (loc: Location) => void;
  markers?: { position: Location; label?: string; icon?: 'default' | 'target' | 'user' }[];
  center?: Location;
  zoom?: number;
  lines?: { from: Location; to: Location }[];
}

const Map: React.FC<MapProps> = ({ onLocationSelect, markers = [], center, zoom = 13, lines = [] }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<L.Map | null>(null);
  const markersLayer = useRef<L.LayerGroup | null>(null);

  useEffect(() => {
    if (!mapRef.current || leafletMap.current) return;

    leafletMap.current = L.map(mapRef.current).setView(
      center ? [center.lat, center.lng] : [51.505, -0.09],
      zoom
    );

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap contributors'
    }).addTo(leafletMap.current);

    markersLayer.current = L.layerGroup().addTo(leafletMap.current);

    leafletMap.current.on('click', (e) => {
      if (onLocationSelect) {
        onLocationSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
      }
    });

    return () => {
      leafletMap.current?.remove();
      leafletMap.current = null;
    };
  }, []);

  useEffect(() => {
    if (!leafletMap.current || !markersLayer.current) return;

    markersLayer.current.clearLayers();

    const bounds = L.latLngBounds([]);

    markers.forEach((m) => {
      const icon = L.divIcon({
        className: 'custom-div-icon',
        html: `<div class="w-8 h-8 rounded-full border-2 border-white shadow-lg flex items-center justify-center ${
          m.icon === 'target' ? 'bg-red-500' : m.icon === 'user' ? 'bg-blue-500' : 'bg-indigo-500'
        }">
          <div class="w-2 h-2 rounded-full bg-white"></div>
        </div>`,
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      });

      const marker = L.marker([m.position.lat, m.position.lng], { icon }).addTo(markersLayer.current!);
      if (m.label) marker.bindPopup(m.label);
      bounds.extend([m.position.lat, m.position.lng]);
    });

    lines.forEach((line) => {
      L.polyline(
        [[line.from.lat, line.from.lng], [line.to.lat, line.to.lng]],
        { color: '#6366f1', weight: 3, dashArray: '5, 10' }
      ).addTo(markersLayer.current!);
      bounds.extend([line.from.lat, line.from.lng]);
      bounds.extend([line.to.lat, line.to.lng]);
    });

    if (markers.length > 1 && bounds.isValid()) {
      leafletMap.current.fitBounds(bounds, { padding: [50, 50] });
    } else if (center) {
      leafletMap.current.setView([center.lat, center.lng], zoom);
    }
  }, [markers, center, zoom, lines]);

  return <div ref={mapRef} className="w-full h-full min-h-[300px]" />;
};

export default Map;

import React, { useState, useEffect, useCallback } from 'react';
import { GameState, Player, Question, Location } from './types';
import { generateId, calculateDistance } from './utils';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';

// Communication hub for local multiplayer simulation across tabs
const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<'HOME' | 'CREATE' | 'LOBBY' | 'PLAYING'>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [isHost, setIsHost] = useState(false);

  // Sync state across tabs
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      const data = event.data;
      if (data.type === 'STATE_UPDATE') {
        setGameState(data.state);
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, []);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleCreateQuiz = (questions: Question[]) => {
    const hostId = generateId();
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions,
      currentQuestionIndex: 0,
      players: [],
      hostId,
    };
    setIsHost(true);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const newPlayer: Player = {
        id: generateId(),
        name,
        score: 0,
        hasGuessed: false
      };
      const newState = {
        ...gameState,
        players: [...gameState.players, newPlayer]
      };
      setCurrentPlayer(newPlayer);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game not found! (In this demo, the game must be created in a separate tab or shared session)");
    }
  };

  const startGame = () => {
    if (!gameState) return;
    updateGameState({ ...gameState, status: 'PLAYING' });
    setView('PLAYING');
  };

  const submitGuess = (guess: Location) => {
    if (!gameState || !currentPlayer) return;
    const currentQ = gameState.questions[gameState.currentQuestionIndex];
    const distance = calculateDistance(guess, currentQ.location);

    const updatedPlayers = gameState.players.map(p => 
      p.id === currentPlayer.id 
        ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } 
        : p
    );

    const newState = { ...gameState, players: updatedPlayers };

    // Check if everyone has guessed
    const allGuessed = updatedPlayers.every(p => p.hasGuessed);
    if (allGuessed) {
      newState.status = 'RESULTS';
    }

    updateGameState(newState);
  };

  const nextRound = () => {
    if (!gameState) return;

    // Calculate scores for the round
    // Sorting by distance ascending (closest first)
    const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));

    const updatedPlayers = gameState.players.map(p => {
      const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
      const points = Math.max(0, gameState.players.length - rank);
      return {
        ...p,
        score: p.score + points,
        hasGuessed: false,
        lastGuess: undefined,
        lastDistance: undefined
      };
    });

    const isLastQuestion = gameState.currentQuestionIndex === gameState.questions.length - 1;

    const newState: GameState = {
      ...gameState,
      players: updatedPlayers,
      currentQuestionIndex: isLastQuestion ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1,
      status: isLastQuestion ? 'FINISHED' : 'PLAYING'
    };

    updateGameState(newState);
  };

  if (view === 'CREATE') {
    return <QuizCreator onComplete={handleCreateQuiz} onCancel={() => setView('HOME')} />;
  }

  if (view === 'LOBBY' && gameState) {
    return <Lobby gameState={gameState} isHost={isHost} onStart={startGame} currentPlayer={currentPlayer} />;
  }

  if (view === 'PLAYING' && gameState) {
    return (
      <GameBoard 
        gameState={gameState} 
        isHost={isHost} 
        currentPlayer={currentPlayer} 
        onGuess={submitGuess}
        onNext={nextRound}
      />
    );
  }

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-gradient-to-br from-indigo-600 to-purple-700 text-white">
      <div className="max-w-md w-full text-center space-y-8">
        <div className="space-y-2">
          <div className="bg-white/20 w-20 h-20 rounded-3xl flex items-center justify-center mx-auto backdrop-blur-md shadow-xl border border-white/30">
            <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </div>
          <h1 className="text-5xl font-extrabold tracking-tight">LocateIt</h1>
          <p className="text-indigo-100 text-lg">Your neighborhood is the playground.</p>
        </div>

        <div className="bg-white rounded-3xl p-8 shadow-2xl text-slate-800 space-y-6">
          <button 
            onClick={() => setView('CREATE')}
            className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-2xl transition-all shadow-lg active:scale-95"
          >
            Create New Quiz
          </button>

          <div className="relative">
            <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div>
            <div className="relative flex justify-center text-sm"><span className="px-2 bg-white text-slate-400 font-medium">OR JOIN GAME</span></div>
          </div>

          <div className="space-y-3">
            <input 
              id="gameCode"
              placeholder="Game Code"
              className="w-full px-4 py-3 border-2 border-slate-100 rounded-xl focus:border-indigo-500 outline-none uppercase font-mono text-center tracking-widest text-lg"
              onChange={(e) => {
                const val = e.target.value.toUpperCase();
                // Check if this matches an existing state in local storage (mock backend)
                if (gameState?.id === val) {
                   // recognized
                }
              }}
            />
            <input 
              id="playerName"
              placeholder="Your Name"
              className="w-full px-4 py-3 border-2 border-slate-100 rounded-xl focus:border-indigo-500 outline-none"
            />
            <button 
              onClick={() => {
                const code = (document.getElementById('gameCode') as HTMLInputElement).value;
                const name = (document.getElementById('playerName') as HTMLInputElement).value;
                if (code && name) handleJoinGame(code, name);
              }}
              className="w-full border-2 border-indigo-600 text-indigo-600 hover:bg-indigo-50 font-bold py-3 rounded-xl transition-all"
            >
              Enter Lobby
            </button>
          </div>
        </div>

        <p className="text-indigo-200 text-sm">Tip: Open a second tab to join your own game!</p>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Question, Location } from '../types';
import { generateId } from '../utils';

interface QuizCreatorProps {
  onComplete: (questions: Question[]) => void;
  onCancel: () => void;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel }) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [isCapturing, setIsCapturing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    // Get geolocation immediately
    if (navigator.geolocation) {
      navigator.geolocation.watchPosition(
        (pos) => setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        (err) => setError("Location access denied. Please enable GPS."),
        { enableHighAccuracy: true }
      );
    }
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCapturing(true);
      }
    } catch (err) {
      setError("Camera access denied.");
    }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current && currentLocation) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);
        const imageUrl = canvasRef.current.toDataURL('image/jpeg');

        const newQuestion: Question = {
          id: generateId(),
          imageUrl,
          location: { ...currentLocation }
        };

        setQuestions([...questions, newQuestion]);
        setIsCapturing(false);

        // Stop camera stream
        const stream = videoRef.current.srcObject as MediaStream;
        stream?.getTracks().forEach(track => track.stop());
      }
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-white flex flex-col p-4">
      <header className="flex justify-between items-center mb-6">
        <div>
          <h2 className="text-2xl font-bold">Create Quiz</h2>
          <p className="text-slate-400">{questions.length} / 10 Locations Saved</p>
        </div>
        <button onClick={onCancel} className="text-slate-400 hover:text-white">Cancel</button>
      </header>

      {error && (
        <div className="bg-red-500/20 border border-red-500 text-red-200 p-3 rounded-lg mb-4">
          {error}
        </div>
      )}

      <div className="flex-1 overflow-y-auto space-y-4">
        {isCapturing ? (
          <div className="relative rounded-2xl overflow-hidden aspect-video bg-black shadow-2xl">
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            <div className="absolute bottom-6 inset-x-0 flex justify-center">
              <button 
                onClick={capturePhoto}
                className="w-16 h-16 rounded-full bg-white border-4 border-slate-300 shadow-xl active:scale-90 transition-transform"
              />
            </div>
            {!currentLocation && (
              <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                <p className="text-sm font-medium animate-pulse">Waiting for GPS lock...</p>
              </div>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-4">
            {questions.map((q, idx) => (
              <div key={q.id} className="relative aspect-square rounded-xl overflow-hidden group">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
                <div className="absolute top-2 left-2 bg-black/50 px-2 py-0.5 rounded text-xs">#{idx + 1}</div>
                <button 
                  onClick={() => setQuestions(questions.filter(item => item.id !== q.id))}
                  className="absolute top-2 right-2 bg-red-500 rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
            {questions.length < 10 && (
              <button 
                onClick={startCamera}
                className="aspect-square rounded-xl border-2 border-dashed border-slate-700 flex flex-col items-center justify-center space-y-2 hover:border-indigo-500 transition-colors"
              >
                <div className="w-12 h-12 rounded-full bg-slate-800 flex items-center justify-center">
                  <svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
                </div>
                <span className="text-sm text-slate-400 font-medium">Add Location</span>
              </button>
            )}
          </div>
        )}
      </div>

      <footer className="mt-6">
        <button 
          disabled={questions.length === 0}
          onClick={() => onComplete(questions)}
          className={`w-full py-4 rounded-2xl font-bold transition-all ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 shadow-lg' : 'bg-slate-800 text-slate-500'}`}
        >
          Finalize & Host Game
        </button>
        <p className="text-center text-xs text-slate-500 mt-4">Note: Questions are stored locally in this browser session.</p>
      </footer>

      <canvas ref={canvasRef} style={{ display: 'none' }} />
    </div>
  );
};

export default QuizCreator;

import React from 'react';
import { GameState, Player } from '../types';

interface LobbyProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onStart: () => void;
}

const Lobby: React.FC<LobbyProps> = ({ gameState, isHost, onStart, currentPlayer }) => {
  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <div className="bg-indigo-600 text-white p-8 pt-12 rounded-b-[3rem] shadow-xl">
        <div className="max-w-2xl mx-auto flex justify-between items-start">
          <div>
            <h1 className="text-3xl font-extrabold mb-2">Game Lobby</h1>
            <p className="text-indigo-100 opacity-80">Waiting for explorers to join...</p>
          </div>
          <div className="text-right">
            <span className="text-xs uppercase font-bold tracking-widest text-indigo-200">Room Code</span>
            <div className="text-4xl font-mono font-black tracking-tighter">{gameState.id}</div>
          </div>
        </div>
      </div>

      <main className="flex-1 max-w-2xl w-full mx-auto p-6 -mt-8">
        <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-100">
          <div className="p-6 border-b border-slate-50 flex justify-between items-center">
            <h3 className="font-bold text-slate-400 uppercase text-xs tracking-wider">Players Joined ({gameState.players.length})</h3>
            <div className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></div>
          </div>
          <div className="divide-y divide-slate-50 max-h-[50vh] overflow-y-auto">
            {gameState.players.length === 0 ? (
              <div className="p-12 text-center text-slate-400">
                <p>Share the code with your friends!</p>
              </div>
            ) : (
              gameState.players.map(p => (
                <div key={p.id} className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                  <div className="flex items-center space-x-3">
                    <div className="w-10 h-10 rounded-xl bg-indigo-100 text-indigo-600 flex items-center justify-center font-bold">
                      {p.name.charAt(0)}
                    </div>
                    <span className="font-semibold text-slate-700">{p.name} {p.id === currentPlayer?.id ? "(You)" : ""}</span>
                  </div>
                  {isHost && p.id === gameState.hostId && <span className="text-[10px] bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full font-bold">HOST</span>}
                </div>
              ))
            )}
          </div>
