import React, { useState, useEffect } from 'react';
import { GameState, Player, Question, Location, User, AppView } from './types';
import { generateId, calculateDistance } from './utils';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';

const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);

  useEffect(() => {
    // Check for existing session
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        setGameState(event.data.state);
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, []);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleCreateQuiz = (questions: Question[]) => {
    if (!user) return;
    const hostId = user.id;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions,
      currentQuestionIndex: 0,
      players: [],
      hostId,
    };
    setIsHost(true);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const newPlayer: Player = {
        id: generateId(),
        name,
        score: 0,
        hasGuessed: false
      };
      const newState = {
        ...gameState,
        players: [...gameState.players, newPlayer]
      };
      setCurrentPlayer(newPlayer);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. In this version, ensure the host has the game open in another tab!");
    }
  };

  const startGame = () => {
    if (!gameState) return;
    updateGameState({ ...gameState, status: 'PLAYING' });
    setView('PLAYING');
  };

  const submitGuess = (guess: Location) => {
    if (!gameState || !currentPlayer) return;
    const currentQ = gameState.questions[gameState.currentQuestionIndex];
    const distance = calculateDistance(guess, currentQ.location);
    const updatedPlayers = gameState.players.map(p => 
      p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p
    );
    const newState = { ...gameState, players: updatedPlayers };
    if (updatedPlayers.every(p => p.hasGuessed)) newState.status = 'RESULTS';
    updateGameState(newState);
  };

  const nextRound = () => {
    if (!gameState) return;
    const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
    const updatedPlayers = gameState.players.map(p => {
      const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
      return { ...p, score: p.score + Math.max(0, gameState.players.length - rank), hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
    });
    const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
    updateGameState({ ...gameState, players: updatedPlayers, currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, status: isLast ? 'FINISHED' : 'PLAYING' });
  };

  // View Switcher
  if (view === 'AUTH') {
    return <Auth onAuthSuccess={(u) => { setUser(u); setView('CREATE'); }} onBack={() => setView('HOME')} />;
  }

  if (view === 'CREATE') {
    return <QuizCreator onComplete={handleCreateQuiz} onCancel={() => setView('HOME')} />;
  }

  if (view === 'LOBBY' && gameState) {
    return <Lobby gameState={gameState} isHost={isHost} onStart={startGame} currentPlayer={currentPlayer} />;
  }

  if (view === 'PLAYING' && gameState) {
    return <GameBoard gameState={gameState} isHost={isHost} currentPlayer={currentPlayer} onGuess={submitGuess} onNext={nextRound} />;
  }

  if (view === 'JOIN') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-50">
        <div className="max-w-md w-full">
          <button onClick={() => setView('HOME')} className="mb-6 text-slate-500 hover:text-indigo-600 flex items-center font-medium">
             <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             Back
          </button>
          <div className="bg-white rounded-[2.5rem] p-10 shadow-xl border border-slate-100">
            <h2 className="text-3xl font-black text-slate-900 mb-6 text-center">Join Expedition</h2>
            <div className="space-y-4">
              <input id="gameCode" placeholder="ENTER GAME CODE" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 focus:bg-white rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl" />
              <input id="playerName" placeholder="YOUR NAME" className="w-full px-5 py-4 bg-slate-50 border-2 border-transparent focus:border-indigo-500 focus:bg-white rounded-2xl outline-none transition-all" />
              <button onClick={() => {
                const code = (document.getElementById('gameCode') as HTMLInputElement).value;
                const name = (document.getElementById('playerName') as HTMLInputElement).value;
                if (code && name) handleJoinGame(code, name);
              }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 rounded-2xl shadow-lg transition-all active:scale-95">
                Enter Lobby
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white text-slate-900 overflow-hidden font-sans">
      <div className="absolute top-0 right-0 p-6">
        {user ? (
          <div className="flex items-center space-x-3 bg-slate-50 px-4 py-2 rounded-full border border-slate-100">
            <div className="w-2 h-2 rounded-full bg-green-500"></div>
            <span className="text-sm font-bold text-slate-600">Hi, {user.username}</span>
            <button onClick={() => { localStorage.removeItem('locateit_user'); setUser(null); }} className="text-xs text-red-500 font-bold hover:underline ml-2">Logout</button>
          </div>
        ) : (
          <button onClick={() => setView('AUTH')} className="text-sm font-bold text-indigo-600 hover:underline">Creator Login</button>
        )}
      </div>

      <div className="max-w-6xl mx-auto h-screen flex flex-col md:flex-row items-center">
        <div className="w-full md:w-1/2 p-8 md:p-16 flex flex-col justify-center space-y-8 text-center md:text-left">
          <div className="inline-block px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-sm font-bold tracking-wide w-fit mx-auto md:mx-0">
            VERSION 1.0 NOW LIVE
          </div>
          <h1 className="text-6xl md:text-8xl font-black tracking-tight text-slate-900 leading-[0.9]">
            Find the <span className="text-indigo-600">Real</span> World.
          </h1>
          <p className="text-xl text-slate-500 max-w-md mx-auto md:mx-0">
            The ultimate personalized map quiz. Host your own trails and challenge your inner circle.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 pt-4">
            <button 
              onClick={() => user ? setView('CREATE') : setView('AUTH')}
              className="px-8 py-5 bg-indigo-600 text-white rounded-[1.5rem] font-black text-lg shadow-2xl shadow-indigo-200 hover:bg-indigo-700 transition-all hover:-translate-y-1 active:scale-95 flex-1"
            >
              Design a Trail
            </button>
            <button 
              onClick={() => setView('JOIN')}
              className="px-8 py-5 bg-white text-slate-900 border-2 border-slate-100 rounded-[1.5rem] font-black text-lg shadow-xl hover:bg-slate-50 transition-all hover:-translate-y-1 active:scale-95 flex-1"
            >
              Join the Quest
            </button>
          </div>
        </div>

        <div className="w-full md:w-1/2 h-[50vh] md:h-full relative overflow-hidden flex items-center justify-center p-8">
           <div className="w-full aspect-square max-w-lg bg-indigo-600/5 rounded-[3rem] relative flex items-center justify-center">
              <div className="w-3/4 h-3/4 bg-white rounded-3xl shadow-2xl rotate-3 flex items-center justify-center overflow-hidden border-8 border-white">
                 <img src="https://images.unsplash.com/photo-1526772662000-3f88f10405ff?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover grayscale" />
              </div>
              <div className="absolute top-1/4 -left-4 w-32 h-32 bg-indigo-600 rounded-3xl shadow-xl -rotate-6 flex items-center justify-center">
                 <svg className="w-16 h-16 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Question, Location } from '../types';
import { generateId } from '../utils';

interface QuizCreatorProps {
  onComplete: (questions: Question[]) => void;
  onCancel: () => void;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel }) => {
  const [questions, setQuestions] = useState<Question[]>([]);
  const [isCapturing, setIsCapturing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const watchId = useRef<number | null>(null);

  // We request location when the creator enters this mode
  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        (err) => setError("Location access required to tag photos. Please enable GPS."),
        { enableHighAccuracy: true }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCapturing(true);
      }
    } catch (err) {
      setError("Camera access required for this mode.");
    }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current && currentLocation) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        canvasRef.current.width = videoRef.current.videoWidth;
        canvasRef.current.height = videoRef.current.videoHeight;
        context.drawImage(videoRef.current, 0, 0);

        // Optional: Simple compression via canvas quality
        const imageUrl = canvasRef.current.toDataURL('image/jpeg', 0.8);

        const newQuestion: Question = {
          id: generateId(),
          imageUrl,
          location: { ...currentLocation }
        };

        setQuestions([...questions, newQuestion]);
        setIsCapturing(false);
        const stream = videoRef.current.srcObject as MediaStream;
        stream?.getTracks().forEach(track => track.stop());
      }
    }
  };

  return (
    <div className="min-h-screen bg-slate-900 text-white flex flex-col p-6">
      <header className="flex justify-between items-center mb-8">
        <div>
          <h2 className="text-3xl font-black tracking-tight">Design Trail</h2>
          <p className="text-slate-400 font-medium">{questions.length} / 10 spots marked</p>
        </div>
        <button onClick={onCancel} className="bg-white/10 hover:bg-white/20 px-4 py-2 rounded-xl text-sm font-bold transition-colors">Cancel</button>
      </header>

      {error && (
        <div className="bg-red-500/20 border border-red-500 text-red-200 p-4 rounded-2xl mb-6 flex items-center space-x-3">
          <svg className="w-6 h-6 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          <span className="text-sm font-bold">{error}</span>
        </div>
      )}

      <div className="flex-1 overflow-y-auto pb-8">
        {isCapturing ? (
          <div className="relative rounded-[2.5rem] overflow-hidden aspect-[4/5] bg-black shadow-2xl border-4 border-white/10">
            <video ref={videoRef} autoPlay playsInline className="w-full h-full object-cover" />
            <div className="absolute bottom-8 inset-x-0 flex justify-center">
              <button 
                onClick={capturePhoto}
                disabled={!currentLocation}
                className={`w-20 h-20 rounded-full bg-white flex items-center justify-center border-8 border-slate-300 shadow-xl active:scale-90 transition-all ${!currentLocation ? 'opacity-50 grayscale' : ''}`}
              >
                {!currentLocation && <div className="w-2 h-2 rounded-full bg-red-500 animate-ping"></div>}
              </button>
            </div>
            {!currentLocation && (
              <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 flex justify-center">
                 <div className="bg-black/60 backdrop-blur px-6 py-3 rounded-full text-xs font-bold border border-white/20">WAITING FOR GPS...</div>
              </div>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-4">
            {questions.map((q, idx) => (
              <div key={q.id} className="relative aspect-[4/5] rounded-3xl overflow-hidden group shadow-lg border-2 border-white/5">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
                <div className="absolute bottom-3 left-3 bg-black/50 backdrop-blur px-3 py-1 rounded-xl text-[10px] font-black uppercase tracking-widest">SPOT {idx + 1}</div>
                <button 
                  onClick={() => setQuestions(questions.filter(item => item.id !== q.id))}
                  className="absolute top-3 right-3 bg-red-500 rounded-full p-2 opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
            ))}
            {questions.length < 10 && (
              <button 
                onClick={startCamera}
                className="aspect-[4/5] rounded-3xl border-2 border-dashed border-slate-700 flex flex-col items-center justify-center space-y-3 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all group"
              >
                <div className="w-14 h-14 rounded-2xl bg-slate-800 flex items-center justify-center group-hover:scale-110 transition-transform">
