            {isLogin ? 'Sign in to manage your trails.' : 'Create an account to start hosting.'}
          </p>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-2 ml-1 uppercase tracking-widest">Username</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                className="w-full px-6 py-4 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white"
                placeholder="Explorer name"
                required
              />
            </div>
            <div>
              <label className="block text-xs font-bold text-slate-500 mb-2 ml-1 uppercase tracking-widest">Password</label>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full px-6 py-4 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white"
                placeholder="••••••••"
                required
              />
            </div>
            <button
              type="submit"
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl shadow-lg shadow-indigo-900/20 transition-all active:scale-95 mt-4 text-lg"
            >
              {isLogin ? 'Sign In' : 'Create Account'}
            </button>
          </form>

          <div className="mt-10 text-center">
            <button
              onClick={() => setIsLogin(!isLogin)}
              className="text-indigo-400 font-bold hover:text-indigo-300 transition-colors"
            >
              {isLogin ? "New here? Create an account" : "Have an account? Log in instead"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Auth;

