import React, { useState, useEffect } from 'react';
import { User, Trail } from '../types';

interface DashboardProps {
  user: User;
  onNewTrail: () => void;
  onEditTrail: (trail: Trail) => void;
  onHostTrail: (trail: Trail) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onNewTrail, onEditTrail, onHostTrail, onLogout }) => {
  const [trails, setTrails] = useState<Trail[]>([]);

  useEffect(() => {
    const saved = localStorage.getItem(`trails_${user.id}`);
    if (saved) {
      setTrails(JSON.parse(saved).sort((a: Trail, b: Trail) => b.lastUpdated - a.lastUpdated));
    }
  }, [user.id]);

  const deleteTrail = (id: string) => {
    if (confirm("Delete this trail forever?")) {
      const updated = trails.filter(t => t.id !== id);
      setTrails(updated);
      localStorage.setItem(`trails_${user.id}`, JSON.stringify(updated));
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 flex flex-col">
      <header className="max-w-4xl w-full mx-auto flex justify-between items-center py-8">
        <div>
          <h1 className="text-3xl font-black tracking-tight">Your Trails</h1>
          <p className="text-slate-400">Welcome back, {user.username}</p>
        </div>
        <button onClick={onLogout} className="text-xs font-bold text-red-400 uppercase tracking-widest hover:text-red-300">Logout</button>
      </header>

      <main className="max-w-4xl w-full mx-auto flex-1 flex flex-col space-y-8 pb-12">
        <button 
          onClick={onNewTrail}
          className="w-full p-8 rounded-[2rem] border-2 border-dashed border-slate-800 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all flex flex-col items-center justify-center space-y-4 group"
        >
          <div className="w-16 h-16 rounded-2xl bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl">
             <svg className="w-8 h-8 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </div>
          <span className="text-lg font-bold">Design New Trail</span>
        </button>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 scroll-smooth-touch overflow-y-auto pr-2">
          {trails.map(trail => (
            <div key={trail.id} className="bg-slate-900 rounded-3xl p-6 border border-slate-800 shadow-xl flex flex-col space-y-6">
              <div className="flex justify-between items-start">
                <div className="flex flex-col">
                  <span className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Trail #{trail.id}</span>
                  <h3 className="text-xl font-bold">{trail.name || "Untitled Trail"}</h3>
                  <span className="text-xs text-slate-500 mt-1">{trail.questions.length} locations marked</span>
                </div>
                <button onClick={() => deleteTrail(trail.id)} className="text-slate-600 hover:text-red-500 transition-colors">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </div>

              <div className="flex gap-3">
                <button 
                  onClick={() => onHostTrail(trail)}
                  className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-indigo-900/20"
                >
                  Start Game
                </button>
                <button 
                  onClick={() => onEditTrail(trail)}
                  className="flex-1 bg-slate-800 hover:bg-slate-700 text-white font-bold py-3 rounded-xl transition-all"
                >
                  Edit
                </button>
              </div>
            </div>
          ))}
        </div>

        {trails.length === 0 && (
          <div className="flex-1 flex flex-col items-center justify-center py-20 opacity-30 text-center">
            <svg className="w-16 h-16 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg>
            <p>No trails yet. Go exploring!</p>
          </div>
        )}
      </main>
    </div>
  );
};

