import React, { useState, useEffect } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        setGameState(event.data.state);
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, []);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const saveTrailToStorage = (trail: Trail) => {
    if (!user) return;
    const key = `trails_${user.id}`;
    const saved = localStorage.getItem(key);
    let trails: Trail[] = saved ? JSON.parse(saved) : [];

    const existingIndex = trails.findIndex(t => t.id === trail.id);
    if (existingIndex > -1) {
      trails[existingIndex] = trail;
    } else {
      trails.push(trail);
    }

    localStorage.setItem(key, JSON.stringify(trails));
  };

  const handleCreateQuiz = (questions: Question[]) => {
    if (!user) return;

    const trail: Trail = editingTrail || {
      id: generateId(),
      name: `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    trail.questions = questions;
    trail.lastUpdated = Date.now();

    saveTrailToStorage(trail);
    setEditingTrail(null);
    setView('DASHBOARD');
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const newPlayer: Player = {
        id: generateId(),
        name,
        score: 0,
        hasGuessed: false
      };
      const newState = {
        ...gameState,
        players: [...gameState.players, newPlayer]
      };
      setCurrentPlayer(newPlayer);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. In this version, ensure the host has the game open in another tab!");
    }
  };

  const startGame = () => {
    if (!gameState) return;
    updateGameState({ ...gameState, status: 'PLAYING' });
    setView('PLAYING');
  };

  const submitGuess = (guess: Location) => {
    if (!gameState || !currentPlayer) return;
    const currentQ = gameState.questions[gameState.currentQuestionIndex];
    const distance = calculateDistance(guess, currentQ.location);
    const updatedPlayers = gameState.players.map(p => 
      p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p
    );
    const newState = { ...gameState, players: updatedPlayers };
    if (updatedPlayers.every(p => p.hasGuessed)) newState.status = 'RESULTS';
    updateGameState(newState);
  };

  const nextRound = () => {
    if (!gameState) return;
    const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
    const updatedPlayers = gameState.players.map(p => {
      const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
      return { ...p, score: p.score + Math.max(0, gameState.players.length - rank), hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
    });
    const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
    updateGameState({ ...gameState, players: updatedPlayers, currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, status: isLast ? 'FINISHED' : 'PLAYING' });
  };

  // View Switcher logic
  if (view === 'AUTH') {
    return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  }

  if (view === 'DASHBOARD' && user) {
    return (
      <Dashboard 
        user={user} 
        onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }}
        onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }}
        onHostTrail={handleHostTrail}
        onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }}
      />
    );
  }

  if (view === 'CREATE') {
    return <QuizCreator initialQuestions={editingTrail?.questions} onComplete={handleCreateQuiz} onCancel={() => setView('DASHBOARD')} />;
  }

  if (view === 'LOBBY' && gameState) {
    return <Lobby gameState={gameState} isHost={isHost} onStart={startGame} currentPlayer={currentPlayer} onBack={() => setView('DASHBOARD')} />;
  }

  if (view === 'PLAYING' && gameState) {
    return <GameBoard gameState={gameState} isHost={isHost} currentPlayer={currentPlayer} onGuess={submitGuess} onNext={nextRound} />;
  }

  if (view === 'JOIN') {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-950">
        <div className="max-w-md w-full">
          <button onClick={() => setView('HOME')} className="mb-8 text-slate-400 hover:text-indigo-400 flex items-center font-medium transition-colors">
             <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             Back
          </button>
          <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl border border-slate-800">
            <h2 className="text-3xl font-black text-white mb-6 text-center tracking-tight">Enter the Quest</h2>
            <div className="space-y-4">
              <input id="gameCode" placeholder="GAME CODE" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl text-white" />
              <input id="playerName" placeholder="YOUR NAME" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white" />
              <button onClick={() => {
                const code = (document.getElementById('gameCode') as HTMLInputElement).value;
                const name = (document.getElementById('playerName') as HTMLInputElement).value;
                if (code && name) handleJoinGame(code, name);
              }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl shadow-lg transition-all active:scale-95 text-lg">
                Join Lobby
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 overflow-hidden">
      <div className="max-w-6xl mx-auto h-screen flex flex-col md:flex-row items-center relative">
        {/* Background Glow */}
        <div className="absolute top-1/2 left-1/4 -translate-y-1/2 w-[500px] h-[500px] bg-indigo-600/10 blur-[120px] rounded-full pointer-events-none"></div>

        <div className="w-full md:w-3/5 p-8 md:p-16 flex flex-col justify-center space-y-12 text-center md:text-left z-10">
          <div className="inline-block px-4 py-1.5 bg-slate-900 text-indigo-400 rounded-full text-xs font-bold tracking-[0.2em] w-fit mx-auto md:mx-0 border border-indigo-500/20 uppercase">
            Personalized Map Exploration
          </div>

          {/* Robust Animated Logo Section */}
          <div className="relative inline-flex flex-col items-center md:items-start select-none">
            <div className="relative text-7xl md:text-9xl font-black tracking-tighter leading-none flex flex-col gap-[1.5rem] md:gap-[2.5rem]">
                <div className="flex items-center">
                   <div className="w-[0.7em] md:w-[0.8em] relative shrink-0">
                      {/* The Sliding T contained within a word-height relative space */}
                      <div className="absolute left-0 top-0 text-indigo-500 font-black animate-t-logic t-shadow">
                        T
                      </div>
                   </div>
                   <span className="text-slate-100">HERE</span>
                </div>

                <div className="text-slate-800 text-4xl md:text-6xl pl-[1.2em] font-light">&</div>

                <div className="flex items-center">
                   <div className="w-[0.7em] md:w-[0.8em] relative shrink-0"></div>
                   <span className="text-slate-100">HERE</span>
                </div>
            </div>
          </div>

          <p className="text-xl text-slate-400 max-w-md mx-auto md:mx-0 leading-relaxed font-light">
            Challenge your friends to find exactly where you stood. Create custom trails from real photos.
          </p>

          <div className="flex flex-col sm:flex-row gap-5 pt-4">
            <button 
              onClick={() => user ? setView('DASHBOARD') : setView('AUTH')}
              className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-2xl shadow-indigo-900/20 hover:bg-indigo-500 transition-all hover:-translate-y-1 active:scale-95 flex-1"
            >
              Design a Trail
            </button>
            <button 
              onClick={() => setView('JOIN')}
              className="px-10 py-5 bg-slate-900 text-white border border-slate-800 rounded-2xl font-bold text-lg shadow-xl hover:bg-slate-800 transition-all hover:-translate-y-1 active:scale-95 flex-1"
            >
              Join the Quest
            </button>
          </div>
        </div>

        <div className="w-full md:w-2/5 h-[40vh] md:h-full relative flex items-center justify-center p-8">
           <div className="relative w-full max-w-sm aspect-[4/5] bg-slate-900 rounded-[3rem] border border-slate-800 p-4 shadow-2xl rotate-2">
              <div className="w-full h-full rounded-[2.5rem] overflow-hidden border-4 border-slate-800 shadow-inner">
                 <img src="https://images.unsplash.com/photo-1526772662000-3f88f10405ff?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover opacity-60 grayscale hover:grayscale-0 transition-all duration-700" />
              </div>
              <div className="absolute -bottom-6 -left-6 w-24 h-24 bg-indigo-600 rounded-3xl shadow-2xl flex items-center justify-center -rotate-12 border-4 border-slate-950">
                 <svg className="w-12 h-12 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

