import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        () => setError("GPS signal lost. Ensure location is enabled."),
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setIsCapturing(true);
      }
    } catch (err) {
      setError("Unable to access camera.");
    }
  };

  const capturePhoto = () => {
    if (videoRef.current && canvasRef.current && currentLocation) {
      const context = canvasRef.current.getContext('2d');
      if (context) {
        // Compress and resize for localStorage safety (Max 800px width)
        const scale = Math.min(1, 800 / videoRef.current.videoWidth);
        canvasRef.current.width = videoRef.current.videoWidth * scale;
        canvasRef.current.height = videoRef.current.videoHeight * scale;
        context.drawImage(videoRef.current, 0, 0, canvasRef.current.width, canvasRef.current.height);

        const imageUrl = canvasRef.current.toDataURL('image/jpeg', 0.6);

        setQuestions([...questions, {
          id: generateId(),
          imageUrl,
          location: { ...currentLocation }
        }]);

        stopCamera();
      }
    }
  };

  const stopCamera = () => {
    setIsCapturing(false);
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
    }
  };

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-50 bg-black flex flex-col">
        <video ref={videoRef} autoPlay playsInline className="flex-1 w-full h-full object-cover" />
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/80 to-transparent">
          <button onClick={stopCamera} className="w-14 h-14 rounded-full bg-white/20 flex items-center justify-center backdrop-blur-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <button 
            onClick={capturePhoto}
            disabled={!currentLocation}
            className={`w-20 h-20 rounded-full bg-white border-[6px] border-slate-300 shadow-2xl active:scale-90 transition-all flex items-center justify-center ${!currentLocation ? 'opacity-30' : ''}`}
          >
             {!currentLocation && <div className="w-2 h-2 rounded-full bg-indigo-600 animate-ping"></div>}
          </button>
          <div className="w-14 h-14" /> {/* Spacer */}
        </div>
        {!currentLocation && (
          <div className="absolute top-10 inset-x-0 flex justify-center">
            <div className="bg-black/50 backdrop-blur px-6 py-2 rounded-full text-xs font-bold tracking-widest text-white border border-white/20">SEARCHING FOR GPS...</div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-6">
          <div className="flex-1 mr-4">
            <input 
              type="text" 
              placeholder="Name your trail..." 
              value={trailName}
              onChange={(e) => setTrailName(e.target.value)}
              className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-700 tracking-tight"
            />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">
              {questions.length} Spots Captured
            </p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 hover:bg-slate-800 px-4 py-2 rounded-xl text-sm font-bold border border-slate-800 transition-colors">Cancel</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-8 scroll-smooth-touch overflow-y-auto">
        {error && (
          <div className="bg-red-500/10 border border-red-500/50 text-red-200 p-5 rounded-[1.5rem] flex items-center space-x-4">
            <svg className="w-6 h-6 shrink-0 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
            <span className="text-sm font-bold">{error}</span>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900 rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl flex flex-col group">
              <div className="relative aspect-video">
                <img src={q.imageUrl} className="w-full h-full object-cover" alt={`Spot ${idx + 1}`} />
                <div className="absolute top-4 left-4 bg-black/60 backdrop-blur px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest">SPOT {idx + 1}</div>
                <button 
                  onClick={() => setQuestions(questions.filter(item => item.id !== q.id))}
                  className="absolute top-4 right-4 bg-red-500/80 backdrop-blur text-white p-2 rounded-xl opacity-0 group-hover:opacity-100 transition-opacity"
                >
