        <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl border border-slate-800">
          <h2 className="text-3xl font-black text-white mb-6 text-center">Join Expedition</h2>
          <div className="space-y-4">
            <input id="gameCode" placeholder="GAME CODE" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl text-white" />
            <input id="playerName" placeholder="YOUR NAME" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white" />
            <button onClick={() => {
