import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
          setError(null);
        },
        (err) => {
          console.error("GPS Error:", err);
          setError("GPS signal lost. Please ensure location services are enabled.");
        },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    } else {
      setError("Geolocation is not supported by this browser.");
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = {
        video: { 
          facingMode: 'environment', 
          width: { ideal: 1280 }, 
          height: { ideal: 720 } 
        }
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      setIsCapturing(true);

      // Delay slightly to ensure video element is rendered
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Video play failed:", e));
          };
        }
      }, 200);
    } catch (err) {
      console.error("Camera Error:", err);
      setError("Unable to access camera. Check permissions.");
    }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current || !currentLocation) {
      if (!currentLocation) alert("Waiting for GPS lock...");
      return;
    }

    const video = videoRef.current;
    const canvas = canvasRef.current;

    // Safety check for video stream readiness
    if (video.readyState < 2 || video.videoWidth === 0) {
      console.warn("Video not ready for capture");
      return;
    }

    setIsProcessing(true);
    setIsFlashing(true);

    const context = canvas.getContext('2d');
    if (context) {
      const vw = video.videoWidth;
      const vh = video.videoHeight;

      // Target max 640px width to keep localStorage size low
      const scale = Math.min(1, 640 / vw);
      canvas.width = vw * scale;
      canvas.height = vh * scale;

      try {
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.6);

        const newQuestion: Question = {
          id: generateId(),
          imageUrl,
          location: { ...currentLocation }
        };

        setQuestions(prev => [...prev, newQuestion]);

        // Finalize UI transition after flash
        setTimeout(() => {
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) {
        console.error("Capture processing failed:", e);
        setIsFlashing(false);
        setIsProcessing(false);
        setError("Failed to process image capture.");
      }
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      const tracks = (videoRef.current.srcObject as MediaStream).getTracks();
      tracks.forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  };

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          muted 
          className="flex-1 w-full h-full object-cover"
        />

        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}

        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/40 to-transparent">
          <button 
            onClick={stopCamera} 
            disabled={isProcessing}
            className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center backdrop-blur-xl border border-white/20 active:bg-white/30 transition-all"
          >
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <div className="relative">
             <button 
              onClick={capturePhoto}
              disabled={!currentLocation || isProcessing}
              className={`w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center ${(!currentLocation || isProcessing) ? 'opacity-30' : 'hover:scale-105'}`}
            >
               {isProcessing ? (
                 <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
               ) : (
                 <div className="w-16 h-16 rounded-full border-4 border-slate-100"></div>
               )}
            </button>
            {!currentLocation && !isProcessing && (
              <div className="absolute -top-14 left-1/2 -translate-x-1/2 whitespace-nowrap bg-indigo-600 text-white px-4 py-1.5 rounded-full text-[10px] font-black tracking-widest uppercase shadow-lg border border-indigo-500 animate-pulse">
                WAITING FOR GPS...
              </div>
            )}
          </div>

          <div className="w-14 h-14" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-6">
          <div className="flex-1 mr-4">
            <input 
              type="text" 
              placeholder="Name your trail..." 
              value={trailName}
              onChange={(e) => setTrailName(e.target.value)}
              className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight"
            />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">
              {questions.length} Locations Tagged
            </p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 hover:bg-slate-800 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800 transition-colors shadow-lg">Cancel</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-8 scroll-smooth-touch overflow-y-auto pb-32">
        {error && (
          <div className="bg-red-500/10 border border-red-500/50 text-red-200 p-5 rounded-[2rem] flex items-center space-x-4">
            <svg className="w-6 h-6 shrink-0 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
            <span className="text-sm font-bold leading-tight">{error}</span>
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900 rounded-[2.5rem] overflow-hidden border border-slate-800/50 shadow-2xl flex flex-col group transition-all hover:border-indigo-500/30">
              <div className="relative aspect-video">
                <img src={q.imageUrl} className="w-full h-full object-cover" alt={`Spot ${idx + 1}`} />
                <div className="absolute top-5 left-5 bg-black/60 backdrop-blur px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border border-white/10">SPOT {idx + 1}</div>
                <button 
                  onClick={() => setQuestions(prev => prev.filter(item => item.id !== q.id))}
                  className="absolute top-5 right-5 bg-red-500/90 backdrop-blur text-white p-2.5 rounded-2xl opacity-0 group-hover:opacity-100 transition-all hover:scale-110 shadow-xl"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
              <div className="h-40 w-full p-2 bg-slate-900">
                 <Map center={q.location} zoom={15} markers={[{ position: q.location, icon: 'target' }]} />
              </div>
            </div>
          ))}

          <button 
            onClick={startCamera}
            className="aspect-[4/5] md:aspect-auto md:min-h-[300px] rounded-[2.5rem] border-2 border-dashed border-slate-800 flex flex-col items-center justify-center space-y-5 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all group py-12"
          >
            <div className="w-24 h-24 rounded-[2rem] bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform shadow-2xl border border-slate-800/50">
               <svg className="w-12 h-12 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
               </svg>
            </div>
            <div className="text-center">
              <span className="block text-xl font-black text-slate-200 group-hover:text-indigo-400 transition-colors">Capture Site</span>
              <span className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-2 block">Photo + Geotag</span>
            </div>
          </button>
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-8 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <div className="max-w-4xl mx-auto">
          <button 
            disabled={questions.length === 0}
            onClick={() => onComplete(questions, trailName)}
            className={`w-full py-5 rounded-[2rem] font-black text-xl transition-all shadow-2xl ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 active:scale-95 text-white' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}
          >
            Finalize Quest
          </button>
        </div>
      </footer>

      <canvas ref={canvasRef} style={{ display: 'none' }} />
    </div>
  );
};

