          <p className="text-xl text-slate-400 max-w-md mx-auto md:mx-0 leading-relaxed font-light">
            Capture your neighborhood. Challenge your friends to find the exact spot where you stood.
          </p>

          <div className="flex flex-col sm:flex-row gap-5 pt-4">
            <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-2xl hover:bg-indigo-500 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              Design a Trail
            </button>
            <button onClick={() => setView('JOIN')} className="px-10 py-5 bg-slate-900 text-white border border-slate-800 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              Join the Quest
            </button>
          </div>
        </div>

        <div className="w-full md:w-1/2 mt-20 md:mt-0 flex items-center justify-center">
           <div className="relative w-full max-w-sm aspect-[4/5] bg-slate-900 rounded-[4rem] border border-slate-800 p-5 shadow-2xl rotate-3">
              <div className="w-full h-full rounded-[3rem] overflow-hidden border-4 border-slate-800">
                 <img src="https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover grayscale opacity-50 hover:grayscale-0 transition-all duration-700" />
              </div>
              <div className="absolute -bottom-8 -left-8 w-28 h-28 bg-indigo-600 rounded-[2rem] shadow-2xl flex items-center justify-center -rotate-12 border-4 border-slate-950">
                 <svg className="w-14 h-14 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
           </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';
// @ts-ignore
import EXIF from 'exif-js';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [pendingQuestion, setPendingQuestion] = useState<{ imageUrl: string, location: Location } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
          setError(null);
        },
        (err) => {
          console.error("GPS Error:", err);
          // Don't block, just fallback to 0,0 or last known
        },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = {
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      setIsCapturing(true);

      // Delay to ensure DOM is ready
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(e => {
            console.error("Video play failed:", e);
            setError("Click to start camera manually.");
          });
        }
      }, 300);
    } catch (err) {
      console.error("Media error:", err);
      setError("Unable to access camera. Please check permissions.");
    }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) {
      console.warn("Refs not ready");
      return;
    }

    const video = videoRef.current;
    if (video.readyState < 2) {
      console.warn("Video stream not ready");
      return;
    }

    setIsProcessing(true);
    setIsFlashing(true);

    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    if (context) {
      const vw = video.videoWidth;
      const vh = video.videoHeight;
      const scale = Math.min(1, 1024 / vw); // Slightly higher res than before but safe
      canvas.width = vw * scale;
      canvas.height = vh * scale;

      try {
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.7);

        // Finalize state
        const location = currentLocation || { lat: 0, lng: 0 };

        setTimeout(() => {
          setPendingQuestion({ imageUrl, location });
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) {
        console.error("Canvas draw error:", e);
        setIsProcessing(false);
        setIsFlashing(false);
        setError("Failed to process image.");
      }
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      const imageUrl = event.target?.result as string;

      // EXIF extraction logic
      try {
        EXIF.getData(file, function(this: any) {
          let lat: number | null = null;
          let lng: number | null = null;

          const latTag = EXIF.getTag(this, "GPSLatitude");
          const latRef = EXIF.getTag(this, "GPSLatitudeRef");
          const lngTag = EXIF.getTag(this, "GPSLongitude");
          const lngRef = EXIF.getTag(this, "GPSLongitudeRef");

          if (latTag && latRef && lngTag && lngRef) {
            lat = latTag[0] + latTag[1] / 60 + latTag[2] / 3600;
            if (latRef === 'S') lat = -lat;
            lng = lngTag[0] + lngTag[1] / 60 + lngTag[2] / 3600;
            if (lngRef === 'W') lng = -lng;
          }

          setIsProcessing(false);
          setPendingQuestion({ 
            imageUrl, 
            location: (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 0, lng: 0 }) 
          });
        });
      } catch (err) {
        console.error("EXIF error:", err);
        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: currentLocation || { lat: 0, lng: 0 } });
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = () => {
    if (pendingQuestion) {
      setQuestions([...questions, { ...pendingQuestion, id: generateId() }]);
      setPendingQuestion(null);
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  };

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur">
          <h2 className="text-xl font-black uppercase tracking-widest">Confirm Location</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold hover:text-white">Cancel</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-hidden">
          <div className="flex-1 p-4 flex items-center justify-center bg-black">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="flex-1 p-4 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-4 rounded-2xl">
               <p className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Instructions</p>
               <p className="text-sm text-slate-300">Drag the marker to the exact spot where the photo was taken.</p>
             </div>
             <div className="flex-1 rounded-3xl overflow-hidden border border-slate-800">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={16} 
                  onLocationSelect={(loc) => setPendingQuestion({ ...pendingQuestion, location: loc })}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button 
               onClick={confirmPending}
               className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all"
             >
               Finalize Spot
             </button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          muted 
          className="flex-1 w-full h-full object-cover"
          onClick={() => videoRef.current?.play()} // Fallback for some mobile browsers
        />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}

        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/40 to-transparent">
          <button onClick={stopCamera} disabled={isProcessing} className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center backdrop-blur-xl border border-white/20 active:bg-white/30">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>

          <button 
            onClick={capturePhoto} 
            disabled={isProcessing} 
            className={`w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center ${isProcessing ? 'opacity-50' : 'hover:scale-105'}`}
          >
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-16 h-16 rounded-full border-4 border-slate-100"></div>}
          </button>

          <div className="w-14 h-14" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-6">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Name your trail..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Locations Tagged</p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 hover:bg-slate-800 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800 shadow-lg transition-colors">Cancel</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-8 scroll-smooth-touch overflow-y-auto pb-32">
        {error && (
          <div className="p-4 bg-red-500/20 border border-red-500/40 rounded-2xl text-red-200 text-sm font-bold flex items-center">
            <svg className="w-5 h-5 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
            {error}
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900 rounded-[2.5rem] overflow-hidden border border-slate-800/50 shadow-2xl flex flex-col group transition-all hover:border-indigo-500/30">
              <div className="relative aspect-video">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
                <div className="absolute top-5 left-5 bg-black/60 backdrop-blur px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest">SPOT {idx + 1}</div>
                <button onClick={() => setQuestions(qs => qs.filter(item => item.id !== q.id))} className="absolute top-5 right-5 bg-red-500/90 backdrop-blur text-white p-2.5 rounded-2xl opacity-0 group-hover:opacity-100 transition-all hover:scale-110">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
              <div className="h-40 w-full p-2 bg-slate-900">
                 <Map center={q.location} zoom={15} markers={[{ position: q.location, icon: 'target' }]} />
              </div>
            </div>
          ))}

          <div className="grid grid-cols-1 gap-4">
            <button onClick={startCamera} className="aspect-[4/5] rounded-[2.5rem] border-2 border-dashed border-slate-800 flex flex-col items-center justify-center space-y-5 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all group p-8">
              <div className="w-20 h-20 rounded-[2rem] bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform shadow-2xl border border-slate-800/50">
                 <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
              <div className="text-center">
                <span className="block text-xl font-black text-slate-200 group-hover:text-indigo-400">Capture Site</span>
                <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-2 block">Take a new photo</span>
              </div>
            </button>

            <button onClick={() => fileInputRef.current?.click()} className="aspect-[4/5] rounded-[2.5rem] border-2 border-dashed border-slate-800 flex flex-col items-center justify-center space-y-5 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all group p-8">
              <div className="w-20 h-20 rounded-[2rem] bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform shadow-2xl border border-slate-800/50">
                 <svg className="w-10 h-10 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
              </div>
              <div className="text-center">
                <span className="block text-xl font-black text-slate-200 group-hover:text-indigo-400">Upload Photo</span>
                <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-2 block">From your gallery</span>
              </div>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
            </button>
          </div>
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-8 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <div className="max-w-4xl mx-auto">
          <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full py-5 rounded-[2rem] font-black text-xl transition-all shadow-2xl ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 text-white' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
        </div>
      </footer>

      <canvas ref={canvasRef} className="hidden" />

      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/60 backdrop-blur flex items-center justify-center">
          <div className="bg-slate-900 p-8 rounded-3xl flex flex-col items-center space-y-4 border border-slate-800">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs">Processing...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreator;

