const getExifData = (file: File): Promise<Location | null> => {
  return new Promise((resolve) => {
    const timeout = setTimeout(() => resolve(null), 3000); // 3s timeout
    try {
      EXIF.getData(file, function(this: any) {
        clearTimeout(timeout);
        const latTag = EXIF.getTag(this, "GPSLatitude");
        const latRef = EXIF.getTag(this, "GPSLatitudeRef");
        const lngTag = EXIF.getTag(this, "GPSLongitude");
        const lngRef = EXIF.getTag(this, "GPSLongitudeRef");

        if (latTag && latRef && lngTag && lngRef) {
          let lat = latTag[0] + latTag[1] / 60 + latTag[2] / 3600;
          if (latRef === 'S') lat = -lat;
          let lng = lngTag[0] + lngTag[1] / 60 + lngTag[2] / 3600;
          if (lngRef === 'W') lng = -lng;
          resolve({ lat, lng });
        } else {
          resolve(null);
        }
      });
    } catch (error) {
