import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [pendingQuestion, setPendingQuestion] = useState<{ imageUrl: string, location: Location } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
          setError(null);
        },
        (err) => {
          console.error("GPS Error:", err);
          // Don't block, just fallback to 0,0 or last known
        },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = {
        video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } }
      };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      setIsCapturing(true);

      // Delay to ensure DOM is ready
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(e => {
            console.error("Video play failed:", e);
            setError("Click to start camera manually.");
          });
        }
      }, 300);
    } catch (err) {
      console.error("Media error:", err);
      setError("Unable to access camera. Please check permissions.");
    }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) {
      console.warn("Refs not ready");
      return;
    }

    const video = videoRef.current;
    if (video.readyState < 2) {
      console.warn("Video stream not ready");
      return;
    }

    setIsProcessing(true);
    setIsFlashing(true);

    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');

    if (context) {
      const vw = video.videoWidth;
      const vh = video.videoHeight;
      const scale = Math.min(1, 1024 / vw);
      canvas.width = vw * scale;
      canvas.height = vh * scale;

      try {
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.7);

        const location = currentLocation || { lat: 0, lng: 0 };

        setTimeout(() => {
          setPendingQuestion({ imageUrl, location });
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) {
        console.error("Canvas draw error:", e);
        setIsProcessing(false);
        setIsFlashing(false);
        setError("Failed to process image.");
      }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);
    setError(null);

    // Safety timeout to prevent infinite "Processing..." hang (10s)
    const timeoutId = setTimeout(() => {
      if (isProcessing) {
        setIsProcessing(false);
        setError("Processing took too long. Falling back to current location.");
        // We still want to show the image even if EXIF extraction hung
        const reader = new FileReader();
        reader.onload = (event) => {
          setPendingQuestion({ 
            imageUrl: event.target?.result as string, 
            location: currentLocation || { lat: 0, lng: 0 } 
          });
        };
        reader.readAsDataURL(file);
      }
    }, 10000);

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const imageUrl = event.target?.result as string;

        let lat: number | null = null;
        let lng: number | null = null;

        // More robust EXIF extraction using ExifReader
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            // ExifReader's .description field often contains the converted decimal coordinate
            lat = Number(tags.GPSLatitude.description);
            lng = Number(tags.GPSLongitude.description);
          }
        } catch (exifErr) {
          console.warn("Metadata extraction failed, falling back to current GPS:", exifErr);
        }

        clearTimeout(timeoutId);
        setIsProcessing(false);

        setPendingQuestion({ 
          imageUrl, 
          location: (lat !== null && !isNaN(lat) && lng !== null && !isNaN(lng)) 
            ? { lat, lng } 
            : (currentLocation || { lat: 0, lng: 0 }) 
        });
      };

      reader.onerror = () => {
        clearTimeout(timeoutId);
        setIsProcessing(false);
        setError("Failed to read the image file.");
      };

      reader.readAsDataURL(file);
    } catch (err) {
      clearTimeout(timeoutId);
      console.error("File processing error:", err);
      setIsProcessing(false);
      setError("An error occurred while processing the photo.");
    }
  };

  const confirmPending = () => {
    if (pendingQuestion) {
      setQuestions([...questions, { ...pendingQuestion, id: generateId() }]);
      setPendingQuestion(null);
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      const stream = videoRef.current.srcObject as MediaStream;
      stream.getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  };

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur">
          <h2 className="text-xl font-black uppercase tracking-widest">Confirm Location</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold hover:text-white">Cancel</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-hidden">
          <div className="flex-1 p-4 flex items-center justify-center bg-black">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="flex-1 p-4 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-4 rounded-2xl">
               <p className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Instructions</p>
               <p className="text-sm text-slate-300">Drag the marker to the exact spot where the photo was taken.</p>
             </div>
             <div className="flex-1 rounded-3xl overflow-hidden border border-slate-800">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={16} 
                  onLocationSelect={(loc) => setPendingQuestion({ ...pendingQuestion, location: loc })}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button 
               onClick={confirmPending}
               className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all"
             >
               Finalize Spot
             </button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video 
          ref={videoRef} 
          autoPlay 
          playsInline 
          muted 
          className="flex-1 w-full h-full object-cover"
          onClick={() => videoRef.current?.play()} 
        />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}

        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/40 to-transparent">
          <button onClick={stopCamera} disabled={isProcessing} className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center backdrop-blur-xl border border-white/20 active:bg-white/30">
