        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900 rounded-[2.5rem] overflow-hidden border border-slate-800/50 shadow-2xl flex flex-col group transition-all hover:border-indigo-500/30">
              <div className="relative aspect-video">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
                <div className="absolute top-5 left-5 bg-black/60 backdrop-blur px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest">SPOT {idx + 1}</div>
                <button onClick={() => setQuestions(qs => qs.filter(item => item.id !== q.id))} className="absolute top-5 right-5 bg-red-500/90 backdrop-blur text-white p-2.5 rounded-2xl opacity-0 group-hover:opacity-100 transition-all hover:scale-110">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
              <div className="h-40 w-full p-2 bg-slate-900">
                 <Map center={q.location} zoom={15} markers={[{ position: q.location, icon: 'target' }]} />
              </div>
            </div>
          ))}

          <div className="grid grid-cols-1 gap-4">
            <button onClick={startCamera} className="aspect-[4/5] rounded-[2.5rem] border-2 border-dashed border-slate-800 flex flex-col items-center justify-center space-y-5 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all group p-8">
              <div className="w-20 h-20 rounded-[2rem] bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform shadow-2xl border border-slate-800/50">
