              <div className="text-center">
                <span className="block text-xl font-black text-slate-200 group-hover:text-indigo-400">Upload Photo</span>
                <span className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-2 block">From your gallery</span>
              </div>
              <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
