import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import { Location } from '../types';

interface MapProps {
  onLocationSelect?: (loc: Location) => void;
  markers?: { position: Location; label?: string; icon?: 'default' | 'target' | 'user' }[];
  center?: Location;
  zoom?: number;
  lines?: { from: Location; to: Location }[];
}

const isValid = (loc?: Location): boolean => {
  return !!loc && typeof loc.lat === 'number' && typeof loc.lng === 'number' && !isNaN(loc.lat) && !isNaN(loc.lng);
};

const Map: React.FC<MapProps> = ({ onLocationSelect, markers = [], center, zoom = 13, lines = [] }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<L.Map | null>(null);
  const markersLayer = useRef<L.LayerGroup | null>(null);
  const initialLoadDone = useRef(false);

  useEffect(() => {
    if (!mapRef.current || leafletMap.current) return;

    const startPos: [number, number] = isValid(center) ? [center!.lat, center!.lng] : [51.505, -0.09];

    leafletMap.current = L.map(mapRef.current, {
      zoomControl: false,
      attributionControl: false
    }).setView(startPos, zoom);

    L.control.zoom({ position: 'bottomright' }).addTo(leafletMap.current);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
    }).addTo(leafletMap.current);

    markersLayer.current = L.layerGroup().addTo(leafletMap.current);

    leafletMap.current.on('click', (e) => {
      if (onLocationSelect) {
        onLocationSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
      }
    });

    return () => {
      leafletMap.current?.remove();
      leafletMap.current = null;
      initialLoadDone.current = false;
    };
  }, []);

  useEffect(() => {
    if (!leafletMap.current || !markersLayer.current) return;

    if (isValid(center) && !initialLoadDone.current) {
      leafletMap.current.setView([center!.lat, center!.lng], zoom);
      initialLoadDone.current = true;
    }

    markersLayer.current.clearLayers();
    const bounds = L.latLngBounds([]);

    markers.forEach((m) => {
      if (!isValid(m.position)) return;

      const icon = L.divIcon({
        className: 'custom-div-icon',
        html: `<div class="w-8 h-8 rounded-full border-2 border-white shadow-lg flex items-center justify-center ${
          m.icon === 'target' ? 'bg-red-500' : m.icon === 'user' ? 'bg-blue-500' : 'bg-indigo-500'
        }">
          <div class="w-2 h-2 rounded-full bg-white"></div>
        </div>`,
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      });

      const isDraggable = !!onLocationSelect;
      const marker = L.marker([m.position.lat, m.position.lng], { 
        icon, 
        draggable: isDraggable 
      }).addTo(markersLayer.current!);

      if (isDraggable) {
        marker.on('dragend', (event) => {
          const { lat, lng } = event.target.getLatLng();
          onLocationSelect({ lat, lng });
        });
      }

      if (m.label) marker.bindPopup(m.label);
      bounds.extend([m.position.lat, m.position.lng]);
    });

    lines.forEach((line) => {
      if (!isValid(line.from) || !isValid(line.to)) return;
      L.polyline(
        [[line.from.lat, line.from.lng], [line.to.lat, line.to.lng]],
        { color: '#6366f1', weight: 3, dashArray: '5, 10' }
      ).addTo(markersLayer.current!);
      bounds.extend([line.from.lat, line.from.lng]);
      bounds.extend([line.to.lat, line.to.lng]);
    });

    if (lines.length > 0 && bounds.isValid()) {
      leafletMap.current.fitBounds(bounds, { padding: [50, 50] });
    }
  }, [markers, center, zoom, lines]);

  return <div ref={mapRef} className="w-full h-full" />;
};

export default Map;

import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [pendingQuestion, setPendingQuestion] = useState<{ imageUrl: string, location: Location, originalLocation: Location } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          if (!isNaN(lat) && !isNaN(lng)) {
            setCurrentLocation({ lat, lng });
          }
          setError(null);
        },
        (err) => { console.error("GPS Error:", err); },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = { video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(() => setError("Click to start camera manually."));
        }
      }, 300);
    } catch (err) { setError("Unable to access camera."); }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current || videoRef.current.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    if (context) {
      const scale = Math.min(1, 1024 / videoRef.current.videoWidth);
      canvas.width = videoRef.current.videoWidth * scale;
      canvas.height = videoRef.current.videoHeight * scale;
      try {
        context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.7);
        const loc = (currentLocation && !isNaN(currentLocation.lat)) ? currentLocation : { lat: 51.505, lng: -0.09 };
        setTimeout(() => {
          setPendingQuestion({ imageUrl, location: loc, originalLocation: loc });
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) { setIsProcessing(false); setError("Failed to process image."); }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const imageUrl = event.target?.result as string;
        let lat: number | null = null;
        let lng: number | null = null;
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = Number(tags.GPSLatitude.description);
            const parsedLng = Number(tags.GPSLongitude.description);
            if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
              lat = parsedLat;
              lng = parsedLng;
            }
          }
        } catch (exifErr) { console.warn("EXIF failed", exifErr); }
        setIsProcessing(false);
        const loc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });
        setPendingQuestion({ imageUrl, location: loc, originalLocation: loc });
      };
      reader.readAsDataURL(file);
    } catch (err) { setIsProcessing(false); setError("An error occurred during upload."); }
  };

  const confirmPending = () => {
    if (pendingQuestion) {
      setQuestions([...questions, { ...pendingQuestion, id: generateId(), title: `Spot ${questions.length + 1}` }]);
      setPendingQuestion(null);
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const newQuestions = [...questions];
    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= questions.length) return;
    [newQuestions[index], newQuestions[newIndex]] = [newQuestions[newIndex], newQuestions[index]];
    setQuestions(newQuestions);
  };

  const updateQuestionTitle = (id: string, title: string) => {
    setQuestions(qs => qs.map(q => q.id === id ? { ...q, title } : q));
  };

