            <span className="font-bold text-sm">Capture</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center space-x-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-4 px-4 rounded-2xl transition-all group">
            <svg className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
            <span className="font-bold text-sm">Upload</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-3">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/50 rounded-2xl border border-slate-800/60 p-3 flex items-center space-x-3 hover:border-slate-700 transition-colors">
              <div className="w-20 h-20 rounded-xl overflow-hidden shrink-0 border border-slate-800">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
              </div>

              <div className="flex-1 min-w-0">
                <input 
                  type="text" 
                  value={q.title || ''} 
                  onChange={(e) => updateQuestionTitle(q.id, e.target.value)}
                  className="bg-transparent border-none p-0 text-sm font-black focus:ring-0 w-full mb-1"
                />
                <div className="h-10 w-full rounded-lg overflow-hidden grayscale pointer-events-none opacity-40">
                  <Map center={q.location} zoom={16} markers={[{ position: q.location, icon: 'target' }]} />
                </div>
              </div>

              <div className="flex flex-col space-y-1">
                <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1.5 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" clipRule="evenodd" /></svg></button>
                <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1.5 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg></button>
              </div>

              <button onClick={() => setQuestions(qs => qs.filter(item => item.id !== q.id))} className="p-2 text-slate-500 hover:text-red-500 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <div className="max-w-4xl mx-auto">
          <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 text-white' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
        </div>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/60 backdrop-blur flex items-center justify-center p-6">
          <div className="bg-slate-900 p-8 rounded-3xl flex flex-col items-center space-y-4 border border-slate-800 shadow-2xl max-w-xs w-full text-center">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs">Analyzing Metadata...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreator;

import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);

  // pendingQuestion now includes 'editingId' to know if we are updating an existing entry
  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    editingId?: string,
    title?: string 
  } | null>(null);

  const [error, setError] = useState<string | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          if (!isNaN(lat) && !isNaN(lng)) {
            setCurrentLocation({ lat, lng });
          }
          setError(null);
        },
        (err) => { console.error("GPS Error:", err); },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = { video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(() => setError("Click to start camera manually."));
        }
      }, 300);
    } catch (err) { setError("Unable to access camera."); }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current || videoRef.current.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    if (context) {
      const scale = Math.min(1, 1024 / videoRef.current.videoWidth);
      canvas.width = videoRef.current.videoWidth * scale;
      canvas.height = videoRef.current.videoHeight * scale;
      try {
        context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.7);
        const loc = (currentLocation && !isNaN(currentLocation.lat)) ? currentLocation : { lat: 51.505, lng: -0.09 };
        setTimeout(() => {
          setPendingQuestion({ imageUrl, location: loc, originalLocation: loc });
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) { setIsProcessing(false); setError("Failed to process image."); }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const imageUrl = event.target?.result as string;
        let lat: number | null = null;
        let lng: number | null = null;
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = Number(tags.GPSLatitude.description);
            const parsedLng = Number(tags.GPSLongitude.description);
            if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
              lat = parsedLat;
              lng = parsedLng;
            }
          }
        } catch (exifErr) { console.warn("EXIF failed", exifErr); }
        setIsProcessing(false);
        const loc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });
        setPendingQuestion({ imageUrl, location: loc, originalLocation: loc });
      };
      reader.readAsDataURL(file);
    } catch (err) { setIsProcessing(false); setError("An error occurred during upload."); }
  };

  const confirmPending = () => {
    if (pendingQuestion) {
      if (pendingQuestion.editingId) {
        // Update existing
        setQuestions(qs => qs.map(q => q.id === pendingQuestion.editingId ? { 
          ...q, 
          location: pendingQuestion.location,
          imageUrl: pendingQuestion.imageUrl,
          title: pendingQuestion.title || q.title 
        } : q));
      } else {
        // Add new
        setQuestions([...questions, { 
          id: generateId(), 
          imageUrl: pendingQuestion.imageUrl, 
          location: pendingQuestion.location,
          title: `Spot ${questions.length + 1}` 
        }]);
      }
      setPendingQuestion(null);
    }
  };

  const startEditingQuestion = (q: Question) => {
    setPendingQuestion({
      imageUrl: q.imageUrl,
      location: q.location,
      originalLocation: q.location,
      editingId: q.id,
      title: q.title
    });
  };

  const deleteQuestion = (q: Question) => {
    if (window.confirm(`Are you sure you want to delete "${q.title || 'this spot'}"?`)) {
      setQuestions(qs => qs.filter(item => item.id !== q.id));
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const newQuestions = [...questions];
    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= questions.length) return;
    [newQuestions[index], newQuestions[newIndex]] = [newQuestions[newIndex], newQuestions[index]];
    setQuestions(newQuestions);
  };

  const updateQuestionTitle = (id: string, title: string) => {
    setQuestions(qs => qs.map(q => q.id === id ? { ...q, title } : q));
  };

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur sticky top-0 z-50">
          <h2 className="text-xl font-black uppercase tracking-widest">{pendingQuestion.editingId ? 'Edit Location' : 'Pin Location'}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold hover:text-white px-4 py-2">Cancel</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto scroll-smooth-touch pb-20">
          <div className="w-full md:w-1/2 p-4 flex items-center justify-center bg-black min-h-[40vh]">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="w-full md:w-1/2 p-4 md:p-8 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-5 rounded-2xl flex justify-between items-center">
               <div>
                 <p className="text-xs font-black text-indigo-400 uppercase tracking-widest">Adjust Spot</p>
                 <p className="text-sm text-slate-300">Drag marker or tap map to set the exact spot.</p>
               </div>
               <button 
                  onClick={() => setPendingQuestion({ ...pendingQuestion, location: pendingQuestion.originalLocation })}
                  className="text-[10px] bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg font-black uppercase tracking-tighter transition-colors"
                >
                  Reset Marker
                </button>
             </div>

             <div className="h-[350px] md:flex-1 min-h-[350px] rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion({ ...pendingQuestion, location: loc })}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>

             <button onClick={confirmPending} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all">
               Finalize Location
             </button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/40 to-transparent">
          <button onClick={stopCamera} className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center backdrop-blur-xl border border-white/20">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-16 h-16 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-14 h-14" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-4">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Name your trail..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Sites Tagged</p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 hover:bg-slate-800 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800">Cancel</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4 space-y-4 overflow-y-auto pb-32">
        <div className="grid grid-cols-2 gap-3">
          <button onClick={startCamera} className="flex items-center justify-center space-x-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-4 px-4 rounded-2xl transition-all group">
            <svg className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            <span className="font-bold text-sm">Capture</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center space-x-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-4 px-4 rounded-2xl transition-all group">
            <svg className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
            <span className="font-bold text-sm">Upload</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-3">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/50 rounded-2xl border border-slate-800/60 p-3 flex items-center space-x-3 hover:border-slate-700 transition-colors">
              <div className="w-16 h-16 rounded-xl overflow-hidden shrink-0 border border-slate-800">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
              </div>

              <div className="flex-1 min-w-0">
                <input 
                  type="text" 
                  value={q.title || ''} 
                  onChange={(e) => updateQuestionTitle(q.id, e.target.value)}
                  className="bg-transparent border-none p-0 text-sm font-black focus:ring-0 w-full mb-1"
                />
                <button 
                  onClick={() => startEditingQuestion(q)}
                  className="flex items-center text-[10px] text-indigo-400 font-black uppercase tracking-widest hover:text-indigo-300 transition-colors"
                >
                  <svg className="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  Edit Location
                </button>
              </div>

              <div className="flex flex-col space-y-1">
                <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" clipRule="evenodd" /></svg></button>
                <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg></button>
              </div>

              <button onClick={() => deleteQuestion(q)} className="p-2 text-slate-500 hover:text-red-500 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <div className="max-w-4xl mx-auto">
          <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 text-white' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
        </div>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/60 backdrop-blur flex items-center justify-center p-6">
          <div className="bg-slate-900 p-8 rounded-3xl flex flex-col items-center space-y-4 border border-slate-800 shadow-2xl max-w-xs w-full text-center">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs">Analyzing Metadata...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreator;

import React, { useState, useEffect } from 'react';
import { User, Trail } from '../types';

interface DashboardProps {
  user: User;
  onNewTrail: () => void;
  onEditTrail: (trail: Trail) => void;
  onHostTrail: (trail: Trail) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onNewTrail, onEditTrail, onHostTrail, onLogout }) => {
  const [trails, setTrails] = useState<Trail[]>([]);

  useEffect(() => {
    const saved = localStorage.getItem(`trails_${user.id}`);
    if (saved) {
      setTrails(JSON.parse(saved).sort((a: Trail, b: Trail) => b.lastUpdated - a.lastUpdated));
    }
  }, [user.id]);

  const deleteTrail = (trail: Trail) => {
    if (window.confirm(`Are you sure you want to delete the trail "${trail.name || 'Untitled Trail'}" and all its locations?`)) {
      const updated = trails.filter(t => t.id !== trail.id);
      setTrails(updated);
      localStorage.setItem(`trails_${user.id}`, JSON.stringify(updated));
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 flex flex-col">
      <header className="max-w-4xl w-full mx-auto flex justify-between items-center py-8">
        <div>
          <h1 className="text-3xl font-black tracking-tight">Your Trails</h1>
          <p className="text-slate-400">Welcome back, {user.username}</p>
        </div>
        <button onClick={onLogout} className="text-xs font-bold text-red-400 uppercase tracking-widest hover:text-red-300">Logout</button>
      </header>

      <main className="max-w-4xl w-full mx-auto flex-1 flex flex-col space-y-8 pb-12">
        <button 
          onClick={onNewTrail}
          className="w-full p-8 rounded-[2rem] border-2 border-dashed border-slate-800 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all flex flex-col items-center justify-center space-y-4 group"
        >
          <div className="w-16 h-16 rounded-2xl bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform shadow-xl">
             <svg className="w-8 h-8 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </div>
          <span className="text-lg font-bold">Design New Trail</span>
        </button>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 scroll-smooth-touch overflow-y-auto pr-2">
          {trails.map(trail => (
            <div key={trail.id} className="bg-slate-900 rounded-3xl p-6 border border-slate-800 shadow-xl flex flex-col space-y-6">
              <div className="flex justify-between items-start">
                <div className="flex-1 mr-2 flex flex-col">
                  <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-1">Trail #{trail.id}</span>
                  <h3 className="text-xl font-bold leading-tight truncate">{trail.name || "Untitled Trail"}</h3>
                  <span className="text-xs text-slate-500 mt-1">{trail.questions.length} locations marked</span>
                </div>
                <button onClick={() => deleteTrail(trail)} className="text-slate-600 hover:text-red-500 transition-colors shrink-0">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </div>

              <div className="flex gap-3">
                <button 
                  onClick={() => onHostTrail(trail)}
                  className="flex-1 bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3 rounded-xl transition-all shadow-lg shadow-indigo-900/20"
                >
                  Start Game
                </button>
                <button 
                  onClick={() => onEditTrail(trail)}
                  className="flex-1 bg-slate-800 hover:bg-slate-700 text-white font-bold py-3 rounded-xl transition-all"
                >
                  Edit
                </button>
              </div>
            </div>
          ))}
        </div>

        {trails.length === 0 && (
          <div className="flex-1 flex flex-col items-center justify-center py-20 opacity-30 text-center">
            <svg className="w-16 h-16 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg>
            <p>No trails yet. Go exploring!</p>
          </div>
        )}
      </main>
    </div>
  );
};

