import React, { useState, useEffect } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        setGameState(event.data.state);
        if (event.data.state.status === 'PLAYING') setView('PLAYING');
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, []);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    const key = `trails_${user.id}`;
    const saved = localStorage.getItem(key);
    let trails: Trail[] = saved ? JSON.parse(saved) : [];
    const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

    if (existingIndex > -1) {
      trails[existingIndex] = trailToSave;
    } else {
      trails.push(trailToSave);
    }

    localStorage.setItem(key, JSON.stringify(trails));
    setEditingTrail(null);
    setView('DASHBOARD');
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const newPlayer: Player = { id: generateId(), name, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. The host must have the lobby open in another tab for this demo.");
    }
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => setView('DASHBOARD')} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) newState.status = 'RESULTS';
        updateGameState(newState);
      }} 
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-950">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-slate-400 hover:text-indigo-400 flex items-center font-medium">
           <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
           Back
        </button>
        <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl border border-slate-800">
          <h2 className="text-3xl font-black text-white mb-6 text-center">Join Expedition</h2>
          <div className="space-y-4">
            <input id="gameCode" placeholder="GAME CODE" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl text-white" />
            <input id="playerName" placeholder="YOUR NAME" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white" />
            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl shadow-lg transition-all active:scale-95 text-lg">
              Join Lobby
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 overflow-hidden flex flex-col">
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col md:flex-row items-center relative py-12 px-8">
        <div className="absolute top-1/2 left-1/4 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-600/10 blur-[150px] rounded-full pointer-events-none"></div>

        <div className="w-full md:w-1/2 space-y-8 text-center md:text-left z-10">
          <div className="relative flex flex-col items-center md:items-start select-none">
            <div className="orbit-stage">
               <div className="orbit-center">&</div>
               <div className="orbit-carousel">
                  <div className="orbiting-word here text-6xl md:text-8xl">HERE</div>
                  <div className="orbiting-word there text-6xl md:text-8xl">THERE</div>
               </div>
            </div>
            <div className="text-indigo-400 font-black tracking-[0.5em] text-sm md:text-lg mt-4 uppercase glow-indigo">The Quest</div>
          </div>

          <p className="text-xl text-slate-400 max-w-md mx-auto md:mx-0 leading-relaxed font-light">
            Capture your neighborhood. Challenge your friends to find the exact spot where you stood.
          </p>

          <div className="flex flex-col sm:flex-row gap-5 pt-4">
            <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-2xl hover:bg-indigo-500 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              Design a Trail
            </button>
            <button onClick={() => setView('JOIN')} className="px-10 py-5 bg-slate-900 text-white border border-slate-800 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              Join the Quest
            </button>
          </div>
        </div>

        <div className="w-full md:w-1/2 mt-20 md:mt-0 flex items-center justify-center">
           <div className="relative w-full max-w-sm aspect-[4/5] bg-slate-900 rounded-[4rem] border border-slate-800 p-5 shadow-2xl rotate-3">
              <div className="w-full h-full rounded-[3rem] overflow-hidden border-4 border-slate-800">
                 <img src="https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover grayscale opacity-50 hover:grayscale-0 transition-all duration-700" />
              </div>
              <div className="absolute -bottom-8 -left-8 w-28 h-28 bg-indigo-600 rounded-[2rem] shadow-2xl flex items-center justify-center -rotate-12 border-4 border-slate-950">
                 <svg className="w-14 h-14 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
           </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT',
    editingId?: string,
    title?: string 
  } | null>(null);

  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          if (!isNaN(lat) && !isNaN(lng)) {
            setCurrentLocation({ lat, lng });
          }
        },
        (err) => { console.warn("GPS Access Denied/Error:", err); },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = { video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(() => setError("Camera failed to start."));
        }
      }, 300);
    } catch (err) { setError("Unable to access camera."); }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current || videoRef.current.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    if (context) {
      const scale = Math.min(1, 1024 / videoRef.current.videoWidth);
      canvas.width = videoRef.current.videoWidth * scale;
      canvas.height = videoRef.current.videoHeight * scale;
      try {
        context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.8);
        const loc = (currentLocation && !isNaN(currentLocation.lat)) ? currentLocation : { lat: 51.505, lng: -0.09 };
        const source = currentLocation ? 'GPS' : 'DEFAULT';

        setTimeout(() => {
          setPendingQuestion({ imageUrl, location: loc, originalLocation: loc, source });
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) { 
        setIsProcessing(false); 
        setError("Capture failed."); 
      }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const imageUrl = event.target?.result as string;
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          // Better decimal extraction
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = tags.GPSLatitude.description;
            const parsedLng = tags.GPSLongitude.description;

            // Check if description is already a decimal
            const dLat = parseFloat(parsedLat);
            const dLng = parseFloat(parsedLng);

            if (!isNaN(dLat) && !isNaN(dLng)) {
              lat = dLat;
              lng = dLng;
              source = 'IMAGE';
            }
          }
        } catch (exifErr) { 
          console.warn("Metadata extraction failed. Likely stripped by browser.", exifErr); 
        }

        const finalLoc = (lat !== null && lng !== null) 
          ? { lat, lng } 
          : (currentLocation || { lat: 51.505, lng: -0.09 });

        if (source === 'GPS' && !currentLocation) source = 'DEFAULT';

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError("Upload failed."); 
    }
  };

  const confirmPending = () => {
    if (pendingQuestion) {
      if (pendingQuestion.editingId) {
        setQuestions(qs => qs.map(q => q.id === pendingQuestion.editingId ? { 
          ...q, 
          location: pendingQuestion.location,
          imageUrl: pendingQuestion.imageUrl,
          title: pendingQuestion.title || q.title 
        } : q));
      } else {
        setQuestions([...questions, { 
          id: generateId(), 
          imageUrl: pendingQuestion.imageUrl, 
          location: pendingQuestion.location,
          title: `Spot ${questions.length + 1}` 
        }]);
      }
      setPendingQuestion(null);
    }
  };

  const startEditingQuestion = (q: Question) => {
    setPendingQuestion({
      imageUrl: q.imageUrl,
      location: q.location,
      originalLocation: q.location,
      editingId: q.id,
      title: q.title,
      source: 'IMAGE' // Existing entries are treated as image-locked
    });
  };

  const deleteQuestion = (q: Question) => {
    if (window.confirm(`Are you sure you want to delete "${q.title || 'this spot'}"?`)) {
      setQuestions(qs => qs.filter(item => item.id !== q.id));
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const newQuestions = [...questions];
    const newIndex = direction === 'up' ? index - 1 : index + 1;
    if (newIndex < 0 || newIndex >= questions.length) return;
    [newQuestions[index], newQuestions[newIndex]] = [newQuestions[newIndex], newQuestions[index]];
    setQuestions(newQuestions);
  };

  const updateQuestionTitle = (id: string, title: string) => {
    setQuestions(qs => qs.map(q => q.id === id ? { ...q, title } : q));
  };

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur sticky top-0 z-50 border-b border-slate-800">
          <h2 className="text-xl font-black uppercase tracking-widest">{pendingQuestion.editingId ? 'Edit Location' : 'Confirm Spot'}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold hover:text-white px-4 py-2">Cancel</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto scroll-smooth-touch pb-20">
          <div className="w-full md:w-1/2 p-4 flex items-center justify-center bg-black min-h-[35vh]">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="w-full md:w-1/2 p-4 md:p-8 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-5 rounded-2xl">
               <div className="flex justify-between items-start mb-2">
                 <div>
                    <p className="text-xs font-black text-indigo-400 uppercase tracking-widest">Verification</p>
                    <p className="text-sm text-slate-300">Tap map or drag marker to correct the position.</p>
                 </div>
                 {pendingQuestion.source === 'IMAGE' && <span className="text-[10px] bg-green-500/20 text-green-400 border border-green-500/30 px-2 py-1 rounded font-black uppercase">From Metadata</span>}
                 {pendingQuestion.source === 'GPS' && <span className="text-[10px] bg-blue-500/20 text-blue-400 border border-blue-500/30 px-2 py-1 rounded font-black uppercase">From Live GPS</span>}
               </div>
               <button 
                  onClick={() => setPendingQuestion({ ...pendingQuestion, location: pendingQuestion.originalLocation })}
                  className="text-[10px] bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg font-black uppercase tracking-tighter transition-colors w-full"
                >
                  Reset to initial spot
                </button>
             </div>

             <div className="h-[300px] md:flex-1 min-h-[300px] rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion({ ...pendingQuestion, location: loc })}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>

             <button onClick={confirmPending} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all">
               Lock in Location
             </button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/40 to-transparent">
          <button onClick={stopCamera} className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center backdrop-blur-xl border border-white/20">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-16 h-16 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-14 h-14" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-4">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Name your trail..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Sites Tagged</p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 hover:bg-slate-800 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800">Cancel</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4 space-y-4 overflow-y-auto pb-32">
        {error && <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-sm font-bold text-center">{error}</div>}

        <div className="grid grid-cols-2 gap-3">
          <button onClick={startCamera} className="flex items-center justify-center space-x-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-4 px-4 rounded-2xl transition-all group">
            <svg className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            <span className="font-bold text-sm">Capture</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center space-x-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-4 px-4 rounded-2xl transition-all group">
            <svg className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
            <span className="font-bold text-sm">Upload</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-3">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/50 rounded-2xl border border-slate-800/60 p-3 flex items-center space-x-3 hover:border-slate-700 transition-colors">
              <div className="w-16 h-16 rounded-xl overflow-hidden shrink-0 border border-slate-800">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
              </div>

              <div className="flex-1 min-w-0">
                <input 
                  type="text" 
                  value={q.title || ''} 
                  onChange={(e) => updateQuestionTitle(q.id, e.target.value)}
                  className="bg-transparent border-none p-0 text-sm font-black focus:ring-0 w-full mb-1"
                />
                <button 
                  onClick={() => startEditingQuestion(q)}
                  className="flex items-center text-[10px] text-indigo-400 font-black uppercase tracking-widest hover:text-indigo-300 transition-colors"
                >
                  <svg className="w-3 h-3 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
                  Edit Location
                </button>
              </div>

              <div className="flex flex-col space-y-1">
                <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" clipRule="evenodd" /></svg></button>
                <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg></button>
              </div>

              <button onClick={() => deleteQuestion(q)} className="p-2 text-slate-500 hover:text-red-500 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <div className="max-w-4xl mx-auto">
          <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 text-white active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
        </div>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/60 backdrop-blur flex items-center justify-center p-6">
          <div className="bg-slate-900 p-8 rounded-3xl flex flex-col items-center space-y-4 border border-slate-800 shadow-2xl max-w-xs w-full text-center">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs">Analyzing Image Meta...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreator;

export interface Location {
  lat: number;
  lng: number;
}

export interface User {
  username: string;
  id: string;
}

export interface Question {
  id: string;
  imageUrl: string;
  location: Location;
  title?: string;
  locationSource?: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL';
}

export interface Trail {
  id: string;
  name: string;
  questions: Question[];
  creatorId: string;
  lastUpdated: number;
}

export interface Player {
  id: string;
  name: string;
  score: number;
  lastGuess?: Location;
  lastDistance?: number;
  hasGuessed: boolean;
}

export interface GameState {
  id: string;
  status: 'LOBBY' | 'PLAYING' | 'RESULTS' | 'FINISHED';
  questions: Question[];
  currentQuestionIndex: number;
  players: Player[];
  hostId: string;
}

export type AppView = 'HOME' | 'AUTH' | 'DASHBOARD' | 'CREATE' | 'LOBBY' | 'PLAYING' | 'JOIN';

import React, { useState, useRef, useEffect } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const [error, setError] = useState<string | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          if (!isNaN(lat) && !isNaN(lng)) {
            setCurrentLocation({ lat, lng });
          }
        },
        (err) => { console.warn("GPS Access Error:", err); },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = { video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } } };
      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(() => setError("Camera failed to start."));
        }
      }, 300);
    } catch (err) { setError("Unable to access camera."); }
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current || videoRef.current.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    if (context) {
      const scale = Math.min(1, 1024 / videoRef.current.videoWidth);
      canvas.width = videoRef.current.videoWidth * scale;
      canvas.height = videoRef.current.videoHeight * scale;
      try {
        context.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.8);
        const loc = (currentLocation && !isNaN(currentLocation.lat)) ? currentLocation : { lat: 51.505, lng: -0.09 };
        const source = currentLocation ? 'GPS' : 'DEFAULT';

        setTimeout(() => {
          setPendingQuestion({ imageUrl, location: loc, originalLocation: loc, source });
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) { 
        setIsProcessing(false); 
        setError("Capture failed."); 
      }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const imageUrl = event.target?.result as string;
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = tags.GPSLatitude.description;
            const parsedLng = tags.GPSLongitude.description;
            const dLat = parseFloat(parsedLat);
            const dLng = parseFloat(parsedLng);

            if (!isNaN(dLat) && !isNaN(dLng)) {
              lat = dLat;
              lng = dLng;
              source = 'IMAGE';
            }
          }
        } catch (exifErr) { 
          console.warn("Metadata extraction failed.", exifErr); 
        }

        if (source !== 'IMAGE') {
            source = currentLocation ? 'GPS' : 'DEFAULT';
        }

        const finalLoc = (lat !== null && lng !== null) 
          ? { lat, lng } 
          : (currentLocation || { lat: 51.505, lng: -0.09 });

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError("Upload failed."); 
    }
  };

  const confirmPending = () => {
    if (pendingQuestion) {
      // If user moved the marker, we mark it as Manual
      const finalSource = (pendingQuestion.location.lat !== pendingQuestion.originalLocation.lat || 
                           pendingQuestion.location.lng !== pendingQuestion.originalLocation.lng) 
                           ? 'MANUAL' : pendingQuestion.source;

      if (pendingQuestion.editingId) {
        setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
          ...q, 
          location: pendingQuestion.location,
          imageUrl: pendingQuestion.imageUrl,
          locationSource: finalSource,
          title: pendingQuestion.title || q.title 
        } : q));
      } else {
        setQuestions(prev => [...prev, { 
          id: generateId(), 
          imageUrl: pendingQuestion.imageUrl, 
          location: pendingQuestion.location,
          locationSource: finalSource,
          title: `Spot ${prev.length + 1}` 
        }]);
      }
      setPendingQuestion(null);
    }
  };

  const startEditingQuestion = (q: Question) => {
    setPendingQuestion({
      imageUrl: q.imageUrl,
      location: q.location,
      originalLocation: q.location,
      editingId: q.id,
      title: q.title,
      source: q.locationSource || 'MANUAL'
    });
  };

  const deleteQuestion = (q: Question) => {
    const confirmation = window.confirm(`Are you sure you want to delete "${q.title || 'this spot'}"?`);
    if (confirmation) {
      setQuestions(prev => prev.filter(item => item.id !== q.id));
    }
  };

  const stopCamera = () => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
        const newQuestions = [...prev];
        const newIndex = direction === 'up' ? index - 1 : index + 1;
        if (newIndex < 0 || newIndex >= newQuestions.length) return prev;
        [newQuestions[index], newQuestions[newIndex]] = [newQuestions[newIndex], newQuestions[index]];
        return newQuestions;
    });
  };

  const updateQuestionTitle = (id: string, title: string) => {
    setQuestions(prev => prev.map(q => q.id === id ? { ...q, title } : q));
  };

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur sticky top-0 z-50 border-b border-slate-800">
          <h2 className="text-xl font-black uppercase tracking-widest">{pendingQuestion.editingId ? 'Edit Location' : 'Confirm Spot'}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold hover:text-white px-4 py-2">Cancel</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto scroll-smooth-touch pb-20">
          <div className="w-full md:w-1/2 p-4 flex items-center justify-center bg-black min-h-[35vh]">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="w-full md:w-1/2 p-4 md:p-8 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-5 rounded-2xl">
               <div className="flex justify-between items-start mb-2">
                 <div>
                    <p className="text-xs font-black text-indigo-400 uppercase tracking-widest">Pin Precision</p>
                    <p className="text-sm text-slate-300">Tap map or drag marker to set the spot.</p>
                 </div>
                 {pendingQuestion.source === 'IMAGE' && <span className="text-[10px] bg-green-500/20 text-green-400 border border-green-500/30 px-2 py-1 rounded font-black uppercase shrink-0">Image Data</span>}
                 {pendingQuestion.source === 'GPS' && <span className="text-[10px] bg-blue-500/20 text-blue-400 border border-blue-500/30 px-2 py-1 rounded font-black uppercase shrink-0">Live GPS</span>}
                 {pendingQuestion.source === 'MANUAL' && <span className="text-[10px] bg-indigo-500/20 text-indigo-400 border border-indigo-500/30 px-2 py-1 rounded font-black uppercase shrink-0">Manual Pin</span>}
               </div>
               <button 
                  onClick={() => setPendingQuestion({ ...pendingQuestion, location: pendingQuestion.originalLocation })}
                  className="text-[10px] bg-slate-800 hover:bg-slate-700 px-3 py-1.5 rounded-lg font-black uppercase tracking-tighter transition-colors w-full mt-2"
                >
                  Reset to Initial Position
                </button>
             </div>

             <div className="h-[300px] md:flex-1 min-h-[300px] rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion({ ...pendingQuestion, location: loc })}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>

             <button onClick={confirmPending} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all">
               Finalize Spot
             </button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/40 to-transparent">
          <button onClick={stopCamera} className="w-14 h-14 rounded-full bg-white/10 flex items-center justify-center backdrop-blur-xl border border-white/20">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-16 h-16 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-14 h-14" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-4">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Name your trail..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Sites Tagged</p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 hover:bg-slate-800 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800">Cancel</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4 space-y-4 overflow-y-auto pb-32">
        {error && <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-sm font-bold text-center">{error}</div>}

        <div className="grid grid-cols-2 gap-3">
          <button onClick={startCamera} className="flex items-center justify-center space-x-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-4 px-4 rounded-2xl transition-all group">
            <svg className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            <span className="font-bold text-sm">Capture</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex items-center justify-center space-x-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-4 px-4 rounded-2xl transition-all group">
            <svg className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
            <span className="font-bold text-sm">Upload</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-3">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/50 rounded-2xl border border-slate-800/60 p-3 flex items-center space-x-3 hover:border-slate-700 transition-colors">
              <div className="w-16 h-16 rounded-xl overflow-hidden shrink-0 border border-slate-800">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
              </div>

              <div className="flex-1 min-w-0">
                <input 
                  type="text" 
                  value={q.title || ''} 
                  onChange={(e) => updateQuestionTitle(q.id, e.target.value)}
                  className="bg-transparent border-none p-0 text-sm font-black focus:ring-0 w-full mb-1"
                />
                <div className="flex items-center space-x-2">
                    <button 
                    onClick={() => startEditingQuestion(q)}
                    className="flex items-center text-[10px] text-indigo-400 font-black uppercase tracking-widest hover:text-indigo-300 transition-colors"
                    >
                        Edit Spot
                    </button>
                    {q.locationSource && (
                        <span className="text-[8px] opacity-40 uppercase font-black tracking-tighter">via {q.locationSource}</span>
                    )}
                </div>
              </div>

              <div className="flex flex-col space-y-1">
                <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" clipRule="evenodd" /></svg></button>
                <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 text-slate-500 hover:text-white disabled:opacity-20"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg></button>
              </div>

              <button onClick={() => deleteQuestion(q)} className="p-2 text-slate-500 hover:text-red-500 transition-colors">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
              </button>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <div className="max-w-4xl mx-auto">
          <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 text-white active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
        </div>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/60 backdrop-blur flex items-center justify-center p-6">
          <div className="bg-slate-900 p-8 rounded-3xl flex flex-col items-center space-y-4 border border-slate-800 shadow-2xl max-w-xs w-full text-center">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs">Analyzing Image Meta...</p>
          </div>
        </div>
      )}
    </div>
  );
};

