import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = createRoot(rootElement);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          if (!isNaN(lat) && !isNaN(lng)) {
            setCurrentLocation({ lat, lng });
          }
        },
        (err) => { console.warn("GPS Warning:", err.message); },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const stopCamera = useCallback(() => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const constraints = { 
        video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      };
      let stream: MediaStream;
      try {
        stream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (e) {
        // Fallback to any camera if environment camera fails (desktop)
        stream = await navigator.mediaDevices.getUserMedia({ video: true });
      }

      setIsCapturing(true);
      // Brief delay to ensure ref is attached
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(e => setError("Please tap to play camera."));
        }
      }, 100);
    } catch (err) { 
      setError("Camera access denied or unavailable."); 
    }
  };

  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas || video.readyState < 1) return;

    setIsProcessing(true);
    setIsFlashing(true);

    const context = canvas.getContext('2d');
    if (context) {
      const scale = Math.min(1, 1280 / video.videoWidth);
      canvas.width = video.videoWidth * scale;
      canvas.height = video.videoHeight * scale;

      try {
        context.drawImage(video, 0, 0, canvas.width, canvas.height);
        const imageUrl = canvas.toDataURL('image/jpeg', 0.85);
        const loc = (currentLocation && !isNaN(currentLocation.lat)) ? currentLocation : { lat: 51.505, lng: -0.09 };
        const source = currentLocation ? 'GPS' : 'DEFAULT';

        setTimeout(() => {
          setPendingQuestion({ imageUrl, location: loc, originalLocation: loc, source });
          setIsFlashing(false);
          setIsProcessing(false);
          stopCamera();
        }, 300);
      } catch (e) { 
        setIsProcessing(false); 
        setIsFlashing(false);
        setError("Failed to process snapshot."); 
      }
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const imageUrl = event.target?.result as string;
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = tags.GPSLatitude.description;
            const parsedLng = tags.GPSLongitude.description;
            const dLat = parseFloat(parsedLat);
            const dLng = parseFloat(parsedLng);

            if (!isNaN(dLat) && !isNaN(dLng)) {
              lat = dLat;
              lng = dLng;
              source = 'IMAGE';
            }
          }
        } catch (exifErr) { 
          console.warn("EXIF read error (stripped by browser):", exifErr); 
        }

        if (source !== 'IMAGE') {
          source = currentLocation ? 'GPS' : 'DEFAULT';
        }

        const finalLoc = (lat !== null && lng !== null) 
          ? { lat, lng } 
          : (currentLocation || { lat: 51.505, lng: -0.09 });

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError("File upload failed."); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;

    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;

    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, 
        location: pendingQuestion.location,
        imageUrl: pendingQuestion.imageUrl,
        locationSource: finalSource,
        title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), 
        imageUrl: pendingQuestion.imageUrl, 
        location: pendingQuestion.location,
        locationSource: finalSource,
        title: `Spot ${prev.length + 1}` 
      }]);
    }
    setPendingQuestion(null);
  };

  const startEditingQuestion = (q: Question) => {
    setPendingQuestion({
      imageUrl: q.imageUrl,
      location: q.location,
      originalLocation: q.location,
      editingId: q.id,
      title: q.title,
      source: q.locationSource || 'MANUAL'
    });
  };

  const deleteQuestion = (q: Question) => {
    if (window.confirm(`Delete "${q.title || 'this spot'}"?`)) {
      setQuestions(prev => prev.filter(item => item.id !== q.id));
    }
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
      const next = [...prev];
      const targetIdx = direction === 'up' ? index - 1 : index + 1;
      if (targetIdx < 0 || targetIdx >= next.length) return prev;
      [next[index], next[targetIdx]] = [next[targetIdx], next[index]];
      return next;
    });
  };

  const updateQuestionTitle = (id: string, title: string) => {
    setQuestions(prev => prev.map(q => q.id === id ? { ...q, title } : q));
  };

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur sticky top-0 z-50 border-b border-slate-800">
          <h2 className="text-xl font-black uppercase tracking-widest">{pendingQuestion.editingId ? 'Edit Location' : 'Tag Spot'}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold hover:text-white px-4 py-2">Back</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-20">
          <div className="w-full md:w-1/2 p-4 flex items-center justify-center bg-black min-h-[40vh]">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="w-full md:w-1/2 p-4 md:p-8 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-5 rounded-2xl">
               <div className="flex justify-between items-start">
                 <div className="flex-1 pr-2">
                    <p className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Positioning</p>
                    <p className="text-sm text-slate-300">Tap map to refine the spot.</p>
                 </div>
                 <div className="shrink-0 flex flex-col items-end">
                    {pendingQuestion.source === 'IMAGE' && <span className="text-[10px] bg-green-500/20 text-green-400 border border-green-500/30 px-2 py-1 rounded font-black uppercase mb-1">Image Metadata</span>}
                    {pendingQuestion.source === 'GPS' && <span className="text-[10px] bg-blue-500/20 text-blue-400 border border-blue-500/30 px-2 py-1 rounded font-black uppercase mb-1">Live Device GPS</span>}
                    {pendingQuestion.source === 'DEFAULT' && <span className="text-[10px] bg-amber-500/20 text-amber-400 border border-amber-500/30 px-2 py-1 rounded font-black uppercase mb-1">Approximate</span>}
                 </div>
               </div>
               <button onClick={() => setPendingQuestion({ ...pendingQuestion, location: pendingQuestion.originalLocation })} className="text-[10px] bg-slate-800 hover:bg-slate-700 px-3 py-2 rounded-lg font-black uppercase tracking-tighter w-full mt-4">Reset to Auto-detected</button>
             </div>
             <div className="h-[350px] md:flex-1 rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button onClick={confirmPending} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl shadow-2xl active:scale-95 transition-all">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center backdrop-blur-xl border border-white/20">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-4">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Trail Name..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Sites Added</p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 hover:bg-slate-800 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800">Exit</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4 space-y-4 overflow-y-auto pb-36">
        {error && <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-sm font-bold text-center mb-4">{error}</div>}

        <div className="grid grid-cols-2 gap-4 mb-8">
          <button onClick={startCamera} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-6 rounded-3xl transition-all group shadow-xl">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Take Photo</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 hover:bg-indigo-600/10 border border-slate-800 hover:border-indigo-500 py-6 rounded-3xl transition-all group shadow-xl">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Upload File</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
