        </div>

        <div className="space-y-3">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/60 backdrop-blur rounded-3xl border border-slate-800 p-4 flex items-center space-x-4">
              <div className="w-16 h-16 rounded-2xl overflow-hidden shrink-0 border border-slate-800 shadow-md">
                <img src={q.imageUrl} className="w-full h-full object-cover" />
              </div>

              <div className="flex-1 min-w-0">
                <input 
                  type="text" 
