                />
                <div className="flex items-center space-x-3">
                  <button onClick={() => startEditingQuestion(q)} className="text-[10px] text-indigo-400 font-black uppercase tracking-widest hover:text-indigo-300">Edit Pin</button>
                  {q.locationSource && <span className="text-[8px] opacity-40 uppercase font-black tracking-tighter">({q.locationSource})</span>}
                </div>
              </div>

              <div className="flex items-center space-x-2">
                <div className="flex flex-col space-y-1">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 text-slate-600 hover:text-white disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" clipRule="evenodd" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 text-slate-600 hover:text-white disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg></button>
                </div>
                <button onClick={() => deleteQuestion(q)} className="p-3 bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white rounded-2xl transition-all"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <div className="max-w-4xl mx-auto">
          <button 
            disabled={questions.length === 0} 
            onClick={() => onComplete(questions, trailName)} 
            className={`w-full py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 text-white active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}
          >
            Finalize Quest
          </button>
        </div>
      </footer>
      <canvas ref={canvasRef} className="hidden" />
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/70 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-slate-900 p-8 rounded-[2.5rem] flex flex-col items-center space-y-4 border border-slate-800 shadow-2xl text-center">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs text-indigo-400">Processing Media...</p>
          </div>
        </div>
      )}
    </div>
  );
};

