  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        },
        (err) => { console.warn("GPS Warning:", err.message); },
        { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const stopCamera = useCallback(() => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1280 } } 
      });
      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play();
        }
      }, 100);
    } catch (err) { 
      setError("Unable to access camera."); 
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;

    setIsProcessing(true);
    setIsFlashing(true);

    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');

    if (ctx) {
      ctx.drawImage(video, 0, 0);
      const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
      const compressedUrl = await compressImage(rawUrl);

      const loc = currentLocation || { lat: 51.505, lng: -0.09 };
      const source = currentLocation ? 'GPS' : 'DEFAULT';

      setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) { console.warn("EXIF read fail", exifErr); }

        if (source !== 'IMAGE') source = currentLocation ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError("Upload failed."); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001;
    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: `Spot ${prev.length + 1}` 
      }]);
    }
    setPendingQuestion(null);
  };

  const handleDelete = () => {
    if (confirmDelete) {
      setQuestions(prev => prev.filter(q => q.id !== confirmDelete));
      setConfirmDelete(null);
    }
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
      const next = [...prev];
      const targetIdx = direction === 'up' ? index - 1 : index + 1;
      if (targetIdx < 0 || targetIdx >= next.length) return prev;
      [next[index], next[targetIdx]] = [next[targetIdx], next[index]];
      return next;
    });
  };

  if (confirmDelete) {
    return (
      <div className="fixed inset-0 z-[400] bg-slate-950/90 backdrop-blur-sm flex items-center justify-center p-6">
        <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] w-full max-w-sm text-center shadow-2xl">
          <div className="w-16 h-16 bg-red-500/10 text-red-500 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </div>
          <h3 className="text-xl font-bold mb-2">Delete this spot?</h3>
          <p className="text-slate-400 text-sm mb-8">This action cannot be undone. The location data will be lost.</p>
          <div className="flex gap-4">
            <button onClick={() => setConfirmDelete(null)} className="flex-1 py-3 bg-slate-800 rounded-xl font-bold">Cancel</button>
            <button onClick={handleDelete} className="flex-1 py-3 bg-red-600 rounded-xl font-bold">Delete</button>
          </div>
        </div>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur sticky top-0 z-50 border-b border-slate-800">
          <h2 className="text-xl font-black uppercase tracking-widest">{pendingQuestion.editingId ? 'Edit' : 'Tag'} Spot</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold px-4 py-2">Back</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-20">
          <div className="w-full md:w-1/2 p-4 flex items-center justify-center bg-black min-h-[40vh]">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="w-full md:w-1/2 p-4 md:p-8 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-5 rounded-2xl flex justify-between items-start">
                <div className="flex-1 pr-2">
                    <p className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Verify Location</p>
                    <p className="text-sm text-slate-300">Tap map to refine the pinpoint.</p>
                </div>
                <span className="text-[10px] bg-slate-800 px-2 py-1 rounded font-black uppercase shrink-0">{pendingQuestion.source}</span>
             </div>
             <div className="h-[350px] md:flex-1 rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button onClick={confirmPending} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl active:scale-95 transition-all">Confirm Pin</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-4">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Trail Name..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Spots Added</p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800">Exit</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4 space-y-4 overflow-y-auto pb-36">
        {error && <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-sm font-bold text-center mb-4">{error}</div>}

        <div className="grid grid-cols-2 gap-4">
          <button onClick={startCamera} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 border border-slate-800 hover:border-indigo-500 py-8 rounded-3xl transition-all group">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Take Photo</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 border border-slate-800 hover:border-indigo-500 py-8 rounded-3xl transition-all group">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Upload Image</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-3 mt-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/60 backdrop-blur rounded-3xl border border-slate-800 p-4 flex items-center space-x-4">
              <img src={q.imageUrl} className="w-16 h-16 rounded-2xl object-cover border border-slate-800 shadow-md" />
              <div className="flex-1 min-w-0">
                <input type="text" value={q.title || ''} onChange={(e) => setQuestions(prev => prev.map(item => item.id === q.id ? { ...item, title: e.target.value } : item))} className="bg-transparent border-none p-0 text-base font-bold focus:ring-0 w-full mb-1" />
                <button onClick={() => setPendingQuestion({ imageUrl: q.imageUrl, location: q.location, originalLocation: q.location, editingId: q.id, title: q.title, source: q.locationSource || 'MANUAL' })} className="text-[10px] text-indigo-400 font-black uppercase tracking-widest">Edit Pin</button>
              </div>
              <div className="flex items-center space-x-2">
                <div className="flex flex-col">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 text-slate-600 disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 text-slate-600 disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
                <button onClick={() => setConfirmDelete(q.id)} className="p-3 bg-red-500/10 text-red-500 rounded-2xl"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full max-w-4xl mx-auto block py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 text-white active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
      </footer>
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/70 backdrop-blur-md flex items-center justify-center p-6 text-center">
          <div className="bg-slate-900 p-8 rounded-[2.5rem] flex flex-col items-center space-y-4 border border-slate-800">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs text-indigo-400">Optimizing Media...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreator;

import React, { useState, useEffect } from 'react';
import { User, Trail } from '../types';

interface DashboardProps {
  user: User;
  onNewTrail: () => void;
  onEditTrail: (trail: Trail) => void;
  onHostTrail: (trail: Trail) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onNewTrail, onEditTrail, onHostTrail, onLogout }) => {
  const [trails, setTrails] = useState<Trail[]>([]);
  const [trailToDelete, setTrailToDelete] = useState<Trail | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem(`trails_${user.id}`);
    if (saved) {
      setTrails(JSON.parse(saved).sort((a: Trail, b: Trail) => b.lastUpdated - a.lastUpdated));
    }
  }, [user.id]);

  const confirmDelete = () => {
    if (trailToDelete) {
      const updated = trails.filter(t => t.id !== trailToDelete.id);
      setTrails(updated);
      localStorage.setItem(`trails_${user.id}`, JSON.stringify(updated));
      setTrailToDelete(null);
    }
  };

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 flex flex-col">
      {trailToDelete && (
        <div className="fixed inset-0 z-[500] bg-slate-950/90 backdrop-blur-sm flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] w-full max-w-sm text-center shadow-2xl">
            <div className="w-16 h-16 bg-red-500/10 text-red-500 rounded-2xl flex items-center justify-center mx-auto mb-6">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </div>
            <h3 className="text-xl font-bold mb-2">Delete Trail?</h3>
            <p className="text-slate-400 text-sm mb-8">Delete "{trailToDelete.name}" and all {trailToDelete.questions.length} locations forever?</p>
            <div className="flex gap-4">
              <button onClick={() => setTrailToDelete(null)} className="flex-1 py-3 bg-slate-800 rounded-xl font-bold">Cancel</button>
              <button onClick={confirmDelete} className="flex-1 py-3 bg-red-600 rounded-xl font-bold">Delete</button>
            </div>
          </div>
        </div>
      )}

      <header className="max-w-4xl w-full mx-auto flex justify-between items-center py-8">
        <div>
          <h1 className="text-3xl font-black tracking-tight">Your Trails</h1>
          <p className="text-slate-400">Hello, {user.username}</p>
        </div>
        <button onClick={onLogout} className="text-xs font-bold text-red-400 uppercase tracking-widest">Logout</button>
      </header>

      <main className="max-w-4xl w-full mx-auto flex-1 flex flex-col space-y-8 pb-12">
        <button 
          onClick={onNewTrail}
          className="w-full p-8 rounded-[2rem] border-2 border-dashed border-slate-800 hover:border-indigo-500 hover:bg-indigo-500/5 transition-all flex flex-col items-center justify-center space-y-4 group"
        >
          <div className="w-16 h-16 rounded-2xl bg-slate-900 flex items-center justify-center group-hover:scale-110 transition-transform">
             <svg className="w-8 h-8 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </div>
          <span className="text-lg font-bold">Design New Trail</span>
        </button>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {trails.map(trail => (
            <div key={trail.id} className="bg-slate-900 rounded-3xl p-6 border border-slate-800 shadow-xl flex flex-col space-y-6">
              <div className="flex justify-between items-start">
                <div className="flex-1 min-w-0">
                  <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Trail ID: {trail.id}</span>
                  <h3 className="text-xl font-bold truncate">{trail.name || "Untitled Trail"}</h3>
                  <span className="text-xs text-slate-500">{trail.questions.length} spots marked</span>
                </div>
                <button onClick={() => setTrailToDelete(trail)} className="text-slate-600 hover:text-red-500 transition-colors">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </div>

              <div className="flex gap-3">
                <button onClick={() => onHostTrail(trail)} className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-lg">Start Game</button>
                <button onClick={() => onEditTrail(trail)} className="flex-1 bg-slate-800 text-white font-bold py-3 rounded-xl">Edit</button>
              </div>
            </div>
          ))}
        </div>

        {trails.length === 0 && (
          <div className="flex-1 flex flex-col items-center justify-center py-20 opacity-30 text-center">
            <svg className="w-16 h-16 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg>
            <p>No trails found. Start exploring!</p>
          </div>
        )}
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        setGameState(event.data.state);
        if (event.data.state.status === 'PLAYING') setView('PLAYING');
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, []);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

      if (existingIndex > -1) {
        trails[existingIndex] = trailToSave;
      } else {
        trails.push(trailToSave);
      }

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      console.error("Save failed:", e);
      alert("Storage limit reached! Try removing some old trails or using fewer/smaller photos.");
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const newPlayer: Player = { id: generateId(), name, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. The host must have the lobby open in another tab for this demo.");
    }
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => setView('DASHBOARD')} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) newState.status = 'RESULTS';
        updateGameState(newState);
      }} 
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-950">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-slate-400 hover:text-indigo-400 flex items-center font-medium">
           <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
           Back
        </button>
        <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl border border-slate-800">
          <h2 className="text-3xl font-black text-white mb-6 text-center">Join Expedition</h2>
          <div className="space-y-4">
            <input id="gameCode" placeholder="GAME CODE" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl text-white" />
            <input id="playerName" placeholder="YOUR NAME" className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white" />
            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl shadow-lg transition-all active:scale-95 text-lg">
              Join Lobby
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 overflow-hidden flex flex-col">
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col md:flex-row items-center relative py-12 px-8">
        <div className="absolute top-1/2 left-1/4 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-600/10 blur-[150px] rounded-full pointer-events-none"></div>

        <div className="w-full md:w-1/2 space-y-8 text-center md:text-left z-10">
          <div className="relative flex flex-col items-center md:items-start select-none">
            <div className="orbit-stage">
               <div className="orbit-center">&</div>
               <div className="orbit-carousel">
                  <div className="orbiting-word here text-6xl md:text-8xl">HERE</div>
                  <div className="orbiting-word there text-6xl md:text-8xl">THERE</div>
               </div>
            </div>
            <div className="text-indigo-400 font-black tracking-[0.5em] text-sm md:text-lg mt-4 uppercase glow-indigo">The Quest</div>
          </div>

          <p className="text-xl text-slate-400 max-w-md mx-auto md:mx-0 leading-relaxed font-light">
            Capture your neighborhood. Challenge your friends to find the exact spot where you stood.
          </p>

          <div className="flex flex-col sm:flex-row gap-5 pt-4">
            <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-2xl hover:bg-indigo-500 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              Design a Trail
            </button>
            <button onClick={() => setView('JOIN')} className="px-10 py-5 bg-slate-900 text-white border border-slate-800 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              Join the Quest
            </button>
          </div>
        </div>

        <div className="w-full md:w-1/2 mt-20 md:mt-0 flex items-center justify-center">
           <div className="relative w-full max-w-sm aspect-[4/5] bg-slate-900 rounded-[4rem] border border-slate-800 p-5 shadow-2xl rotate-3">
              <div className="w-full h-full rounded-[3rem] overflow-hidden border-4 border-slate-800">
                 <img src="https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover grayscale opacity-50 hover:grayscale-0 transition-all duration-700" />
              </div>
              <div className="absolute -bottom-8 -left-8 w-28 h-28 bg-indigo-600 rounded-[2rem] shadow-2xl flex items-center justify-center -rotate-12 border-4 border-slate-950">
                 <svg className="w-14 h-14 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
           </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          if (!isNaN(lat) && !isNaN(lng)) {
            setCurrentLocation({ lat, lng });
          }
        },
        (err) => { console.warn("GPS Access Failed:", err.message); },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const stopCamera = useCallback(() => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1920 } } 
      });
      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          const playPromise = videoRef.current.play();
          if (playPromise !== undefined) {
             playPromise.catch(() => { /* Auto-play handled */ });
          }
        }
      }, 100);
    } catch (err) { 
      setError("Unable to access camera. Check permissions."); 
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;

    setIsProcessing(true);
    setIsFlashing(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);

        // Fallback sequence: Live GPS -> Default London
        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = currentLocation ? 'GPS' : 'DEFAULT';

        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } catch (e) {
      setError("Failed to process photo capture.");
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = parseFloat(tags.GPSLatitude.description);
            const parsedLng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
              lat = parsedLat;
              lng = parsedLng;
              source = 'IMAGE';
            }
          }
        } catch (exifErr) { console.warn("EXIF extraction failed:", exifErr); }

        // Logic check: if IMAGE data failed, fall back to GPS/Default
        if (source !== 'IMAGE' || lat === null || lng === null) {
          source = currentLocation ? 'GPS' : 'DEFAULT';
        }

        const finalLoc = (lat !== null && lng !== null && !isNaN(lat) && !isNaN(lng)) 
          ? { lat, lng } 
          : (currentLocation || { lat: 51.505, lng: -0.09 });

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError("File upload failed."); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;

    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: `Spot ${prev.length + 1}` 
      }]);
    }
    setPendingQuestion(null);
  };

  const handleDelete = () => {
    if (confirmDelete) {
      setQuestions(prev => prev.filter(q => q.id !== confirmDelete));
      setConfirmDelete(null);
    }
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
      const next = [...prev];
      const targetIdx = direction === 'up' ? index - 1 : index + 1;
      if (targetIdx < 0 || targetIdx >= next.length) return prev;
      [next[index], next[targetIdx]] = [next[targetIdx], next[index]];
      return next;
    });
  };

  if (confirmDelete) {
    return (
      <div className="fixed inset-0 z-[400] bg-slate-950/90 backdrop-blur-sm flex items-center justify-center p-6">
        <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] w-full max-w-sm text-center shadow-2xl">
          <div className="w-16 h-16 bg-red-500/10 text-red-500 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </div>
          <h3 className="text-xl font-bold mb-2">Delete spot?</h3>
          <p className="text-slate-400 text-sm mb-8">This site will be removed from your trail.</p>
          <div className="flex gap-4">
            <button onClick={() => setConfirmDelete(null)} className="flex-1 py-3 bg-slate-800 rounded-xl font-bold">Cancel</button>
            <button onClick={handleDelete} className="flex-1 py-3 bg-red-600 rounded-xl font-bold">Delete</button>
          </div>
        </div>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur sticky top-0 z-50 border-b border-slate-800">
          <h2 className="text-xl font-black uppercase tracking-widest">{pendingQuestion.editingId ? 'Edit' : 'Tag'} Spot</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold px-4 py-2">Back</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-20 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-4 flex items-center justify-center bg-black min-h-[40vh]">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="w-full md:w-1/2 p-4 md:p-8 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-5 rounded-2xl flex justify-between items-start">
                <div className="flex-1 pr-2">
                    <p className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Verify Location</p>
                    <p className="text-sm text-slate-300">Tap map to refine the spot manually.</p>
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[10px] bg-slate-800 text-slate-300 px-2 py-1 rounded font-black uppercase mb-1">{pendingQuestion.source}</span>
                   {pendingQuestion.source === 'DEFAULT' && <span className="text-[8px] text-amber-500 font-bold">Using Fallback</span>}
                </div>
             </div>
             <div className="h-[350px] md:flex-1 rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button onClick={confirmPending} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl active:scale-95 transition-all">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-4">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Trail Name..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Spots in Trail</p>
          </div>
          <button onClick={onCancel} className="bg-slate-900 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800">Exit</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4 space-y-4 overflow-y-auto pb-36 scroll-smooth-touch">
        {error && <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-sm font-bold text-center mb-4">{error}</div>}

        <div className="grid grid-cols-2 gap-4">
          <button onClick={startCamera} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 border border-slate-800 hover:border-indigo-500 py-8 rounded-3xl transition-all group">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Take Photo</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 border border-slate-800 hover:border-indigo-500 py-8 rounded-3xl transition-all group">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Upload Image</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-3 mt-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/60 backdrop-blur rounded-3xl border border-slate-800 p-4 flex items-center space-x-4">
              <img src={q.imageUrl} className="w-16 h-16 rounded-2xl object-cover border border-slate-800 shadow-md" />
              <div className="flex-1 min-w-0">
                <input type="text" value={q.title || ''} onChange={(e) => setQuestions(prev => prev.map(item => item.id === q.id ? { ...item, title: e.target.value } : item))} className="bg-transparent border-none p-0 text-base font-bold focus:ring-0 w-full mb-1" />
                <button onClick={() => setPendingQuestion({ imageUrl: q.imageUrl, location: q.location, originalLocation: q.location, editingId: q.id, title: q.title, source: q.locationSource || 'MANUAL' })} className="text-[10px] text-indigo-400 font-black uppercase tracking-widest">Edit Pin</button>
              </div>
              <div className="flex items-center space-x-2">
                <div className="flex flex-col">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 text-slate-600 disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 text-slate-600 disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
                <button onClick={() => setConfirmDelete(q.id)} className="p-3 bg-red-500/10 text-red-500 rounded-2xl"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full max-w-4xl mx-auto block py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 text-white active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
      </footer>
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/70 backdrop-blur-md flex items-center justify-center p-6 text-center">
          <div className="bg-slate-900 p-8 rounded-[2.5rem] flex flex-col items-center space-y-4 border border-slate-800">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs text-indigo-400">Processing Media...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreator;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  // Check if any changes have been made to prompt on cancel
  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';

    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;

    // Check for content differences in questions
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (navigator.geolocation) {
      watchId.current = navigator.geolocation.watchPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          if (!isNaN(lat) && !isNaN(lng)) {
            setCurrentLocation({ lat, lng });
          }
        },
        (err) => { console.warn("GPS Access Failed:", err.message); },
        { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
      );
    }
    return () => {
      if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current);
    };
  }, []);

  const stopCamera = useCallback(() => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1920 } } 
      });
      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          const playPromise = videoRef.current.play();
          if (playPromise !== undefined) {
             playPromise.catch(() => { /* Auto-play handled */ });
          }
        }
      }, 100);
    } catch (err) { 
      setError("Unable to access camera. Check permissions."); 
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;

    setIsProcessing(true);
    setIsFlashing(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);

        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = currentLocation ? 'GPS' : 'DEFAULT';

        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } catch (e) {
      setError("Failed to process photo capture.");
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = parseFloat(tags.GPSLatitude.description);
            const parsedLng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
              lat = parsedLat;
              lng = parsedLng;
              source = 'IMAGE';
            }
          }
        } catch (exifErr) { console.warn("EXIF extraction failed:", exifErr); }

        if (source !== 'IMAGE' || lat === null || lng === null) {
          source = currentLocation ? 'GPS' : 'DEFAULT';
        }

        const finalLoc = (lat !== null && lng !== null && !isNaN(lat) && !isNaN(lng)) 
          ? { lat, lng } 
          : (currentLocation || { lat: 51.505, lng: -0.09 });

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError("File upload failed."); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;

    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: `Spot ${prev.length + 1}` 
      }]);
    }
    setPendingQuestion(null);
  };

  const handleDelete = () => {
    if (confirmDelete) {
      setQuestions(prev => prev.filter(q => q.id !== confirmDelete));
      setConfirmDelete(null);
    }
  };

  const handleCancelClick = () => {
    if (hasChanges) {
      setShowExitConfirm(true);
    } else {
      onCancel();
    }
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
      const next = [...prev];
      const targetIdx = direction === 'up' ? index - 1 : index + 1;
      if (targetIdx < 0 || targetIdx >= next.length) return prev;
      [next[index], next[targetIdx]] = [next[targetIdx], next[index]];
      return next;
    });
  };

  // Exit Confirmation Modal
  if (showExitConfirm) {
    return (
      <div className="fixed inset-0 z-[400] bg-slate-950/90 backdrop-blur-sm flex items-center justify-center p-6 text-center">
        <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-amber-500/10 text-amber-500 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h3 className="text-xl font-bold mb-2">Unsaved Changes</h3>
          <p className="text-slate-400 text-sm mb-8">Canceling will remove all your unsaved changes, are you sure you want to proceed?</p>
          <div className="flex gap-4">
            <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-3 bg-slate-800 rounded-xl font-bold">Keep Editing</button>
            <button onClick={onCancel} className="flex-1 py-3 bg-red-600 rounded-xl font-bold">Discard</button>
          </div>
        </div>
      </div>
    );
  }

  if (confirmDelete) {
    return (
      <div className="fixed inset-0 z-[400] bg-slate-950/90 backdrop-blur-sm flex items-center justify-center p-6 text-center">
        <div className="bg-slate-900 border border-slate-800 p-8 rounded-[2.5rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-red-500/10 text-red-500 rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </div>
          <h3 className="text-xl font-bold mb-2">Delete spot?</h3>
          <p className="text-slate-400 text-sm mb-8">This site will be removed from your trail.</p>
          <div className="flex gap-4">
            <button onClick={() => setConfirmDelete(null)} className="flex-1 py-3 bg-slate-800 rounded-xl font-bold">Cancel</button>
            <button onClick={handleDelete} className="flex-1 py-3 bg-red-600 rounded-xl font-bold">Delete</button>
          </div>
        </div>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-slate-950 flex flex-col">
        <header className="p-6 flex justify-between items-center bg-slate-900/50 backdrop-blur sticky top-0 z-50 border-b border-slate-800">
          <h2 className="text-xl font-black uppercase tracking-widest">{pendingQuestion.editingId ? 'Edit' : 'Tag'} Spot</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-slate-400 font-bold px-4 py-2">Back</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-20 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-4 flex items-center justify-center bg-black min-h-[40vh]">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-2xl shadow-2xl object-contain" />
          </div>
          <div className="w-full md:w-1/2 p-4 md:p-8 flex flex-col space-y-4">
             <div className="bg-indigo-600/10 border border-indigo-500/20 p-5 rounded-2xl flex justify-between items-start">
                <div className="flex-1 pr-2">
                    <p className="text-xs font-black text-indigo-400 uppercase tracking-widest mb-1">Verify Location</p>
                    <p className="text-sm text-slate-300">Tap map to refine the spot manually.</p>
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[10px] bg-slate-800 text-slate-300 px-2 py-1 rounded font-black uppercase mb-1">{pendingQuestion.source}</span>
                   {pendingQuestion.source === 'DEFAULT' && <span className="text-[8px] text-amber-500 font-bold">Using Fallback</span>}
                </div>
             </div>
             <div className="h-[350px] md:flex-1 rounded-[2rem] overflow-hidden border border-slate-800 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button onClick={confirmPending} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white py-5 rounded-2xl font-black text-xl active:scale-95 transition-all">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-10 flex justify-between items-center bg-gradient-to-t from-black/90 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-slate-300/50 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col text-white">
      <header className="px-6 pt-10 pb-6 shrink-0 bg-slate-950/80 backdrop-blur sticky top-0 z-30 border-b border-slate-900">
        <div className="max-w-4xl mx-auto flex justify-between items-start mb-4">
          <div className="flex-1 mr-4">
            <input type="text" placeholder="Trail Name..." value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-slate-800 tracking-tight" />
            <p className="text-slate-500 font-bold uppercase text-[10px] tracking-widest mt-1">{questions.length} Spots in Trail</p>
          </div>
          <button onClick={handleCancelClick} className="bg-slate-900 px-5 py-2.5 rounded-2xl text-sm font-bold border border-slate-800 transition-colors hover:bg-slate-800">Cancel</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-4 space-y-4 overflow-y-auto pb-36 scroll-smooth-touch">
        {error && <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-xl text-red-400 text-sm font-bold text-center mb-4">{error}</div>}

        <div className="grid grid-cols-2 gap-4">
          <button onClick={startCamera} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 border border-slate-800 hover:border-indigo-500 py-8 rounded-3xl transition-all group">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Take Photo</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-3 bg-slate-900 border border-slate-800 hover:border-indigo-500 py-8 rounded-3xl transition-all group">
            <div className="p-4 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform"><svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div>
            <span className="font-bold text-xs uppercase tracking-widest">Upload Image</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-3 mt-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-slate-900/60 backdrop-blur rounded-3xl border border-slate-800 p-4 flex items-center space-x-4">
              <img src={q.imageUrl} className="w-16 h-16 rounded-2xl object-cover border border-slate-800 shadow-md" />
              <div className="flex-1 min-w-0">
                <input type="text" value={q.title || ''} onChange={(e) => setQuestions(prev => prev.map(item => item.id === q.id ? { ...item, title: e.target.value } : item))} className="bg-transparent border-none p-0 text-base font-bold focus:ring-0 w-full mb-1" />
                <button onClick={() => setPendingQuestion({ imageUrl: q.imageUrl, location: q.location, originalLocation: q.location, editingId: q.id, title: q.title, source: q.locationSource || 'MANUAL' })} className="text-[10px] text-indigo-400 font-black uppercase tracking-widest">Edit Pin</button>
              </div>
              <div className="flex items-center space-x-2">
                <div className="flex flex-col">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 text-slate-600 disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 text-slate-600 disabled:opacity-10"><svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
                <button onClick={() => setConfirmDelete(q.id)} className="p-3 bg-red-500/10 text-red-500 rounded-2xl transition-colors hover:bg-red-500 hover:text-white"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-6 bg-slate-950/90 backdrop-blur border-t border-slate-900 z-40">
        <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full max-w-4xl mx-auto block py-5 rounded-[2rem] font-black text-xl shadow-2xl transition-all ${questions.length > 0 ? 'bg-indigo-600 text-white active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>Finalize Quest</button>
      </footer>
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-black/70 backdrop-blur-md flex items-center justify-center p-6 text-center">
          <div className="bg-slate-900 p-8 rounded-[2.5rem] flex flex-col items-center space-y-4 border border-slate-800 shadow-2xl">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-widest text-xs text-indigo-400">Processing Media...</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreator;

import React, { useState, useEffect } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        setGameState(event.data.state);
        if (event.data.state.status === 'PLAYING') setView('PLAYING');
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, []);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

      if (existingIndex > -1) {
        trails[existingIndex] = trailToSave;
      } else {
        trails.push(trailToSave);
      }

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      console.error("Save failed:", e);
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const newPlayer: Player = { id: generateId(), name, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. The host must have the lobby open in another tab for this demo.");
    }
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => setView('DASHBOARD')} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) newState.status = 'RESULTS';
        updateGameState(newState);
      }} 
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-950">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-slate-400 hover:text-indigo-400 flex items-center font-medium">
           <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
           {strings.join.back}
        </button>
        <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl border border-slate-800">
          <h2 className="text-3xl font-black text-white mb-6 text-center">{strings.join.title}</h2>
          <div className="space-y-4">
            <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl text-white" />
            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white" />
            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl shadow-lg transition-all active:scale-95 text-lg">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 overflow-hidden flex flex-col">
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col md:flex-row items-center relative py-12 px-8">
        <div className="absolute top-1/2 left-1/4 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-600/10 blur-[150px] rounded-full pointer-events-none"></div>

        <div className="w-full md:w-1/2 space-y-8 text-center md:text-left z-10">
          <div className="relative flex flex-col items-center md:items-start select-none">
            <div className="orbit-stage">
               <div className="orbit-center">&</div>
               <div className="orbit-carousel">
                  <div className="orbiting-word here text-6xl md:text-8xl">{strings.home.here}</div>
                  <div className="orbiting-word there text-6xl md:text-8xl">{strings.home.there}</div>
               </div>
            </div>
            <div className="text-indigo-400 font-black tracking-[0.5em] text-sm md:text-lg mt-4 uppercase glow-indigo">{strings.home.title}</div>
          </div>

          <p className="text-xl text-slate-400 max-w-md mx-auto md:mx-0 leading-relaxed font-light">
            {strings.home.subtitle}
          </p>

          <div className="flex flex-col sm:flex-row gap-5 pt-4">
            <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-2xl hover:bg-indigo-500 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              {strings.home.designTrail}
            </button>
            <button onClick={() => setView('JOIN')} className="px-10 py-5 bg-slate-900 text-white border border-slate-800 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              {strings.home.joinQuest}
            </button>
          </div>
        </div>

        <div className="w-full md:w-1/2 mt-20 md:mt-0 flex items-center justify-center">
           <div className="relative w-full max-w-sm aspect-[4/5] bg-slate-900 rounded-[4rem] border border-slate-800 p-5 shadow-2xl rotate-3">
              <div className="w-full h-full rounded-[3rem] overflow-hidden border-4 border-slate-800">
                 <img src="https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover grayscale opacity-50 hover:grayscale-0 transition-all duration-700" />
              </div>
              <div className="absolute -bottom-8 -left-8 w-28 h-28 bg-indigo-600 rounded-[2rem] shadow-2xl flex items-center justify-center -rotate-12 border-4 border-slate-950">
                 <svg className="w-14 h-14 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
           </div>
        </div>
      </main>
    </div>
  );
};

export default App;

