import React, { useState, useEffect } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onNext: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ gameState, isHost, currentPlayer, onGuess, onNext }) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  useEffect(() => {
    setHasSubmitted(false);
    setSelectedGuess(null);
  }, [gameState.currentQuestionIndex]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
      setHasSubmitted(true);
    }
  };

  const isRoundFinished = gameState.status === 'RESULTS';
  const isGameFinished = gameState.status === 'FINISHED';

  const sortedPlayers = [...gameState.players].sort((a, b) => b.score - a.score);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-indigo-600 p-6 flex flex-col items-center justify-center text-white">
        <h1 className="text-4xl font-black mb-8">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-3xl p-8 shadow-2xl w-full max-w-md text-slate-800">
          <div className="space-y-4">
            {sortedPlayers.map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-4 rounded-2xl ${idx === 0 ? 'bg-amber-50 border-2 border-amber-200' : 'bg-slate-50'}`}>
                <div className="flex items-center space-x-4">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-amber-500' : 'text-slate-300'}`}>#{idx + 1}</div>
                  <div className="font-bold">{p.name}</div>
                </div>
                <div className="text-xl font-black text-indigo-600">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button 
            onClick={() => window.location.reload()}
            className="w-full mt-8 bg-indigo-600 text-white font-bold py-4 rounded-xl"
          >
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col md:flex-row bg-slate-100 overflow-hidden">
      <div className="w-full md:w-1/2 h-1/2 md:h-full flex flex-col p-4 space-y-4">
        <div className="bg-white rounded-2xl p-4 shadow-sm flex justify-between items-center">
          <div className="font-bold text-slate-500">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="font-black text-indigo-600">{strings.game.points(currentPlayer?.score || 0)}</div>
        </div>

        <div className="flex-1 relative rounded-3xl overflow-hidden bg-slate-800 shadow-2xl">
          <img src={currentQ.imageUrl} className="w-full h-full object-contain" alt="Guess this location" />
          {isRoundFinished && (
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center p-6 text-center text-white">
              <h2 className="text-3xl font-black mb-4">{strings.game.roundResults}</h2>
              <div className="space-y-3 w-full max-w-sm">
                {gameState.players.map(p => (
                   <div key={p.id} className="flex justify-between items-center bg-white/10 p-3 rounded-xl border border-white/20">
                     <span className="font-bold">{p.name}</span>
                     <span className="font-mono text-sm">{p.lastDistance ? formatDistance(p.lastDistance) : strings.game.noGuess}</span>
                   </div>
                ))}
              </div>
              {isHost && (
                <button 
                  onClick={onNext}
                  className="mt-8 bg-white text-indigo-600 px-8 py-3 rounded-full font-black hover:bg-indigo-50 transition-all shadow-xl"
                >
                  {strings.game.nextLocation} &rarr;
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="w-full md:w-1/2 h-1/2 md:h-full p-4 md:pl-0 flex flex-col space-y-4">
        <div className="flex-1 relative bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
          <Map 
            onLocationSelect={isRoundFinished ? undefined : setSelectedGuess}
            markers={[
              ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const }] : []),
              ...(isRoundFinished ? [{ position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const }] : []),
              ...(isRoundFinished ? gameState.players.filter(p => p.lastGuess).map(p => ({ 
                  position: p.lastGuess!, 
                  label: `${p.name}'s guess`,
                  icon: p.id === currentPlayer?.id ? 'user' as const : 'default' as const
                })) : [])
            ]}
            lines={isRoundFinished ? gameState.players.filter(p => p.lastGuess).map(p => ({
              from: p.lastGuess!,
              to: currentQ.location
            })) : []}
            center={currentQ.location}
            zoom={12}
          />

          {!isRoundFinished && !hasSubmitted && (
            <div className="absolute bottom-6 inset-x-0 flex justify-center px-4">
              <button 
                disabled={!selectedGuess}
                onClick={handleGuessSubmit}
                className={`w-full max-w-xs py-4 rounded-2xl font-black text-lg shadow-2xl transition-all ${selectedGuess ? 'bg-indigo-600 hover:bg-indigo-700 text-white active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
              >
                {strings.game.submitGuess}
              </button>
            </div>
          )}

          {!isRoundFinished && hasSubmitted && (
             <div className="absolute bottom-6 inset-x-0 flex justify-center px-4">
               <div className="bg-white/90 backdrop-blur shadow-xl px-8 py-3 rounded-2xl border border-indigo-100 flex items-center space-x-3">
                 <div className="w-2 h-2 rounded-full bg-indigo-600 animate-ping"></div>
                 <span className="font-bold text-indigo-600">{strings.game.waitingPlayers}</span>
               </div>
             </div>
          )}
        </div>

        <div className="md:hidden flex justify-between p-2">
           <div className="text-xs text-slate-400 font-medium italic">{strings.game.precisionTip}</div>
        </div>
      </div>
    </div>
  );
};

