import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import { Location } from '../types';

interface MapProps {
  onLocationSelect?: (loc: Location) => void;
  markers?: { position: Location; label?: string; icon?: 'default' | 'target' | 'user'; color?: string }[];
  center?: Location;
  zoom?: number;
  lines?: { from: Location; to: Location; color?: string }[];
}

const isValid = (loc?: Location): boolean => {
  return !!loc && typeof loc.lat === 'number' && typeof loc.lng === 'number' && !isNaN(loc.lat) && !isNaN(loc.lng);
};

const Map: React.FC<MapProps> = ({ onLocationSelect, markers = [], center, zoom = 13, lines = [] }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const leafletMap = useRef<L.Map | null>(null);
  const markersLayer = useRef<L.LayerGroup | null>(null);
  const initialLoadDone = useRef(false);

  useEffect(() => {
    if (!mapRef.current || leafletMap.current) return;

    const startPos: [number, number] = isValid(center) ? [center!.lat, center!.lng] : [51.505, -0.09];

    leafletMap.current = L.map(mapRef.current, {
      zoomControl: false,
      attributionControl: false
    }).setView(startPos, zoom);

    L.control.zoom({ position: 'bottomright' }).addTo(leafletMap.current);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
    }).addTo(leafletMap.current);

    markersLayer.current = L.layerGroup().addTo(leafletMap.current);

    leafletMap.current.on('click', (e) => {
      if (onLocationSelect) {
        onLocationSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
      }
    });

    return () => {
      leafletMap.current?.remove();
      leafletMap.current = null;
      initialLoadDone.current = false;
    };
  }, []);

  useEffect(() => {
    if (!leafletMap.current || !markersLayer.current) return;

    if (isValid(center) && !initialLoadDone.current) {
      leafletMap.current.setView([center!.lat, center!.lng], zoom);
      initialLoadDone.current = true;
    }

    markersLayer.current.clearLayers();
    const bounds = L.latLngBounds([]);

    markers.forEach((m) => {
      if (!isValid(m.position)) return;

      const bgColor = m.color ? m.color : (m.icon === 'target' ? '#ef4444' : m.icon === 'user' ? '#3b82f6' : '#6366f1');

      const icon = L.divIcon({
        className: 'custom-div-icon',
        html: `<div class="w-8 h-8 rounded-full border-2 border-white shadow-lg flex items-center justify-center" style="background-color: ${bgColor}">
          <div class="w-2 h-2 rounded-full bg-white"></div>
        </div>`,
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      });

      const isDraggable = !!onLocationSelect;
      const marker = L.marker([m.position.lat, m.position.lng], { 
        icon, 
        draggable: isDraggable 
      }).addTo(markersLayer.current!);

      if (isDraggable) {
        marker.on('dragend', (event) => {
          const { lat, lng } = event.target.getLatLng();
          onLocationSelect({ lat, lng });
        });
      }

      if (m.label) marker.bindPopup(m.label);
      bounds.extend([m.position.lat, m.position.lng]);
    });

    lines.forEach((line) => {
      if (!isValid(line.from) || !isValid(line.to)) return;
      L.polyline(
        [[line.from.lat, line.from.lng], [line.to.lat, line.to.lng]],
        { color: line.color || '#6366f1', weight: 3, dashArray: '5, 10' }
      ).addTo(markersLayer.current!);
      bounds.extend([line.from.lat, line.from.lng]);
      bounds.extend([line.to.lat, line.to.lng]);
    });

    if ((lines.length > 0 || markers.length > 1) && bounds.isValid()) {
      leafletMap.current.fitBounds(bounds, { padding: [50, 50] });
    }
  }, [markers, center, zoom, lines]);

  return <div ref={mapRef} className="w-full h-full" />;
};

export default Map;

import React, { useState, useEffect } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [selectedColor, setSelectedColor] = useState('#6366f1');

  const availableColors = [
    '#6366f1', '#ef4444', '#10b981', '#f59e0b', '#ec4899', 
    '#8b5cf6', '#06b6d4', '#84cc16', '#f97316', '#64748b'
  ];

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        const newState = event.data.state as GameState;
        setGameState(newState);

        // Handle kick
        if (currentPlayer && !newState.players.find(p => p.id === currentPlayer.id) && !isHost) {
          alert(strings.lobby.kickedDesc);
          setCurrentPlayer(null);
          setView('HOME');
          localStorage.removeItem('locateit_last_player_id');
          return;
        }

        if (newState.status === 'PLAYING' || newState.status === 'COUNTDOWN' || newState.status === 'RESULTS') setView('PLAYING');
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, [currentPlayer, isHost]);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

      if (existingIndex > -1) {
        trails[existingIndex] = trailToSave;
      } else {
        trails.push(trailToSave);
      }

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      console.error("Save failed:", e);
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      // Re-join check
      const savedPlayerId = localStorage.getItem('locateit_last_player_id');
      const existingPlayer = gameState.players.find(p => p.id === savedPlayerId);

      if (existingPlayer) {
        setCurrentPlayer(existingPlayer);
        setIsHost(false);
        setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
        return;
      }

      const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', newPlayer.id);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. The host must have the lobby open in another tab for this demo.");
    }
  };

  const handleKickPlayer = (playerId: string) => {
    if (!gameState || !isHost) return;
    const updatedPlayers = gameState.players.filter(p => p.id !== playerId);
    updateGameState({ ...gameState, players: updatedPlayers });
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { setGameState(null); setView('DASHBOARD'); }} onKick={handleKickPlayer} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) {
          newState.status = 'COUNTDOWN';
        }
        updateGameState(newState);
      }} 
      onCountdownFinish={() => {
        if (isHost && gameState.status === 'COUNTDOWN') {
          updateGameState({ ...gameState, status: 'RESULTS' });
        }
      }}
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-950">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-slate-400 hover:text-indigo-400 flex items-center font-medium">
           <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
           {strings.join.back}
        </button>
        <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl border border-slate-800">
          <h2 className="text-3xl font-black text-white mb-6 text-center">{strings.join.title}</h2>
          <div className="space-y-6">
            <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl text-white" />
            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white" />

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-widest ml-1">{strings.lobby.chooseColor}</label>
              <div className="flex flex-wrap gap-3">
                {availableColors.map(color => (
                  <button 
                    key={color} 
                    onClick={() => setSelectedColor(color)}
                    className={`w-8 h-8 rounded-full border-2 transition-transform active:scale-90 ${selectedColor === color ? 'border-white scale-125' : 'border-transparent'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl shadow-lg transition-all active:scale-95 text-lg">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 overflow-hidden flex flex-col">
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col md:flex-row items-center relative py-12 px-8">
        <div className="absolute top-1/2 left-1/4 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-600/10 blur-[150px] rounded-full pointer-events-none"></div>

        <div className="w-full md:w-1/2 space-y-8 text-center md:text-left z-10">
          <div className="relative flex flex-col items-center md:items-start select-none">
            <div className="orbit-stage">
               <div className="orbit-center">&</div>
               <div className="orbit-carousel">
                  <div className="orbiting-word here text-6xl md:text-8xl">{strings.home.here}</div>
                  <div className="orbiting-word there text-6xl md:text-8xl">{strings.home.there}</div>
               </div>
            </div>
            <div className="text-indigo-400 font-black tracking-[0.5em] text-sm md:text-lg mt-4 uppercase glow-indigo">{strings.home.title}</div>
          </div>

          <p className="text-xl text-slate-400 max-w-md mx-auto md:mx-0 leading-relaxed font-light">
            {strings.home.subtitle}
          </p>

          <div className="flex flex-col sm:flex-row gap-5 pt-4">
            <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-2xl hover:bg-indigo-500 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              {strings.home.designTrail}
            </button>
            <button onClick={() => setView('JOIN')} className="px-10 py-5 bg-slate-900 text-white border border-slate-800 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              {strings.home.joinQuest}
            </button>
          </div>
        </div>

        <div className="w-full md:w-1/2 mt-20 md:mt-0 flex items-center justify-center">
           <div className="relative w-full max-w-sm aspect-[4/5] bg-slate-900 rounded-[4rem] border border-slate-800 p-5 shadow-2xl rotate-3">
              <div className="w-full h-full rounded-[3rem] overflow-hidden border-4 border-slate-800">
                 <img src="https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?auto=format&fit=crop&q=80&w=800" className="w-full h-full object-cover grayscale opacity-50 hover:grayscale-0 transition-all duration-700" />
              </div>
              <div className="absolute -bottom-8 -left-8 w-28 h-28 bg-indigo-600 rounded-[2rem] shadow-2xl flex items-center justify-center -rotate-12 border-4 border-slate-950">
                 <svg className="w-14 h-14 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
              </div>
           </div>
        </div>
      </main>
    </div>
  );
};

