               <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
               {strings.lobby.backToDash}
             </button>
            <h1 className="text-3xl font-black mb-1">{strings.lobby.title}</h1>
            <p className="text-indigo-100 opacity-80 text-sm">{strings.lobby.subtitle}</p>
          </div>
          <div className="text-right">
            <span className="text-[10px] uppercase font-black tracking-widest text-indigo-300">{strings.lobby.roomCode}</span>
            <div className="text-4xl font-mono font-black tracking-tighter">{gameState.id}</div>
          </div>
        </div>
      </div>

      <main className="flex-1 max-w-2xl w-full mx-auto p-6 -mt-8 relative z-20">
        <div className="bg-slate-900 rounded-3xl shadow-2xl overflow-hidden border border-slate-800">
          <div className="p-6 border-b border-slate-800 flex justify-between items-center">
            <h3 className="font-bold text-slate-400 uppercase text-xs tracking-wider">{strings.lobby.playersJoined(gameState.players.length)}</h3>
            <div className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)] animate-pulse"></div>
          </div>
          <div className="divide-y divide-slate-800 max-h-[50vh] overflow-y-auto scroll-smooth-touch">
            {gameState.players.length === 0 ? (
              <div className="p-16 text-center text-slate-500">
                <p className="mb-2">{strings.lobby.noPlayers}</p>
                <div className="inline-block p-4 bg-slate-800 rounded-2xl font-mono text-2xl tracking-widest select-all">{gameState.id}</div>
              </div>
            ) : (
              gameState.players.map(p => (
                <div key={p.id} className="p-5 flex items-center justify-between hover:bg-slate-800 transition-colors">
                  <div className="flex items-center space-x-4">
                    <div className="w-12 h-12 rounded-2xl flex items-center justify-center font-black text-xl shadow-md" style={{ backgroundColor: p.color }}>
                      {p.name.charAt(0)}
                    </div>
                    <div>
                      <span className="font-bold text-slate-200 block">{p.name} {p.id === currentPlayer?.id ? "(You)" : ""}</span>
                      <span className="text-[10px] text-slate-500 uppercase font-black tracking-widest">{strings.lobby.explorer}</span>
                    </div>
                  </div>
                  <div className="flex items-center space-x-3">
                    {p.id === gameState.hostId && <span className="text-[10px] bg-indigo-500 text-white px-3 py-1 rounded-full font-black uppercase">{strings.lobby.host}</span>}
                    {isHost && p.id !== gameState.hostId && (
                      <button 
                        onClick={() => onKick(p.id)}
                        className="text-xs font-bold text-red-500/60 hover:text-red-500 uppercase tracking-tighter"
                      >
                        {strings.common.kick}
                      </button>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {isHost ? (
          <div className="mt-8 space-y-4">
            <button 
              disabled={gameState.players.length === 0}
              onClick={onStart}
              className={`w-full py-5 rounded-[1.5rem] font-black text-xl shadow-2xl transition-all active:scale-95 ${gameState.players.length > 0 ? 'bg-indigo-600 hover:bg-indigo-700 text-white' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}
            >
              {strings.lobby.startExpedition}
            </button>
          </div>
        ) : (
          <div className="mt-8 p-8 bg-slate-900/50 rounded-3xl border-2 border-dashed border-slate-800 text-center">
            <div className="w-12 h-12 bg-slate-800 rounded-2xl flex items-center justify-center mx-auto mb-4 animate-bounce">
              <svg className="w-6 h-6 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            </div>
            <p className="text-slate-400 font-medium italic">{strings.lobby.waitingForHost}</p>
          </div>
        )}
      </main>
    </div>
  );
};

export default Lobby;

import React, { useState, useEffect } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onCountdownFinish: () => void;
  onNext: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ gameState, isHost, currentPlayer, onGuess, onCountdownFinish, onNext }) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  useEffect(() => {
    setHasSubmitted(false);
    setSelectedGuess(null);
    setCountdownValue(3);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (gameState.status === 'COUNTDOWN') {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [gameState.status, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
      setHasSubmitted(true);
    }
  };

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isGameFinished = gameState.status === 'FINISHED';

  const sortedPlayers = [...gameState.players].sort((a, b) => b.score - a.score);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-indigo-600 p-6 flex flex-col items-center justify-center text-white">
        <h1 className="text-4xl font-black mb-8">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-3xl p-8 shadow-2xl w-full max-w-md text-slate-800">
          <div className="space-y-4">
            {sortedPlayers.map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-4 rounded-2xl ${idx === 0 ? 'bg-amber-50 border-2 border-amber-200' : 'bg-slate-50'}`}>
                <div className="flex items-center space-x-4">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-amber-500' : 'text-slate-300'}`}>#{idx + 1}</div>
                  <div className="w-10 h-10 rounded-xl flex items-center justify-center font-black text-white" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-bold">{p.name}</div>
                </div>
                <div className="text-xl font-black text-indigo-600">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button 
            onClick={() => window.location.reload()}
            className="w-full mt-8 bg-indigo-600 text-white font-bold py-4 rounded-xl active:scale-95 transition-transform"
          >
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col md:flex-row bg-slate-100 overflow-hidden">
      {/* Visual Overlay for Countdown */}
      {isCountingDown && (
        <div className="fixed inset-0 z-[600] bg-slate-950/80 backdrop-blur-xl flex flex-col items-center justify-center text-white">
           <p className="text-indigo-400 font-black uppercase tracking-widest mb-4">{strings.game.countdownTitle}</p>
           <div className="text-9xl font-black animate-ping">{countdownValue}</div>
        </div>
      )}

      <div className="w-full md:w-1/2 h-1/2 md:h-full flex flex-col p-4 space-y-4">
        <div className="bg-white rounded-2xl p-4 shadow-sm flex justify-between items-center">
          <div className="font-bold text-slate-500">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="flex items-center space-x-4">
             <div className="flex -space-x-2">
                {gameState.players.map(p => (
                  <div 
                    key={p.id} 
                    className={`w-6 h-6 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black text-white transition-opacity ${p.hasGuessed ? 'opacity-100' : 'opacity-20'}`}
                    style={{ backgroundColor: p.color }}
                  >
                    {p.name.charAt(0)}
                  </div>
                ))}
             </div>
             <div className="font-black text-indigo-600">{strings.game.points(currentPlayer?.score || 0)}</div>
          </div>
        </div>

        <div className="flex-1 relative rounded-3xl overflow-hidden bg-slate-800 shadow-2xl">
          <img src={currentQ.imageUrl} className="w-full h-full object-contain" alt="Guess this location" />
          {isRoundFinished && (
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm flex flex-col items-center justify-center p-6 text-center text-white">
              <h2 className="text-3xl font-black mb-4">{strings.game.roundResults}</h2>
              <div className="space-y-3 w-full max-w-sm">
                {gameState.players.map(p => (
                   <div key={p.id} className="flex justify-between items-center bg-white/10 p-3 rounded-xl border border-white/20">
                     <div className="flex items-center space-x-2">
                        <div className="w-4 h-4 rounded-full" style={{ backgroundColor: p.color }} />
                        <span className="font-bold">{p.name}</span>
                     </div>
                     <span className="font-mono text-sm">{p.lastDistance ? formatDistance(p.lastDistance) : strings.game.noGuess}</span>
                   </div>
                ))}
              </div>
              {isHost && (
                <button 
                  onClick={onNext}
                  className="mt-8 bg-white text-indigo-600 px-8 py-3 rounded-full font-black hover:bg-indigo-50 transition-all shadow-xl active:scale-95"
                >
                  {strings.game.nextLocation} &rarr;
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="w-full md:w-1/2 h-1/2 md:h-full p-4 md:pl-0 flex flex-col space-y-4">
        <div className="flex-1 relative bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
          <Map 
            onLocationSelect={isRoundFinished ? undefined : setSelectedGuess}
            markers={[
              ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
              ...(isRoundFinished ? [{ position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const }] : []),
              ...(isRoundFinished ? gameState.players.filter(p => p.lastGuess).map(p => ({ 
                  position: p.lastGuess!, 
                  label: `${p.name}'s guess`,
                  icon: 'user' as const,
                  color: p.color
                })) : [])
            ]}
            lines={isRoundFinished ? gameState.players.filter(p => p.lastGuess).map(p => ({
              from: p.lastGuess!,
              to: currentQ.location,
              color: p.color
            })) : []}
            center={currentQ.location}
            zoom={12}
          />

          {!isRoundFinished && !hasSubmitted && (
            <div className="absolute bottom-6 inset-x-0 flex justify-center px-4">
              <button 
                disabled={!selectedGuess}
                onClick={handleGuessSubmit}
                className={`w-full max-w-xs py-4 rounded-2xl font-black text-lg shadow-2xl transition-all ${selectedGuess ? 'bg-indigo-600 hover:bg-indigo-700 text-white active:scale-95' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}
              >
                {strings.game.submitGuess}
              </button>
            </div>
          )}

          {!isRoundFinished && hasSubmitted && !isCountingDown && (
             <div className="absolute bottom-6 inset-x-0 flex justify-center px-4">
               <div className="bg-white/90 backdrop-blur shadow-xl px-8 py-3 rounded-2xl border border-indigo-100 flex items-center space-x-3">
                 <div className="w-2 h-2 rounded-full bg-indigo-600 animate-ping"></div>
                 <span className="font-bold text-indigo-600">{strings.game.waitingPlayers}</span>
               </div>
             </div>
          )}
        </div>

        <div className="md:hidden flex justify-between p-2">
           <div className="text-xs text-slate-400 font-medium italic">{strings.game.precisionTip}</div>
        </div>
      </div>
    </div>
  );
};

export default GameBoard;

import React, { useState, useEffect } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [selectedColor, setSelectedColor] = useState('#6366f1');

  const availableColors = [
    '#6366f1', '#ef4444', '#10b981', '#f59e0b', '#ec4899', 
    '#8b5cf6', '#06b6d4', '#84cc16', '#f97316', '#64748b'
  ];

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        const newState = event.data.state as GameState;
        setGameState(newState);

        // Handle kick
        if (currentPlayer && !newState.players.find(p => p.id === currentPlayer.id) && !isHost) {
          alert(strings.lobby.kickedDesc);
          setCurrentPlayer(null);
          setView('HOME');
          localStorage.removeItem('locateit_last_player_id');
          return;
        }

        if (newState.status === 'PLAYING' || newState.status === 'COUNTDOWN' || newState.status === 'RESULTS') {
          setView('PLAYING');
        }
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, [currentPlayer, isHost]);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

      if (existingIndex > -1) {
        trails[existingIndex] = trailToSave;
      } else {
        trails.push(trailToSave);
      }

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      console.error("Save failed:", e);
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      // Re-join check based on saved player ID in localStorage
      const savedPlayerId = localStorage.getItem('locateit_last_player_id');
      const existingPlayer = gameState.players.find(p => p.id === savedPlayerId);

      if (existingPlayer) {
        setCurrentPlayer(existingPlayer);
        setIsHost(false);
        // Navigate based on game state
        if (gameState.status === 'LOBBY') setView('LOBBY');
        else if (['PLAYING', 'COUNTDOWN', 'RESULTS'].includes(gameState.status)) setView('PLAYING');
        else setView('HOME');
        return;
      }

      const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', newPlayer.id);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. Ensure the Host has the lobby open in another tab.");
    }
  };

  const handleKickPlayer = (playerId: string) => {
    if (!gameState || !isHost) return;
    const updatedPlayers = gameState.players.filter(p => p.id !== playerId);
    updateGameState({ ...gameState, players: updatedPlayers });
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { setGameState(null); setView('DASHBOARD'); }} onKick={handleKickPlayer} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) {
          newState.status = 'COUNTDOWN';
        }
        updateGameState(newState);
      }} 
      onCountdownFinish={() => {
        if (isHost && gameState.status === 'COUNTDOWN') {
          updateGameState({ ...gameState, status: 'RESULTS' });
        }
      }}
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-slate-950">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-slate-400 hover:text-indigo-400 flex items-center font-medium">
           <svg className="w-5 h-5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
           {strings.join.back}
        </button>
        <div className="bg-slate-900 rounded-[2.5rem] p-10 shadow-2xl border border-slate-800">
          <h2 className="text-3xl font-black text-white mb-6 text-center">{strings.join.title}</h2>
          <div className="space-y-6">
            <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all uppercase font-mono text-center tracking-widest text-xl text-white" />
            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-6 py-5 bg-slate-800 border-2 border-transparent focus:border-indigo-500 focus:bg-slate-800 rounded-2xl outline-none transition-all text-white" />

            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase tracking-widest ml-1">{strings.lobby.chooseColor}</label>
              <div className="flex flex-wrap gap-3">
                {availableColors.map(color => (
                  <button 
                    key={color} 
                    onClick={() => setSelectedColor(color)}
                    className={`w-8 h-8 rounded-full border-2 transition-transform active:scale-90 ${selectedColor === color ? 'border-white scale-125 shadow-[0_0_15px_rgba(255,255,255,0.3)]' : 'border-transparent'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-5 rounded-2xl shadow-lg transition-all active:scale-95 text-lg">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-50 overflow-hidden flex flex-col">
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col md:flex-row items-center relative py-12 px-8">
        <div className="absolute top-1/2 left-1/4 -translate-y-1/2 w-[600px] h-[600px] bg-indigo-600/10 blur-[150px] rounded-full pointer-events-none"></div>

        <div className="w-full md:w-1/2 space-y-8 text-center md:text-left z-10">
          <div className="relative flex flex-col items-center md:items-start select-none">
            <div className="orbit-stage">
               <div className="orbit-center">&</div>
               <div className="orbit-carousel">
                  <div className="orbiting-word here text-6xl md:text-8xl">{strings.home.here}</div>
                  <div className="orbiting-word there text-6xl md:text-8xl">{strings.home.there}</div>
               </div>
            </div>
            <div className="text-indigo-400 font-black tracking-[0.5em] text-sm md:text-lg mt-4 uppercase glow-indigo">{strings.home.title}</div>
          </div>

          <p className="text-xl text-slate-400 max-w-md mx-auto md:mx-0 leading-relaxed font-light">
            {strings.home.subtitle}
          </p>

          <div className="flex flex-col sm:flex-row gap-5 pt-4">
            <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-10 py-5 bg-indigo-600 text-white rounded-2xl font-bold text-lg shadow-2xl hover:bg-indigo-50 transition-all hover:-translate-y-1 active:scale-95 flex-1">
              {strings.home.designTrail}
            </button>
