            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-6 py-5 bg-slate-100 border-4 border-slate-900 rounded-2xl outline-none focus:bg-white text-slate-900 font-bold placeholder:opacity-30" />

            <div className="space-y-3">
              <label className="text-xs font-black text-slate-400 uppercase tracking-widest ml-1">{strings.lobby.chooseColor}</label>
              <div className="flex flex-wrap gap-4 justify-center">
                {availableColors.map(color => (
                  <button 
                    key={color} 
                    onClick={() => setSelectedColor(color)}
                    className={`w-10 h-10 rounded-xl border-4 transition-all active:scale-90 ${selectedColor === color ? 'border-slate-900 scale-110' : 'border-transparent opacity-60 hover:opacity-100'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full bg-blue-500 hover:bg-blue-400 text-white font-black py-6 rounded-2xl shadow-[6px_6px_0px_#0f172a] border-4 border-slate-900 transition-all active:translate-y-1 active:shadow-none text-xl tracking-tight uppercase">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#f0f9ff] text-slate-900 overflow-hidden flex flex-col relative selection:bg-yellow-300">
      <FlyingWordsBackground />

      {/* Decorative Primary Orbs */}
      <div className="fixed -top-40 -left-40 w-[600px] h-[600px] bg-blue-400/10 blur-[150px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-40 -right-40 w-[600px] h-[600px] bg-red-400/10 blur-[150px] rounded-full pointer-events-none"></div>

      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col items-center relative py-12 px-8 z-10 gap-32 overflow-y-auto scroll-smooth-touch">

