                <AnimationVariantSwapT fontSize="clamp(2.5rem, 8vw, 6rem)" />
                <div className="bg-yellow-400 text-slate-900 border-4 border-slate-900 px-8 py-3 rounded-2xl font-black tracking-[0.2em] text-sm md:text-base mt-[-1.5rem] z-20 uppercase shadow-[6px_6px_0px_#0f172a] transform -rotate-1 hover:rotate-0 transition-transform cursor-default">
                  {strings.home.title}
                </div>
            </div>

            <div className="max-w-2xl text-center space-y-10">
              <p className="text-2xl md:text-4xl text-slate-700 leading-tight font-black tracking-tighter">
                {strings.home.subtitle}
              </p>

              <div className="flex flex-col sm:flex-row gap-8 justify-center w-full px-4">
                <button 
                  onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} 
