                     />
                     <div className="absolute inset-0 bg-blue-500/10 group-hover:bg-transparent transition-colors"></div>
                  </div>

                  <div className="absolute -bottom-10 -right-10 w-32 h-32 bg-yellow-400 rounded-full shadow-[8px_8px_0px_#0f172a] flex items-center justify-center rotate-12 border-8 border-slate-900 text-slate-900 group-hover:scale-110 transition-all">
                     <svg className="w-16 h-16" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
