  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#ecf3f0]">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-emerald-800 hover:text-emerald-950 flex items-center font-black uppercase tracking-widest text-xs">
           <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
           {strings.join.back}
        </button>
        <div className="bg-[#fdfaf3] rounded-[2.5rem] p-10 border-4 border-emerald-900 shadow-[10px_10px_0px_rgba(6,78,59,1)]">
          <h2 className="text-2xl font-black text-emerald-950 mb-10 text-center tracking-tighter uppercase">{strings.join.title}</h2>
