import React, { useState, useEffect, useMemo } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const FlyingWordsBackground: React.FC = () => {
  const words = useMemo(() => {
    const palette = [
      '#4a5d4e', // Forest Green
      '#8b4513', // Bark Brown
      '#6b705c', // Olive Moss
      '#4a646c', // Slate Blue
      '#a47e3c', // Sand Gold
    ];

    return Array.from({ length: 30 }).map((_, i) => ({
      id: i,
      text: i % 2 === 0 ? 'HERE' : 'THERE',
      top: `${Math.random() * 100}%`,
      duration: `${30 + Math.random() * 40}s`,
      delay: `${-Math.random() * 60}s`,
      size: `${1.2 + Math.random() * 6}rem`,
      color: palette[Math.floor(Math.random() * palette.length)],
      opacity: 0.04 + Math.random() * 0.04, // Very subtle forest drift
      direction: Math.random() > 0.5 ? 'normal' : 'reverse'
    }));
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
      {words.map(w => (
        <div 
          key={w.id}
          className="flying-word"
          style={{
            top: w.top,
            fontSize: w.size,
            color: w.color,
            opacity: w.opacity,
            animation: `${w.direction === 'normal' ? 'fly-across' : 'fly-across-reverse'} ${w.duration} linear infinite`,
            animationDelay: w.delay
          }}
        >
          {w.text}
        </div>
      ))}
    </div>
  );
};

const AnimationVariantSwapT: React.FC<{ fontSize?: string }> = ({ fontSize = '4rem' }) => {
  const [showLeftT, setShowLeftT] = useState(true);

  useEffect(() => {
    const interval = setInterval(() => {
      setShowLeftT(prev => !prev);
    }, 2500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="trail-sign group transition-all hover:scale-[1.02] hover:-rotate-1">
      <div className="swap-t-stage" style={{ fontSize }}>
        <div className="swap-t-word">
          <span className={`t-char text-[#f1f3f0] ${showLeftT ? 't-visible' : 't-hidden'}`}>T</span>
          <span className="text-[#f1f3f0]">HERE</span>
        </div>
        <div className="text-[#f1f3f0]/20 font-light mx-4 md:mx-10 select-none italic">&</div>
        <div className="swap-t-word">
          <span className={`t-char text-[#a47e3c] ${!showLeftT ? 't-visible' : 't-hidden'}`}>T</span>
          <span className="text-[#a47e3c]">HERE</span>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [selectedColor, setSelectedColor] = useState('#2d4a3e');

  const availableColors = [
    '#2d4a3e', '#8b4513', '#4a646c', '#ca8a04', '#7c2d12', 
    '#0f766e', '#4c1d95', '#1a261a', '#6b705c', '#5d2e0d'
  ];

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        const newState = event.data.state as GameState;
        setGameState(newState);

        if (currentPlayer && !newState.players.find(p => p.id === currentPlayer.id) && !isHost) {
          alert(strings.lobby.kickedDesc);
          setCurrentPlayer(null);
          setView('HOME');
          localStorage.removeItem('locateit_last_player_id');
          return;
        }

        if (newState.status === 'PLAYING' || newState.status === 'COUNTDOWN' || newState.status === 'RESULTS') {
          setView('PLAYING');
        }
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, [currentPlayer, isHost]);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

      if (existingIndex > -1) {
        trails[existingIndex] = trailToSave;
      } else {
        trails.push(trailToSave);
      }

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      console.error("Save failed:", e);
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const savedPlayerId = localStorage.getItem('locateit_last_player_id');
      const existingPlayer = gameState.players.find(p => p.id === savedPlayerId);

      if (existingPlayer) {
        setCurrentPlayer(existingPlayer);
        setIsHost(false);
        if (gameState.status === 'LOBBY') setView('LOBBY');
        else if (['PLAYING', 'COUNTDOWN', 'RESULTS'].includes(gameState.status)) setView('PLAYING');
        else setView('HOME');
        return;
      }

      const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', newPlayer.id);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. Ensure the Host has the lobby open in another tab.");
    }
  };

  const handleKickPlayer = (playerId: string) => {
    if (!gameState || !isHost) return;
    const updatedPlayers = gameState.players.filter(p => p.id !== playerId);
    updateGameState({ ...gameState, players: updatedPlayers });
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { setGameState(null); setView('DASHBOARD'); }} onKick={handleKickPlayer} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) {
          newState.status = 'COUNTDOWN';
        }
        updateGameState(newState);
      }} 
      onCountdownFinish={() => {
        if (isHost && gameState.status === 'COUNTDOWN') {
          updateGameState({ ...gameState, status: 'RESULTS' });
        }
      }}
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#d9e0d2]">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-[#2d4a3e] hover:text-[#1a261a] flex items-center font-black uppercase tracking-[0.2em] text-[10px]">
           <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
           {strings.join.back}
        </button>
        <div className="bg-[#f1f3f0] rounded-[2rem] p-10 border-2 border-[#1a261a] shadow-xl">
          <h2 className="text-2xl font-black text-[#1a261a] mb-8 text-center tracking-tighter uppercase">{strings.join.title}</h2>
          <div className="space-y-6">
            <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-6 py-5 bg-[#d9e0d2]/40 border-2 border-[#1a261a]/10 rounded-xl outline-none focus:border-[#2d4a3e] uppercase font-black text-center tracking-widest text-xl text-[#1a261a] placeholder:opacity-20 transition-all" />
            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-6 py-5 bg-[#d9e0d2]/40 border-2 border-[#1a261a]/10 rounded-xl outline-none focus:border-[#2d4a3e] text-[#1a261a] font-bold placeholder:opacity-20 transition-all" />

            <div className="space-y-3">
              <label className="text-[10px] font-black text-[#2d4a3e]/40 uppercase tracking-[0.2em] ml-1">{strings.lobby.chooseColor}</label>
              <div className="flex flex-wrap gap-3 justify-center">
                {availableColors.map(color => (
                  <button 
                    key={color} 
                    onClick={() => setSelectedColor(color)}
                    className={`w-10 h-10 rounded-full border-2 transition-all active:scale-90 ${selectedColor === color ? 'border-[#1a261a] scale-110 shadow-lg' : 'border-transparent opacity-60'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full py-5 btn-gear text-xl tracking-tight uppercase">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#d9e0d2] text-[#1a261a] overflow-hidden flex flex-col relative selection:bg-[#a47e3c]/30">
      <FlyingWordsBackground />

      {/* Soft Forest Glows */}
      <div className="fixed -top-40 -left-40 w-[600px] h-[600px] bg-[#2d4a3e]/5 blur-[120px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-40 -right-40 w-[600px] h-[600px] bg-[#8b4513]/5 blur-[120px] rounded-full pointer-events-none"></div>

      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col items-center relative py-12 px-8 z-10 gap-32 overflow-y-auto scroll-smooth-touch">

        {/* HERO SECTION */}
        <section className="w-full flex flex-col items-center gap-16 py-12">
            <div className="flex flex-col items-center select-none text-center">
                <AnimationVariantSwapT fontSize="clamp(1.5rem, 6vw, 4rem)" />
                <div className="bg-[#a47e3c] text-[#f1f3f0] border-2 border-[#1a261a] px-8 py-2 rounded-xl font-black tracking-[0.2em] text-[10px] md:text-xs mt-[-1rem] z-20 uppercase shadow-lg transform rotate-1 cursor-default">
                  {strings.home.title}
                </div>
            </div>

            <div className="max-w-2xl text-center space-y-12">
              <p className="text-3xl md:text-5xl text-[#1a261a] leading-tight font-black tracking-tight">
                {strings.home.subtitle}
              </p>

              <div className="flex flex-col sm:flex-row gap-6 justify-center w-full max-w-xl mx-auto">
                <button 
                  onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} 
                  className="px-12 py-6 btn-gear text-xl uppercase tracking-widest flex-1"
                >
                  {strings.home.designTrail}
                </button>
                <button 
                  onClick={() => setView('JOIN')} 
                  className="px-12 py-6 bg-[#2d4a3e] text-[#f1f3f0] border-2 border-[#1a261a] rounded-[1.25rem] font-black text-xl hover:bg-[#1a261a] transition-all uppercase tracking-widest flex-1 shadow-lg"
                >
                  {strings.home.joinQuest}
                </button>
              </div>
            </div>

            <div className="w-full max-w-3xl flex items-center justify-center pt-8">
               <div className="relative w-full max-w-xl aspect-[16/10] bg-[#f1f3f0] rounded-[2.5rem] border-4 border-[#1a261a] p-4 shadow-2xl group overflow-hidden">
                  <div className="relative w-full h-full rounded-[1.8rem] overflow-hidden border border-[#1a261a]/10 bg-[#d9e0d2]">
                     <img 
                        src="https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=1200" 
                        className="w-full h-full object-cover opacity-90 transition-all duration-[3s] group-hover:scale-105 group-hover:opacity-100" 
                        alt="Forest Morning"
                     />
                     <div className="absolute inset-0 bg-[#2d4a3e]/10 group-hover:bg-transparent transition-colors"></div>
                  </div>

                  <div className="absolute bottom-6 right-6 w-24 h-24 bg-[#a47e3c] rounded-2xl shadow-xl flex items-center justify-center rotate-6 border-4 border-[#1a261a] text-[#f1f3f0] group-hover:rotate-0 transition-all">
