const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [selectedColor, setSelectedColor] = useState('#2d4a3e');

  const availableColors = [
    '#2d4a3e', '#8b4513', '#4a646c', '#ca8a04', '#7c2d12', 
    '#0f766e', '#1a261a', '#6b705c', '#5d2e0d', '#27272a'
  ];

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        const newState = event.data.state as GameState;
        setGameState(newState);

        if (currentPlayer && !newState.players.find(p => p.id === currentPlayer.id) && !isHost) {
          alert(strings.lobby.kickedDesc);
          setCurrentPlayer(null);
          setView('HOME');
          localStorage.removeItem('locateit_last_player_id');
          return;
        }

        if (newState.status === 'PLAYING' || newState.status === 'COUNTDOWN' || newState.status === 'RESULTS') {
          setView('PLAYING');
        }
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, [currentPlayer, isHost]);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

      if (existingIndex > -1) {
        trails[existingIndex] = trailToSave;
      } else {
        trails.push(trailToSave);
      }

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      console.error("Save failed:", e);
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const savedPlayerId = localStorage.getItem('locateit_last_player_id');
      const existingPlayer = gameState.players.find(p => p.id === savedPlayerId);

      if (existingPlayer) {
        setCurrentPlayer(existingPlayer);
        setIsHost(false);
        if (gameState.status === 'LOBBY') setView('LOBBY');
        else if (['PLAYING', 'COUNTDOWN', 'RESULTS'].includes(gameState.status)) setView('PLAYING');
        else setView('HOME');
        return;
      }

      const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', newPlayer.id);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. Ensure the Host has the lobby open in another tab.");
    }
  };

  const handleKickPlayer = (playerId: string) => {
    if (!gameState || !isHost) return;
    const updatedPlayers = gameState.players.filter(p => p.id !== playerId);
    updateGameState({ ...gameState, players: updatedPlayers });
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { setGameState(null); setView('DASHBOARD'); }} onKick={handleKickPlayer} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) {
          newState.status = 'COUNTDOWN';
        }
        updateGameState(newState);
      }} 
      onCountdownFinish={() => {
        if (isHost && gameState.status === 'COUNTDOWN') {
          updateGameState({ ...gameState, status: 'RESULTS' });
        }
      }}
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#d9e0d2]">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-[#2d4a3e] hover:text-[#1a261a] flex items-center font-semibold text-sm opacity-60 hover:opacity-100 transition-opacity">
           <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
           {strings.join.back}
        </button>
        <div className="bg-[#f1f3f0]/90 backdrop-blur-xl rounded-[2.5rem] p-12 border border-black/5 shadow-2xl">
          <h2 className="text-3xl font-black text-[#1a261a] mb-10 text-center tracking-tight uppercase">{strings.join.title}</h2>
          <div className="space-y-6">
            <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-8 py-5 bg-white/50 border border-black/5 rounded-2xl outline-none focus:border-[#2d4a3e] uppercase font-bold text-center tracking-[0.2em] text-xl text-[#1a261a] placeholder:opacity-20 transition-all" />
            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-8 py-5 bg-white/50 border border-black/5 rounded-2xl outline-none focus:border-[#2d4a3e] text-[#1a261a] font-bold placeholder:opacity-20 transition-all" />

            <div className="space-y-4 pt-2">
              <label className="text-[10px] font-bold text-[#1a261a]/40 uppercase tracking-[0.3em] ml-2">{strings.lobby.chooseColor}</label>
              <div className="flex flex-wrap gap-3 justify-center">
                {availableColors.map(color => (
                  <button 
                    key={color} 
                    onClick={() => setSelectedColor(color)}
                    className={`w-10 h-10 rounded-full transition-all active:scale-90 ${selectedColor === color ? 'ring-4 ring-[#2d4a3e]/20 scale-110 shadow-lg border-2 border-white' : 'opacity-40 hover:opacity-100'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full py-5 btn-modern btn-modern-primary text-lg mt-4">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#d9e0d2] text-[#1a261a] overflow-hidden flex flex-col relative selection:bg-[#a47e3c]/20">
      <FlyingWordsBackground />

      {/* Dynamic Nature Ambiance */}
      <div className="fixed -top-60 -left-60 w-[800px] h-[800px] bg-[#2d4a3e]/10 blur-[160px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-60 -right-60 w-[800px] h-[800px] bg-[#8b4513]/5 blur-[160px] rounded-full pointer-events-none"></div>

      <main className="flex-1 max-w-7xl mx-auto w-full flex flex-col items-center relative py-16 px-8 z-10 gap-24 overflow-y-auto scroll-smooth-touch">

        {/* REFINED HERO SECTION */}
        <section className="w-full flex flex-col items-center gap-20 py-12">
            <div className="flex flex-col items-center select-none text-center">
                <AnimationVariantSwapT fontSize="clamp(1.2rem, 5vw, 3.5rem)" />
                <div className="bg-[#f1f3f0] text-[#a47e3c] border border-black/5 px-8 py-2 rounded-full font-bold tracking-[0.4em] text-[10px] mt-[-1rem] z-20 uppercase shadow-sm">
                  {strings.home.title}
                </div>
            </div>

            <div className="max-w-3xl text-center space-y-12">
              <h1 className="text-4xl md:text-7xl text-[#1a261a] leading-[1.1] font-black tracking-tight">
                {strings.home.subtitle}
              </h1>

              <div className="flex flex-col sm:flex-row gap-8 justify-center w-full max-w-2xl mx-auto px-4">
                <button 
                  onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} 
                  className="px-14 py-7 btn-modern btn-modern-secondary text-lg flex-1"
                >
                  {strings.home.designTrail}
                </button>
                <button 
                  onClick={() => setView('JOIN')} 
                  className="px-14 py-7 btn-modern btn-modern-primary text-lg flex-1"
                >
                  {strings.home.joinQuest}
                </button>
              </div>
            </div>

            {/* MODERNIZED PREVIEW FRAME */}
            <div className="w-full max-w-5xl flex items-center justify-center pt-8">
               <div className="relative w-full max-w-4xl aspect-[21/10] bg-[#f1f3f0]/50 backdrop-blur-md rounded-[4rem] border border-white/40 p-3 shadow-2xl group overflow-hidden">
                  <div className="relative w-full h-full rounded-[3.2rem] overflow-hidden border border-black/5">
                     <img 
                        src="https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&q=80&w=1600" 
                        className="w-full h-full object-cover transition-all duration-[4s] ease-out group-hover:scale-110" 
                        alt="Serene Forest View"
                     />
                     <div className="absolute inset-0 bg-gradient-to-t from-[#2d4a3e]/20 to-transparent"></div>
