                     <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z" />
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 11a3 3 0 11-6 0 3 3 0 016 0z" />
                     </svg>
                  </div>
               </div>
            </div>
        </section>

        {/* REFINED MINIMAL UTILITY CARDS */}
        <section className="w-full max-w-6xl grid grid-cols-1 md:grid-cols-2 gap-10 pb-32">
            <div className="bg-[#f1f3f0]/30 backdrop-blur-md p-14 rounded-[3rem] border border-white/40 flex items-center gap-10 hover:bg-[#f1f3f0]/60 transition-all duration-500 group">
                <div className="shrink-0 w-16 h-16 bg-[#2d4a3e] rounded-2xl flex items-center justify-center text-[#f1f3f0] shadow-xl group-hover:rotate-6 transition-transform">
