            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 text-[#0f1a16] font-bold placeholder:opacity-20 transition-all" />

            <div className="space-y-4 pt-2">
              <label className="text-[10px] font-bold text-[#0f1a16]/30 uppercase tracking-[0.4em] ml-2">{strings.lobby.chooseColor}</label>
              <div className="flex flex-wrap gap-4 justify-center">
                {availableColors.map(color => (
                  <button 
                    key={color} 
                    onClick={() => setSelectedColor(color)}
                    className={`w-10 h-10 rounded-full transition-all active:scale-90 ${selectedColor === color ? 'ring-4 ring-[#0f1a16]/10 scale-110 shadow-lg border-2 border-white' : 'opacity-30 hover:opacity-100'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full py-5 btn-sleek btn-sleek-pine text-base mt-6">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#f9fbfa] text-[#0f1a16] overflow-hidden flex flex-col relative selection:bg-[#8c6b4f]/20">
      <FlyingWordsBackground />

      {/* Soft Nordic Glows */}
      <div className="fixed -top-80 -left-60 w-[1000px] h-[1000px] bg-[#2d4239]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-80 -right-60 w-[1000px] h-[1000px] bg-[#8c6b4f]/5 blur-[180px] rounded-full pointer-events-none"></div>

      <main className="flex-1 max-w-7xl mx-auto w-full flex flex-col items-center relative py-20 px-8 z-10 gap-28 overflow-y-auto scroll-smooth-touch">

        {/* MODERN HERO SECTION */}
        <section className="w-full flex flex-col items-center gap-24 py-12">
            <div className="flex flex-col items-center select-none text-center">
                <AnimationVariantSwapT fontSize="clamp(1.2rem, 5vw, 3rem)" />
                <div className="text-[#8c6b4f] font-bold tracking-[0.6em] text-[10px] mt-6 z-20 uppercase opacity-60">
                  {strings.home.title}
                </div>
            </div>

            <div className="max-w-4xl text-center space-y-16">
              <h1 className="text-5xl md:text-8xl text-[#0f1a16] leading-[1] font-black tracking-tight">
                {strings.home.subtitle}
              </h1>

              <div className="flex flex-col sm:flex-row gap-10 justify-center w-full max-w-2xl mx-auto px-4">
                <button 
                  onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} 
                  className="px-16 py-8 btn-sleek btn-sleek-oak text-base flex-1"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
