import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';

    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;

    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  const ensureLocation = useCallback(async (): Promise<Location> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve({ lat: 51.505, lng: -0.09 });
        return;
      }

      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          setCurrentLocation(loc);
          if (!watchId.current) {
            watchId.current = navigator.geolocation.watchPosition(
              (p) => setCurrentLocation({ lat: p.coords.latitude, lng: p.coords.longitude }),
              undefined,
              { enableHighAccuracy: true }
            );
          }
          resolve(loc);
        },
        () => resolve({ lat: 51.505, lng: -0.09 }),
        { enableHighAccuracy: true, timeout: 5000 }
      );
    });
  }, []);

  useEffect(() => {
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, []);

  const stopCamera = useCallback(() => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const [stream] = await Promise.all([
        navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1920 } } }),
        ensureLocation()
      ]);

      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(() => {});
        }
      }, 100);
    } catch (err) { 
      setError(strings.creator.cameraError); 
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;

    setIsProcessing(true);
    setIsFlashing(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);

        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = currentLocation ? 'GPS' : 'DEFAULT';

        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } catch (e) {
      setError(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);

    const locPromise = ensureLocation();

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = parseFloat(tags.GPSLatitude.description);
            const parsedLng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
              lat = parsedLat;
              lng = parsedLng;
              source = 'IMAGE';
            }
          }
        } catch (exifErr) { console.warn("EXIF extraction failed:", exifErr); }

        const currentLoc = await locPromise;

        if (source !== 'IMAGE' || lat === null || lng === null) {
          source = currentLoc ? 'GPS' : 'DEFAULT';
        }

        const finalLoc = (lat !== null && lng !== null && !isNaN(lat) && !isNaN(lng)) 
          ? { lat, lng } 
          : (currentLoc || { lat: 51.505, lng: -0.09 });

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError(strings.creator.uploadError); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;

    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) 
      }]);
    }
    setPendingQuestion(null);
  };

  const handleDelete = () => {
    if (confirmDelete) {
      setQuestions(prev => prev.filter(q => q.id !== confirmDelete));
      setConfirmDelete(null);
    }
  };

  const handleCancelClick = () => {
    if (hasChanges) {
      setShowExitConfirm(true);
    } else {
      onCancel();
    }
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
      const next = [...prev];
      const targetIdx = direction === 'up' ? index - 1 : index + 1;
      if (targetIdx < 0 || targetIdx >= next.length) return prev;
      [next[index], next[targetIdx]] = [next[targetIdx], next[index]];
      return next;
    });
  };

  if (showExitConfirm) {
    return (
      <div className="fixed inset-0 z-[400] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
        <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-[#ca8a04]/10 text-[#ca8a04] rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
          <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
          <div className="flex gap-4">
            <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
            <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
          </div>
        </div>
      </div>
    );
  }

  if (confirmDelete) {
    return (
      <div className="fixed inset-0 z-[400] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
        <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-[#7c2d12]/10 text-[#7c2d12] rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </div>
          <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
          <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
          <div className="flex gap-4">
            <button onClick={() => setConfirmDelete(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
            <button onClick={handleDelete} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
          </div>
        </div>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-black/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em]">{pendingQuestion.editingId ? strings.creator.editSpot : strings.creator.tagSpot}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-[#0f1a16]/40 font-bold uppercase text-[10px] tracking-widest px-4 py-2 hover:text-[#0f1a16] transition-colors">{strings.common.back}</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-24 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-6 flex items-center justify-center bg-black/5">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="bg-white p-6 rounded-[2rem] border border-black/5 shadow-sm flex justify-between items-center">
                <div className="flex-1 pr-2">
                    <p className="text-[9px] font-black text-[#8c6b4f] uppercase tracking-[0.3em] mb-1">{strings.creator.verifyLocation}</p>
                    <p className="text-sm text-[#0f1a16]/60 font-medium">{strings.creator.tapToRefine}</p>
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[8px] bg-[#0f1a16] text-white px-2 py-1 rounded-full font-black uppercase mb-1 tracking-widest">{pendingQuestion.source}</span>
                </div>
             </div>
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !text-lg !tracking-widest">{strings.creator.confirmMarker}</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-black flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-12 flex justify-between items-center bg-gradient-to-t from-black/80 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-white/30 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-slate-100"></div>}
          </button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-black/5">
        <div className="max-w-4xl mx-auto flex justify-between items-start">
          <div className="flex-1 mr-4">
            <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase" />
            <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em] mt-2">{strings.creator.spotsInTrail(questions.length)}</p>
          </div>
          <button onClick={handleCancelClick} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm">{strings.common.cancel}</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-6 overflow-y-auto pb-40 scroll-smooth-touch">
        {error && <div className="bg-[#7c2d12]/10 border border-[#7c2d12]/20 p-5 rounded-[2rem] text-[#7c2d12] text-xs font-bold text-center uppercase tracking-widest">{error}</div>}

        <div className="grid grid-cols-2 gap-6">
          <button onClick={startCamera} className="flex flex-col items-center justify-center space-y-4 bg-white border border-black/5 hover:border-[#0f1a16]/20 py-10 rounded-[3rem] transition-all group shadow-sm">
            <div className="p-4 bg-[#f9fbfa] rounded-3xl group-hover:scale-110 transition-transform shadow-inner"><svg className="w-8 h-8 text-[#0f1a16]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-black text-[10px] uppercase tracking-[0.3em]">{strings.creator.takePhoto}</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-4 bg-white border border-black/5 hover:border-[#0f1a16]/20 py-10 rounded-[3rem] transition-all group shadow-sm">
            <div className="p-4 bg-[#f9fbfa] rounded-3xl group-hover:scale-110 transition-transform shadow-inner"><svg className="w-8 h-8 text-[#8c6b4f]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div>
            <span className="font-black text-[10px] uppercase tracking-[0.3em]">{strings.creator.uploadImage}</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-4 mt-12">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-white rounded-[2.5rem] border border-black/5 p-4 flex items-center space-x-6 shadow-sm hover:shadow-md transition-shadow">
              <img src={q.imageUrl} className="w-20 h-20 rounded-[1.5rem] object-cover border border-black/5 shadow-sm" />
              <div className="flex-1 min-w-0">
                <input type="text" value={q.title || ''} onChange={(e) => setQuestions(prev => prev.map(item => item.id === q.id ? { ...item, title: e.target.value } : item))} className="bg-transparent border-none p-0 text-lg font-black tracking-tight uppercase focus:ring-0 w-full mb-1" />
                <button onClick={() => setPendingQuestion({ imageUrl: q.imageUrl, location: q.location, originalLocation: q.location, editingId: q.id, title: q.title, source: q.locationSource || 'MANUAL' })} className="text-[9px] text-[#8c6b4f] font-black uppercase tracking-[0.3em] hover:opacity-70 transition-opacity">{strings.creator.editPin}</button>
              </div>
              <div className="flex items-center space-x-3">
                <div className="flex flex-col opacity-20">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 hover:opacity-100 disabled:opacity-0"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 hover:opacity-100 disabled:opacity-0"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
                <button onClick={() => setConfirmDelete(q.id)} className="p-4 bg-[#7c2d12]/5 text-[#7c2d12] rounded-2xl transition-all hover:bg-[#7c2d12] hover:text-white"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-8 bg-white/70 backdrop-blur-xl border-t border-black/5 z-40">
        <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName)} className={`w-full max-w-4xl mx-auto block py-6 btn-sleek !text-xl !tracking-[0.2em] ${questions.length > 0 ? 'btn-sleek-pine' : 'bg-[#f9fbfa] text-[#0f1a16]/10 cursor-not-allowed shadow-none'}`}>{strings.creator.finalize}</button>
      </footer>
      {isProcessing && (
        <div className="fixed inset-0 z-[300] bg-[#f9fbfa]/80 backdrop-blur-xl flex items-center justify-center p-6 text-center">
          <div className="bg-white p-10 rounded-[3rem] flex flex-col items-center space-y-6 border border-black/5 shadow-2xl">
            <div className="w-12 h-12 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div>
            <p className="font-black uppercase tracking-[0.4em] text-[10px] text-[#0f1a16]">{strings.creator.optimizingMedia}</p>
          </div>
        </div>
      )}
    </div>
  );
};

