import React, { useState, useEffect } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onCountdownFinish: () => void;
  onNext: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ gameState, isHost, currentPlayer, onGuess, onCountdownFinish, onNext }) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  useEffect(() => {
    setHasSubmitted(false);
    setSelectedGuess(null);
    setCountdownValue(3);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (gameState.status === 'COUNTDOWN') {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [gameState.status, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
      setHasSubmitted(true);
    }
  };

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isGameFinished = gameState.status === 'FINISHED';

  const sortedPlayers = [...gameState.players].sort((a, b) => b.score - a.score);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(15,26,22,0.15)] w-full max-w-md border border-black/5">
          <div className="space-y-6">
            {sortedPlayers.map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all ${idx === 0 ? 'bg-[#ca8a04]/5 ring-2 ring-[#ca8a04]/10' : 'bg-[#f9fbfa]'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-sm">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#0f1a16] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button 
            onClick={() => window.location.reload()}
            className="w-full mt-12 btn-sleek btn-sleek-pine !py-6"
          >
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden selection:bg-[#8c6b4f]/20">
      {isCountingDown && (
        <div className="fixed inset-0 z-[600] bg-[#0f1a16]/40 backdrop-blur-3xl flex flex-col items-center justify-center text-white">
           <p className="text-white/60 font-black uppercase tracking-[0.6em] text-[10px] mb-6">{strings.game.countdownTitle}</p>
           <div className="text-9xl font-black animate-pulse">{countdownValue}</div>
        </div>
      )}

      <div className="w-full md:w-1/2 h-1/2 md:h-full flex flex-col p-6 space-y-6">
        <div className="bg-white/70 backdrop-blur-xl rounded-[2.5rem] p-5 shadow-sm border border-black/5 flex justify-between items-center">
          <div className="font-black text-[10px] uppercase tracking-[0.4em] opacity-40">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="flex items-center space-x-6">
             <div className="flex -space-x-3">
                {gameState.players.map(p => (
                  <div 
                    key={p.id} 
                    className={`w-8 h-8 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black text-white shadow-sm transition-all ${p.hasGuessed ? 'scale-110 opacity-100' : 'scale-90 opacity-10'}`}
                    style={{ backgroundColor: p.color }}
                  >
                    {p.name.charAt(0)}
                  </div>
                ))}
             </div>
             <div className="font-black text-[#0f1a16] text-sm uppercase tracking-tight">{strings.game.points(currentPlayer?.score || 0)}</div>
          </div>
        </div>

        <div className="flex-1 relative rounded-[3rem] overflow-hidden bg-white/40 border border-black/5 shadow-2xl group">
          <img src={currentQ.imageUrl} className="w-full h-full object-contain transition-transform duration-[10s] group-hover:scale-110" alt="Guess this location" />

          {isRoundFinished && (
            <div className="absolute inset-0 bg-white/40 backdrop-blur-xl flex flex-col items-center justify-center p-8 text-center text-[#0f1a16]">
              <h2 className="text-3xl font-black mb-8 uppercase tracking-tight">{strings.game.roundResults}</h2>
              <div className="space-y-4 w-full max-w-sm">
                {gameState.players.map(p => (
                   <div key={p.id} className="flex justify-between items-center bg-white p-4 rounded-[1.5rem] shadow-sm border border-black/5">
                     <div className="flex items-center space-x-4">
                        <div className="w-4 h-4 rounded-full shadow-inner" style={{ backgroundColor: p.color }} />
                        <span className="font-black uppercase tracking-tight text-xs">{p.name}</span>
                     </div>
                     <span className="font-bold text-xs tracking-widest opacity-40">{p.lastDistance ? formatDistance(p.lastDistance) : strings.game.noGuess}</span>
                   </div>
                ))}
              </div>
              {isHost && (
                <button 
                  onClick={onNext}
                  className="mt-10 btn-sleek btn-sleek-pine !px-12 !py-5"
                >
                  {strings.game.nextLocation} &rarr;
                </button>
              )}
            </div>
          )}
        </div>
      </div>

      <div className="w-full md:w-1/2 h-1/2 md:h-full p-6 md:pl-0 flex flex-col space-y-6">
        <div className="flex-1 relative bg-white rounded-[3.5rem] shadow-[0_40px_80px_-20px_rgba(15,26,22,0.1)] border border-black/5 overflow-hidden">
          <Map 
            onLocationSelect={isRoundFinished ? undefined : setSelectedGuess}
            markers={[
              ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
              ...(isRoundFinished ? [{ position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const }] : []),
              ...(isRoundFinished ? gameState.players.filter(p => p.lastGuess).map(p => ({ 
                  position: p.lastGuess!, 
                  label: `${p.name}'s guess`,
                  icon: 'user' as const,
                  color: p.color
                })) : [])
            ]}
            lines={isRoundFinished ? gameState.players.filter(p => p.lastGuess).map(p => ({
              from: p.lastGuess!,
              to: currentQ.location,
              color: p.color
            })) : []}
            center={currentQ.location}
            zoom={12}
          />

          {!isRoundFinished && !hasSubmitted && (
            <div className="absolute bottom-8 inset-x-0 flex justify-center px-6">
              <button 
                disabled={!selectedGuess}
                onClick={handleGuessSubmit}
                className={`w-full max-w-xs py-5 btn-sleek !text-lg !tracking-widest ${selectedGuess ? 'btn-sleek-pine' : 'bg-white/80 text-[#0f1a16]/10 shadow-none cursor-not-allowed'}`}
              >
                {strings.game.submitGuess}
              </button>
            </div>
          )}

          {!isRoundFinished && hasSubmitted && !isCountingDown && (
             <div className="absolute bottom-8 inset-x-0 flex justify-center px-6">
               <div className="bg-white/80 backdrop-blur-xl shadow-2xl px-10 py-5 rounded-[2rem] border border-black/5 flex items-center space-x-5">
                 <div className="w-2.5 h-2.5 rounded-full bg-[#0f1a16] animate-ping"></div>
                 <span className="font-black text-[10px] uppercase tracking-[0.4em]">{strings.game.waitingPlayers}</span>
               </div>
             </div>
          )}
        </div>

        <div className="hidden md:flex justify-center p-2">
           <div className="text-[9px] text-[#0f1a16]/20 font-black uppercase tracking-[0.3em]">{strings.game.precisionTip}</div>
        </div>
      </div>
    </div>
  );
};

export default GameBoard;

import React, { useState, useEffect, useMemo } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';

const gameChannel = new BroadcastChannel('locateit_sync');

const FlyingWordsBackground: React.FC = () => {
  const words = useMemo(() => {
    const palette = [
      '#2d4239', // Nordic Green
      '#8c6b4f', // Oak
      '#b4c4bc', // Mist Sage
      '#4a5d55', // Slate Forest
    ];

    return Array.from({ length: 20 }).map((_, i) => ({
      id: i,
      text: i % 2 === 0 ? 'HERE' : 'THERE',
      top: `${Math.random() * 100}%`,
      duration: `${45 + Math.random() * 35}s`,
      delay: `${-Math.random() * 60}s`,
      size: `${0.8 + Math.random() * 4}rem`,
      color: palette[Math.floor(Math.random() * palette.length)],
      opacity: 0.02 + Math.random() * 0.03,
    }));
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none overflow-hidden z-0">
      {words.map(w => (
        <div 
          key={w.id}
          className="flying-word fixed z-0 pointer-events-none whitespace-nowrap uppercase font-medium select-none"
          style={{
            top: w.top,
            fontSize: w.size,
            color: w.color,
            opacity: w.opacity,
            animation: `subtle-drift ${w.duration} linear infinite`,
            animationDelay: w.delay
          }}
        >
          {w.text}
        </div>
      ))}
    </div>
  );
};

const AnimationVariantSwapT: React.FC<{ fontSize?: string }> = ({ fontSize = '3rem' }) => {
  const [showLeftT, setShowLeftT] = useState(true);

  useEffect(() => {
    const interval = setInterval(() => {
      setShowLeftT(prev => !prev);
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="glacial-capsule">
      <div className="flex items-center" style={{ fontSize }}>
        <div className="swap-t-word">
          <span className={`t-char text-[#0f1a16] ${showLeftT ? 't-visible' : 't-hidden'}`}>T</span>
          <span className="text-[#0f1a16]">HERE</span>
        </div>
        <div className="text-[#0f1a16]/10 font-light mx-4 md:mx-10 select-none tracking-[0.4em]">&</div>
        <div className="swap-t-word">
          <span className={`t-char text-[#8c6b4f] ${!showLeftT ? 't-visible' : 't-hidden'}`}>T</span>
          <span className="text-[#8c6b4f]">HERE</span>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [gameState, setGameState] = useState<GameState | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);

  // Vivid, distinct colors for pins
  const availableColors = [
    '#6366f1', // Indigo
    '#f43f5e', // Rose
    '#10b981', // Emerald
    '#f59e0b', // Amber
    '#06b6d4', // Cyan
    '#d946ef', // Fuchsia
    '#8b5cf6', // Violet
    '#f97316', // Orange
  ];
  const [selectedColor, setSelectedColor] = useState(availableColors[0]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }

    const handleMessage = (event: MessageEvent) => {
      if (event.data.type === 'STATE_UPDATE') {
        const newState = event.data.state as GameState;
        setGameState(newState);

        if (currentPlayer && !newState.players.find(p => p.id === currentPlayer.id) && !isHost) {
          alert(strings.lobby.kickedDesc);
          setCurrentPlayer(null);
          setView('HOME');
          localStorage.removeItem('locateit_last_player_id');
          return;
        }

        if (newState.status === 'PLAYING' || newState.status === 'COUNTDOWN' || newState.status === 'RESULTS') {
          setView('PLAYING');
        }
      }
    };
    gameChannel.onmessage = handleMessage;
    return () => { gameChannel.onmessage = null; };
  }, [currentPlayer, isHost]);

  const updateGameState = (newState: GameState) => {
    setGameState(newState);
    gameChannel.postMessage({ type: 'STATE_UPDATE', state: newState });
  };

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;

    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const existingIndex = trails.findIndex(t => t.id === trailToSave.id);

      if (existingIndex > -1) {
        trails[existingIndex] = trailToSave;
      } else {
        trails.push(trailToSave);
      }

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      console.error("Save failed:", e);
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    const newGameState: GameState = {
      id: generateId(),
      status: 'LOBBY',
      questions: trail.questions,
      currentQuestionIndex: 0,
      players: [],
      hostId: user.id,
    };
    setIsHost(true);
    setCurrentPlayer(null);
    updateGameState(newGameState);
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const savedPlayerId = localStorage.getItem('locateit_last_player_id');
      const existingPlayer = gameState.players.find(p => p.id === savedPlayerId);

      if (existingPlayer) {
        setCurrentPlayer(existingPlayer);
        setIsHost(false);
        if (gameState.status === 'LOBBY') setView('LOBBY');
        else if (['PLAYING', 'COUNTDOWN', 'RESULTS'].includes(gameState.status)) setView('PLAYING');
        else setView('HOME');
        return;
      }

      const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
      const newState = { ...gameState, players: [...gameState.players, newPlayer] };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', newPlayer.id);
      updateGameState(newState);
      setView('LOBBY');
    } else {
      alert("Game code not found. Ensure the Host has the lobby open in another tab.");
    }
  };

  const handleKickPlayer = (playerId: string) => {
    if (!gameState || !isHost) return;
    const updatedPlayers = gameState.players.filter(p => p.id !== playerId);
    updateGameState({ ...gameState, players: updatedPlayers });
  };

  if (view === 'AUTH') return <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />;
  if (view === 'DASHBOARD' && user) return <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />;
  if (view === 'CREATE') return <QuizCreator initialTrail={editingTrail || undefined} onComplete={handleSaveTrail} onCancel={() => setView('DASHBOARD')} />;
  if (view === 'LOBBY' && gameState) return <Lobby gameState={gameState} isHost={isHost} onStart={() => updateGameState({ ...gameState, status: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { setGameState(null); setView('DASHBOARD'); }} onKick={handleKickPlayer} />;

  if (view === 'PLAYING' && gameState) return (
    <GameBoard 
      gameState={gameState} 
      isHost={isHost} 
      currentPlayer={currentPlayer} 
      onGuess={(guess) => {
        if (!currentPlayer) return;
        const currentQ = gameState.questions[gameState.currentQuestionIndex];
        const distance = calculateDistance(guess, currentQ.location);
        const updatedPlayers = gameState.players.map(p => p.id === currentPlayer.id ? { ...p, hasGuessed: true, lastGuess: guess, lastDistance: distance } : p);
        const newState = { ...gameState, players: updatedPlayers };
        if (updatedPlayers.every(p => p.hasGuessed)) {
          newState.status = 'COUNTDOWN';
        }
        updateGameState(newState);
      }} 
      onCountdownFinish={() => {
        if (isHost && gameState.status === 'COUNTDOWN') {
          updateGameState({ ...gameState, status: 'RESULTS' });
        }
      }}
      onNext={() => {
        const sortedPlayers = [...gameState.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
        const updatedPlayers = gameState.players.map(p => {
          const rank = sortedPlayers.findIndex(sp => sp.id === p.id);
          const pointsGained = Math.max(0, gameState.players.length - rank);
          return { ...p, score: p.score + pointsGained, hasGuessed: false, lastGuess: undefined, lastDistance: undefined };
        });
        const isLast = gameState.currentQuestionIndex === gameState.questions.length - 1;
        updateGameState({ 
          ...gameState, 
          players: updatedPlayers, 
          currentQuestionIndex: isLast ? gameState.currentQuestionIndex : gameState.currentQuestionIndex + 1, 
          status: isLast ? 'FINISHED' : 'PLAYING' 
        });
      }} 
    />
  );

  if (view === 'JOIN') return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#f9fbfa]">
      <div className="max-w-md w-full">
        <button onClick={() => setView('HOME')} className="mb-8 text-[#0f1a16]/40 hover:text-[#0f1a16] flex items-center font-bold text-xs uppercase tracking-widest transition-all">
           <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
           {strings.join.back}
        </button>
        <div className="bg-white rounded-[3rem] p-12 border border-black/5 shadow-[0_40px_80px_-15px_rgba(15,26,22,0.1)]">
          <h2 className="text-3xl font-black text-[#0f1a16] mb-10 text-center tracking-tight uppercase">{strings.join.title}</h2>
          <div className="space-y-6">
            <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 uppercase font-bold text-center tracking-[0.3em] text-xl text-[#0f1a16] placeholder:opacity-20 transition-all" />
            <input id="playerName" placeholder={strings.join.yourName} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 text-[#0f1a16] font-bold placeholder:opacity-20 transition-all" />

            <div className="space-y-4 pt-2">
              <label className="text-[10px] font-bold text-[#0f1a16]/30 uppercase tracking-[0.4em] ml-2">{strings.lobby.chooseColor}</label>
              <div className="flex flex-wrap gap-4 justify-center">
                {availableColors.map(color => (
                  <button 
                    key={color} 
                    onClick={() => setSelectedColor(color)}
                    className={`w-10 h-10 rounded-full transition-all active:scale-90 ${selectedColor === color ? 'ring-4 ring-black/10 scale-110 shadow-lg border-2 border-white' : 'opacity-40 hover:opacity-100'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            </div>

            <button onClick={() => {
              const code = (document.getElementById('gameCode') as HTMLInputElement).value;
              const name = (document.getElementById('playerName') as HTMLInputElement).value;
              if (code && name) handleJoinGame(code, name);
            }} className="w-full py-5 btn-sleek btn-sleek-pine text-base mt-6">
              {strings.join.joinLobby}
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  return (
    <div className="h-screen bg-[#f9fbfa] text-[#0f1a16] overflow-hidden flex flex-col relative selection:bg-[#8c6b4f]/20">
      <FlyingWordsBackground />

      {/* Subtle Nordic Ambiance */}
      <div className="fixed -top-80 -left-60 w-[1000px] h-[1000px] bg-[#2d4239]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-80 -right-60 w-[1000px] h-[1000px] bg-[#8c6b4f]/5 blur-[180px] rounded-full pointer-events-none"></div>

      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col items-center relative py-10 md:py-12 px-6 z-10 gap-8 md:gap-12 overflow-y-auto scroll-smooth-touch">

        {/* COMPACT LOGO */}
        <div className="flex flex-col items-center select-none text-center pt-2">
            <AnimationVariantSwapT fontSize="clamp(1.1rem, 4.5vw, 2.4rem)" />
        </div>

        {/* HERO CONTENT */}
        <section className="w-full max-w-3xl flex flex-col items-center gap-10 md:gap-14">
            <div className="w-full text-center flex flex-col items-center space-y-8">
              {/* Refined Glass Protection */}
              <div className="bg-white/45 backdrop-blur-md px-6 md:px-10 py-8 md:py-10 rounded-[2.5rem] border border-black/5 shadow-sm space-y-4 md:space-y-6">
                <h1 className="text-3xl md:text-6xl text-[#0f1a16] leading-[1.1] font-black tracking-tight">
                  {strings.home.subtitle}
                </h1>
                <p className="text-[#0f1a16]/60 text-sm md:text-base font-bold uppercase tracking-[0.2em] max-w-lg mx-auto">
                   Build unique trails & challenge your inner circle.
                </p>
              </div>

              {/* PRIMARY ACTIONS - ALWAYS VISIBLE */}
              <div className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center w-full max-w-xl mx-auto px-2 relative z-20">
                <button 
                  onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} 
                  className="px-8 py-5 md:py-6 btn-sleek btn-sleek-oak text-sm md:text-base flex-1"
                >
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                  {strings.home.designTrail}
                </button>
                <button 
                  onClick={() => setView('JOIN')} 
                  className="px-8 py-5 md:py-6 btn-sleek btn-sleek-pine text-sm md:text-base flex-1"
                >
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                  {strings.home.joinQuest}
                </button>
              </div>
            </div>

            {/* PREVIEW FRAME - COMPACT ON MOBILE */}
            <div className="w-full max-w-4xl flex items-center justify-center opacity-80 md:opacity-100">
               <div className="relative w-full aspect-[21/9] max-h-[220px] md:max-h-[320px] bg-white rounded-[2.5rem] md:rounded-[3.5rem] border border-black/5 p-2 md:p-3 shadow-2xl group overflow-hidden">
                  <div className="relative w-full h-full rounded-[2rem] md:rounded-[2.8rem] overflow-hidden border border-black/5">
                     <img 
                        src="https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&q=80&w=2000" 
                        className="w-full h-full object-cover grayscale-[10%] opacity-90 transition-all duration-[6s] ease-out group-hover:scale-105 group-hover:grayscale-0 group-hover:opacity-100" 
                        alt="Highland Pine Forest"
                     />
                     <div className="absolute inset-0 bg-gradient-to-b from-transparent via-black/5 to-black/20"></div>
                  </div>
               </div>
            </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { User, Trail } from '../types';
import { strings } from '../i18n';

interface DashboardProps {
  user: User;
  onNewTrail: () => void;
  onEditTrail: (trail: Trail) => void;
  onHostTrail: (trail: Trail) => void;
  onLogout: () => void;
}

const Dashboard: React.FC<DashboardProps> = ({ user, onNewTrail, onEditTrail, onHostTrail, onLogout }) => {
  const [trails, setTrails] = useState<Trail[]>([]);
  const [trailToDelete, setTrailToDelete] = useState<Trail | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem(`trails_${user.id}`);
    if (saved) {
      setTrails(JSON.parse(saved).sort((a: Trail, b: Trail) => b.lastUpdated - a.lastUpdated));
    }
  }, [user.id]);

  const confirmDelete = () => {
    if (trailToDelete) {
      const updated = trails.filter(t => t.id !== trailToDelete.id);
      setTrails(updated);
      localStorage.setItem(`trails_${user.id}`, JSON.stringify(updated));
      setTrailToDelete(null);
    }
  };

  return (
    <div className="min-h-screen bg-[#f9fbfa] text-[#0f1a16] p-6 flex flex-col selection:bg-[#8c6b4f]/20">
      {trailToDelete && (
        <div className="fixed inset-0 z-[500] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm text-center shadow-2xl">
            <div className="w-16 h-16 bg-[#7c2d12]/10 text-[#7c2d12] rounded-2xl flex items-center justify-center mx-auto mb-6">
              <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </div>
            <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.dashboard.deleteTrailTitle}</h3>
            <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.dashboard.deleteTrailDesc(trailToDelete.name, trailToDelete.questions.length)}</p>
            <div className="flex gap-4">
              <button onClick={() => setTrailToDelete(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
              <button onClick={confirmDelete} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
            </div>
          </div>
        </div>
      )}

      <header className="max-w-4xl w-full mx-auto flex justify-between items-center py-10">
        <div>
          <h1 className="text-3xl font-black tracking-tight uppercase text-[#0f1a16]">{strings.dashboard.title}</h1>
          <p className="text-[#8c6b4f] font-bold text-xs uppercase tracking-[0.4em] mt-1">{strings.dashboard.greeting(user.username)}</p>
        </div>
        <button onClick={onLogout} className="text-[10px] font-bold text-[#7c2d12] uppercase tracking-[0.4em] opacity-60 hover:opacity-100 transition-opacity">{strings.dashboard.logout}</button>
      </header>

      <main className="max-w-4xl w-full mx-auto flex-1 flex flex-col space-y-10 pb-12">
        <button 
          onClick={onNewTrail}
          className="w-full p-10 rounded-[3rem] border-2 border-dashed border-[#2d4239]/10 hover:border-[#2d4239]/40 hover:bg-[#2d4239]/5 transition-all flex flex-col items-center justify-center space-y-4 group shadow-sm bg-white"
        >
          <div className="w-16 h-16 rounded-3xl bg-[#2d4239] flex items-center justify-center text-white group-hover:scale-110 transition-transform shadow-xl">
             <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>
          </div>
          <span className="text-sm font-black uppercase tracking-[0.2em] text-[#2d4239]">{strings.dashboard.designNew}</span>
        </button>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {trails.map(trail => (
            <div key={trail.id} className="bg-white rounded-[3rem] p-8 border border-[#2d4239]/5 shadow-[0_20px_40px_-10px_rgba(45,66,57,0.05)] flex flex-col space-y-8 group hover:shadow-[0_40px_80px_-15px_rgba(45,66,57,0.1)] transition-all relative overflow-hidden">
              <div className="absolute top-0 right-0 p-4 opacity-[0.03] group-hover:opacity-[0.08] transition-opacity">
                <svg className="w-24 h-24 text-[#2d4239]" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2L4.5 20.29l.71.71L12 18l6.79 3 .71-.71L12 2z" /></svg>
              </div>
              <div className="flex justify-between items-start relative z-10">
                <div className="flex-1 min-w-0">
                  <span className="text-[9px] font-black text-[#8c6b4f] uppercase tracking-[0.4em]">{strings.dashboard.trailId(trail.id)}</span>
                  <h3 className="text-xl font-black truncate mt-1 uppercase tracking-tight text-[#0f1a16]">{trail.name || "Untitled Trail"}</h3>
                  <span className="text-[10px] text-[#2d4239]/60 font-bold uppercase tracking-widest">{strings.dashboard.spotsCount(trail.questions.length)}</span>
                </div>
                <button onClick={() => setTrailToDelete(trail)} className="text-[#0f1a16]/10 hover:text-[#7c2d12] transition-colors p-2">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </div>

              <div className="flex gap-4 relative z-10">
                <button onClick={() => onHostTrail(trail)} className="flex-1 py-4 btn-sleek btn-sleek-pine !bg-[#2d4239]">{strings.dashboard.startGame}</button>
                <button onClick={() => onEditTrail(trail)} className="flex-1 py-4 btn-sleek btn-sleek-oak !bg-white !text-[#8c6b4f] border border-[#8c6b4f]/10 !shadow-none hover:!bg-[#8c6b4f]/5">{strings.dashboard.edit}</button>
              </div>
            </div>
          ))}
        </div>

        {trails.length === 0 && (
          <div className="flex-1 flex flex-col items-center justify-center py-20 opacity-10 text-center">
            <svg className="w-20 h-20 mb-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg>
            <p className="font-bold uppercase tracking-widest text-sm">{strings.dashboard.noTrails}</p>
          </div>
        )}
      </main>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, initialTrail }) => {
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';

    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;

    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  const ensureLocation = useCallback(async (): Promise<Location> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) {
        resolve({ lat: 51.505, lng: -0.09 });
        return;
      }

      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          setCurrentLocation(loc);
          if (!watchId.current) {
            watchId.current = navigator.geolocation.watchPosition(
              (p) => setCurrentLocation({ lat: p.coords.latitude, lng: p.coords.longitude }),
              undefined,
              { enableHighAccuracy: true }
            );
          }
          resolve(loc);
        },
        () => resolve({ lat: 51.505, lng: -0.09 }),
        { enableHighAccuracy: true, timeout: 5000 }
      );
    });
  }, []);

  useEffect(() => {
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, []);

  const stopCamera = useCallback(() => {
    if (videoRef.current?.srcObject) {
      (videoRef.current.srcObject as MediaStream).getTracks().forEach(track => track.stop());
      videoRef.current.srcObject = null;
    }
    setIsCapturing(false);
  }, []);

  const startCamera = async () => {
    setError(null);
    try {
      const [stream] = await Promise.all([
        navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1920 } } }),
        ensureLocation()
      ]);

      setIsCapturing(true);
      setTimeout(() => {
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.setAttribute('playsinline', 'true');
          videoRef.current.play().catch(() => {});
        }
      }, 100);
    } catch (err) { 
      setError(strings.creator.cameraError); 
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;

    setIsProcessing(true);
    setIsFlashing(true);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);

        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = currentLocation ? 'GPS' : 'DEFAULT';

        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } catch (e) {
      setError(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);

    const locPromise = ensureLocation();

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null;
        let lng: number | null = null;
        let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            const parsedLat = parseFloat(tags.GPSLatitude.description);
            const parsedLng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
              lat = parsedLat;
              lng = parsedLng;
              source = 'IMAGE';
            }
          }
        } catch (exifErr) { console.warn("EXIF extraction failed:", exifErr); }

        const currentLoc = await locPromise;

        if (source !== 'IMAGE' || lat === null || lng === null) {
          source = currentLoc ? 'GPS' : 'DEFAULT';
        }

        const finalLoc = (lat !== null && lng !== null && !isNaN(lat) && !isNaN(lng)) 
          ? { lat, lng } 
          : (currentLoc || { lat: 51.505, lng: -0.09 });

        setIsProcessing(false);
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError(strings.creator.uploadError); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;

    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) 
      }]);
    }
    setPendingQuestion(null);
  };

  const handleDelete = () => {
    if (confirmDelete) {
      setQuestions(prev => prev.filter(q => q.id !== confirmDelete));
      setConfirmDelete(null);
    }
  };

  const handleCancelClick = () => {
    if (hasChanges) {
      setShowExitConfirm(true);
    } else {
      onCancel();
    }
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
      const next = [...prev];
      const targetIdx = direction === 'up' ? index - 1 : index + 1;
      if (targetIdx < 0 || targetIdx >= next.length) return prev;
      [next[index], next[targetIdx]] = [next[targetIdx], next[index]];
      return next;
    });
  };

  if (showExitConfirm) {
    return (
      <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
        <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-[#ca8a04]/10 text-[#ca8a04] rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
          <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
          <div className="flex gap-4">
            <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
            <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
          </div>
        </div>
      </div>
    );
  }

  if (confirmDelete) {
    return (
      <div className="fixed inset-0 z-[400] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
        <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-[#7c2d12]/10 text-[#7c2d12] rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </div>
          <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
          <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
          <div className="flex gap-4">
            <button onClick={() => setConfirmDelete(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
            <button onClick={handleDelete} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
          </div>
        </div>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">{pendingQuestion.editingId ? strings.creator.editSpot : strings.creator.tagSpot}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest px-4 py-2 hover:opacity-70 transition-colors">{strings.common.back}</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-24 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-6 flex items-center justify-center bg-[#2d4239]/5">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="bg-white p-6 rounded-[2rem] border border-[#2d4239]/5 shadow-sm flex justify-between items-center">
                <div className="flex-1 pr-2">
                    <p className="text-[9px] font-black text-[#8c6b4f] uppercase tracking-[0.3em] mb-1">{strings.creator.verifyLocation}</p>
                    <p className="text-sm text-[#0f1a16]/60 font-medium">{strings.creator.tapToRefine}</p>
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[8px] bg-[#2d4239] text-white px-2 py-1 rounded-full font-black uppercase mb-1 tracking-widest">{pendingQuestion.source}</span>
                </div>
             </div>
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !bg-[#2d4239] !text-lg !tracking-widest">{strings.creator.confirmMarker}</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#0f1a16] flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute inset-x-0 bottom-0 p-12 flex justify-between items-center bg-gradient-to-t from-black/80 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-white/30 shadow-2xl active:scale-90 transition-all flex items-center justify-center">
             {isProcessing ? <div className="w-10 h-10 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-[#f9fbfa]"></div>}
          </button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
        <div className="max-w-4xl mx-auto flex justify-between items-start">
          <div className="flex-1 mr-4">
            <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
            <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em] mt-2">{strings.creator.spotsInTrail(questions.length)}</p>
          </div>
          <button onClick={handleCancelClick} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm text-[#0f1a16]">{strings.common.cancel}</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-6 overflow-y-auto pb-40 scroll-smooth-touch">
        {error && <div className="bg-[#7c2d12]/10 border border-[#7c2d12]/20 p-5 rounded-[2rem] text-[#7c2d12] text-xs font-bold text-center uppercase tracking-widest">{error}</div>}

        <div className="grid grid-cols-2 gap-6">
          <button onClick={startCamera} className="flex flex-col items-center justify-center space-y-4 bg-white border border-[#2d4239]/5 hover:border-[#2d4239]/20 py-10 rounded-[3rem] transition-all group shadow-sm">
            <div className="p-4 bg-[#2d4239]/5 rounded-3xl group-hover:scale-110 transition-transform shadow-inner"><svg className="w-8 h-8 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#2d4239]">{strings.creator.takePhoto}</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-4 bg-white border border-[#8c6b4f]/5 hover:border-[#8c6b4f]/20 py-10 rounded-[3rem] transition-all group shadow-sm">
            <div className="p-4 bg-[#8c6b4f]/5 rounded-3xl group-hover:scale-110 transition-transform shadow-inner"><svg className="w-8 h-8 text-[#8c6b4f]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div>
            <span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#8c6b4f]">{strings.creator.uploadImage}</span>
            <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
          </button>
        </div>

        <div className="space-y-4 mt-12">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-white rounded-[2.5rem] border border-black/5 p-4 flex items-center space-x-6 shadow-sm hover:shadow-md transition-shadow">
              <img src={q.imageUrl} className="w-20 h-20 rounded-[1.5rem] object-cover border border-black/5 shadow-sm" />
              <div className="flex-1 min-w-0">
                <input type="text" value={q.title || ''} onChange={(e) => setQuestions(prev => prev.map(item => item.id === q.id ? { ...item, title: e.target.value } : item))} className="bg-transparent border-none p-0 text-lg font-black tracking-tight uppercase focus:ring-0 w-full mb-1 text-[#0f1a16]" />
                <button onClick={() => setPendingQuestion({ imageUrl: q.imageUrl, location: q.location, originalLocation: q.location, editingId: q.id, title: q.title, source: q.locationSource || 'MANUAL' })} className="text-[9px] text-[#8c6b4f] font-black uppercase tracking-[0.3em] hover:opacity-70 transition-opacity">{strings.creator.editPin}</button>
              </div>
              <div className="flex items-center space-x-3">
                <div className="flex flex-col opacity-20">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 hover:opacity-100 disabled:opacity-0"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 hover:opacity-100 disabled:opacity-0"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
                <button onClick={() => setConfirmDelete(q.id)} className="p-4 bg-[#7c2d12]/5 text-[#7c2d12] rounded-2xl transition-all hover:bg-[#7c2d12] hover:text-white"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
