import { GameState, Player, Location, Question } from './types';

export type GameAction = 
  | { type: 'SYNC_STATE'; payload: GameState }
  | { type: 'INIT_LOBBY'; payload: { id: string, questions: Question[], hostId: string } }
  | { type: 'JOIN_PLAYER'; payload: Player }
  | { type: 'KICK_PLAYER'; payload: string }
  | { type: 'SET_STATUS'; payload: GameState['status'] }
  | { type: 'SUBMIT_GUESS'; payload: { playerId: string, guess: Location, distance: number } }
  | { type: 'NEXT_ROUND' }
  | { type: 'EXIT_GAME' };

export const gameReducer = (state: GameState | null, action: GameAction): GameState | null => {
  switch (action.type) {
    case 'SYNC_STATE':
      return action.payload;

    case 'INIT_LOBBY':
      return {
        id: action.payload.id,
        status: 'LOBBY',
        questions: action.payload.questions,
        currentQuestionIndex: 0,
        players: [],
        hostId: action.payload.hostId,
      };

    case 'JOIN_PLAYER':
      if (!state) return null;
      // Prevent duplicates
      if (state.players.find(p => p.id === action.payload.id)) return state;
      return { ...state, players: [...state.players, action.payload] };

    case 'KICK_PLAYER':
      if (!state) return null;
      return { ...state, players: state.players.filter(p => p.id !== action.payload) };

    case 'SET_STATUS':
      if (!state) return null;
      return { ...state, status: action.payload };

    case 'SUBMIT_GUESS':
      if (!state) return null;
      const updatedPlayers = state.players.map(p => 
        p.id === action.payload.playerId 
          ? { ...p, hasGuessed: true, lastGuess: action.payload.guess, lastDistance: action.payload.distance } 
          : p
      );
      // Check if everyone has guessed to trigger countdown
      const allGuessed = updatedPlayers.every(p => p.hasGuessed);
      return { 
        ...state, 
        players: updatedPlayers, 
        status: allGuessed ? 'COUNTDOWN' : state.status 
      };

    case 'NEXT_ROUND':
      if (!state) return null;

      // Calculate scores for the round
      const sorted = [...state.players].sort((a, b) => (a.lastDistance || 0) - (b.lastDistance || 0));
      const playersWithNewScores = state.players.map(p => {
        const rank = sorted.findIndex(sp => sp.id === p.id);
        const pointsGained = Math.max(0, state.players.length - rank);
        return { 
          ...p, 
          score: p.score + pointsGained, 
          hasGuessed: false, 
          lastGuess: undefined, 
          lastDistance: undefined 
        };
      });

      const isLastQuestion = state.currentQuestionIndex === state.questions.length - 1;

      return {
        ...state,
        players: playersWithNewScores,
        currentQuestionIndex: isLastQuestion ? state.currentQuestionIndex : state.currentQuestionIndex + 1,
        status: isLastQuestion ? 'FINISHED' : 'PLAYING'
      };

    case 'EXIT_GAME':
      return null;

    default:
      return state;
  }
};

import { useEffect, useCallback, useRef } from 'react';
import { GameState } from './types';

const CHANNEL_NAME = 'locateit_sync';

export const useGameSync = (onMessage: (state: GameState) => void) => {
  const channelRef = useRef<BroadcastChannel | null>(null);

  useEffect(() => {
    const channel = new BroadcastChannel(CHANNEL_NAME);
    channelRef.current = channel;

    channel.onmessage = (event) => {
      if (event.data?.type === 'STATE_UPDATE') {
        onMessage(event.data.state);
      }
    };

    return () => {
      channel.close();
      channelRef.current = null;
    };
  }, [onMessage]);

  const broadcast = useCallback((state: GameState) => {
    if (channelRef.current) {
      channelRef.current.postMessage({ type: 'STATE_UPDATE', state });
    }
  }, []);

  return { broadcast };
};

