                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1 hover:opacity-100 disabled:opacity-0"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1 hover:opacity-100 disabled:opacity-0"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
