import { Location } from './types';

/**
 * Calculates distance between two coordinates in kilometers using Haversine formula.
 */
export const calculateDistance = (loc1: Location, loc2: Location): number => {
  const R = 6371; // Earth radius in km
  const dLat = (loc2.lat - loc1.lat) * Math.PI / 180;
  const dLng = (loc2.lng - loc1.lng) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(loc1.lat * Math.PI / 180) * Math.cos(loc2.lat * Math.PI / 180) * 
    Math.sin(dLng/2) * Math.sin(dLng/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
};

export const formatDistance = (km: number): string => {
  if (km < 1) return `${(km * 1000).toFixed(0)}m`;
  return `${km.toFixed(2)}km`;
};

export const generateId = () => Math.random().toString(36).substr(2, 6).toUpperCase();

/**
 * Converts a dataURL/base64 string to a Blob.
 */
export const dataUrlToBlob = (dataUrl: string): Blob => {
  const arr = dataUrl.split(',');
  const mimeMatch = arr[0].match(/:(.*?);/);
  if (!mimeMatch) throw new Error('Invalid dataURL');
  const mime = mimeMatch[1];
  const bstr = atob(arr[1]);
  let n = bstr.length;
  const u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = bstr.charCodeAt(n);
  }
  return new Blob([u8arr], { type: mime });
};

// Singleton worker instance to avoid creating too many workers
let compressionWorker: Worker | null = null;
const pendingCompressions = new Map<string, { resolve: (val: string) => void, reject: (err: any) => void }>();

const getWorker = () => {
  if (!compressionWorker) {
    // Inlining the worker code to bypass cross-origin script access restrictions
    const workerCode = `
      self.onmessage = async (e) => {
        const { id, blob, maxWidth, quality } = e.data;
        try {
          const img = await createImageBitmap(blob);
          let width = img.width;
          let height = img.height;
          if (width > maxWidth) {
            height = Math.round((height * maxWidth) / width);
            width = maxWidth;
          }
          const canvas = new OffscreenCanvas(width, height);
          const ctx = canvas.getContext('2d');
          if (!ctx) throw new Error('Failed to get 2D context');
          ctx.drawImage(img, 0, 0, width, height);
          const compressedBlob = await canvas.convertToBlob({ type: 'image/jpeg', quality });
          const reader = new FileReader();
          reader.onloadend = () => self.postMessage({ id, dataUrl: reader.result });
          reader.readAsDataURL(compressedBlob);
          img.close();
        } catch (error) {
          self.postMessage({ id, error: error instanceof Error ? error.message : 'Unknown compression error' });
        }
      };
    `;
    const workerBlob = new Blob([workerCode], { type: 'application/javascript' });
    const workerUrl = URL.createObjectURL(workerBlob);

    compressionWorker = new Worker(workerUrl);
    compressionWorker.onmessage = (e) => {
      const { id, dataUrl, error } = e.data;
      const promise = pendingCompressions.get(id);
      if (promise) {
        if (error) promise.reject(error);
        else promise.resolve(dataUrl);
        pendingCompressions.delete(id);
      }
    };
  }
  return compressionWorker;
};

/**
 * Offloads image compression to a Web Worker to keep the UI responsive.
 * Falls back to main thread if OffscreenCanvas is unavailable.
 */
export const compressImage = (dataUrl: string, maxWidth = 1024, quality = 0.5): Promise<string> => {
  // If browser doesn't support OffscreenCanvas, fallback to main thread
  if (typeof OffscreenCanvas === 'undefined') {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return reject('No context');
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.onerror = reject;
      img.src = dataUrl;
    });
  }

  // Use Worker
  return new Promise((resolve, reject) => {
    const id = Math.random().toString(36).substr(2, 9);
    try {
      const blob = dataUrlToBlob(dataUrl);
      pendingCompressions.set(id, { resolve, reject });
      getWorker().postMessage({ id, blob, maxWidth, quality });
    } catch (err) {
      reject(err);
    }
  });
};

