const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [showPermissionModal, setShowPermissionModal] = useState(false);

  // REDUCER BASED STATE MANAGEMENT
  const [gameState, dispatch] = useReducer(gameReducer, null);

  // ENCAPSULATED SYNC LOGIC
  const { broadcast } = useGameSync(useCallback((state) => {
    dispatch({ type: 'SYNC_STATE', payload: state });
  }, []));

  // Sync effect: Only the host pushes updates to the channel
  useEffect(() => {
    if (isHost && gameState) {
      broadcast(gameState);
    }
  }, [gameState, isHost, broadcast]);

  // Handle automatic navigation based on game state
  useEffect(() => {
    if (gameState) {
      if (['PLAYING', 'COUNTDOWN', 'RESULTS'].includes(gameState.status)) {
        setView('PLAYING');
      }

      // Check for kick
      if (currentPlayer && !gameState.players.find(p => p.id === currentPlayer.id) && !isHost) {
        alert(strings.lobby.kickedDesc);
        setCurrentPlayer(null);
        setView('HOME');
        localStorage.removeItem('locateit_last_player_id');
      }
    }
  }, [gameState, currentPlayer, isHost]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  const availableColors = ['#6366f1', '#f43f5e', '#10b981', '#f59e0b', '#06b6d4', '#d946ef', '#8b5cf6', '#f97316'];
  const [selectedColor, setSelectedColor] = useState(availableColors[0]);

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;
    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const idx = trails.findIndex(t => t.id === trailToSave.id);
      if (idx > -1) trails[idx] = trailToSave;
      else trails.push(trailToSave);

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null);
    dispatch({ type: 'INIT_LOBBY', payload: { id: generateId(), questions: trail.questions, hostId: user.id } });
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    if (gameState && gameState.id === gameCode) {
      const savedId = localStorage.getItem('locateit_last_player_id');
      const existing = gameState.players.find(p => p.id === savedId);

      if (existing) {
        setCurrentPlayer(existing);
        setIsHost(false);
        setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
        return;
      }

      const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
      setCurrentPlayer(newPlayer);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', newPlayer.id);
      dispatch({ type: 'JOIN_PLAYER', payload: newPlayer });
      setView('LOBBY');
    } else {
      alert("Game code not found.");
    }
  };

  const PermissionElements = (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
    </>
  );

  if (view === 'AUTH') return (
    <>
      {PermissionElements}
      <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />
    </>
  );

  if (view === 'DASHBOARD' && user) return (
    <>
      {PermissionElements}
      <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />
    </>
  );

  if (view === 'CREATE') return (
    <>
      {PermissionElements}
      <QuizCreator 
        initialTrail={editingTrail || undefined} 
        onComplete={handleSaveTrail} 
        onCancel={() => setView('DASHBOARD')} 
        onRequestPermissions={() => setShowPermissionModal(true)}
      />
    </>
  );

  if (view === 'LOBBY' && gameState) return (
    <>
      {PermissionElements}
      <Lobby gameState={gameState} isHost={isHost} onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { dispatch({ type: 'EXIT_GAME' }); setView('DASHBOARD'); }} onKick={(id) => dispatch({ type: 'KICK_PLAYER', payload: id })} />
    </>
  );

  if (view === 'PLAYING' && gameState) return (
    <>
      {PermissionElements}
      <GameBoard 
        gameState={gameState} 
        isHost={isHost} 
        currentPlayer={currentPlayer} 
        onGuess={(guess) => {
          if (!currentPlayer) return;
          const currentQ = gameState.questions[gameState.currentQuestionIndex];
          const dist = calculateDistance(guess, currentQ.location);
          dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
        }} 
        onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
        onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
      />
    </>
  );

  if (view === 'JOIN') return (
    <>
      {PermissionElements}
      <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#f9fbfa]">
        <div className="max-w-md w-full">
          <button onClick={() => setView('HOME')} className="mb-8 text-[#0f1a16]/40 hover:text-[#0f1a16] flex items-center font-bold text-xs uppercase tracking-widest transition-all">
             <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
             {strings.join.back}
          </button>
          <div className="bg-white rounded-[3rem] p-12 border border-black/5 shadow-[0_40px_80px_-15px_rgba(15,26,22,0.1)]">
            <h2 className="text-3xl font-black text-[#0f1a16] mb-10 text-center tracking-tight uppercase">{strings.join.title}</h2>
            <div className="space-y-6">
              <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 uppercase font-bold text-center tracking-[0.3em] text-xl text-[#0f1a16] placeholder:opacity-20 transition-all" />
              <input id="playerName" placeholder={strings.join.yourName} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 text-[#0f1a16] font-bold placeholder:opacity-20 transition-all" />
              <div className="space-y-4 pt-2">
                <label className="text-[10px] font-bold text-[#0f1a16]/30 uppercase tracking-[0.4em] ml-2">{strings.lobby.chooseColor}</label>
                <div className="flex flex-wrap gap-4 justify-center">
                  {availableColors.map(color => (
                    <button key={color} onClick={() => setSelectedColor(color)} className={`w-10 h-10 rounded-full transition-all active:scale-90 ${selectedColor === color ? 'ring-4 ring-black/10 scale-110 shadow-lg border-2 border-white' : 'opacity-40 hover:opacity-100'}`} style={{ backgroundColor: color }} />
                  ))}
                </div>
              </div>
              <button onClick={() => {
                const code = (document.getElementById('gameCode') as HTMLInputElement).value;
                const name = (document.getElementById('playerName') as HTMLInputElement).value;
                if (code && name) handleJoinGame(code, name);
              }} className="w-full py-5 btn-sleek btn-sleek-pine text-base mt-6">
                {strings.join.joinLobby}
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );

  return (
    <div className="h-screen bg-[#f9fbfa] text-[#0f1a16] overflow-hidden flex flex-col relative selection:bg-[#8c6b4f]/20">
      <FlyingWordsBackground />
      {PermissionElements}
      <div className="fixed -top-80 -left-60 w-[1000px] h-[1000px] bg-[#2d4239]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-80 -right-60 w-[1000px] h-[1000px] bg-[#8c6b4f]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col items-center relative py-10 md:py-12 px-6 z-10 gap-8 md:gap-12 overflow-y-auto scroll-smooth-touch">
        <div className="flex flex-col items-center select-none text-center pt-2">
            <AnimationVariantSwapT fontSize="clamp(1.1rem, 4.5vw, 2.4rem)" />
        </div>
        <section className="w-full max-w-3xl flex flex-col items-center gap-10 md:gap-14">
            <div className="w-full text-center flex flex-col items-center space-y-8">
              <div className="bg-white/45 backdrop-blur-md px-6 md:px-10 py-8 md:py-10 rounded-[2.5rem] border border-black/5 shadow-sm space-y-4 md:space-y-6">
                <h1 className="text-3xl md:text-6xl text-[#0f1a16] leading-[1.1] font-black tracking-tight">{strings.home.subtitle}</h1>
                <p className="text-[#0f1a16]/60 text-sm md:text-base font-bold uppercase tracking-[0.2em] max-w-lg mx-auto">Build unique trails & challenge your inner circle.</p>
              </div>
              <div className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center w-full max-w-xl mx-auto px-2 relative z-20">
                <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-oak text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                  {strings.home.designTrail}
                </button>
                <button onClick={() => setView('JOIN')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-pine text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                  {strings.home.joinQuest}
                </button>
              </div>
            </div>
            <div className="w-full max-w-4xl flex items-center justify-center opacity-80 md:opacity-100">
               <div className="relative w-full aspect-[21/9] max-h-[220px] md:max-h-[320px] bg-white rounded-[2.5rem] md:rounded-[3.5rem] border border-black/5 p-2 md:p-3 shadow-2xl group overflow-hidden">
                  <div className="relative w-full h-full rounded-[2rem] md:rounded-[2.8rem] overflow-hidden border border-black/5">
                     <img src="https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&q=80&w=2000" className="w-full h-full object-cover grayscale-[10%] opacity-90 transition-all duration-[6s] ease-out group-hover:scale-105 group-hover:grayscale-0 group-hover:opacity-100" alt="Highland Pine Forest" />
                     <div className="absolute inset-0 bg-gradient-to-b from-transparent via-black/5 to-black/20"></div>
                  </div>
               </div>
            </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [isCapturing, setIsCapturing] = useState(false);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';

    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;

    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  const ensureLocation = useCallback(async (): Promise<Location> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation || locationStatus === 'denied') {
        resolve({ lat: 51.505, lng: -0.09 });
        return;
      }

      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          setCurrentLocation(loc);
          setGpsAccuracy(pos.coords.accuracy);
          if (!watchId.current) {
            watchId.current = navigator.geolocation.watchPosition(
              (p) => {
                setCurrentLocation({ lat: p.coords.latitude, lng: p.coords.longitude });
                setGpsAccuracy(p.coords.accuracy);
              },
              undefined,
              { enableHighAccuracy: true, maximumAge: 0 }
            );
          }
          resolve(loc);
        },
        () => resolve({ lat: 51.505, lng: -0.09 }),
        { enableHighAccuracy: true, timeout: 5000 }
      );
    });
  }, [locationStatus]);

  useEffect(() => {
    ensureLocation();
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, [ensureLocation]);

  const stopCamera = useCallback(() => {
    if (activeStream) {
      activeStream.getTracks().forEach(track => track.stop());
      setActiveStream(null);
    }
    setIsCapturing(false);
  }, [activeStream]);

  // Request camera stream inside the capture view for better lifecycle management
  useEffect(() => {
    if (isCapturing && !activeStream) {
      const startStream = async () => {
        try {
          const stream = await navigator.mediaDevices.getUserMedia({ 
            video: { facingMode: 'environment', width: { ideal: 1920 } } 
          });
          setActiveStream(stream);
          ensureLocation();
        } catch (err) {
          console.error("Camera startup failed:", err);
          setError(strings.creator.cameraError);
          setIsCapturing(false);
        }
      };
      startStream();
    }
  }, [isCapturing, activeStream, ensureLocation]);

  const startCameraUI = () => {
    if (cameraStatus === 'denied') {
      setError(strings.creator.cameraError);
      return;
    }
    setError(null);
    setIsCapturing(true);
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    // Readiness check: make sure video is playing and has frames
    if (!video || video.readyState < 2) return;

    setIsProcessing(true);
    setIsFlashing(true);

    try {
      // Use standard dimensions if video reporting is delayed
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;

      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        ctx.drawImage(video, 0, 0, w, h);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);

        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';

        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      } else {
        throw new Error('Canvas context unavailable');
      }
    } catch (e) {
      console.error("Capture failed:", e);
      setError(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);

    const locPromise = ensureLocation();

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        try {
          const rawUrl = event.target?.result as string;
          const imageUrl = await compressImage(rawUrl);
          let lat: number | null = null;
          let lng: number | null = null;
          let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

          try {
            const tags = await ExifReader.load(file);
            if (tags.GPSLatitude && tags.GPSLongitude) {
              const parsedLat = parseFloat(tags.GPSLatitude.description);
              const parsedLng = parseFloat(tags.GPSLongitude.description);
              if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
                lat = parsedLat;
                lng = parsedLng;
                source = 'IMAGE';
              }
            }
          } catch (exifErr) { console.warn("EXIF extraction failed:", exifErr); }

          const currentLoc = await locPromise;

          if (source !== 'IMAGE' || lat === null || lng === null) {
            source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
          }

          const finalLoc = (lat !== null && lng !== null && !isNaN(lat) && !isNaN(lng)) 
            ? { lat, lng } 
            : (currentLoc || { lat: 51.505, lng: -0.09 });

          setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
        } catch (err) {
          setError(strings.creator.uploadError);
        } finally {
          setIsProcessing(false);
        }
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError(strings.creator.uploadError); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;

    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) 
      }]);
    }
    setPendingQuestion(null);
  };

  const handleDelete = () => {
    if (confirmDelete) {
      setQuestions(prev => prev.filter(q => q.id !== confirmDelete));
      setConfirmDelete(null);
    }
  };

  const handleCancelClick = () => {
    if (hasChanges) {
      setShowExitConfirm(true);
    } else {
      onCancel();
    }
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    setQuestions(prev => {
      const next = [...prev];
      const targetIdx = direction === 'up' ? index - 1 : index + 1;
      if (targetIdx < 0 || targetIdx >= next.length) return prev;
      [next[index], next[targetIdx]] = [next[targetIdx], next[index]];
      return next;
    });
  };

  if (showExitConfirm) {
    return (
      <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
        <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-[#ca8a04]/10 text-[#ca8a04] rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
          </div>
          <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
          <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
          <div className="flex gap-4">
            <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
            <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
          </div>
        </div>
      </div>
    );
  }

  if (confirmDelete) {
    return (
      <div className="fixed inset-0 z-[400] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
        <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
          <div className="w-16 h-16 bg-[#7c2d12]/10 text-[#7c2d12] rounded-2xl flex items-center justify-center mx-auto mb-6">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </div>
          <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
          <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
          <div className="flex gap-4">
            <button onClick={() => setConfirmDelete(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
            <button onClick={handleDelete} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
          </div>
        </div>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">{pendingQuestion.editingId ? strings.creator.editSpot : strings.creator.tagSpot}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest px-4 py-2 hover:opacity-70 transition-colors">{strings.common.back}</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-24 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-6 flex items-center justify-center bg-[#2d4239]/5">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="bg-white p-6 rounded-[2rem] border border-[#2d4239]/5 shadow-sm flex justify-between items-center">
                <div className="flex-1 pr-2">
                    <p className="text-[9px] font-black text-[#8c6b4f] uppercase tracking-[0.3em] mb-1">{strings.creator.verifyLocation}</p>
                    <p className="text-sm text-[#0f1a16]/60 font-medium">{strings.creator.tapToRefine}</p>
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[8px] bg-[#2d4239] text-white px-2 py-1 rounded-full font-black uppercase mb-1 tracking-widest">{pendingQuestion.source}</span>
                </div>
             </div>
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map 
                  center={pendingQuestion.location} 
                  zoom={17} 
                  onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)}
                  markers={[{ position: pendingQuestion.location, icon: 'target' }]} 
                />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !bg-[#2d4239] !text-lg !tracking-widest">{strings.creator.confirmMarker}</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#0f1a16] flex flex-col overflow-hidden">
        <video 
          ref={(el) => {
            if (el && activeStream) {
              el.srcObject = activeStream;
            }
          }}
          autoPlay 
          playsInline 
          muted 
          className="flex-1 w-full h-full object-cover" 
        />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] camera-flash-fx pointer-events-none"></div>}
        <div className="absolute top-8 left-0 right-0 px-8 flex justify-center z-[120]">
           <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
        </div>
        <div className="absolute inset-x-0 bottom-0 p-12 flex justify-between items-center bg-gradient-to-t from-black/80 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20 active:scale-90 transition-transform">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
          <button 
            onClick={capturePhoto} 
            disabled={isProcessing || !activeStream} 
            className="w-24 h-24 rounded-full bg-white border-[8px] border-white/30 shadow-2xl active:scale-90 transition-all flex items-center justify-center disabled:opacity-50"
          >
             {isProcessing ? (
               <div className="w-10 h-10 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div>
             ) : !activeStream ? (
               <div className="w-8 h-8 border-2 border-[#0f1a16]/20 border-t-[#0f1a16] rounded-full animate-spin"></div>
             ) : (
               <div className="w-14 h-14 rounded-full border-4 border-[#f9fbfa]"></div>
             )}
          </button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      <PermissionBanner onCheck={onRequestPermissions} />
      <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
        <div className="max-w-4xl mx-auto flex justify-between items-start">
          <div className="flex-1 mr-4">
