import { Location } from './types';

/**
 * Calculates distance between two coordinates in kilometers using Haversine formula.
 */
export const calculateDistance = (loc1: Location, loc2: Location): number => {
  const R = 6371; // Earth radius in km
  const dLat = (loc2.lat - loc1.lat) * Math.PI / 180;
  const dLng = (loc2.lng - loc1.lng) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(loc1.lat * Math.PI / 180) * Math.cos(loc2.lat * Math.PI / 180) * 
    Math.sin(dLng/2) * Math.sin(dLng/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
};

export const formatDistance = (km: number): string => {
  if (km < 1) return `${(km * 1000).toFixed(0)}m`;
  return `${km.toFixed(2)}km`;
};

export const generateId = () => Math.random().toString(36).substr(2, 6).toUpperCase();

/**
 * Converts a dataURL/base64 string to a Blob.
 */
export const dataUrlToBlob = (dataUrl: string): Blob => {
  try {
    const arr = dataUrl.split(',');
    const mimeMatch = arr[0].match(/:(.*?);/);
    if (!mimeMatch) throw new Error('Invalid dataURL');
    const mime = mimeMatch[1];
    // Clean string of spaces/newlines before decoding
    const base64Data = arr[1].replace(/\s/g, '');
    const bstr = atob(base64Data);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);
    while (n--) {
      u8arr[n] = bstr.charCodeAt(n);
    }
    return new Blob([u8arr], { type: mime });
  } catch (e) {
    console.error("dataUrlToBlob failed", e);
    throw e;
  }
};

// Singleton worker instance
let compressionWorker: Worker | null = null;
const pendingCompressions = new Map<string, { resolve: (val: string) => void, reject: (err: any) => void }>();

const getWorker = () => {
  if (!compressionWorker && typeof Worker !== 'undefined') {
    try {
      const workerCode = `
        self.onmessage = async (e) => {
          const { id, blob, maxWidth, quality } = e.data;
          try {
            if (typeof createImageBitmap === 'undefined') {
               throw new Error('createImageBitmap not supported in worker');
            }
            const img = await createImageBitmap(blob);
            let width = img.width;
            let height = img.height;
            if (width > maxWidth) {
              height = Math.round((height * maxWidth) / width);
              width = maxWidth;
            }
            if (typeof OffscreenCanvas === 'undefined') {
               throw new Error('OffscreenCanvas not supported in worker');
            }
            const canvas = new OffscreenCanvas(width, height);
            const ctx = canvas.getContext('2d');
            if (!ctx) throw new Error('Failed to get 2D context');
            ctx.drawImage(img, 0, 0, width, height);
            const compressedBlob = await canvas.convertToBlob({ type: 'image/jpeg', quality });
            const reader = new FileReader();
            reader.onloadend = () => self.postMessage({ id, dataUrl: reader.result });
            reader.readAsDataURL(compressedBlob);
            img.close();
          } catch (error) {
            self.postMessage({ id, error: error instanceof Error ? error.message : 'Unknown compression error' });
          }
        };
      `;
      const workerBlob = new Blob([workerCode], { type: 'application/javascript' });
      const workerUrl = URL.createObjectURL(workerBlob);

      compressionWorker = new Worker(workerUrl);
      compressionWorker.onmessage = (e) => {
        const { id, dataUrl, error } = e.data;
        const promise = pendingCompressions.get(id);
        if (promise) {
          if (error) promise.reject(new Error(error));
          else promise.resolve(dataUrl);
          pendingCompressions.delete(id);
        }
      };
      compressionWorker.onerror = (e) => {
        console.error("Worker lifecycle error", e);
      };
    } catch (err) {
      console.warn("Could not initialize compression worker", err);
      return null;
    }
  }
  return compressionWorker;
};

/**
 * Offloads image compression to a Web Worker or falls back to the main thread.
 */
export const compressImage = async (dataUrl: string, maxWidth = 1024, quality = 0.5): Promise<string> => {
  // Use Worker if supported
  if (typeof OffscreenCanvas !== 'undefined' && typeof Worker !== 'undefined') {
    const worker = getWorker();
    if (worker) {
      try {
        return await new Promise((resolve, reject) => {
          const id = Math.random().toString(36).substr(2, 9);
          try {
            const blob = dataUrlToBlob(dataUrl);
            pendingCompressions.set(id, { resolve, reject });
            worker.postMessage({ id, blob, maxWidth, quality });

            // Timeout protection for the worker
            setTimeout(() => {
              if (pendingCompressions.has(id)) {
                pendingCompressions.delete(id);
                reject(new Error('Compression worker timed out'));
              }
            }, 8000);
          } catch (blobErr) {
            reject(blobErr);
          }
        });
      } catch (err) {
        console.warn("Worker compression failed, falling back to main thread:", err);
      }
    }
  }

  // Robust Main Thread Fallback
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('Could not get canvas context');
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      } catch (err) {
        reject(err);
      }
    };
    img.onerror = () => reject(new Error('Failed to load image for compression fallback'));
    img.src = dataUrl;
  });
};

import { Location } from './types';

/**
 * Calculates distance between two coordinates in kilometers using Haversine formula.
 */
export const calculateDistance = (loc1: Location, loc2: Location): number => {
  const R = 6371; // Earth radius in km
  const dLat = (loc2.lat - loc1.lat) * Math.PI / 180;
  const dLng = (loc2.lng - loc1.lng) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(loc1.lat * Math.PI / 180) * Math.cos(loc2.lat * Math.PI / 180) * 
    Math.sin(dLng/2) * Math.sin(dLng/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
};

export const formatDistance = (km: number): string => {
  if (km < 1) return `${(km * 1000).toFixed(0)}m`;
  return `${km.toFixed(2)}km`;
};

export const generateId = () => Math.random().toString(36).substr(2, 6).toUpperCase();

/**
 * Compresses an image dataURL using a hidden canvas.
 * This version uses the main thread but remains async to prevent blocking.
 * It is significantly more reliable on mobile browsers than Web Workers for this specific task.
 */
export const compressImage = async (dataUrl: string, maxWidth = 1024, quality = 0.6): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;

        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }

        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        if (!ctx) {
          throw new Error('Could not get canvas context');
        }

        // Use high-quality image smoothing
        ctx.imageSmoothingEnabled = true;
        ctx.imageSmoothingQuality = 'high';

        ctx.drawImage(img, 0, 0, width, height);

        const result = canvas.toDataURL('image/jpeg', quality);
        resolve(result);
      } catch (err) {
        console.error("Compression execution failed:", err);
        reject(err);
      }
    };
    img.onerror = () => {
      console.error("Failed to load image for compression");
      reject(new Error('Failed to load image for compression'));
    };
    img.src = dataUrl;
  });
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');

  // Camera State
  const [isCapturing, setIsCapturing] = useState(false);
  const [isStartingCamera, setIsStartingCamera] = useState(false);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);

  // Processing States
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);

  // Location States
  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  // UI States
  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  const ensureLocation = useCallback(async (): Promise<Location> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation || locationStatus === 'denied') {
        resolve({ lat: 51.505, lng: -0.09 });
        return;
      }
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          setCurrentLocation(loc);
          setGpsAccuracy(pos.coords.accuracy);
          if (!watchId.current) {
            watchId.current = navigator.geolocation.watchPosition(
              (p) => {
                setCurrentLocation({ lat: p.coords.latitude, lng: p.coords.longitude });
                setGpsAccuracy(p.coords.accuracy);
              },
              undefined,
              { enableHighAccuracy: true, maximumAge: 0 }
            );
          }
          resolve(loc);
        },
        () => resolve({ lat: 51.505, lng: -0.09 }),
        { enableHighAccuracy: true, timeout: 5000 }
      );
    });
  }, [locationStatus]);

  useEffect(() => {
    ensureLocation();
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, [ensureLocation]);

  // Sync stream to video element
  useEffect(() => {
    if (isCapturing && activeStream && videoRef.current) {
      videoRef.current.srcObject = activeStream;
      videoRef.current.play().catch(err => console.error("Video play failed:", err));
    }
  }, [isCapturing, activeStream]);

  const stopCamera = useCallback(() => {
    if (activeStream) {
      activeStream.getTracks().forEach(track => track.stop());
      setActiveStream(null);
    }
    setIsCapturing(false);
    setIsStartingCamera(false);
  }, [activeStream]);

  const startCamera = async () => {
    if (cameraStatus === 'denied') {
      setError(strings.creator.cameraError);
      return;
    }

    setError(null);
    setIsStartingCamera(true);

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1920 } } 
      });
      setActiveStream(stream);
      setIsCapturing(true);
      setIsStartingCamera(false);
      ensureLocation();
    } catch (err) {
      console.error("Camera startup failed:", err);
      setError(strings.creator.cameraError);
      setIsStartingCamera(false);
      setIsCapturing(false);
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) {
      console.warn("Capture aborted: video not ready", video?.readyState);
      return;
    }

    setIsProcessing(true);
    setIsFlashing(true);

    try {
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;

      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        ctx.drawImage(video, 0, 0, w, h);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);

        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';

        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      } else {
        throw new Error('Canvas context unavailable');
      }
    } catch (e) {
      console.error("Capture process failed:", e);
      setError(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);

    const locPromise = ensureLocation();

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        try {
          const rawUrl = event.target?.result as string;
          const imageUrl = await compressImage(rawUrl);
          let lat: number | null = null;
          let lng: number | null = null;
          let source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL' = 'GPS';

          try {
            const tags = await ExifReader.load(file);
            if (tags.GPSLatitude && tags.GPSLongitude) {
              const parsedLat = parseFloat(tags.GPSLatitude.description);
              const parsedLng = parseFloat(tags.GPSLongitude.description);
              if (!isNaN(parsedLat) && !isNaN(parsedLng)) {
                lat = parsedLat;
                lng = parsedLng;
                source = 'IMAGE';
              }
            }
          } catch (exifErr) { console.warn("EXIF extraction failed:", exifErr); }

          const currentLoc = await locPromise;

          if (source !== 'IMAGE' || lat === null || lng === null) {
            source = (currentLoc && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
          }

          const finalLoc = (lat !== null && lng !== null && !isNaN(lat) && !isNaN(lng)) 
            ? { lat, lng } 
            : (currentLoc || { lat: 51.505, lng: -0.09 });

          setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
        } catch (err) {
          setError(strings.creator.uploadError);
        } finally {
          setIsProcessing(false);
        }
      };
      reader.readAsDataURL(file);
    } catch (err) { 
      setIsProcessing(false); 
      setError(strings.creator.uploadError); 
    }
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;

    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { 
        ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title 
      } : q));
    } else {
      setQuestions(prev => [...prev, { 
        id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) 
      }]);
    }
    setPendingQuestion(null);
  };

  const handleDelete = () => {
    if (confirmDelete) {
      setQuestions(prev => prev.filter(q => q.id !== confirmDelete));
      setConfirmDelete(null);
    }
  };

  const handleCancelClick = () => {
    if (hasChanges) {
