        setView('PLAYING');
      }

      // Check for kick
      if (currentPlayer && !gameState.players.find(p => p.id === currentPlayer.id) && !isHost) {
        alert(strings.lobby.kickedDesc);
        setCurrentPlayer(null);
        setView('HOME');
        localStorage.removeItem('locateit_last_player_id');
      }
    }
  }, [gameState, currentPlayer, isHost, view]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  const availableColors = ['#6366f1', '#f43f5e', '#10b981', '#f59e0b', '#06b6d4', '#d946ef', '#8b5cf6', '#f97316'];
  const [selectedColor, setSelectedColor] = useState(availableColors[0]);

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;
    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const idx = trails.findIndex(t => t.id === trailToSave.id);
      if (idx > -1) trails[idx] = trailToSave;
      else trails.push(trailToSave);

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); // Host is not a player

    const newGameId = generateId();
    dispatch({ type: 'INIT_LOBBY', payload: { id: newGameId, questions: trail.questions, hostId: user.id } });
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();

    if (!gameState) {
      setJoinError("Searching for expedition... Please wait a moment.");
      requestSync();
      return;
    }

    if (gameState.id !== code) {
      setJoinError(`Expedition ${code} not found. Are you in the right area?`);
      requestSync();
      return;
    }

    const savedId = localStorage.getItem('locateit_last_player_id');
    const existing = gameState.players.find(p => p.id === savedId);

    if (existing) {
      setCurrentPlayer(existing);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  const PermissionElements = (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
    </>
  );

  if (view === 'AUTH') return (
    <>
      {PermissionElements}
      <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />
    </>
  );

  if (view === 'DASHBOARD' && user) return (
    <>
      {PermissionElements}
      <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />
    </>
  );

  if (view === 'CREATE') return (
    <>
      {PermissionElements}
      <QuizCreator 
        initialTrail={editingTrail || undefined} 
        onComplete={handleSaveTrail} 
        onCancel={() => setView('DASHBOARD')} 
        onRequestPermissions={() => setShowPermissionModal(true)}
      />
    </>
  );

  if (view === 'LOBBY' && gameState) return (
    <>
      {PermissionElements}
      <Lobby gameState={gameState} isHost={isHost} onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { dispatch({ type: 'EXIT_GAME' }); setView('DASHBOARD'); }} onKick={(id) => dispatch({ type: 'KICK_PLAYER', payload: id })} />
    </>
  );

  if (view === 'PLAYING' && gameState) return (
    <>
      {PermissionElements}
      <GameBoard 
        gameState={gameState} 
        isHost={isHost} 
        currentPlayer={currentPlayer} 
        onGuess={(guess) => {
          if (!currentPlayer) return;
          const currentQ = gameState.questions[gameState.currentQuestionIndex];
          const dist = calculateDistance(guess, currentQ.location);
          sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
        }} 
        onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
        onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
      />
    </>
  );

  if (view === 'JOIN') return (
    <>
      {PermissionElements}
      <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#f9fbfa]">
        <div className="max-w-md w-full">
          <button onClick={() => setView('HOME')} className="mb-8 text-[#0f1a16]/40 hover:text-[#0f1a16] flex items-center font-bold text-xs uppercase tracking-widest transition-all">
             <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
             {strings.join.back}
          </button>
          <div className="bg-white rounded-[3rem] p-12 border border-black/5 shadow-[0_40px_80px_-15px_rgba(15,26,22,0.1)]">
            <h2 className="text-3xl font-black text-[#0f1a16] mb-10 text-center tracking-tight uppercase">{strings.join.title}</h2>
            <div className="space-y-6">
              <div className="relative">
                <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 uppercase font-bold text-center tracking-[0.3em] text-xl text-[#0f1a16] placeholder:opacity-20 transition-all" />
                {!gameState && <div className="absolute top-2 right-4"><div className="w-2 h-2 rounded-full bg-[#8c6b4f] animate-ping"></div></div>}
              </div>
              <input id="playerName" placeholder={strings.join.yourName} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 text-[#0f1a16] font-bold placeholder:opacity-20 transition-all" />

              {joinError && (
                <p className="text-[#7c2d12] text-[10px] font-black uppercase text-center tracking-widest animate-pulse">{joinError}</p>
              )}

              <div className="space-y-4 pt-2">
                <label className="text-[10px] font-bold text-[#0f1a16]/30 uppercase tracking-[0.4em] ml-2">{strings.lobby.chooseColor}</label>
                <div className="flex flex-wrap gap-4 justify-center">
                  {availableColors.map(color => (
                    <button key={color} onClick={() => setSelectedColor(color)} className={`w-10 h-10 rounded-full transition-all active:scale-90 ${selectedColor === color ? 'ring-4 ring-black/10 scale-110 shadow-lg border-2 border-white' : 'opacity-40 hover:opacity-100'}`} style={{ backgroundColor: color }} />
                  ))}
                </div>
              </div>
              <button onClick={() => {
                const code = (document.getElementById('gameCode') as HTMLInputElement).value;
                const name = (document.getElementById('playerName') as HTMLInputElement).value;
                if (code && name) handleJoinGame(code, name);
              }} className="w-full py-5 btn-sleek btn-sleek-pine text-base mt-6">
                {strings.join.joinLobby}
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );

  return (
    <div className="h-screen bg-[#f9fbfa] text-[#0f1a16] overflow-hidden flex flex-col relative selection:bg-[#8c6b4f]/20">
      <FlyingWordsBackground />
      {PermissionElements}
      <div className="fixed -top-80 -left-60 w-[1000px] h-[1000px] bg-[#2d4239]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-80 -right-60 w-[1000px] h-[1000px] bg-[#8c6b4f]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col items-center relative py-10 md:py-12 px-6 z-10 gap-8 md:gap-12 overflow-y-auto scroll-smooth-touch">
        <div className="flex flex-col items-center select-none text-center pt-2">
            <AnimationVariantSwapT fontSize="clamp(1.1rem, 4.5vw, 2.4rem)" />
        </div>
        <section className="w-full max-w-3xl flex flex-col items-center gap-10 md:gap-14">
            <div className="w-full text-center flex flex-col items-center space-y-8">
              <div className="bg-white/45 backdrop-blur-md px-6 md:px-10 py-8 md:py-10 rounded-[2.5rem] border border-black/5 shadow-sm space-y-4 md:space-y-6">
                <h1 className="text-3xl md:text-6xl text-[#0f1a16] leading-[1.1] font-black tracking-tight">{strings.home.subtitle}</h1>
                <p className="text-[#0f1a16]/60 text-sm md:text-base font-bold uppercase tracking-[0.2em] max-w-lg mx-auto">Build unique trails & challenge your inner circle.</p>
              </div>
              <div className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center w-full max-w-xl mx-auto px-2 relative z-20">
                <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-oak text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                  {strings.home.designTrail}
                </button>
                <button onClick={() => setView('JOIN')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-pine text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                  {strings.home.joinQuest}
                </button>
              </div>
            </div>
            <div className="w-full max-w-4xl flex items-center justify-center opacity-80 md:opacity-100">
               <div className="relative w-full aspect-[21/9] max-h-[220px] md:max-h-[320px] bg-white rounded-[2.5rem] md:rounded-[3.5rem] border border-black/5 p-2 md:p-3 shadow-2xl group overflow-hidden">
                  <div className="relative w-full h-full rounded-[2rem] md:rounded-[2.8rem] overflow-hidden border border-black/5">
                     <img src="https://images.unsplash.com/photo-1473448912268-2022ce9509d8?auto=format&fit=crop&q=80&w=2000" className="w-full h-full object-cover grayscale-[10%] opacity-90 transition-all duration-[6s] ease-out group-hover:scale-105 group-hover:grayscale-0 group-hover:opacity-100" alt="Highland Pine Forest" />
                     <div className="absolute inset-0 bg-gradient-to-b from-transparent via-black/5 to-black/20"></div>
                  </div>
               </div>
            </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onCountdownFinish: () => void;
  onNext: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ gameState, isHost, currentPlayer, onGuess, onCountdownFinish, onNext }) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  useEffect(() => {
    setHasSubmitted(false);
    setSelectedGuess(null);
    setCountdownValue(3);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (gameState.status === 'COUNTDOWN') {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [gameState.status, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
      setHasSubmitted(true);
    }
  };

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isGameFinished = gameState.status === 'FINISHED';

  const sortedPlayers = [...gameState.players].sort((a, b) => b.score - a.score);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(45,66,57,0.15)] w-full max-w-md border border-[#2d4239]/10">
          <div className="space-y-6">
            {sortedPlayers.map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all border ${idx === 0 ? 'bg-[#ca8a04]/5 border-[#ca8a04]/20 shadow-lg scale-105' : 'bg-[#f9fbfa] border-black/5'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md border-2 border-white/20" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-sm text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#2d4239] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button 
            onClick={() => window.location.reload()}
            className="w-full mt-12 btn-sleek btn-sleek-pine !bg-[#2d4239] !py-6"
          >
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  // --- HOST VIEW ---
  if (isHost) {
    return (
      <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden">
        <div className="w-full md:w-80 h-1/2 md:h-full bg-white border-r border-[#2d4239]/5 p-8 flex flex-col overflow-y-auto">
          <div className="mb-10">
             <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8c6b4f] block mb-2">{strings.lobby.host}</span>
             <h2 className="text-2xl font-black uppercase tracking-tight">{strings.game.roundResults}</h2>
          </div>

          <div className="space-y-4 flex-1">
             <label className="text-[9px] font-black uppercase tracking-widest text-[#0f1a16]/40">{strings.lobby.playersJoined(gameState.players.length)}</label>
             {gameState.players.map(p => (
               <div key={p.id} className="flex items-center justify-between p-4 bg-[#f9fbfa] rounded-2xl border border-black/5">
                 <div className="flex items-center space-x-3">
                   <div className="w-8 h-8 rounded-lg flex items-center justify-center font-black text-white text-xs" style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                   <span className="font-black text-xs uppercase tracking-tight">{p.name}</span>
                 </div>
                 {p.hasGuessed ? (
                   <div className="w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center text-white">
                      <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                   </div>
                 ) : (
                   <div className="w-5 h-5 border-2 border-dashed border-[#0f1a16]/10 rounded-full"></div>
                 )}
               </div>
             ))}
          </div>

          <div className="pt-8 border-t border-black/5 mt-auto">
             <button 
               onClick={onNext}
               className="w-full py-5 btn-sleek btn-sleek-pine !text-sm"
             >
               {isRoundFinished ? strings.game.nextLocation : strings.common.continue}
             </button>
          </div>
        </div>

        <div className="flex-1 relative">
           <Map 
             center={currentQ.location}
             zoom={14}
             markers={[
               { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' },
               ...gameState.players.filter(p => p.lastGuess).map(p => ({
                 position: p.lastGuess!,
                 label: p.name,
                 color: p.color,
                 icon: 'user' as const
               }))
             ]}
             lines={gameState.players.filter(p => p.lastGuess).map(p => ({
               from: p.lastGuess!,
               to: currentQ.location,
               color: p.color
             }))}
           />
           <div className="absolute top-8 left-8 p-6 bg-white/80 backdrop-blur-xl rounded-[2.5rem] border border-black/5 shadow-2xl max-w-xs">
              <img src={currentQ.imageUrl} className="w-full aspect-square object-cover rounded-[1.5rem] mb-4 border border-black/5" />
              <p className="text-[10px] font-black uppercase tracking-[0.4em] text-[#8c6b4f] text-center">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</p>
           </div>
        </div>
      </div>
    );
  }

  // --- PLAYER VIEW ---
  return (
    <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden selection:bg-[#8c6b4f]/20">
      {isCountingDown && (
        <div className="fixed inset-0 z-[600] bg-[#2d4239]/40 backdrop-blur-3xl flex flex-col items-center justify-center text-white">
           <p className="text-white/60 font-black uppercase tracking-[0.6em] text-[10px] mb-6">{strings.game.countdownTitle}</p>
           <div className="text-9xl font-black animate-pulse">{countdownValue}</div>
        </div>
      )}

      <div className="w-full md:w-1/2 h-1/2 md:h-full flex flex-col p-6 space-y-6">
        <div className="bg-white/70 backdrop-blur-xl rounded-[2.5rem] p-5 shadow-sm border border-[#2d4239]/5 flex justify-between items-center">
          <div className="font-black text-[10px] uppercase tracking-[0.4em] text-[#8c6b4f]">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="flex items-center space-x-6">
             <div className="flex -space-x-3">
                {gameState.players.map(p => (
                  <div 
                    key={p.id} 
                    className={`w-8 h-8 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black text-white shadow-sm transition-all ${p.hasGuessed ? 'scale-110 opacity-100 ring-4 ring-[#10b981]/20' : 'scale-90 opacity-20'}`}
                    style={{ backgroundColor: p.color }}
                  >
                    {p.name.charAt(0)}
                  </div>
                ))}
             </div>
             <div className="font-black text-[#2d4239] text-sm uppercase tracking-tight">{strings.game.points(currentPlayer?.score || 0)}</div>
          </div>
        </div>

        <div className="flex-1 relative rounded-[3rem] overflow-hidden bg-[#2d4239]/5 border border-[#2d4239]/10 shadow-2xl group">
          <img src={currentQ.imageUrl} className="w-full h-full object-contain transition-transform duration-[10s] group-hover:scale-105" alt="Guess this location" />

          {isRoundFinished && (
            <div className="absolute inset-0 bg-white/50 backdrop-blur-2xl flex flex-col items-center justify-center p-8 text-center text-[#0f1a16]">
              <h2 className="text-3xl font-black mb-8 uppercase tracking-tight text-[#0f1a16]">{strings.game.roundResults}</h2>
              <div className="space-y-4 w-full max-w-sm">
                {gameState.players.map(p => (
                   <div key={p.id} className="flex justify-between items-center bg-white p-4 rounded-[1.5rem] shadow-sm border border-[#2d4239]/5">
                     <div className="flex items-center space-x-4">
                        <div className="w-5 h-5 rounded-[0.5rem] shadow-md border-2 border-white/30" style={{ backgroundColor: p.color }} />
                        <span className="font-black uppercase tracking-tight text-xs text-[#0f1a16]">{p.name}</span>
                     </div>
                     <span className="font-bold text-xs tracking-widest text-[#8c6b4f]">{p.lastDistance ? formatDistance(p.lastDistance) : strings.game.noGuess}</span>
                   </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="w-full md:w-1/2 h-1/2 md:h-full p-6 md:pl-0 flex flex-col space-y-6">
        <div className="flex-1 relative bg-white rounded-[3.5rem] shadow-[0_40px_80px_-20px_rgba(45,66,57,0.1)] border border-[#2d4239]/5 overflow-hidden">
          <Map 
            onLocationSelect={isRoundFinished || hasSubmitted ? undefined : setSelectedGuess}
            markers={[
              ...(selectedGuess ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
              ...(isRoundFinished ? [{ position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const }] : []),
              ...(isRoundFinished ? gameState.players.filter(p => p.id !== currentPlayer?.id && p.lastGuess).map(p => ({ 
                  position: p.lastGuess!, 
                  label: `${p.name}'s guess`,
                  icon: 'user' as const,
                  color: p.color
                })) : [])
            ]}
            lines={isRoundFinished ? gameState.players.filter(p => p.lastGuess).map(p => ({
              from: p.lastGuess!,
              to: currentQ.location,
              color: p.color
            })) : []}
            center={currentQ.location}
            zoom={12}
          />

          {!isRoundFinished && !hasSubmitted && (
            <div className="absolute bottom-8 inset-x-0 flex justify-center px-6">
              <button 
                disabled={!selectedGuess}
                onClick={handleGuessSubmit}
                className={`w-full max-w-xs py-5 btn-sleek !text-lg !tracking-widest ${selectedGuess ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-white/80 text-[#0f1a16]/10 shadow-none cursor-not-allowed border border-black/5'}`}
              >
                {strings.game.submitGuess}
              </button>
            </div>
          )}

          {!isRoundFinished && hasSubmitted && !isCountingDown && (
             <div className="absolute bottom-8 inset-x-0 flex justify-center px-6">
               <div className="bg-white/80 backdrop-blur-xl shadow-2xl px-10 py-5 rounded-[2rem] border border-[#2d4239]/10 flex items-center space-x-5">
