    <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden selection:bg-[#8c6b4f]/20">
      {isCountingDown && (
        <div className="fixed inset-0 z-[2500] bg-[#0f1a16]/90 backdrop-blur-3xl flex flex-col items-center justify-center text-white animate-in fade-in duration-500">
