                className={`w-full max-w-xs py-6 btn-sleek !text-lg !tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${selectedGuess ? 'text-white' : 'bg-white/80 text-[#0f1a16]/10 shadow-none cursor-not-allowed border border-black/5'}`}
              >
                {strings.game.submitGuess}
              </button>
            </div>
          )}

          {!isRoundFinished && hasSubmitted && !isCountingDown && (
             <div className="absolute bottom-12 inset-x-0 flex flex-col items-center justify-center px-6 z-[1600] space-y-4">
               <div className="bg-white/95 backdrop-blur-xl shadow-2xl px-12 py-6 rounded-[2.5rem] border border-[#2d4239]/10 flex items-center space-x-6">
                 <div className="w-6 h-6 bg-[#10b981] rounded-full flex items-center justify-center text-white shadow-lg">
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
