                 {strings.game.unlockGuess}
               </button>
             </div>
          )}
        </div>
      </div>
      <style>{`
        .leaflet-control-container { 
          display: ${isCountingDown ? 'none' : 'block'} !important;
          z-index: 500;
        }
      `}</style>
    </div>
  );
};

export default GameBoard;

import { useEffect, useRef } from 'react';
import L from 'leaflet';
import { Location } from '../types';

interface MarkerData {
  position: Location;
  label?: string;
  icon?: 'default' | 'target' | 'user';
  color?: string;
}

interface LineData {
  from: Location;
  to: Location;
  color?: string;
}

export const useMapLayers = (
  map: L.Map | null,
  markers: MarkerData[],
  lines: LineData[],
  onLocationSelect?: (loc: Location) => void
) => {
  const layerGroupRef = useRef<L.LayerGroup | null>(null);

  // Initialize LayerGroup once map is ready
  useEffect(() => {
    if (!map) return;
    layerGroupRef.current = L.layerGroup().addTo(map);
    return () => {
      layerGroupRef.current?.remove();
      layerGroupRef.current = null;
    };
  }, [map]);

  // Sync Markers and Lines
  useEffect(() => {
    const layerGroup = layerGroupRef.current;
    if (!map || !layerGroup) return;

    layerGroup.clearLayers();

    const bounds = L.latLngBounds([]);

    markers.forEach((m) => {
      const bgColor = m.color || (m.icon === 'target' ? '#ef4444' : m.icon === 'user' ? '#3b82f6' : '#6366f1');

      const icon = L.divIcon({
        className: 'custom-div-icon',
        html: `<div class="w-8 h-8 rounded-full border-2 border-white shadow-lg flex items-center justify-center transition-all duration-300" style="background-color: ${bgColor}">
          <div class="w-2.5 h-2.5 rounded-full bg-white/80"></div>
        </div>`,
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      });

      const marker = L.marker([m.position.lat, m.position.lng], { 
        icon, 
        draggable: !!onLocationSelect 
      }).addTo(layerGroup);

      if (onLocationSelect) {
        marker.on('dragend', (event) => {
          const { lat, lng } = event.target.getLatLng();
          onLocationSelect({ lat, lng });
        });
      }

      if (m.label) {
        marker.bindTooltip(m.label, { 
          permanent: false, 
          direction: 'top', 
          className: 'nordic-tooltip',
          offset: [0, -10]
        });
      }

      bounds.extend([m.position.lat, m.position.lng]);
    });

    lines.forEach((line) => {
      L.polyline(
        [[line.from.lat, line.from.lng], [line.to.lat, line.to.lng]],
        { 
          color: line.color || '#6366f1', 
          weight: 4, 
          dashArray: '10, 15',
          opacity: 0.8,
          lineCap: 'round'
        }
      ).addTo(layerGroup);

      bounds.extend([line.from.lat, line.from.lng]);
      bounds.extend([line.to.lat, line.to.lng]);
    });

    // Fit bounds if we have significant map data (Host seeing guesses or Results screen)
    if (bounds.isValid() && (markers.length > 1 || lines.length > 0)) {
      // Force a slight delay to ensure UI transitions have settled
      setTimeout(() => {
        map.invalidateSize();
        map.fitBounds(bounds, { 
          padding: [80, 80], 
          maxZoom: 15, 
          animate: true,
          duration: 1.0
        });
      }, 50);
    }
  }, [map, markers, lines, onLocationSelect]);
};

export interface Location {
  lat: number;
  lng: number;
}

export interface User {
  username: string;
  id: string;
}

export interface Question {
  id: string;
  imageUrl: string;
  location: Location;
  title?: string;
  locationSource?: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL';
}

export interface Trail {
  id: string;
  name: string;
  questions: Question[];
  creatorId: string;
  lastUpdated: number;
}

export interface Player {
  id: string;
  name: string;
  color: string;
  score: number;
  lastGuess?: Location;
  lastDistance?: number;
  lastPointsGained?: number;
  hasGuessed: boolean;
}

export interface GameState {
  id: string;
  status: 'LOBBY' | 'PLAYING' | 'COUNTDOWN' | 'RESULTS' | 'SCOREBOARD' | 'FINISHED';
  questions: Question[];
  currentQuestionIndex: number;
  players: Player[];
  hostId: string;
}

export type AppView = 'HOME' | 'AUTH' | 'DASHBOARD' | 'CREATE' | 'LOBBY' | 'PLAYING' | 'JOIN';

import { GameState, Player, Location, Question } from './types';

export type GameAction = 
  | { type: 'SYNC_STATE'; payload: GameState }
  | { type: 'INIT_LOBBY'; payload: { id: string, questions: Question[], hostId: string } }
  | { type: 'JOIN_PLAYER'; payload: Player }
  | { type: 'KICK_PLAYER'; payload: string }
  | { type: 'SET_STATUS'; payload: GameState['status'] }
  | { type: 'SUBMIT_GUESS'; payload: { playerId: string, guess: Location, distance: number } }
  | { type: 'UNLOCK_GUESS'; payload: string }
  | { type: 'CALCULATE_SCORES' }
  | { type: 'NEXT_ROUND' }
  | { type: 'EXIT_GAME' };

export const gameReducer = (state: GameState | null, action: GameAction): GameState | null => {
  switch (action.type) {
    case 'SYNC_STATE':
      return action.payload;

    case 'INIT_LOBBY':
      return {
        id: action.payload.id,
        status: 'LOBBY',
        questions: action.payload.questions,
        currentQuestionIndex: 0,
        players: [],
        hostId: action.payload.hostId,
      };

    case 'JOIN_PLAYER':
      if (!state) return null;
      if (state.players.find(p => p.id === action.payload.id)) return state;
      return { ...state, players: [...state.players, action.payload] };

    case 'KICK_PLAYER':
      if (!state) return null;
      return { ...state, players: state.players.filter(p => p.id !== action.payload) };

    case 'SET_STATUS':
      if (!state) return null;
      return { ...state, status: action.payload };

    case 'SUBMIT_GUESS':
      if (!state) return null;
      const updatedPlayers = state.players.map(p => 
        p.id === action.payload.playerId 
          ? { ...p, hasGuessed: true, lastGuess: action.payload.guess, lastDistance: action.payload.distance } 
          : p
      );
      return { ...state, players: updatedPlayers };

    case 'UNLOCK_GUESS':
      if (!state) return null;
      return { 
        ...state, 
        players: state.players.map(p => 
          p.id === action.payload 
            ? { ...p, hasGuessed: false, lastGuess: undefined, lastDistance: undefined } 
            : p
        )
      };

    case 'CALCULATE_SCORES':
      if (!state) return null;
      // Calculate gains but keep status at SCOREBOARD for animation
      const sortedByDistance = [...state.players].sort((a, b) => (a.lastDistance || Infinity) - (b.lastDistance || Infinity));
      const playersWithCalculatedScores = state.players.map(p => {
        const rank = sortedByDistance.findIndex(sp => sp.id === p.id);
        const pointsGained = p.lastDistance !== undefined ? Math.max(0, state.players.length - rank) : 0;
        return { 
          ...p, 
          lastPointsGained: pointsGained,
          score: p.score + pointsGained 
        };
      });
      return { ...state, players: playersWithCalculatedScores, status: 'SCOREBOARD' };

    case 'NEXT_ROUND':
      if (!state) return null;
      const isLastQuestion = state.currentQuestionIndex === state.questions.length - 1;

      if (isLastQuestion) return { ...state, status: 'FINISHED' };

      const resetPlayers = state.players.map(p => ({
        ...p,
        hasGuessed: false,
        lastGuess: undefined,
        lastDistance: undefined,
        lastPointsGained: 0
      }));

      return {
        ...state,
        players: resetPlayers,
        currentQuestionIndex: state.currentQuestionIndex + 1,
        status: 'PLAYING'
      };

    case 'EXIT_GAME':
      return null;

    default:
      return state;
  }
};

import React, { useState, useEffect, useMemo, useReducer, useCallback, useRef } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
