  const [gameState, dispatch] = useReducer(gameReducer, null);

  const { broadcast, sendAction, requestSync } = useGameSync(
    useCallback((state) => dispatch({ type: 'SYNC_STATE', payload: state }), []),
    useCallback((action) => dispatch(action), []),
    isHost,
    gameState
  );

  useEffect(() => {
    if (isHost && gameState) {
      broadcast(gameState);
    }
  }, [gameState, isHost, broadcast]);

  useEffect(() => {
    if (view === 'JOIN' && !gameState) {
      requestSync();
      const interval = setInterval(requestSync, 2000);
      return () => clearInterval(interval);
    }
  }, [view, gameState, requestSync]);

  // Handle automatic navigation based on game state
  // FIX: Only navigate to PLAYING if the user is actually IN the game (as host or player)
  useEffect(() => {
    if (gameState && (isHost || currentPlayer)) {
      const inGameStatus = ['PLAYING', 'COUNTDOWN', 'RESULTS', 'SCOREBOARD', 'FINISHED'];
      if (inGameStatus.includes(gameState.status) && view !== 'PLAYING') {
        setView('PLAYING');
      }

      if (currentPlayer && !isHost && !isJoining) {
        const isPresent = gameState.players.some(p => p.id === currentPlayer.id);
        if (!isPresent && (view === 'LOBBY' || view === 'PLAYING')) {
           alert(strings.lobby.kickedDesc);
           setCurrentPlayer(null);
           setView('HOME');
           localStorage.removeItem('locateit_last_player_id');
        }
      }
    }
  }, [gameState, currentPlayer, isHost, view, isJoining]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  const availableColors = ['#6366f1', '#f43f5e', '#10b981', '#f59e0b', '#06b6d4', '#d946ef', '#8b5cf6', '#f97316'];
  const [selectedColor, setSelectedColor] = useState(availableColors[0]);

  const handleSaveTrail = (questions: Question[], name: string) => {
    if (!user) return;
    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now()
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now()
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const idx = trails.findIndex(t => t.id === trailToSave.id);
      if (idx > -1) trails[idx] = trailToSave;
      else trails.push(trailToSave);

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); 

    const newGameId = generateId();
    dispatch({ type: 'INIT_LOBBY', payload: { id: newGameId, questions: trail.questions, hostId: user.id } });
    setView('LOBBY');
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();

    if (!gameState || gameState.id !== code) {
      setJoinError(`Expedition ${code} not found. Ensure the code is correct.`);
      requestSync();
      return;
    }

    // Persistent re-join: Try ID match first
    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);

    if (existingById) {
      setCurrentPlayer(existingById);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    // Try name match as secondary re-join (if they lost their local storage but use same name)
    const existingByName = gameState.players.find(p => p.name.toLowerCase() === name.toLowerCase());
    if (existingByName) {
      setCurrentPlayer(existingByName);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', existingByName.id);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    // Brand new join
    const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    setIsJoining(true);

    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 5000);

    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  const PermissionElements = (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
    </>
  );

  if (view === 'AUTH') return (
    <>
      {PermissionElements}
      <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />
    </>
  );

  if (view === 'DASHBOARD' && user) return (
    <>
      {PermissionElements}
      <Dashboard user={user} onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} onHostTrail={handleHostTrail} onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }} />
    </>
  );

  if (view === 'CREATE') return (
    <>
      {PermissionElements}
      <QuizCreator 
        initialTrail={editingTrail || undefined} 
        onComplete={handleSaveTrail} 
        onCancel={() => setView('DASHBOARD')} 
        onRequestPermissions={() => setShowPermissionModal(true)}
      />
    </>
  );

  if (view === 'LOBBY' && gameState) return (
    <>
      {PermissionElements}
      <Lobby gameState={gameState} isHost={isHost} onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} currentPlayer={currentPlayer} onBack={() => { dispatch({ type: 'EXIT_GAME' }); setView('DASHBOARD'); }} onKick={(id) => dispatch({ type: 'KICK_PLAYER', payload: id })} />
    </>
  );

  if (view === 'PLAYING' && gameState) return (
    <>
      {PermissionElements}
      <GameBoard 
        gameState={gameState} 
        isHost={isHost} 
        currentPlayer={currentPlayer} 
        onGuess={(guess) => {
          if (!currentPlayer) return;
          const currentQ = gameState.questions[gameState.currentQuestionIndex];
          const dist = calculateDistance(guess, currentQ.location);
          sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
          if (isHost) dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
        }} 
        onUnlock={() => {
          if (!currentPlayer) return;
          sendAction({ type: 'PLAYER_UNLOCK_REQUEST', playerId: currentPlayer.id });
          if (isHost) dispatch({ type: 'UNLOCK_GUESS', payload: currentPlayer.id });
        }}
        onReveal={() => {
          if (!isHost) return;
          dispatch({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
          sendAction({ type: 'HOST_REVEAL_REQUEST' });
        }}
        onForceReveal={() => {
          if (!isHost) return;
          dispatch({ type: 'FORCE_REVEAL' });
          sendAction({ type: 'FORCE_REVEAL' });
        }}
        onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
        onShowScoreboard={() => isHost && dispatch({ type: 'CALCULATE_SCORES' })}
        onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
        onExit={() => {
          dispatch({ type: 'EXIT_GAME' });
          setView(isHost ? 'DASHBOARD' : 'HOME');
        }}
      />
    </>
  );

  if (view === 'JOIN') return (
    <>
      {PermissionElements}
      <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#f9fbfa]">
        <div className="max-w-md w-full">
          <button onClick={() => setView('HOME')} className="mb-8 text-[#0f1a16]/40 hover:text-[#0f1a16] flex items-center font-bold text-xs uppercase tracking-widest transition-all">
             <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
             {strings.join.back}
          </button>
          <div className="bg-white rounded-[3rem] p-12 border border-black/5 shadow-[0_40px_80px_-15px_rgba(15,26,22,0.1)]">
            <h2 className="text-3xl font-black text-[#0f1a16] mb-10 text-center tracking-tight uppercase">{strings.join.title}</h2>
            <div className="space-y-6">
              <div className="relative">
                <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 uppercase font-bold text-center tracking-[0.3em] text-xl text-[#0f1a16] placeholder:opacity-20 transition-all" />
                {!gameState && <div className="absolute top-2 right-4"><div className="w-2 h-2 rounded-full bg-[#8c6b4f] animate-ping"></div></div>}
              </div>
              <input id="playerName" placeholder={strings.join.yourName} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 text-[#0f1a16] font-bold placeholder:opacity-20 transition-all" />

              {joinError && (
                <p className="text-[#7c2d12] text-[10px] font-black uppercase text-center tracking-widest animate-pulse">{joinError}</p>
              )}

              <div className="space-y-4 pt-2">
                <label className="text-[10px] font-bold text-[#0f1a16]/30 uppercase tracking-[0.4em] ml-2">{strings.lobby.chooseColor}</label>
                <div className="flex flex-wrap gap-4 justify-center">
                  {availableColors.map(color => (
                    <button key={color} onClick={() => setSelectedColor(color)} className={`w-10 h-10 rounded-full transition-all active:scale-90 ${selectedColor === color ? 'ring-4 ring-black/10 scale-110 shadow-lg border-2 border-white' : 'opacity-40 hover:opacity-100'}`} style={{ backgroundColor: color }} />
                  ))}
                </div>
              </div>
              <button onClick={() => {
                const code = (document.getElementById('gameCode') as HTMLInputElement).value;
                const name = (document.getElementById('playerName') as HTMLInputElement).value;
                if (code && name) handleJoinGame(code, name);
              }} className="w-full py-5 btn-sleek btn-sleek-pine text-base mt-6">
                {strings.join.joinLobby}
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );

  return (
    <div className="h-screen bg-[#f9fbfa] text-[#0f1a16] overflow-hidden flex flex-col relative selection:bg-[#8c6b4f]/20">
      <FlyingWordsBackground />
      {PermissionElements}
      <div className="fixed -top-80 -left-60 w-[1000px] h-[1000px] bg-[#2d4239]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-80 -right-60 w-[1000px] h-[1000px] bg-[#8c6b4f]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col items-center relative py-10 md:py-12 px-6 z-10 gap-8 md:gap-12 overflow-y-auto scroll-smooth-touch">
        <div className="flex flex-col items-center select-none text-center pt-2">
            <AnimationVariantSwapT fontSize="clamp(1.1rem, 4.5vw, 2.4rem)" />
        </div>
        <section className="w-full max-w-3xl flex flex-col items-center gap-10 md:gap-14">
            <div className="w-full text-center flex flex-col items-center space-y-8">
              <div className="bg-white/45 backdrop-blur-md px-6 md:px-10 py-8 md:py-10 rounded-[2.5rem] border border-black/5 shadow-sm space-y-4 md:space-y-6">
                <h1 className="text-3xl md:text-6xl text-[#0f1a16] leading-[1.1] font-black tracking-tight">{strings.home.subtitle}</h1>
                <p className="text-[#0f1a16]/60 text-sm md:text-base font-bold uppercase tracking-[0.2em] max-w-lg mx-auto">Build unique trails & challenge your inner circle.</p>
              </div>
              <div className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center w-full max-w-xl mx-auto px-2 relative z-20">
                <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-oak text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                  {strings.home.designTrail}
                </button>
                <button onClick={() => setView('JOIN')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-pine text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                  {strings.home.joinQuest}
                </button>
              </div>
            </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface ScoreboardProps {
  players: Player[];
  isLastRound: boolean;
  onAnimationComplete: () => void;
  isHost?: boolean;
}

const Scoreboard: React.FC<ScoreboardProps> = ({ players, isLastRound, onAnimationComplete, isHost }) => {
  const [step, setStep] = useState<'initial' | 'showingPoints' | 'counting' | 'sorting'>('initial');
  const [visibleCount, setVisibleCount] = useState(0); 
  const [displayScores, setDisplayScores] = useState<Record<string, number>>(
    Object.fromEntries(players.map(p => [p.id, p.score - (p.lastPointsGained || 0)]))
  );

  const sortedInitial = useMemo(() => {
    return [...players].sort((a, b) => {
      const scoreA = a.score - (a.lastPointsGained || 0);
      const scoreB = b.score - (b.lastPointsGained || 0);
      return scoreB - scoreA;
    });
  }, [players]);

  const sortedFinal = useMemo(() => {
    return [...players].sort((a, b) => b.score - a.score);
  }, [players]);

  const currentList = step === 'sorting' ? sortedFinal : sortedInitial;

  useEffect(() => {
    if (isLastRound) {
      const interval = setInterval(() => {
        setVisibleCount(prev => {
          if (prev >= players.length) {
            clearInterval(interval);
            onAnimationComplete();
            return prev;
          }
          return prev + 1;
        });
      }, 1500);
      return () => clearInterval(interval);
    } else {
      const timers = [
        setTimeout(() => setStep('showingPoints'), 1000),
        setTimeout(() => setStep('counting'), 2500),
        setTimeout(() => {
          const newScores = Object.fromEntries(players.map(p => [p.id, p.score]));
          setDisplayScores(newScores);
        }, 3000),
        setTimeout(() => setStep('sorting'), 4500),
        setTimeout(() => onAnimationComplete(), 5500)
      ];
      return () => timers.forEach(clearTimeout);
    }
  }, [isLastRound, players, onAnimationComplete]);

  if (isLastRound) {
    const reversedRanking = [...sortedFinal].reverse();
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-6 bg-white rounded-[3.5rem] shadow-2xl border border-black/5 animate-in fade-in zoom-in duration-700">
        <h2 className="text-4xl font-black mb-12 uppercase tracking-tighter text-[#0f1a16]">{strings.game.expeditionComplete}</h2>
        <div className="w-full max-w-lg space-y-4">
          {reversedRanking.slice(0, visibleCount).reverse().map((p, idx) => {
            const rank = sortedFinal.findIndex(sp => sp.id === p.id) + 1;
            return (
              <div 
                key={p.id} 
                className={`flex items-center justify-between p-6 rounded-[2rem] border transition-all duration-700 animate-in slide-in-from-bottom-8 ${rank === 1 ? 'bg-[#ca8a04]/10 border-[#ca8a04]/30 shadow-xl scale-110 mb-8' : 'bg-[#f9fbfa] border-black/5 shadow-sm'}`}
              >
                <div className="flex items-center space-x-6">
                  <div className={`text-3xl font-black ${rank === 1 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{rank}</div>
                  <div className="w-14 h-14 rounded-[1.5rem] flex items-center justify-center font-black text-2xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-2xl font-black text-[#2d4239]">{strings.game.points(p.score)}</div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col items-center justify-start p-10 bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-y-auto scroll-smooth-touch">
      <h2 className="text-3xl font-black mb-10 uppercase tracking-tight text-[#0f1a16]">{strings.game.roundResults}</h2>
      <div className="w-full max-w-lg relative">
        <div className="space-y-4">
          {currentList.map((p, idx) => {
            const isGaining = step === 'showingPoints' || step === 'counting';
            const points = p.lastPointsGained || 0;

            return (
              <div 
                key={p.id} 
                className="flex items-center justify-between p-5 rounded-[2rem] bg-[#f9fbfa] border border-black/5 shadow-sm transition-all duration-700"
                style={{ transform: step === 'sorting' ? 'translateY(0)' : 'none' }}
              >
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-[#0f1a16] text-sm">{p.name}</div>
                </div>

                <div className="flex items-center space-x-4">
                  {isGaining && points > 0 && !isHost && (
                    <div className={`px-4 py-2 bg-[#10b981] text-white rounded-full font-black text-xs uppercase tracking-widest animate-in zoom-in bounce-in duration-500 ${step === 'counting' ? 'animate-out fade-out slide-out-to-right-8' : ''}`}>
                      +{points}
                    </div>
                  )}
                  {isHost && isGaining && points > 0 && (
                    <div className="text-[10px] font-black text-[#10b981]">+{points}</div>
                  )}
                  <div className="text-xl font-black text-[#2d4239] tabular-nums min-w-[3ch] text-right">
                    {displayScores[p.id]}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onUnlock?: () => void;
  onReveal?: () => void;
  onForceReveal?: () => void;
  onCountdownFinish: () => void;
  onShowScoreboard: () => void;
  onNext: () => void;
  onExit: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ 
  gameState, 
  isHost, 
  currentPlayer, 
  onGuess, 
  onUnlock,
  onReveal,
  onForceReveal,
  onCountdownFinish, 
  onShowScoreboard,
  onNext, 
  onExit 
}) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [isFullscreenImage, setIsFullscreenImage] = useState(false);
  const [imageZoom, setImageZoom] = useState(1);
  const [imageOffset, setImageOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [canProceed, setCanProceed] = useState(false);
  const [showForceRevealConfirm, setShowForceRevealConfirm] = useState(false);

  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isScoreboard = gameState.status === 'SCOREBOARD';
  const isGameFinished = gameState.status === 'FINISHED';
  const isLastRound = gameState.currentQuestionIndex === gameState.questions.length - 1;

  // Real-time derive current player status from gameState
  const matchingPlayer = gameState.players.find(p => p.id === currentPlayer?.id);
  const hasSubmitted = !!matchingPlayer?.hasGuessed;
  const currentTotalScore = matchingPlayer?.score || 0;

  useEffect(() => {
    if (isRoundFinished || isCountingDown || isScoreboard) {
      setIsFullscreenImage(false);
    }
  }, [gameState.status]);

  useEffect(() => {
    setSelectedGuess(null);
    setCountdownValue(3);
    setIsFullscreenImage(false);
    setImageZoom(1);
    setImageOffset({ x: 0, y: 0 });
    setCanProceed(false);
    setShowForceRevealConfirm(false);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (isCountingDown) {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [isCountingDown, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
    }
  };

  const handleRevealClick = () => {
    const nonGuessed = gameState.players.filter(p => !p.hasGuessed);
    if (nonGuessed.length > 0) {
      setShowForceRevealConfirm(true);
    } else {
      onReveal?.();
    }
  };

  const markersForMap = isHost 
    ? [
        { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
        ...gameState.players.filter(p => p.hasGuessed && p.lastGuess).map(p => ({
          position: p.lastGuess!,
          label: p.name,
          color: p.color,
          icon: 'user' as const
        }))
      ]
    : [
        ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
        ...(isRoundFinished ? [
            { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
            ...gameState.players.filter(p => p.lastGuess).map(p => ({ 
              position: p.lastGuess!, 
              label: p.id === currentPlayer?.id ? strings.game.yourGuess : `${p.name}'s guess`, 
              icon: 'user' as const, 
              color: p.color 
            }))
        ] : [])
      ];

  const linesForMap = (isHost || isRoundFinished) 
    ? gameState.players.filter(p => p.lastGuess && (isHost || isRoundFinished)).map(p => ({ 
        from: p.lastGuess!, 
        to: currentQ.location, 
        color: p.color 
      })) 
    : [];

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => Math.min(prev + 0.5, 4));
  };
  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => {
      const next = Math.max(prev - 0.5, 1);
      if (next === 1) setImageOffset({ x: 0, y: 0 });
      return next;
    });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (imageZoom === 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - imageOffset.x, y: e.clientY - imageOffset.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setImageOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  const handleMouseUp = () => setIsDragging(false);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
