          <button onClick={() => setIsSettingView(false)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest">{strings.common.back}</button>
        </header>
        <main className="flex-1 relative">
           <Map center={viewCenter} zoom={startingView?.zoom || 12} />
           <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
