           <div className="absolute bottom-10 inset-x-0 flex justify-center p-6">
              <button onClick={handleSaveView} className="w-full max-w-sm py-5 btn-sleek btn-sleek-pine !bg-[#2d4239]">Set Current View as Start</button>
           </div>
