  useEffect(() => {
    if (gameState && (isHost || currentPlayer)) {
      const inGameStatus = ['PLAYING', 'COUNTDOWN', 'RESULTS', 'SCOREBOARD', 'FINISHED'];
      if (inGameStatus.includes(gameState.status) && view !== 'PLAYING') {
        setView('PLAYING');
      }

      if (currentPlayer && !isHost && !isJoining) {
        const isPresent = gameState.players.some(p => p.id === currentPlayer.id);
        if (!isPresent && (view === 'LOBBY' || view === 'PLAYING')) {
           alert(strings.lobby.kickedDesc);
           setCurrentPlayer(null);
           setView('HOME');
           localStorage.removeItem('locateit_last_player_id');
        }
      }
    }
  }, [gameState, currentPlayer, isHost, view, isJoining]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  const availableColors = ['#6366f1', '#0d9488', '#10b981', '#f59e0b', '#06b6d4', '#d946ef', '#8b5cf6', '#f97316'];
  const [selectedColor, setSelectedColor] = useState(availableColors[0]);

  const handleSaveTrail = (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => {
    if (!user) return;
    const trailToSave: Trail = editingTrail ? {
      ...editingTrail,
      name: name || editingTrail.name,
      questions: questions,
      lastUpdated: Date.now(),
      startingView
    } : {
      id: generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now(),
      startingView
    };

    try {
      const key = `trails_${user.id}`;
      const saved = localStorage.getItem(key);
      let trails: Trail[] = saved ? JSON.parse(saved) : [];
      const idx = trails.findIndex(t => t.id === trailToSave.id);
      if (idx > -1) trails[idx] = trailToSave;
      else trails.push(trailToSave);

      localStorage.setItem(key, JSON.stringify(trails));
      setEditingTrail(null);
      setView('DASHBOARD');
    } catch (e) {
      alert(strings.storage.limitReached);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); 

    const newGameId = generateId();
    dispatch({ 
      type: 'INIT_LOBBY', 
      payload: { 
        id: newGameId, 
        questions: trail.questions, 
        hostId: user.id, 
        startingView: trail.startingView 
      } 
    });
    setView('LOBBY');
  };

  const handleResumeHost = () => {
    const saved = localStorage.getItem('locateit_active_host_state');
    if (saved) {
      const state = JSON.parse(saved) as GameState;
      setIsHost(true);
      setCurrentPlayer(null);
      dispatch({ type: 'SYNC_STATE', payload: state });
      setView(state.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
    }
  };

  const handleJoinGame = (gameCode: string, name: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();

    if (!gameState || gameState.id !== code) {
      setJoinError(`Expedition ${code} not found. Ensure the code is correct.`);
      requestSync();
      return;
    }

    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);

    if (existingById) {
      setCurrentPlayer(existingById);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    const existingByName = gameState.players.find(p => p.name.toLowerCase() === name.toLowerCase());
    if (existingByName) {
      setCurrentPlayer(existingByName);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', existingByName.id);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    const newPlayer: Player = { id: generateId(), name, color: selectedColor, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    setIsJoining(true);

    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 5000);

    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  const handleExitGame = () => {
    localStorage.removeItem('locateit_active_host_state');
    dispatch({ type: 'EXIT_GAME' });
    setView(isHost ? 'DASHBOARD' : 'HOME');
  };

  const PermissionElements = (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
    </>
  );

  if (view === 'AUTH') return (
    <>
      {PermissionElements}
      <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />
    </>
  );

  if (view === 'DASHBOARD' && user) return (
    <>
      {PermissionElements}
      <Dashboard 
        user={user} 
        onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} 
        onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} 
        onHostTrail={handleHostTrail} 
        onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }}
        onResumeHost={localStorage.getItem('locateit_active_host_state') ? handleResumeHost : undefined}
      />
    </>
  );

  if (view === 'CREATE') return (
    <>
      {PermissionElements}
      <QuizCreator 
        initialTrail={editingTrail || undefined} 
        onComplete={handleSaveTrail} 
        onCancel={() => setView('DASHBOARD')} 
        onRequestPermissions={() => setShowPermissionModal(true)}
      />
    </>
  );

  if (view === 'LOBBY' && gameState) return (
    <>
      {PermissionElements}
      <Lobby gameState={gameState} isHost={isHost} onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} currentPlayer={currentPlayer} onBack={handleExitGame} onKick={(id) => dispatch({ type: 'KICK_PLAYER', payload: id })} />
    </>
  );

  if (view === 'PLAYING' && gameState) return (
    <>
      {PermissionElements}
      <GameBoard 
        gameState={gameState} 
        isHost={isHost} 
        currentPlayer={currentPlayer} 
        onGuess={(guess) => {
          if (!currentPlayer) return;
          const currentQ = gameState.questions[gameState.currentQuestionIndex];
          const dist = calculateDistance(guess, currentQ.location);
          sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
          if (isHost) dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
        }} 
        onUnlock={() => {
          if (!currentPlayer) return;
          sendAction({ type: 'PLAYER_UNLOCK_REQUEST', playerId: currentPlayer.id });
          if (isHost) dispatch({ type: 'UNLOCK_GUESS', payload: currentPlayer.id });
        }}
        onReveal={() => {
          if (!isHost) return;
          dispatch({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
          sendAction({ type: 'HOST_REVEAL_REQUEST' });
        }}
        onForceReveal={() => {
          if (!isHost) return;
          dispatch({ type: 'FORCE_REVEAL' });
          sendAction({ type: 'FORCE_REVEAL' });
        }}
        onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
        onShowScoreboard={() => isHost && dispatch({ type: 'CALCULATE_SCORES' })}
        onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
        onExit={handleExitGame}
      />
    </>
  );

  if (view === 'JOIN') return (
    <>
      {PermissionElements}
      <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-[#f9fbfa]">
        <div className="max-w-md w-full">
          <button onClick={() => setView('HOME')} className="mb-8 text-[#0f1a16]/40 hover:text-[#0f1a16] flex items-center font-bold text-xs uppercase tracking-widest transition-all">
             <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
             {strings.join.back}
          </button>
          <div className="bg-white rounded-[3rem] p-12 border border-black/5 shadow-[0_40px_80px_-15px_rgba(15,26,22,0.1)]">
            <h2 className="text-3xl font-black text-[#0f1a16] mb-10 text-center tracking-tight uppercase">{strings.join.title}</h2>
            <div className="space-y-6">
              <div className="relative">
                <input id="gameCode" placeholder={strings.join.gameCode} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 uppercase font-bold text-center tracking-[0.3em] text-xl text-[#0f1a16] placeholder:opacity-20 transition-all" />
                {!gameState && <div className="absolute top-2 right-4"><div className="w-2 h-2 rounded-full bg-[#8c6b4f] animate-ping"></div></div>}
              </div>
              <input id="playerName" placeholder={strings.join.yourName} className="w-full px-8 py-5 bg-[#f9fbfa] border-0 rounded-2xl outline-none focus:ring-2 focus:ring-[#0f1a16]/5 text-[#0f1a16] font-bold placeholder:opacity-20 transition-all" />

              {joinError && (
                <p className="text-[#7c2d12] text-[10px] font-black uppercase text-center tracking-widest animate-pulse">{joinError}</p>
              )}

              <div className="space-y-4 pt-2">
                <label className="text-[10px] font-bold text-[#0f1a16]/30 uppercase tracking-[0.4em] ml-2">{strings.lobby.chooseColor}</label>
                <div className="flex flex-wrap gap-4 justify-center">
                  {availableColors.map(color => (
                    <button key={color} onClick={() => setSelectedColor(color)} className={`w-10 h-10 rounded-full transition-all active:scale-90 ${selectedColor === color ? 'ring-4 ring-black/10 scale-110 shadow-lg border-2 border-white' : 'opacity-40 hover:opacity-100'}`} style={{ backgroundColor: color }} />
                  ))}
                </div>
              </div>
              <button onClick={() => {
                const code = (document.getElementById('gameCode') as HTMLInputElement).value;
                const name = (document.getElementById('playerName') as HTMLInputElement).value;
                if (code && name) handleJoinGame(code, name);
              }} className="w-full py-5 btn-sleek btn-sleek-pine text-base mt-6">
                {strings.join.joinLobby}
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  );

  return (
    <div className="h-screen bg-[#f9fbfa] text-[#0f1a16] overflow-hidden flex flex-col relative selection:bg-[#8c6b4f]/20">
      <FlyingWordsBackground />
      {PermissionElements}
      <div className="fixed -top-80 -left-60 w-[1000px] h-[1000px] bg-[#2d4239]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <div className="fixed -bottom-80 -right-60 w-[1000px] h-[1000px] bg-[#8c6b4f]/5 blur-[180px] rounded-full pointer-events-none"></div>
      <main className="flex-1 max-w-6xl mx-auto w-full flex flex-col items-center relative py-10 md:py-12 px-6 z-10 gap-8 md:gap-12 overflow-y-auto scroll-smooth-touch">
        <div className="flex flex-col items-center select-none text-center pt-2">
            <AnimationVariantSwapT fontSize="clamp(1.1rem, 4.5vw, 2.4rem)" />
        </div>
        <section className="w-full max-w-3xl flex flex-col items-center gap-10 md:gap-14">
            <div className="w-full text-center flex flex-col items-center space-y-8">
              <div className="bg-white/45 backdrop-blur-md px-6 md:px-10 py-8 md:py-10 rounded-[2.5rem] border border-black/5 shadow-sm space-y-4 md:space-y-6">
                <h1 className="text-3xl md:text-6xl text-[#0f1a16] leading-[1.1] font-black tracking-tight">{strings.home.subtitle}</h1>
                <p className="text-[#0f1a16]/60 text-sm md:text-base font-bold uppercase tracking-[0.2em] max-w-lg mx-auto">Build unique trails & challenge your inner circle.</p>
              </div>
              <div className="flex flex-col sm:flex-row gap-4 md:gap-6 justify-center w-full max-w-xl mx-auto px-2 relative z-20">
                <button onClick={() => user ? setView('DASHBOARD') : setView('AUTH')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-oak text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
                  {strings.home.designTrail}
                </button>
                <button onClick={() => setView('JOIN')} className="px-8 py-5 md:py-6 btn-sleek btn-sleek-pine text-sm md:text-base flex-1">
                  <svg className="w-4 md:w-5 h-4 md:h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" /></svg>
                  {strings.home.joinQuest}
                </button>
              </div>
            </div>
        </section>
      </main>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { Location } from '../types';
import { useMapLayers } from '../hooks/useMapLayers';

interface MapProps {
  onLocationSelect?: (loc: Location) => void;
  onViewChange?: (view: { center: Location, zoom: number }) => void;
  markers?: { position: Location; label?: string; icon?: 'default' | 'target' | 'user'; color?: string }[];
  center?: Location;
  zoom?: number;
  lines?: { from: Location; to: Location; color?: string }[];
  roundIndex?: number;
}

const isValid = (loc?: Location): boolean => {
  return !!loc && typeof loc.lat === 'number' && typeof loc.lng === 'number' && !isNaN(loc.lat) && !isNaN(loc.lng);
};

const Map: React.FC<MapProps> = ({ 
  onLocationSelect, 
  onViewChange,
  markers = [], 
  center, 
  zoom = 13, 
  lines = [],
  roundIndex = 0
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const [map, setMap] = useState<L.Map | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current || map) return;

    const startPos: [number, number] = isValid(center) ? [center!.lat, center!.lng] : [51.505, -0.09];

    const instance = L.map(mapContainerRef.current, {
      zoomControl: false,
      attributionControl: false,
      scrollWheelZoom: true,
      fadeAnimation: false,
      markerZoomAnimation: true
    }).setView(startPos, zoom);

    L.control.zoom({ position: 'bottomright' }).addTo(instance);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
    }).addTo(instance);

    instance.on('click', (e) => {
      if (onLocationSelect) {
        onLocationSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
      }
    });

    instance.on('moveend', () => {
      if (onViewChange) {
        const c = instance.getCenter();
        onViewChange({ center: { lat: c.lat, lng: c.lng }, zoom: instance.getZoom() });
      }
    });

    setMap(instance);

    const resizeObserver = new ResizeObserver(() => {
      instance.invalidateSize();
    });
    resizeObserver.observe(mapContainerRef.current);

    return () => {
      resizeObserver.disconnect();
      instance.off();
      instance.remove();
      setMap(null);
    };
  }, []);

  useEffect(() => {
    if (map && isValid(center)) {
      map.setView([center!.lat, center!.lng], zoom);
    }
  }, [map, center, zoom, roundIndex]);

  useMapLayers(map, markers, lines, onLocationSelect);

  return (
    <div className="w-full h-full relative group bg-white">
      <div ref={mapContainerRef} className="w-full h-full" />
      <style>{`
        .nordic-tooltip {
          background: #ffffff;
          border: 1px solid rgba(45, 66, 57, 0.1);
          border-radius: 12px;
          padding: 6px 12px;
          font-family: 'Space Grotesk', sans-serif;
          font-weight: 700;
          font-size: 10px;
          text-transform: uppercase;
          letter-spacing: 0.1em;
          box-shadow: 0 10px 20px -5px rgba(15, 26, 22, 0.1);
          color: #0f1a16;
        }
        .nordic-tooltip:before {
          border-top-color: #ffffff;
        }
        .leaflet-bottom.leaflet-right {
          bottom: 24px !important;
          right: 24px !important;
          z-index: 1000 !important;
        }
        .leaflet-bar {
          border: none !important;
          box-shadow: 0 10px 20px -5px rgba(15, 26, 22, 0.2) !important;
        }
        .leaflet-bar a {
          background-color: #ffffff !important;
          color: #0f1a16 !important;
          border: 1px solid rgba(15, 26, 22, 0.05) !important;
          border-radius: 12px !important;
          margin-bottom: 8px !important;
          width: 44px !important;
          height: 44px !important;
          line-height: 44px !important;
          font-weight: bold !important;
          font-size: 18px !important;
        }
        .leaflet-bar a:hover {
          background-color: #f9fbfa !important;
        }
      `}</style>
    </div>
  );
};

export default Map;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);
  const [temporaryView, setTemporaryView] = useState<{ center: Location, zoom: number } | null>(null);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isStartingCamera, setIsStartingCamera] = useState(false);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);
  const [showSavedToast, setShowSavedToast] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;

    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      setCurrentLocation(loc);
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = (err: GeolocationPositionError) => {
      if (err.code === err.TIMEOUT && !currentLocation) {
        navigator.geolocation.getCurrentPosition(success, undefined, { ...options, enableHighAccuracy: false });
      }
    };
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    navigator.geolocation.getCurrentPosition(success, handleError, options);
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, [locationStatus]);

  useEffect(() => {
    if (isCapturing && activeStream && videoRef.current) {
      videoRef.current.srcObject = activeStream;
      videoRef.current.play().catch(err => console.error("Video play failed:", err));
    }
  }, [isCapturing, activeStream]);

  const stopCamera = useCallback(() => {
    if (activeStream) {
      activeStream.getTracks().forEach(track => track.stop());
      setActiveStream(null);
    }
    setIsCapturing(false);
    setIsStartingCamera(false);
  }, [activeStream]);

  const startCamera = async () => {
    if (cameraStatus === 'denied') { setError(strings.creator.cameraError); return; }
    setError(null);
    setIsStartingCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1920 } } });
      setActiveStream(stream);
      setIsCapturing(true);
      setIsStartingCamera(false);
    } catch (err) {
      setError(strings.creator.cameraError);
      setIsStartingCamera(false);
      setIsCapturing(false);
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, w, h);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}
        if (source !== 'IMAGE') source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;
    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
    } else {
      setQuestions(prev => [...prev, { id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
    }
    setPendingQuestion(null);
  };

  const handleSaveView = () => {
    if (temporaryView) {
      setStartingView(temporaryView);
      setShowSavedToast(true);
      setTimeout(() => {
        setShowSavedToast(false);
        setIsSettingView(false);
      }, 1000);
    } else {
      setIsSettingView(false);
    }
  };

  if (isSettingView) {
    const viewCenter = startingView?.center || (questions.length > 0 ? questions[0].location : { lat: 51.505, lng: -0.09 });
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
