            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map center={pendingQuestion.location} zoom={17} onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} markers={[{ position: pendingQuestion.location, icon: 'target' }]} />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !bg-[#2d4239] !text-lg !tracking-widest">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#0f1a16] flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
