};

export default QuizCreator;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface ScoreboardProps {
  players: Player[];
  isLastRound: boolean;
  onAnimationComplete: () => void;
  isHost?: boolean;
}

const Scoreboard: React.FC<ScoreboardProps> = ({ players, isLastRound, onAnimationComplete, isHost }) => {
  const [step, setStep] = useState<'initial' | 'showingPoints' | 'counting' | 'sorting'>('initial');
  const [visibleCount, setVisibleCount] = useState(0); 
  const [displayScores, setDisplayScores] = useState<Record<string, number>>(
    Object.fromEntries(players.map(p => [p.id, p.score - (p.lastPointsGained || 0)]))
  );

  const sortedInitial = useMemo(() => {
    return [...players].sort((a, b) => {
      const scoreA = a.score - (a.lastPointsGained || 0);
      const scoreB = b.score - (b.lastPointsGained || 0);
      return scoreB - scoreA;
    });
  }, [players]);

  const sortedFinal = useMemo(() => {
    return [...players].sort((a, b) => b.score - a.score);
  }, [players]);

  const currentList = step === 'sorting' ? sortedFinal : sortedInitial;

  useEffect(() => {
    if (isLastRound) {
      const interval = setInterval(() => {
        setVisibleCount(prev => {
          if (prev >= players.length) {
            clearInterval(interval);
            onAnimationComplete();
            return prev;
          }
          return prev + 1;
        });
      }, 1500);
      return () => clearInterval(interval);
    } else {
      const timers = [
        setTimeout(() => setStep('showingPoints'), 1000),
        setTimeout(() => setStep('counting'), 2500),
        setTimeout(() => {
          const newScores = Object.fromEntries(players.map(p => [p.id, p.score]));
          setDisplayScores(newScores);
        }, 3000),
        setTimeout(() => setStep('sorting'), 4500),
        setTimeout(() => onAnimationComplete(), 5500)
      ];
      return () => timers.forEach(clearTimeout);
    }
  }, [isLastRound, players, onAnimationComplete]);

  if (isLastRound) {
    const reversedRanking = [...sortedFinal].reverse();
    return (
      <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden animate-in fade-in zoom-in duration-700">
        <h2 className="text-4xl font-black p-12 pb-6 uppercase tracking-tighter text-[#0f1a16] shrink-0 text-center">
          {strings.game.expeditionComplete}
        </h2>
        <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
          <div className="max-w-lg mx-auto space-y-4">
            {reversedRanking.slice(0, visibleCount).reverse().map((p, idx) => {
              const rank = sortedFinal.findIndex(sp => sp.id === p.id) + 1;
              return (
                <div 
                  key={p.id} 
                  className={`flex items-center justify-between p-6 rounded-[2rem] border transition-all duration-700 animate-in slide-in-from-bottom-8 ${rank === 1 ? 'bg-[#ca8a04]/10 border-[#ca8a04]/30 shadow-xl scale-105 mb-4' : 'bg-[#f9fbfa] border-black/5 shadow-sm'}`}
                >
                  <div className="flex items-center space-x-6">
                    <div className={`text-3xl font-black ${rank === 1 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{rank}</div>
                    <div className="w-14 h-14 rounded-[1.5rem] flex items-center justify-center font-black text-2xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                      {p.name.charAt(0)}
                    </div>
                    <div className="font-black uppercase tracking-tight text-[#0f1a16] text-sm md:text-base">{p.name}</div>
                  </div>
                  <div className="text-xl md:text-2xl font-black text-[#2d4239]">{strings.game.points(p.score)}</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden">
      <h2 className="text-3xl font-black p-10 pb-6 uppercase tracking-tight text-[#0f1a16] shrink-0 text-center">
        {strings.game.roundResults}
      </h2>
      <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
        <div className="max-w-lg mx-auto space-y-4">
          {currentList.map((p, idx) => {
            const isGaining = step === 'showingPoints';
            const points = p.lastPointsGained || 0;

            return (
              <div 
                key={p.id} 
                className="flex items-center justify-between p-5 rounded-[2rem] bg-[#f9fbfa] border border-black/5 shadow-sm transition-all duration-700"
              >
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-[#0f1a16] text-xs md:text-sm">{p.name}</div>
                </div>

                <div className="flex items-center space-x-4">
                  {isGaining && points > 0 && !isHost && (
                    <div className="px-4 py-2 bg-[#10b981] text-white rounded-full font-black text-[10px] uppercase tracking-widest animate-in zoom-in bounce-in duration-500">
                      +{points}
                    </div>
                  )}
                  {isHost && isGaining && points > 0 && (
                    <div className="text-[10px] font-black text-[#10b981] animate-in zoom-in duration-300">+{points}</div>
                  )}
                  <div className="text-xl font-black text-[#2d4239] tabular-nums min-w-[3ch] text-right">
                    {displayScores[p.id]}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onUnlock?: () => void;
  onReveal?: () => void;
  onForceReveal?: () => void;
  onCountdownFinish: () => void;
  onShowScoreboard: () => void;
  onNext: () => void;
  onExit: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ 
  gameState, 
  isHost, 
  currentPlayer, 
  onGuess, 
  onUnlock,
  onReveal,
  onForceReveal,
  onCountdownFinish, 
  onShowScoreboard,
  onNext, 
  onExit 
}) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [isFullscreenImage, setIsFullscreenImage] = useState(false);
  const [imageZoom, setImageZoom] = useState(1);
  const [imageOffset, setImageOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [canProceed, setCanProceed] = useState(false);
  const [showForceRevealConfirm, setShowForceRevealConfirm] = useState(false);

  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isScoreboard = gameState.status === 'SCOREBOARD';
  const isGameFinished = gameState.status === 'FINISHED';
  const isLastRound = gameState.currentQuestionIndex === gameState.questions.length - 1;

  const playerMapConfig = useMemo(() => {
    if (gameState.startingView) return gameState.startingView;

    const lats = gameState.questions.map(q => q.location.lat);
    const lngs = gameState.questions.map(q => q.location.lng);
    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);

    return {
      center: { lat: (minLat + maxLat) / 2, lng: (minLng + maxLng) / 2 },
      zoom: 12
    };
  }, [gameState.startingView, gameState.questions]);

  const matchingPlayer = gameState.players.find(p => p.id === currentPlayer?.id);
  const hasSubmitted = !!matchingPlayer?.hasGuessed;
  const currentTotalScore = matchingPlayer?.score || 0;

  useEffect(() => {
    if (isRoundFinished || isCountingDown || isScoreboard) {
      setIsFullscreenImage(false);
    }
  }, [gameState.status]);

  useEffect(() => {
    setSelectedGuess(null);
    setCountdownValue(3);
    setIsFullscreenImage(false);
    setImageZoom(1);
    setImageOffset({ x: 0, y: 0 });
    setCanProceed(false);
    setShowForceRevealConfirm(false);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (isCountingDown) {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [isCountingDown, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
    }
  };

  const markersForMap = isHost 
    ? [
        { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
        ...gameState.players.filter(p => p.hasGuessed && p.lastGuess).map(p => ({
          position: p.lastGuess!,
          label: p.name,
          color: p.color,
          icon: 'user' as const
        }))
      ]
    : [
        ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
        ...(isRoundFinished ? [
            { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
            ...gameState.players.filter(p => p.lastGuess).map(p => ({ 
              position: p.lastGuess!, 
              label: p.id === currentPlayer?.id ? strings.game.yourGuess : `${p.name}'s guess`, 
              icon: 'user' as const, 
              color: p.color 
            }))
        ] : [])
      ];

  const linesForMap = (isHost || isRoundFinished) 
    ? gameState.players.filter(p => p.lastGuess && (isHost || isRoundFinished)).map(p => ({ 
        from: p.lastGuess!, 
        to: currentQ.location, 
        color: p.color 
      })) 
    : [];

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => Math.min(prev + 0.5, 4));
  };
  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => {
      const next = Math.max(prev - 0.5, 1);
      if (next === 1) setImageOffset({ x: 0, y: 0 });
      return next;
    });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (imageZoom === 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - imageOffset.x, y: e.clientY - imageOffset.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setImageOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };
  const handleMouseUp = () => setIsDragging(false);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(45,66,57,0.15)] w-full max-w-md border border-[#2d4239]/10">
          <div className="space-y-6">
            {[...gameState.players].sort((a,b) => b.score - a.score).map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all border ${idx === 0 ? 'bg-[#ca8a04]/5 border-[#ca8a04]/20 shadow-lg scale-105' : 'bg-[#f9fbfa] border-black/5'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md border-2 border-white/20" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-sm text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#2d4239] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button onClick={onExit} className="w-full mt-12 btn-sleek btn-sleek-pine !bg-[#2d4239] !py-6">
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  if (isHost) {
    const nonGuessedNames = gameState.players.filter(p => !p.hasGuessed).map(p => p.name).join(', ');
    return (
      <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden">
        {showForceRevealConfirm && (
          <div className="fixed inset-0 z-[3000] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6">
            <div className="bg-white p-10 rounded-[3rem] w-full max-w-sm text-center shadow-2xl border border-black/5 animate-in zoom-in duration-300">
              <h3 className="text-xl font-black mb-4 uppercase tracking-tight">Reveal Results?</h3>
              <p className="text-[#0f1a16]/60 text-sm mb-8 font-medium">
                {nonGuessedNames} haven't locked in yet. They will receive 0 points if you proceed.
              </p>
              <div className="flex gap-4">
                <button onClick={() => setShowForceRevealConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:bg-black/5">Wait</button>
                <button onClick={() => { setShowForceRevealConfirm(false); onForceReveal?.(); }} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:opacity-90">Reveal Now</button>
              </div>
            </div>
          </div>
        )}
        <div className="w-full md:w-80 h-1/2 md:h-full bg-white border-r border-[#2d4239]/5 p-8 flex flex-col overflow-y-auto z-20">
          <div className="mb-6">
             <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8c6b4f]">
                   {strings.lobby.host} <span className="opacity-30 ml-2 tracking-widest">#{gameState.id}</span>
                </span>
             </div>
             <h2 className="text-2xl font-black uppercase tracking-tight">{isRoundFinished ? strings.game.roundResults : isScoreboard ? "Standings" : "In Progress"}</h2>
          </div>
          <div className="space-y-4 flex-1">
             <label className="text-[9px] font-black uppercase tracking-widest text-[#0f1a16]/40">{strings.lobby.playersJoined(gameState.players.length)}</label>
             {gameState.players.map(p => (
               <div key={p.id} className="p-4 bg-[#f9fbfa] rounded-2xl border border-black/5 flex items-center justify-between space-x-4">
                 <div className="flex items-center space-x-3 overflow-hidden flex-1">
                    <div className="w-8 h-8 rounded-lg flex items-center justify-center font-black text-white text-xs shrink-0" style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                    <div className="flex items-center space-x-2 truncate">
                       <span className="font-black text-xs uppercase tracking-tight truncate">{p.name}</span>
                       {p.hasGuessed && p.lastDistance !== undefined && !isScoreboard && (
                          <span className="text-[10px] font-black text-[#8c6b4f] whitespace-nowrap">
                             {formatDistance(p.lastDistance)}
                          </span>
                       )}
                    </div>
                 </div>
                 <div className="shrink-0">
                    {p.hasGuessed ? (
                      <div className="w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center text-white">
                         <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                      </div>
                    ) : (
                      <div className="w-5 h-5 border-2 border-dashed border-[#0f1a16]/10 rounded-full"></div>
                    )}
                 </div>
               </div>
             ))}
          </div>
          <div className="pt-8 border-t border-black/5 mt-auto space-y-3 pb-6">
             {(!isRoundFinished && !isCountingDown && !isScoreboard) ? (
               <button 
                onClick={() => {
                  const nonGuessed = gameState.players.filter(p => !p.hasGuessed);
                  if (nonGuessed.length > 0) setShowForceRevealConfirm(true); else onReveal?.();
                }}
                disabled={gameState.players.length === 0}
                className={`w-full py-5 btn-sleek !text-sm ${gameState.players.length > 0 ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none cursor-not-allowed'}`}
               >
                 {strings.game.revealResults}
               </button>
             ) : isRoundFinished ? (
               <button onClick={onShowScoreboard} className="w-full py-5 btn-sleek btn-sleek-pine !text-sm">View Scoreboard</button>
             ) : (
               <button 
                disabled={!canProceed && !isGameFinished}
                onClick={onNext} 
                className={`w-full py-5 btn-sleek !text-sm ${canProceed ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none'}`}
               >
                 {isLastRound ? "Finish Expedition" : "Start Next Location"}
               </button>
             )}
          </div>
          <div className="mt-2 p-3 bg-[#f9fbfa] rounded-[2rem] border border-black/5 shadow-inner shrink-0">
             <button onClick={() => setIsFullscreenImage(true)} className="w-full relative group">
                <img src={currentQ.imageUrl} className="w-full aspect-square object-cover rounded-[1.5rem] border border-black/5 shadow-sm" />
                <div className="absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity rounded-[1.5rem] flex items-center justify-center backdrop-blur-[2px]">
                   <span className="bg-white text-[#0f1a16] px-4 py-2 rounded-full font-black text-[9px] uppercase tracking-widest">{strings.common.expand}</span>
                </div>
             </button>
             <p className="mt-3 text-[10px] font-black uppercase tracking-[0.4em] text-[#8c6b4f] text-center">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</p>
          </div>
        </div>
        <div className="flex-1 relative bg-[#f9fbfa] p-8">
           {isScoreboard ? (
             <Scoreboard players={gameState.players} isLastRound={isLastRound} isHost onAnimationComplete={() => setCanProceed(true)} />
           ) : (
             <Map center={currentQ.location} zoom={14} markers={markersForMap} lines={linesForMap} roundIndex={gameState.currentQuestionIndex} />
           )}
        </div>
        {isFullscreenImage && (
          <div className="fixed inset-0 z-[2000] bg-black/95 flex items-center justify-center p-0 animate-in fade-in zoom-in duration-300 overflow-hidden" 
               onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
             <div className="absolute top-8 right-8 z-[2010] flex space-x-4">
                <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-1 flex items-center border border-white/10">
                   <button onClick={handleZoomOut} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg></button>
                   <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                   <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
                </div>
                <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl hover:scale-110 transition-transform"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
             </div>
             <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
                <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
             </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-[#f9fbfa] overflow-hidden selection:bg-[#8c6b4f]/20">
      {isCountingDown && (
        <div className="fixed inset-0 z-[2500] bg-[#0f1a16]/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white animate-in fade-in duration-500">
           <p className="text-white/40 font-black uppercase tracking-[1em] text-[10px] mb-8">{strings.game.countdownTitle}</p>
           <div className="text-[12rem] font-black animate-bounce tracking-tighter">{countdownValue}</div>
        </div>
      )}
      <div className="bg-white/70 backdrop-blur-xl rounded-b-[2rem] p-5 shadow-sm border-b border-[#2d4239]/5 flex justify-between items-center z-[100] shrink-0">
          <div className="font-black text-[10px] uppercase tracking-[0.4em] text-[#8c6b4f]">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="flex items-center space-x-6">
             <div className="flex -space-x-3">
                {gameState.players.map(p => (
                  <div key={p.id} className={`w-8 h-8 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black text-white shadow-sm transition-all ${p.hasGuessed ? 'scale-110 opacity-100 ring-4 ring-[#10b981]/20' : 'scale-90 opacity-20'}`} style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                ))}
             </div>
             <div className="font-black text-[#2d4239] text-sm uppercase tracking-tight tabular-nums">{strings.game.points(currentTotalScore)}</div>
          </div>
      </div>

      <div className="flex-1 flex flex-col md:flex-row relative">
        <div className={`w-full md:w-1/2 flex flex-col p-6 space-y-6 ${isScoreboard ? 'hidden' : 'flex'}`}>
          {isRoundFinished ? (
            <div className="flex-1 flex flex-col items-center justify-start text-center text-[#0f1a16] bg-white rounded-[3rem] border border-[#2d4239]/5 shadow-sm overflow-hidden animate-in fade-in duration-700">
              <h2 className="text-2xl font-black pt-10 pb-6 uppercase tracking-tight text-[#0f1a16] shrink-0">{strings.game.roundResults}</h2>
              <div className="flex-1 w-full overflow-y-auto px-8 pb-10 scroll-smooth-touch">
                <div className="space-y-4 w-full max-w-sm mx-auto">
                  {gameState.players.map(p => (
                    <div key={p.id} className="flex justify-between items-center bg-[#f9fbfa] p-4 rounded-[1.5rem] border border-black/5">
                      <div className="flex items-center space-x-4">
                        <div className="w-5 h-5 rounded-[0.5rem] shadow-sm" style={{ backgroundColor: p.color }} />
                        <span className="font-black uppercase tracking-tight text-[10px] text-[#0f1a16]">{p.name}</span>
                      </div>
                      <span className="font-bold text-[10px] tracking-widest text-[#8c6b4f]">{p.lastDistance && p.lastDistance < 19000 ? formatDistance(p.lastDistance) : strings.game.noGuess}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ) : (
            <div className="flex-1 relative rounded-[3rem] overflow-hidden bg-[#2d4239]/5 border border-[#2d4239]/10 shadow-2xl group">
              <img src={currentQ.imageUrl} className="w-full h-full object-contain transition-transform duration-[15s] group-hover:scale-105" alt="Spot" />
              <button onClick={() => setIsFullscreenImage(true)} className="absolute top-6 right-6 bg-[#0f1a16] text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all z-10 border border-white/10">{strings.common.expand}</button>
            </div>
          )}
        </div>

        <div className={`flex-1 p-6 md:pl-0 flex flex-col space-y-6 ${isScoreboard ? 'w-full' : 'w-full md:w-1/2'}`}>
          <div className="flex-1 relative bg-white rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(45,66,57,0.1)] border border-[#2d4239]/5 overflow-hidden transition-all">
            {isScoreboard ? (
              <Scoreboard players={gameState.players} isLastRound={isLastRound} onAnimationComplete={() => {}} />
            ) : (
              <Map 
                onLocationSelect={isRoundFinished || hasSubmitted ? undefined : setSelectedGuess}
                markers={markersForMap}
                lines={linesForMap}
                center={playerMapConfig.center}
                zoom={playerMapConfig.zoom}
                roundIndex={gameState.currentQuestionIndex}
              />
            )}

            {!isRoundFinished && !hasSubmitted && !isScoreboard && (
              <div className="absolute bottom-10 inset-x-0 flex justify-center px-6 z-[1600]">
                <button disabled={!selectedGuess} onClick={handleGuessSubmit} style={{ backgroundColor: selectedGuess ? (currentPlayer?.color || '#2d4239') : undefined }} className={`w-full max-w-xs py-6 btn-sleek !text-lg !tracking-[0.2em] shadow-2xl transition-all active:scale-95 ${selectedGuess ? 'text-white' : 'bg-white/80 text-[#0f1a16]/10 shadow-none cursor-not-allowed border border-black/5'}`}>
                  {strings.game.submitGuess}
                </button>
              </div>
            )}

            {!isRoundFinished && hasSubmitted && !isCountingDown && !isScoreboard && (
               <div className="absolute bottom-10 inset-x-0 flex flex-col items-center justify-center px-6 z-[1600] space-y-4">
                 <div className="bg-white/95 backdrop-blur-xl shadow-2xl px-12 py-6 rounded-[2.5rem] border border-[#2d4239]/10 flex items-center space-x-6">
                   <div className="w-6 h-6 bg-[#10b981] rounded-full flex items-center justify-center text-white shadow-lg"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg></div>
                   <span className="font-black text-xs uppercase tracking-[0.3em] text-[#0f1a16]">{strings.game.waitingHost}</span>
                 </div>
                 <button onClick={onUnlock} className="bg-white/60 hover:bg-white text-[9px] font-black uppercase tracking-widest px-8 py-3 rounded-full shadow-lg transition-all border border-black/5">{strings.game.unlockGuess}</button>
               </div>
            )}
          </div>
        </div>
      </div>

      {isFullscreenImage && (
        <div className="fixed inset-0 z-[2000] bg-black/95 flex items-center justify-center p-0 animate-in fade-in zoom-in duration-300 overflow-hidden" onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
           <div className="absolute top-8 right-8 z-[2010] flex space-x-4">
              <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-1 flex items-center border border-white/10">
                 <button onClick={handleZoomOut} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg></button>
                 <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                 <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
              </div>
              <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
           </div>
           <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
              <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
           </div>
        </div>
      )}
      <style>{` .leaflet-control-container { display: ${isCountingDown ? 'none' : 'block'} !important; z-index: 500; } `}</style>
    </div>
  );
};

export default GameBoard;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);
  const [temporaryView, setTemporaryView] = useState<{ center: Location, zoom: number } | null>(null);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isStartingCamera, setIsStartingCamera] = useState(false);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);
  const [showSavedToast, setShowSavedToast] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;

    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      setCurrentLocation(loc);
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = (err: GeolocationPositionError) => {
      if (err.code === err.TIMEOUT && !currentLocation) {
        navigator.geolocation.getCurrentPosition(success, undefined, { ...options, enableHighAccuracy: false });
      }
    };
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    navigator.geolocation.getCurrentPosition(success, handleError, options);
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, [locationStatus]);

  useEffect(() => {
    if (isCapturing && activeStream && videoRef.current) {
      videoRef.current.srcObject = activeStream;
      videoRef.current.play().catch(err => console.error("Video play failed:", err));
    }
  }, [isCapturing, activeStream]);

  const stopCamera = useCallback(() => {
    if (activeStream) {
      activeStream.getTracks().forEach(track => track.stop());
      setActiveStream(null);
    }
    setIsCapturing(false);
    setIsStartingCamera(false);
  }, [activeStream]);

  const startCamera = async () => {
    if (cameraStatus === 'denied') { setError(strings.creator.cameraError); return; }
    setError(null);
    setIsStartingCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1920 } } });
      setActiveStream(stream);
      setIsCapturing(true);
      setIsStartingCamera(false);
    } catch (err) {
      setError(strings.creator.cameraError);
      setIsStartingCamera(false);
      setIsCapturing(false);
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, w, h);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}
        if (source !== 'IMAGE') source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;
    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
    } else {
      setQuestions(prev => [...prev, { id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
    }
    setPendingQuestion(null);
  };

  // Fix: Added moveQuestion function to handle reordering of spots in the trail
  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const newQuestions = [...questions];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newQuestions.length) return;

    const temp = newQuestions[index];
    newQuestions[index] = newQuestions[targetIndex];
    newQuestions[targetIndex] = temp;
    setQuestions(newQuestions);
  };

  // Fix: Added handleDeleteSpot to handle removal of spots from the trail
  const handleDeleteSpot = (id: string) => {
    setQuestions(prev => prev.filter(q => q.id !== id));
    setConfirmDelete(null);
  };

  const handleSaveView = () => {
    if (temporaryView) {
      setStartingView(temporaryView);
      setShowSavedToast(true);
      setTimeout(() => {
        setShowSavedToast(false);
        setIsSettingView(false);
      }, 1000);
    } else {
      setIsSettingView(false);
    }
  };

  if (isSettingView) {
    const viewCenter = startingView?.center || (questions.length > 0 ? questions[0].location : { lat: 51.505, lng: -0.09 });
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">Set Starting View</h2>
          <button onClick={() => setIsSettingView(false)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest">{strings.common.back}</button>
        </header>
        <main className="flex-1 relative">
           <Map center={viewCenter} zoom={startingView?.zoom || 12} onViewChange={setTemporaryView} />
           <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-10 h-10 border-2 border-[#2d4239] rounded-full flex items-center justify-center bg-white/40 backdrop-blur-sm">
                 <div className="w-2 h-2 bg-[#2d4239] rounded-full"></div>
              </div>
           </div>
           {showSavedToast && (
             <div className="absolute top-10 inset-x-0 flex justify-center z-50">
                <div className="bg-[#10b981] text-white px-8 py-4 rounded-full font-black uppercase tracking-widest shadow-2xl animate-in fade-in zoom-in duration-300">
                  View Saved!
                </div>
             </div>
           )}
           <div className="absolute bottom-10 inset-x-0 flex justify-center p-6">
              <button onClick={handleSaveView} className="w-full max-w-sm py-5 btn-sleek btn-sleek-pine !bg-[#2d4239]">Set Current View as Start</button>
           </div>
        </main>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">{pendingQuestion.editingId ? strings.creator.editSpot : strings.creator.tagSpot}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest px-4 py-2">{strings.common.back}</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-24 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-6 flex items-center justify-center bg-[#2d4239]/5">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map center={pendingQuestion.location} zoom={17} onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} markers={[{ position: pendingQuestion.location, icon: 'target' }]} />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !bg-[#2d4239] !text-lg !tracking-widest">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#0f1a16] flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] animate-flash pointer-events-none"></div>}
        <div className="absolute top-8 left-0 right-0 px-8 flex justify-center z-[120]">
           <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
        </div>
        <div className="absolute inset-x-0 bottom-0 p-12 flex justify-between items-center bg-gradient-to-t from-black/80 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-white/30 shadow-2xl active:scale-95 transition-all flex items-center justify-center disabled:opacity-50">{isProcessing ? <div className="w-10 h-10 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-[#f9fbfa]"></div>}</button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      <PermissionBanner onCheck={onRequestPermissions} />
      <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
        <div className="max-w-4xl mx-auto flex justify-between items-start">
          <div className="flex-1 mr-4">
            <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
            <div className="flex items-center space-x-4 mt-2">
               <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em]">{strings.creator.spotsInTrail(questions.length)}</p>
               <div className="w-1 h-1 rounded-full bg-[#0f1a16]/10" />
               <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
            </div>
          </div>
          <button onClick={() => hasChanges ? setShowExitConfirm(true) : onCancel()} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm text-[#0f1a16]">{strings.common.cancel}</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-6 overflow-y-auto pb-40 scroll-smooth-touch">
        {showExitConfirm && (
          <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
            <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
              <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
              <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
              <div className="flex gap-4">
                <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
                <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
              </div>
            </div>
          </div>
        )}
        {/* Fix: Added deletion confirmation dialog for spots */}
        {confirmDelete && (
          <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
            <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
              <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
              <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
              <div className="flex gap-4">
                <button onClick={() => setConfirmDelete(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
                <button onClick={() => handleDeleteSpot(confirmDelete)} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
              </div>
            </div>
          </div>
        )}
        <div className="grid grid-cols-2 gap-6">
          <button disabled={isStartingCamera || cameraStatus === 'denied'} onClick={startCamera} className={`flex flex-col items-center justify-center space-y-4 bg-white border border-[#2d4239]/5 py-10 rounded-[3rem] transition-all group shadow-sm ${cameraStatus === 'denied' ? 'opacity-20 grayscale' : ''}`}>
            <div className="p-4 bg-[#2d4239]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#2d4239]">{strings.creator.takePhoto}</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-4 bg-white border border-[#8c6b4f]/5 py-10 rounded-[3rem] transition-all group shadow-sm"><div className="p-4 bg-[#8c6b4f]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#8c6b4f]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div><span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#8c6b4f]">{strings.creator.uploadImage}</span><input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} /></button>
        </div>

        <button onClick={() => setIsSettingView(true)} className="w-full p-6 bg-white border border-[#2d4239]/10 rounded-[2rem] flex items-center justify-between hover:bg-[#2d4239]/5 transition-all group">
           <div className="flex items-center space-x-4">
              <div className="w-10 h-10 bg-[#2d4239]/5 rounded-xl flex items-center justify-center"><svg className="w-5 h-5 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg></div>
              <div className="text-left">
                 <p className="text-[10px] font-black uppercase tracking-widest text-[#2d4239]">Starting Map View</p>
                 <p className="text-[9px] text-[#2d4239]/40 uppercase font-bold">{startingView ? "Custom View Set" : "Auto-calculated from spots"}</p>
              </div>
           </div>
           <svg className="w-5 h-5 opacity-20 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
        </button>

        <div className="space-y-4 mt-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-white rounded-[2.5rem] border border-black/5 p-4 flex items-center space-x-6 shadow-sm">
              <img src={q.imageUrl} className="w-20 h-20 rounded-[1.5rem] object-cover" />
              <div className="flex-1 min-w-0">
                <input type="text" value={q.title || ''} onChange={(e) => setQuestions(prev => prev.map(item => item.id === q.id ? { ...item, title: e.target.value } : item))} className="bg-transparent border-none p-0 text-lg font-black tracking-tight uppercase focus:ring-0 w-full mb-1" />
                <button onClick={() => setPendingQuestion({ imageUrl: q.imageUrl, location: q.location, originalLocation: q.location, editingId: q.id, title: q.title, source: q.locationSource || 'MANUAL' })} className="text-[9px] text-[#8c6b4f] font-black uppercase tracking-[0.3em]">Edit Pin</button>
              </div>
              <div className="flex items-center space-x-3">
                <div className="flex flex-col opacity-20">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
                <button onClick={() => setConfirmDelete(q.id)} className="p-4 bg-[#7c2d12]/5 text-[#7c2d12] rounded-2xl"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-8 bg-white/70 backdrop-blur-xl border-t border-[#2d4239]/5 z-40">
        <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName, startingView)} className={`w-full max-w-4xl mx-auto block py-6 btn-sleek !text-xl !tracking-[0.2em] ${questions.length > 0 ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 cursor-not-allowed shadow-none'}`}>Finalize Trail</button>
      </footer>
    </div>
  );
};

export default QuizCreator;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);
  const [temporaryView, setTemporaryView] = useState<{ center: Location, zoom: number } | null>(null);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isStartingCamera, setIsStartingCamera] = useState(false);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);
  const [showSavedToast, setShowSavedToast] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;

    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      setCurrentLocation(loc);
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = (err: GeolocationPositionError) => {
      if (err.code === err.TIMEOUT && !currentLocation) {
        navigator.geolocation.getCurrentPosition(success, undefined, { ...options, enableHighAccuracy: false });
      }
    };
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    navigator.geolocation.getCurrentPosition(success, handleError, options);
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, [locationStatus]);

  useEffect(() => {
    if (isCapturing && activeStream && videoRef.current) {
      videoRef.current.srcObject = activeStream;
      videoRef.current.play().catch(err => console.error("Video play failed:", err));
    }
  }, [isCapturing, activeStream]);

  const stopCamera = useCallback(() => {
    if (activeStream) {
      activeStream.getTracks().forEach(track => track.stop());
      setActiveStream(null);
    }
    setIsCapturing(false);
    setIsStartingCamera(false);
  }, [activeStream]);

  const startCamera = async () => {
    if (cameraStatus === 'denied') { setError(strings.creator.cameraError); return; }
    setError(null);
    setIsStartingCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1920 } } });
      setActiveStream(stream);
      setIsCapturing(true);
      setIsStartingCamera(false);
    } catch (err) {
      setError(strings.creator.cameraError);
      setIsStartingCamera(false);
      setIsCapturing(false);
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, w, h);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}
        if (source !== 'IMAGE') source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;
    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
    } else {
      setQuestions(prev => [...prev, { id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
    }
    setPendingQuestion(null);
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const newQuestions = [...questions];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newQuestions.length) return;

    const temp = newQuestions[index];
    newQuestions[index] = newQuestions[targetIndex];
    newQuestions[targetIndex] = temp;
    setQuestions(newQuestions);
  };

  const handleDeleteSpot = (id: string) => {
    setQuestions(prev => prev.filter(q => q.id !== id));
    setConfirmDelete(null);
  };

  const handleSaveView = () => {
    if (temporaryView) {
      setStartingView(temporaryView);
      setShowSavedToast(true);
      setTimeout(() => {
        setShowSavedToast(false);
        setIsSettingView(false);
      }, 1000);
    } else {
      setIsSettingView(false);
    }
  };

  if (isSettingView) {
    const viewCenter = startingView?.center || (questions.length > 0 ? questions[0].location : { lat: 51.505, lng: -0.09 });
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">Set Starting View</h2>
          <button onClick={() => setIsSettingView(false)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest">{strings.common.back}</button>
        </header>
        <main className="flex-1 relative">
           <Map center={viewCenter} zoom={startingView?.zoom || 12} onViewChange={setTemporaryView} />
           <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
              <div className="w-10 h-10 border-2 border-[#2d4239] rounded-full flex items-center justify-center bg-white/40 backdrop-blur-sm">
                 <div className="w-2 h-2 bg-[#2d4239] rounded-full"></div>
              </div>
           </div>
           {showSavedToast && (
             <div className="absolute top-10 inset-x-0 flex justify-center z-[2000]">
                <div className="bg-[#10b981] text-white px-8 py-4 rounded-full font-black uppercase tracking-widest shadow-2xl animate-in fade-in zoom-in duration-300">
                  View Saved!
                </div>
             </div>
           )}
           <div className="absolute bottom-10 inset-x-0 flex justify-center p-6 z-[2000]">
              <button onClick={handleSaveView} className="w-full max-w-xs py-4 btn-sleek btn-sleek-pine !bg-[#2d4239] shadow-2xl">Set Current View as Start</button>
           </div>
        </main>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">{pendingQuestion.editingId ? strings.creator.editSpot : strings.creator.tagSpot}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest px-4 py-2">{strings.common.back}</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-24 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-6 flex items-center justify-center bg-[#2d4239]/5">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map center={pendingQuestion.location} zoom={17} onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} markers={[{ position: pendingQuestion.location, icon: 'target' }]} />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !bg-[#2d4239] !text-lg !tracking-widest">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#0f1a16] flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] animate-flash pointer-events-none"></div>}
        <div className="absolute top-8 left-0 right-0 px-8 flex justify-center z-[120]">
           <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
        </div>
        <div className="absolute inset-x-0 bottom-0 p-12 flex justify-between items-center bg-gradient-to-t from-black/80 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-white/30 shadow-2xl active:scale-95 transition-all flex items-center justify-center disabled:opacity-50">{isProcessing ? <div className="w-10 h-10 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-[#f9fbfa]"></div>}</button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      <PermissionBanner onCheck={onRequestPermissions} />
      <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
        <div className="max-w-4xl mx-auto flex justify-between items-start">
          <div className="flex-1 mr-4">
            <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
            <div className="flex items-center space-x-4 mt-2">
               <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em]">{strings.creator.spotsInTrail(questions.length)}</p>
               <div className="w-1 h-1 rounded-full bg-[#0f1a16]/10" />
               <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
            </div>
          </div>
          <button onClick={() => hasChanges ? setShowExitConfirm(true) : onCancel()} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm text-[#0f1a16]">{strings.common.cancel}</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-6 overflow-y-auto pb-40 scroll-smooth-touch">
        {showExitConfirm && (
          <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
            <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
              <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
              <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
              <div className="flex gap-4">
                <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
                <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
              </div>
            </div>
          </div>
        )}
        {confirmDelete && (
          <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
            <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
              <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
              <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
              <div className="flex gap-4">
                <button onClick={() => setConfirmDelete(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
                <button onClick={() => handleDeleteSpot(confirmDelete)} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
              </div>
            </div>
          </div>
        )}
        <div className="grid grid-cols-2 gap-6">
          <button disabled={isStartingCamera || cameraStatus === 'denied'} onClick={startCamera} className={`flex flex-col items-center justify-center space-y-4 bg-white border border-[#2d4239]/5 py-10 rounded-[3rem] transition-all group shadow-sm ${cameraStatus === 'denied' ? 'opacity-20 grayscale' : ''}`}>
            <div className="p-4 bg-[#2d4239]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
            <span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#2d4239]">{strings.creator.takePhoto}</span>
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-4 bg-white border border-[#8c6b4f]/5 py-10 rounded-[3rem] transition-all group shadow-sm"><div className="p-4 bg-[#8c6b4f]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#8c6b4f]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div><span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#8c6b4f]">{strings.creator.uploadImage}</span><input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} /></button>
        </div>

        <button onClick={() => setIsSettingView(true)} className="w-full p-6 bg-white border border-[#2d4239]/10 rounded-[2rem] flex items-center justify-between hover:bg-[#2d4239]/5 transition-all group">
           <div className="flex items-center space-x-4">
              <div className="w-10 h-10 bg-[#2d4239]/5 rounded-xl flex items-center justify-center"><svg className="w-5 h-5 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg></div>
              <div className="text-left">
                 <p className="text-[10px] font-black uppercase tracking-widest text-[#2d4239]">Starting Map View</p>
                 <p className="text-[9px] text-[#2d4239]/40 uppercase font-bold">{startingView ? "Custom View Set" : "Auto-calculated from spots"}</p>
              </div>
           </div>
           <svg className="w-5 h-5 opacity-20 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
        </button>

        <div className="space-y-4 mt-8">
          {questions.map((q, idx) => (
            <div key={q.id} className="bg-white rounded-[2.5rem] border border-black/5 p-4 flex items-center space-x-6 shadow-sm">
              <img src={q.imageUrl} className="w-20 h-20 rounded-[1.5rem] object-cover" />
              <div className="flex-1 min-w-0">
                <input type="text" value={q.title || ''} onChange={(e) => setQuestions(prev => prev.map(item => item.id === q.id ? { ...item, title: e.target.value } : item))} className="bg-transparent border-none p-0 text-lg font-black tracking-tight uppercase focus:ring-0 w-full mb-1" />
                <button onClick={() => setPendingQuestion({ imageUrl: q.imageUrl, location: q.location, originalLocation: q.location, editingId: q.id, title: q.title, source: q.locationSource || 'MANUAL' })} className="text-[9px] text-[#8c6b4f] font-black uppercase tracking-[0.3em]">Edit Pin</button>
              </div>
              <div className="flex items-center space-x-3">
                <div className="flex flex-col opacity-20">
                  <button onClick={() => moveQuestion(idx, 'up')} disabled={idx === 0} className="p-1"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z" /></svg></button>
                  <button onClick={() => moveQuestion(idx, 'down')} disabled={idx === questions.length - 1} className="p-1"><svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" /></svg></button>
                </div>
                <button onClick={() => setConfirmDelete(q.id)} className="p-4 bg-[#7c2d12]/5 text-[#7c2d12] rounded-2xl"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>
              </div>
            </div>
          ))}
        </div>
      </main>

      <footer className="fixed bottom-0 left-0 right-0 p-8 bg-white/70 backdrop-blur-xl border-t border-[#2d4239]/5 z-40">
        <button disabled={questions.length === 0} onClick={() => onComplete(questions, trailName, startingView)} className={`w-full max-w-4xl mx-auto block py-6 btn-sleek !text-xl !tracking-[0.2em] ${questions.length > 0 ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 cursor-not-allowed shadow-none'}`}>Finalize Trail</button>
      </footer>
    </div>
  );
};

export default QuizCreator;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface ScoreboardProps {
  players: Player[];
  isLastRound: boolean;
  onAnimationComplete: () => void;
  isHost?: boolean;
}

const Scoreboard: React.FC<ScoreboardProps> = ({ players, isLastRound, onAnimationComplete, isHost }) => {
  const [step, setStep] = useState<'initial' | 'showingPoints' | 'counting' | 'sorting'>('initial');
  const [visibleCount, setVisibleCount] = useState(0); 
  const [displayScores, setDisplayScores] = useState<Record<string, number>>(
    Object.fromEntries(players.map(p => [p.id, p.score - (p.lastPointsGained || 0)]))
  );

  const sortedInitial = useMemo(() => {
    return [...players].sort((a, b) => {
      const scoreA = a.score - (a.lastPointsGained || 0);
      const scoreB = b.score - (b.lastPointsGained || 0);
      return scoreB - scoreA;
    });
  }, [players]);

  const sortedFinal = useMemo(() => {
    return [...players].sort((a, b) => b.score - a.score);
  }, [players]);

  const currentList = step === 'sorting' ? sortedFinal : sortedInitial;

  useEffect(() => {
    if (isLastRound) {
      const interval = setInterval(() => {
        setVisibleCount(prev => {
          if (prev >= players.length) {
            clearInterval(interval);
            onAnimationComplete();
            return prev;
          }
          return prev + 1;
        });
      }, 1500);
      return () => clearInterval(interval);
    } else {
      const timers = [
        setTimeout(() => setStep('showingPoints'), 1000),
        setTimeout(() => setStep('counting'), 2500),
        setTimeout(() => {
          const newScores = Object.fromEntries(players.map(p => [p.id, p.score]));
          setDisplayScores(newScores);
        }, 3000),
        setTimeout(() => setStep('sorting'), 4500),
        setTimeout(() => onAnimationComplete(), 5500)
      ];
      return () => timers.forEach(clearTimeout);
    }
  }, [isLastRound, players, onAnimationComplete]);

  if (isLastRound) {
    const reversedRanking = [...sortedFinal].reverse();
    return (
      <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden animate-in fade-in zoom-in duration-700">
        <h2 className="text-4xl font-black p-12 pb-6 uppercase tracking-tighter text-[#0f1a16] shrink-0 text-center">
          {strings.game.expeditionComplete}
        </h2>
        <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
          <div className="max-w-lg mx-auto space-y-4">
            {reversedRanking.slice(0, visibleCount).reverse().map((p, idx) => {
              const rank = sortedFinal.findIndex(sp => sp.id === p.id) + 1;
              return (
                <div 
                  key={p.id} 
                  className={`flex items-center justify-between p-6 rounded-[2rem] border transition-all duration-700 animate-in slide-in-from-bottom-8 ${rank === 1 ? 'bg-[#ca8a04]/10 border-[#ca8a04]/30 shadow-xl scale-105 mb-4' : 'bg-[#f9fbfa] border-black/5 shadow-sm'}`}
                >
                  <div className="flex items-center space-x-6">
                    <div className={`text-3xl font-black ${rank === 1 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{rank}</div>
                    <div className="w-14 h-14 rounded-[1.5rem] flex items-center justify-center font-black text-2xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                      {p.name.charAt(0)}
                    </div>
                    <div className="font-black uppercase tracking-tight text-[#0f1a16] text-sm md:text-base">{p.name}</div>
                  </div>
                  <div className="text-xl md:text-2xl font-black text-[#2d4239]">{strings.game.points(p.score)}</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden">
      <h2 className="text-3xl font-black p-10 pb-6 uppercase tracking-tight text-[#0f1a16] shrink-0 text-center">
        {strings.game.roundResults}
      </h2>
      <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
        <div className="max-w-lg mx-auto space-y-4">
          {currentList.map((p, idx) => {
            const isGaining = step === 'showingPoints';
            const points = p.lastPointsGained || 0;

            return (
              <div 
                key={p.id} 
                className="flex items-center justify-between p-5 rounded-[2rem] bg-[#f9fbfa] border border-black/5 shadow-sm transition-all duration-700"
              >
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-[#0f1a16] text-xs md:text-sm">{p.name}</div>
                </div>

                <div className="flex items-center space-x-4">
                  {isGaining && points > 0 && !isHost && (
                    <div className="px-4 py-2 bg-[#10b981] text-white rounded-full font-black text-[10px] uppercase tracking-widest animate-in zoom-in bounce-in duration-500">
                      +{points}
                    </div>
                  )}
                  {isHost && isGaining && points > 0 && (
                    <div className="text-[10px] font-black text-[#10b981] animate-in zoom-in duration-300">+{points}</div>
                  )}
                  <div className="text-xl font-black text-[#2d4239] tabular-nums min-w-[3ch] text-right">
                    {displayScores[p.id]}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onUnlock?: () => void;
  onReveal?: () => void;
  onForceReveal?: () => void;
  onCountdownFinish: () => void;
  onShowScoreboard: () => void;
  onNext: () => void;
  onExit: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ 
  gameState, 
  isHost, 
  currentPlayer, 
  onGuess, 
  onUnlock,
  onReveal,
  onForceReveal,
  onCountdownFinish, 
  onShowScoreboard,
  onNext, 
  onExit 
}) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [isFullscreenImage, setIsFullscreenImage] = useState(false);
  const [imageZoom, setImageZoom] = useState(1);
  const [imageOffset, setImageOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: e.clientX, y: e.clientY });
  const [canProceed, setCanProceed] = useState(false);
  const [showForceRevealConfirm, setShowForceRevealConfirm] = useState(false);

  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isScoreboard = gameState.status === 'SCOREBOARD';
  const isGameFinished = gameState.status === 'FINISHED';
  const isLastRound = gameState.currentQuestionIndex === gameState.questions.length - 1;

  const playerMapConfig = useMemo(() => {
    if (gameState.startingView) return gameState.startingView;

    const lats = gameState.questions.map(q => q.location.lat);
    const lngs = gameState.questions.map(q => q.location.lng);
    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);

    return {
      center: { lat: (minLat + maxLat) / 2, lng: (minLng + maxLng) / 2 },
      zoom: 12
    };
  }, [gameState.startingView, gameState.questions]);

  const matchingPlayer = gameState.players.find(p => p.id === currentPlayer?.id);
  const hasSubmitted = !!matchingPlayer?.hasGuessed;
  const currentTotalScore = matchingPlayer?.score || 0;

  useEffect(() => {
    if (isRoundFinished || isCountingDown || isScoreboard) {
      setIsFullscreenImage(false);
    }
  }, [gameState.status]);

  useEffect(() => {
    setSelectedGuess(null);
    setCountdownValue(3);
    setIsFullscreenImage(false);
    setImageZoom(1);
    setImageOffset({ x: 0, y: 0 });
    setCanProceed(false);
    setShowForceRevealConfirm(false);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (isCountingDown) {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [isCountingDown, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
    }
  };

  const markersForMap = isHost 
    ? [
        { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
        ...gameState.players.filter(p => p.hasGuessed && p.lastGuess).map(p => ({
          position: p.lastGuess!,
          label: p.name,
          color: p.color,
          icon: 'user' as const
        }))
      ]
    : [
        ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
        ...(isRoundFinished ? [
            { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
            ...gameState.players.filter(p => p.lastGuess).map(p => ({ 
              position: p.lastGuess!, 
              label: p.id === currentPlayer?.id ? strings.game.yourGuess : `${p.name}'s guess`, 
              icon: 'user' as const, 
              color: p.color 
            }))
        ] : [])
      ];

  const linesForMap = (isHost || isRoundFinished) 
    ? gameState.players.filter(p => p.lastGuess && (isHost || isRoundFinished)).map(p => ({ 
        from: p.lastGuess!, 
        to: currentQ.location, 
        color: p.color 
      })) 
    : [];

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => Math.min(prev + 0.5, 4));
  };
  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => {
      const next = Math.max(prev - 0.5, 1);
      if (next === 1) setImageOffset({ x: 0, y: 0 });
      return next;
    });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (imageZoom === 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - imageOffset.x, y: e.clientY - imageOffset.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setImageOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };
  const handleMouseUp = () => setIsDragging(false);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(45,66,57,0.15)] w-full max-w-md border border-[#2d4239]/10">
          <div className="space-y-6">
            {[...gameState.players].sort((a,b) => b.score - a.score).map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all border ${idx === 0 ? 'bg-[#ca8a04]/5 border-[#ca8a04]/20 shadow-lg scale-105' : 'bg-[#f9fbfa] border-black/5'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md border-2 border-white/20" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-sm text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#2d4239] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button onClick={onExit} className="w-full mt-12 btn-sleek btn-sleek-pine !bg-[#2d4239] !py-6">
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  if (isHost) {
    const nonGuessedNames = gameState.players.filter(p => !p.hasGuessed).map(p => p.name).join(', ');
    return (
      <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden">
        {showForceRevealConfirm && (
          <div className="fixed inset-0 z-[3000] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6">
            <div className="bg-white p-10 rounded-[3rem] w-full max-w-sm text-center shadow-2xl border border-black/5 animate-in zoom-in duration-300">
              <h3 className="text-xl font-black mb-4 uppercase tracking-tight">Reveal Results?</h3>
              <p className="text-[#0f1a16]/60 text-sm mb-8 font-medium">
                {nonGuessedNames} haven't locked in yet. They will receive 0 points if you proceed.
              </p>
              <div className="flex gap-4">
                <button onClick={() => setShowForceRevealConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:bg-black/5">Wait</button>
                <button onClick={() => { setShowForceRevealConfirm(false); onForceReveal?.(); }} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:opacity-90">Reveal Now</button>
              </div>
            </div>
          </div>
        )}
        <div className="w-full md:w-80 h-1/2 md:h-full bg-white border-r border-[#2d4239]/5 p-8 flex flex-col overflow-y-auto z-20">
          <div className="mb-6">
             <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8c6b4f]">
                   {strings.lobby.host} <span className="opacity-30 ml-2 tracking-widest">#{gameState.id}</span>
                </span>
             </div>
             <h2 className="text-2xl font-black uppercase tracking-tight">{isRoundFinished ? strings.game.roundResults : isScoreboard ? "Standings" : "In Progress"}</h2>
          </div>
          <div className="space-y-4 flex-1">
             <label className="text-[9px] font-black uppercase tracking-widest text-[#0f1a16]/40">{strings.lobby.playersJoined(gameState.players.length)}</label>
             {gameState.players.map(p => (
               <div key={p.id} className="p-4 bg-[#f9fbfa] rounded-2xl border border-black/5 flex items-center justify-between space-x-4">
                 <div className="flex items-center space-x-3 overflow-hidden flex-1">
                    <div className="w-8 h-8 rounded-lg flex items-center justify-center font-black text-white text-xs shrink-0" style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                    <div className="flex items-center space-x-2 truncate">
                       <span className="font-black text-xs uppercase tracking-tight truncate">{p.name}</span>
                       {p.hasGuessed && p.lastDistance !== undefined && !isScoreboard && (
                          <span className="text-[10px] font-black text-[#8c6b4f] whitespace-nowrap">
                             {formatDistance(p.lastDistance)}
                          </span>
                       )}
                    </div>
                 </div>
                 <div className="shrink-0">
                    {p.hasGuessed ? (
                      <div className="w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center text-white">
                         <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                      </div>
                    ) : (
                      <div className="w-5 h-5 border-2 border-dashed border-[#0f1a16]/10 rounded-full"></div>
                    )}
                 </div>
               </div>
             ))}
          </div>
          <div className="pt-8 border-t border-black/5 mt-auto space-y-3 pb-6">
             {(!isRoundFinished && !isCountingDown && !isScoreboard) ? (
               <button 
                onClick={() => {
                  const nonGuessed = gameState.players.filter(p => !p.hasGuessed);
                  if (nonGuessed.length > 0) setShowForceRevealConfirm(true); else onReveal?.();
                }}
                disabled={gameState.players.length === 0}
                className={`w-full py-5 btn-sleek !text-sm ${gameState.players.length > 0 ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none cursor-not-allowed'}`}
               >
                 {strings.game.revealResults}
               </button>
             ) : isRoundFinished ? (
               <button onClick={onShowScoreboard} className="w-full py-5 btn-sleek btn-sleek-pine !text-sm">View Scoreboard</button>
             ) : (
               <button 
                disabled={!canProceed && !isGameFinished}
                onClick={onNext} 
                className={`w-full py-5 btn-sleek !text-sm ${canProceed ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none'}`}
               >
                 {isLastRound ? "Finish Expedition" : "Start Next Location"}
               </button>
             )}
          </div>
          <div className="mt-2 p-3 bg-[#f9fbfa] rounded-[2rem] border border-black/5 shadow-inner shrink-0">
             <button onClick={() => setIsFullscreenImage(true)} className="w-full relative group">
                <img src={currentQ.imageUrl} className="w-full aspect-square object-cover rounded-[1.5rem] border border-black/5 shadow-sm" />
                <div className="absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity rounded-[1.5rem] flex items-center justify-center backdrop-blur-[2px]">
                   <span className="bg-white text-[#0f1a16] px-4 py-2 rounded-full font-black text-[9px] uppercase tracking-widest">{strings.common.expand}</span>
                </div>
             </button>
             <p className="mt-3 text-[10px] font-black uppercase tracking-[0.4em] text-[#8c6b4f] text-center">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</p>
          </div>
        </div>
        <div className="flex-1 relative bg-[#f9fbfa] p-8">
           {isScoreboard ? (
             <Scoreboard players={gameState.players} isLastRound={isLastRound} isHost onAnimationComplete={() => setCanProceed(true)} />
           ) : (
             <Map center={currentQ.location} zoom={14} markers={markersForMap} lines={linesForMap} roundIndex={gameState.currentQuestionIndex} />
           )}
        </div>
        {isFullscreenImage && (
          <div className="fixed inset-0 z-[2000] bg-black/95 flex items-center justify-center p-0 animate-in fade-in zoom-in duration-300 overflow-hidden" 
               onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
             <div className="absolute top-8 right-8 z-[2010] flex space-x-4">
                <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-1 flex items-center border border-white/10">
                   <button onClick={handleZoomOut} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg></button>
                   <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                   <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
                </div>
                <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl hover:scale-110 transition-transform"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
             </div>
             <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
                <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
             </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-[#f9fbfa] overflow-hidden selection:bg-[#8c6b4f]/20">
      {isCountingDown && (
        <div className="fixed inset-0 z-[2500] bg-[#0f1a16]/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white animate-in fade-in duration-500">
           <p className="text-white/40 font-black uppercase tracking-[1em] text-[10px] mb-8">{strings.game.countdownTitle}</p>
           <div className="text-[12rem] font-black animate-bounce tracking-tighter">{countdownValue}</div>
        </div>
      )}

      {/* Permanent Location Counter Header */}
      <div className="bg-white/70 backdrop-blur-xl rounded-b-[2rem] p-5 shadow-sm border-b border-[#2d4239]/5 flex justify-between items-center z-[100] shrink-0">
          <div className="font-black text-[10px] uppercase tracking-[0.4em] text-[#8c6b4f]">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="flex items-center space-x-6">
             <div className="flex -space-x-3">
                {gameState.players.map(p => (
                  <div key={p.id} className={`w-8 h-8 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black text-white shadow-sm transition-all ${p.hasGuessed ? 'scale-110 opacity-100 ring-4 ring-[#10b981]/20' : 'scale-90 opacity-20'}`} style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                ))}
             </div>
             <div className="font-black text-[#2d4239] text-sm uppercase tracking-tight tabular-nums">{strings.game.points(currentTotalScore)}</div>
          </div>
      </div>

      <div className="flex-1 flex flex-col relative">
        {isScoreboard ? (
          /* Full Screen Scoreboard */
          <div className="absolute inset-0 z-[200] p-6 bg-[#f9fbfa] animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <Scoreboard players={gameState.players} isLastRound={isLastRound} onAnimationComplete={() => {}} />
          </div>
        ) : (
          /* Main Game / Results Layout */
          <>
            <div className="w-full h-1/2 flex flex-col p-6 pb-3 space-y-4">
              {isRoundFinished ? (
                /* Top half scrollable distances (Results) */
                <div className="flex-1 flex flex-col items-center justify-start text-center text-[#0f1a16] overflow-hidden animate-in fade-in duration-700">
                  <h2 className="text-xl font-black py-4 uppercase tracking-tight text-[#0f1a16] shrink-0">{strings.game.roundResults}</h2>
                  <div className="flex-1 w-full overflow-y-auto px-2 pb-6 scroll-smooth-touch">
                    <div className="space-y-3 w-full max-w-sm mx-auto">
                      {gameState.players.map(p => (
                        <div key={p.id} className="flex justify-between items-center bg-white p-4 rounded-[1.5rem] border border-[#2d4239]/5 shadow-sm">
                          <div className="flex items-center space-x-4">
                            <div className="w-4 h-4 rounded-[0.4rem] shadow-sm" style={{ backgroundColor: p.color }} />
                            <span className="font-black uppercase tracking-tight text-[10px] text-[#0f1a16]">{p.name}</span>
                          </div>
                          <span className="font-bold text-[10px] tracking-widest text-[#8c6b4f]">{p.lastDistance && p.lastDistance < 19000 ? formatDistance(p.lastDistance) : strings.game.noGuess}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              ) : (
                /* Top half glossy image box (Playing) */
                <div className="flex-1 relative rounded-[3rem] overflow-hidden bg-white/40 backdrop-blur-xl border border-white shadow-2xl group">
                  <img src={currentQ.imageUrl} className="w-full h-full object-contain transition-transform duration-[15s] group-hover:scale-105" alt="Spot" />
                  <button onClick={() => setIsFullscreenImage(true)} className="absolute top-4 right-4 bg-[#0f1a16] text-white px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all z-10 border border-white/10">{strings.common.expand}</button>
                </div>
              )}
            </div>

            <div className="w-full h-1/2 p-6 pt-3 flex flex-col space-y-4">
              <div className="flex-1 relative bg-white rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(45,66,57,0.1)] border border-[#2d4239]/5 overflow-hidden transition-all">
                <Map 
                  onLocationSelect={isRoundFinished || hasSubmitted ? undefined : setSelectedGuess}
                  markers={markersForMap}
                  lines={linesForMap}
                  center={playerMapConfig.center}
                  zoom={playerMapConfig.zoom}
                  roundIndex={gameState.currentQuestionIndex}
                />

                {!isRoundFinished && !hasSubmitted && (
                  <div className="absolute bottom-8 inset-x-0 flex justify-center px-6 z-[1600]">
                    <button 
                      disabled={!selectedGuess} 
                      onClick={handleGuessSubmit} 
                      style={{ backgroundColor: selectedGuess ? (currentPlayer?.color || '#2d4239') : undefined }} 
                      className={`w-full max-w-[180px] py-3.5 btn-sleek !text-[11px] !tracking-[0.15em] shadow-2xl transition-all active:scale-95 ${selectedGuess ? 'text-white' : 'bg-white/80 text-[#0f1a16]/10 shadow-none cursor-not-allowed border border-black/5'}`}
                    >
                      {strings.game.submitGuess}
                    </button>
                  </div>
                )}

                {!isRoundFinished && hasSubmitted && !isCountingDown && (
                   <div className="absolute bottom-8 inset-x-0 flex flex-col items-center justify-center px-6 z-[1600] space-y-3">
                     <div className="bg-white/95 backdrop-blur-xl shadow-2xl px-8 py-4 rounded-[2rem] border border-[#2d4239]/10 flex items-center space-x-4">
                       <div className="w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center text-white shadow-lg"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg></div>
                       <span className="font-black text-[10px] uppercase tracking-[0.2em] text-[#0f1a16]">{strings.game.waitingHost}</span>
                     </div>
                     <button onClick={onUnlock} className="bg-white/60 hover:bg-white text-[8px] font-black uppercase tracking-widest px-6 py-2 rounded-full shadow-lg transition-all border border-black/5">{strings.game.unlockGuess}</button>
                   </div>
                )}
              </div>
            </div>
          </>
        )}
      </div>

      {isFullscreenImage && (
        <div className="fixed inset-0 z-[2000] bg-black/95 flex items-center justify-center p-0 animate-in fade-in zoom-in duration-300 overflow-hidden" onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
           <div className="absolute top-8 right-8 z-[2010] flex space-x-4">
              <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-1 flex items-center border border-white/10">
                 <button onClick={handleZoomOut} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg></button>
                 <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                 <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
              </div>
              <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
           </div>
           <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
              <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
           </div>
        </div>
      )}
      <style>{` .leaflet-control-container { display: ${isCountingDown ? 'none' : 'block'} !important; z-index: 500; } `}</style>
    </div>
  );
};

export default GameBoard;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface ScoreboardProps {
  players: Player[];
  isLastRound: boolean;
  onAnimationComplete: () => void;
  isHost?: boolean;
}

const Scoreboard: React.FC<ScoreboardProps> = ({ players, isLastRound, onAnimationComplete, isHost }) => {
  const [step, setStep] = useState<'initial' | 'showingPoints' | 'counting' | 'sorting'>('initial');
  const [visibleCount, setVisibleCount] = useState(0); 
  const [displayScores, setDisplayScores] = useState<Record<string, number>>(
    Object.fromEntries(players.map(p => [p.id, p.score - (p.lastPointsGained || 0)]))
  );

  const sortedInitial = useMemo(() => {
    return [...players].sort((a, b) => {
      const scoreA = a.score - (a.lastPointsGained || 0);
      const scoreB = b.score - (b.lastPointsGained || 0);
      return scoreB - scoreA;
    });
  }, [players]);

  const sortedFinal = useMemo(() => {
    return [...players].sort((a, b) => b.score - a.score);
  }, [players]);

  const currentList = step === 'sorting' ? sortedFinal : sortedInitial;

  useEffect(() => {
    if (isLastRound) {
      const interval = setInterval(() => {
        setVisibleCount(prev => {
          if (prev >= players.length) {
            clearInterval(interval);
            onAnimationComplete();
            return prev;
          }
          return prev + 1;
        });
      }, 1500);
      return () => clearInterval(interval);
    } else {
      const timers = [
        setTimeout(() => setStep('showingPoints'), 1000),
        setTimeout(() => setStep('counting'), 2500),
        setTimeout(() => {
          const newScores = Object.fromEntries(players.map(p => [p.id, p.score]));
          setDisplayScores(newScores);
        }, 3000),
        setTimeout(() => setStep('sorting'), 4500),
        setTimeout(() => onAnimationComplete(), 5500)
      ];
      return () => timers.forEach(clearTimeout);
    }
  }, [isLastRound, players, onAnimationComplete]);

  if (isLastRound) {
    const reversedRanking = [...sortedFinal].reverse();
    return (
      <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden animate-in fade-in zoom-in duration-700">
        <h2 className="text-4xl font-black p-12 pb-6 uppercase tracking-tighter text-[#0f1a16] shrink-0 text-center">
          {strings.game.expeditionComplete}
        </h2>
        <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
          <div className="max-w-lg mx-auto space-y-4">
            {reversedRanking.slice(0, visibleCount).reverse().map((p, idx) => {
              const rank = sortedFinal.findIndex(sp => sp.id === p.id) + 1;
              return (
                <div 
                  key={p.id} 
                  className={`flex items-center justify-between p-6 rounded-[2rem] border transition-all duration-700 animate-in slide-in-from-bottom-8 ${rank === 1 ? 'bg-[#ca8a04]/10 border-[#ca8a04]/30 shadow-xl scale-105 mb-4' : 'bg-[#f9fbfa] border-black/5 shadow-sm'}`}
                >
                  <div className="flex items-center space-x-6">
                    <div className={`text-3xl font-black ${rank === 1 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{rank}</div>
                    <div className="w-14 h-14 rounded-[1.5rem] flex items-center justify-center font-black text-2xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                      {p.name.charAt(0)}
                    </div>
                    <div className="font-black uppercase tracking-tight text-[#0f1a16] text-sm md:text-base">{p.name}</div>
                  </div>
                  <div className="text-xl md:text-2xl font-black text-[#2d4239]">{strings.game.points(p.score)}</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden">
      <h2 className="text-3xl font-black p-10 pb-6 uppercase tracking-tight text-[#0f1a16] shrink-0 text-center">
        {strings.game.roundResults}
      </h2>
      <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
        <div className="max-w-lg mx-auto space-y-4">
          {currentList.map((p, idx) => {
            const isGaining = step === 'showingPoints';
            const points = p.lastPointsGained || 0;

            return (
              <div 
                key={p.id} 
                className="flex items-center justify-between p-5 rounded-[2rem] bg-[#f9fbfa] border border-black/5 shadow-sm transition-all duration-700"
              >
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-[#0f1a16] text-xs md:text-sm">{p.name}</div>
                </div>

                <div className="flex items-center space-x-4">
                  {isGaining && points > 0 && !isHost && (
                    <div className="px-4 py-2 bg-[#10b981] text-white rounded-full font-black text-[10px] uppercase tracking-widest animate-in zoom-in bounce-in duration-500">
                      +{points}
                    </div>
                  )}
                  {isHost && isGaining && points > 0 && (
                    <div className="text-[10px] font-black text-[#10b981] animate-in zoom-in duration-300">+{points}</div>
                  )}
                  <div className="text-xl font-black text-[#2d4239] tabular-nums min-w-[3ch] text-right">
                    {displayScores[p.id]}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onUnlock?: () => void;
  onReveal?: () => void;
  onForceReveal?: () => void;
  onCountdownFinish: () => void;
  onShowScoreboard: () => void;
  onNext: () => void;
  onExit: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ 
  gameState, 
  isHost, 
  currentPlayer, 
  onGuess, 
  onUnlock,
  onReveal,
  onForceReveal,
  onCountdownFinish, 
  onShowScoreboard,
  onNext, 
  onExit 
}) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [isFullscreenImage, setIsFullscreenImage] = useState(false);
  const [imageZoom, setImageZoom] = useState(1);
  const [imageOffset, setImageOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  // Fix undefined 'e' variable in dragStart state initialization.
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [canProceed, setCanProceed] = useState(false);
  const [showForceRevealConfirm, setShowForceRevealConfirm] = useState(false);

  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isScoreboard = gameState.status === 'SCOREBOARD';
  const isGameFinished = gameState.status === 'FINISHED';
  const isLastRound = gameState.currentQuestionIndex === gameState.questions.length - 1;

  const playerMapConfig = useMemo(() => {
    if (gameState.startingView) return gameState.startingView;

    const lats = gameState.questions.map(q => q.location.lat);
    const lngs = gameState.questions.map(q => q.location.lng);
    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);

    return {
      center: { lat: (minLat + maxLat) / 2, lng: (minLng + maxLng) / 2 },
      zoom: 12
    };
  }, [gameState.startingView, gameState.questions]);

  const matchingPlayer = gameState.players.find(p => p.id === currentPlayer?.id);
  const hasSubmitted = !!matchingPlayer?.hasGuessed;
  const currentTotalScore = matchingPlayer?.score || 0;

  useEffect(() => {
    if (isRoundFinished || isCountingDown || isScoreboard) {
      setIsFullscreenImage(false);
    }
  }, [gameState.status]);

  useEffect(() => {
    setSelectedGuess(null);
    setCountdownValue(3);
    setIsFullscreenImage(false);
    setImageZoom(1);
    setImageOffset({ x: 0, y: 0 });
    setCanProceed(false);
    setShowForceRevealConfirm(false);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (isCountingDown) {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [isCountingDown, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
    }
  };

  const markersForMap = isHost 
    ? [
        { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
        ...gameState.players.filter(p => p.hasGuessed && p.lastGuess).map(p => ({
          position: p.lastGuess!,
          label: p.name,
          color: p.color,
          icon: 'user' as const
        }))
      ]
    : [
        ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
        ...(isRoundFinished ? [
            { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
            ...gameState.players.filter(p => p.lastGuess).map(p => ({ 
              position: p.lastGuess!, 
              label: p.id === currentPlayer?.id ? strings.game.yourGuess : `${p.name}'s guess`, 
              icon: 'user' as const, 
              color: p.color 
            }))
        ] : [])
      ];

  const linesForMap = (isHost || isRoundFinished) 
    ? gameState.players.filter(p => p.lastGuess && (isHost || isRoundFinished)).map(p => ({ 
        from: p.lastGuess!, 
        to: currentQ.location, 
        color: p.color 
      })) 
    : [];

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => Math.min(prev + 0.5, 4));
  };
  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => {
      const next = Math.max(prev - 0.5, 1);
      if (next === 1) setImageOffset({ x: 0, y: 0 });
      return next;
    });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (imageZoom === 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - imageOffset.x, y: e.clientY - imageOffset.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setImageOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };
  const handleMouseUp = () => setIsDragging(false);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(45,66,57,0.15)] w-full max-w-md border border-[#2d4239]/10">
          <div className="space-y-6">
            {[...gameState.players].sort((a,b) => b.score - a.score).map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all border ${idx === 0 ? 'bg-[#ca8a04]/5 border-[#ca8a04]/20 shadow-lg scale-105' : 'bg-[#f9fbfa] border-black/5'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md border-2 border-white/20" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-sm text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#2d4239] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button onClick={onExit} className="w-full mt-12 btn-sleek btn-sleek-pine !bg-[#2d4239] !py-6">
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  if (isHost) {
    const nonGuessedNames = gameState.players.filter(p => !p.hasGuessed).map(p => p.name).join(', ');
    return (
      <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden">
        {showForceRevealConfirm && (
          <div className="fixed inset-0 z-[3000] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6">
            <div className="bg-white p-10 rounded-[3rem] w-full max-sm text-center shadow-2xl border border-black/5 animate-in zoom-in duration-300">
              <h3 className="text-xl font-black mb-4 uppercase tracking-tight">Reveal Results?</h3>
              <p className="text-[#0f1a16]/60 text-sm mb-8 font-medium">
                {nonGuessedNames} haven't locked in yet. They will receive 0 points if you proceed.
              </p>
              <div className="flex gap-4">
                <button onClick={() => setShowForceRevealConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:bg-black/5">Wait</button>
                <button onClick={() => { setShowForceRevealConfirm(false); onForceReveal?.(); }} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:opacity-90">Reveal Now</button>
              </div>
            </div>
          </div>
        )}
        <div className="w-full md:w-80 h-1/2 md:h-full bg-white border-r border-[#2d4239]/5 p-8 flex flex-col overflow-y-auto z-20">
          <div className="mb-6">
             <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8c6b4f]">
                   {strings.lobby.host} <span className="opacity-30 ml-2 tracking-widest">#{gameState.id}</span>
                </span>
             </div>
             <h2 className="text-2xl font-black uppercase tracking-tight">{isRoundFinished ? strings.game.roundResults : isScoreboard ? "Standings" : "In Progress"}</h2>
          </div>
          <div className="space-y-4 flex-1">
             <label className="text-[9px] font-black uppercase tracking-widest text-[#0f1a16]/40">{strings.lobby.playersJoined(gameState.players.length)}</label>
             {gameState.players.map(p => (
               <div key={p.id} className="p-4 bg-[#f9fbfa] rounded-2xl border border-black/5 flex items-center justify-between space-x-4">
                 <div className="flex items-center space-x-3 overflow-hidden flex-1">
                    <div className="w-8 h-8 rounded-lg flex items-center justify-center font-black text-white text-xs shrink-0" style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                    <div className="flex items-center space-x-2 truncate">
                       <span className="font-black text-xs uppercase tracking-tight truncate">{p.name}</span>
                       {p.hasGuessed && p.lastDistance !== undefined && !isScoreboard && (
                          <span className="text-[10px] font-black text-[#8c6b4f] whitespace-nowrap">
                             {formatDistance(p.lastDistance)}
                          </span>
                       )}
                    </div>
                 </div>
                 <div className="shrink-0">
                    {p.hasGuessed ? (
                      <div className="w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center text-white">
                         <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                      </div>
                    ) : (
                      <div className="w-5 h-5 border-2 border-dashed border-[#0f1a16]/10 rounded-full"></div>
                    )}
                 </div>
               </div>
             ))}
          </div>
          <div className="pt-8 border-t border-black/5 mt-auto space-y-3 pb-6">
             {(!isRoundFinished && !isCountingDown && !isScoreboard) ? (
               <button 
                onClick={() => {
                  const nonGuessed = gameState.players.filter(p => !p.hasGuessed);
                  if (nonGuessed.length > 0) setShowForceRevealConfirm(true); else onReveal?.();
                }}
                disabled={gameState.players.length === 0}
                className={`w-full py-5 btn-sleek !text-sm ${gameState.players.length > 0 ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none cursor-not-allowed'}`}
               >
                 {strings.game.revealResults}
               </button>
             ) : isRoundFinished ? (
               <button onClick={onShowScoreboard} className="w-full py-5 btn-sleek btn-sleek-pine !text-sm">View Scoreboard</button>
             ) : (
               <button 
                disabled={!canProceed && !isGameFinished}
                onClick={onNext} 
                className={`w-full py-5 btn-sleek !text-sm ${canProceed ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none'}`}
               >
                 {isLastRound ? "Finish Expedition" : "Start Next Location"}
               </button>
             )}
          </div>
          <div className="mt-2 p-3 bg-[#f9fbfa] rounded-[2rem] border border-black/5 shadow-inner shrink-0">
             <button onClick={() => setIsFullscreenImage(true)} className="w-full relative group">
                <img src={currentQ.imageUrl} className="w-full aspect-square object-cover rounded-[1.5rem] border border-black/5 shadow-sm" />
                <div className="absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity rounded-[1.5rem] flex items-center justify-center backdrop-blur-[2px]">
                   <span className="bg-white text-[#0f1a16] px-4 py-2 rounded-full font-black text-[9px] uppercase tracking-widest">{strings.common.expand}</span>
                </div>
             </button>
             <p className="mt-3 text-[10px] font-black uppercase tracking-[0.4em] text-[#8c6b4f] text-center">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</p>
          </div>
        </div>
        <div className="flex-1 relative bg-[#f9fbfa] p-8">
           {isScoreboard ? (
             <Scoreboard players={gameState.players} isLastRound={isLastRound} isHost onAnimationComplete={() => setCanProceed(true)} />
           ) : (
             <Map center={currentQ.location} zoom={14} markers={markersForMap} lines={linesForMap} roundIndex={gameState.currentQuestionIndex} />
           )}
        </div>
        {isFullscreenImage && (
          <div className="fixed inset-0 z-[2000] bg-black/95 flex items-center justify-center p-0 animate-in fade-in zoom-in duration-300 overflow-hidden" 
               onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
             <div className="absolute top-8 right-8 z-[2010] flex space-x-4">
                <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-1 flex items-center border border-white/10">
                   <button onClick={handleZoomOut} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg></button>
                   <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                   <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
                </div>
                <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl hover:scale-110 transition-transform"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
             </div>
             <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
                <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
             </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-[#f9fbfa] overflow-hidden selection:bg-[#8c6b4f]/20">
      {isCountingDown && (
        <div className="fixed inset-0 z-[2500] bg-[#0f1a16]/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white animate-in fade-in duration-500">
           <p className="text-white/40 font-black uppercase tracking-[1em] text-[10px] mb-8">{strings.game.countdownTitle}</p>
           <div className="text-[12rem] font-black animate-bounce tracking-tighter">{countdownValue}</div>
        </div>
      )}

      {/* Permanent Location Counter Header */}
      <div className="bg-white/70 backdrop-blur-xl rounded-b-[2rem] p-5 shadow-sm border-b border-[#2d4239]/5 flex justify-between items-center z-[100] shrink-0">
          <div className="font-black text-[10px] uppercase tracking-[0.4em] text-[#8c6b4f]">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="flex items-center space-x-6">
             <div className="flex -space-x-3">
                {gameState.players.map(p => (
                  <div key={p.id} className={`w-8 h-8 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black text-white shadow-sm transition-all ${p.hasGuessed ? 'scale-110 opacity-100 ring-4 ring-[#10b981]/20' : 'scale-90 opacity-20'}`} style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                ))}
             </div>
             <div className="font-black text-[#2d4239] text-sm uppercase tracking-tight tabular-nums">{strings.game.points(currentTotalScore)}</div>
          </div>
      </div>

      <div className="flex-1 flex flex-col relative">
        {isScoreboard ? (
          /* Full Screen Scoreboard */
          <div className="absolute inset-0 z-[200] p-6 bg-[#f9fbfa] animate-in slide-in-from-bottom duration-500 overflow-hidden">
            <Scoreboard players={gameState.players} isLastRound={isLastRound} onAnimationComplete={() => {}} />
          </div>
        ) : (
          /* Main Game / Results Layout */
          <>
            <div className="w-full h-1/2 flex flex-col p-6 pb-3 space-y-4">
              {isRoundFinished ? (
                /* Top half scrollable distances (Results) */
                <div className="flex-1 flex flex-col items-center justify-start text-center text-[#0f1a16] overflow-hidden animate-in fade-in duration-700">
                  <h2 className="text-xl font-black py-4 uppercase tracking-tight text-[#0f1a16] shrink-0">{strings.game.roundResults}</h2>
                  <div className="flex-1 w-full overflow-y-auto px-2 pb-6 scroll-smooth-touch">
                    <div className="space-y-3 w-full max-w-sm mx-auto">
                      {gameState.players.map(p => (
                        <div key={p.id} className="flex justify-between items-center bg-white p-4 rounded-[1.5rem] border border-[#2d4239]/5 shadow-sm">
                          <div className="flex items-center space-x-4">
                            <div className="w-4 h-4 rounded-[0.4rem] shadow-sm" style={{ backgroundColor: p.color }} />
                            <span className="font-black uppercase tracking-tight text-[10px] text-[#0f1a16]">{p.name}</span>
                          </div>
                          <span className="font-bold text-[10px] tracking-widest text-[#8c6b4f]">{p.lastDistance && p.lastDistance < 19000 ? formatDistance(p.lastDistance) : strings.game.noGuess}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              ) : (
                /* Top half glossy image box (Playing) */
                <div className="flex-1 relative rounded-[3rem] overflow-hidden bg-white/40 backdrop-blur-xl border border-white shadow-2xl group">
                  <img src={currentQ.imageUrl} className="w-full h-full object-contain transition-transform duration-[15s] group-hover:scale-105" alt="Spot" />
                  <button onClick={() => setIsFullscreenImage(true)} className="absolute top-4 right-4 bg-[#0f1a16] text-white px-5 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all z-10 border border-white/10">{strings.common.expand}</button>
                </div>
              )}
            </div>

            <div className="w-full h-1/2 p-6 pt-3 flex flex-col space-y-4">
              <div className="flex-1 relative bg-white rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(45,66,57,0.1)] border border-[#2d4239]/5 overflow-hidden transition-all">
                <Map 
                  onLocationSelect={isRoundFinished || hasSubmitted ? undefined : setSelectedGuess}
                  markers={markersForMap}
                  lines={linesForMap}
                  center={playerMapConfig.center}
                  zoom={playerMapConfig.zoom}
                  roundIndex={gameState.currentQuestionIndex}
                />

                {!isRoundFinished && !hasSubmitted && (
                  <div className="absolute bottom-8 inset-x-0 flex justify-center px-6 z-[1600]">
                    <button 
                      disabled={!selectedGuess} 
                      onClick={handleGuessSubmit} 
                      style={{ backgroundColor: selectedGuess ? (currentPlayer?.color || '#2d4239') : undefined }} 
                      className={`w-full max-w-[180px] py-3.5 btn-sleek !text-[11px] !tracking-[0.15em] shadow-2xl transition-all active:scale-95 ${selectedGuess ? 'text-white' : 'bg-white/80 text-[#0f1a16]/10 shadow-none cursor-not-allowed border border-black/5'}`}
                    >
                      {strings.game.submitGuess}
                    </button>
                  </div>
                )}

                {!isRoundFinished && hasSubmitted && !isCountingDown && (
                   <div className="absolute bottom-8 inset-x-0 flex flex-col items-center justify-center px-6 z-[1600] space-y-3">
                     <div className="bg-white/95 backdrop-blur-xl shadow-2xl px-8 py-4 rounded-[2rem] border border-[#2d4239]/10 flex items-center space-x-4">
                       <div className="w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center text-white shadow-lg"><svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg></div>
                       <span className="font-black text-[10px] uppercase tracking-[0.2em] text-[#0f1a16]">{strings.game.waitingHost}</span>
                     </div>
                     <button onClick={onUnlock} className="bg-white/60 hover:bg-white text-[8px] font-black uppercase tracking-widest px-6 py-2 rounded-full shadow-lg transition-all border border-black/5">{strings.game.unlockGuess}</button>
                   </div>
                )}
              </div>
            </div>
          </>
        )}
      </div>

      {isFullscreenImage && (
        <div className="fixed inset-0 z-[2000] bg-black/95 flex items-center justify-center p-0 animate-in fade-in zoom-in duration-300 overflow-hidden" onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
           <div className="absolute top-8 right-8 z-[2010] flex space-x-4">
              <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-1 flex items-center border border-white/10">
                 <button onClick={handleZoomOut} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg></button>
                 <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                 <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
              </div>
              <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
           </div>
           <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
              <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
           </div>
        </div>
      )}
      <style>{` .leaflet-control-container { display: ${isCountingDown ? 'none' : 'block'} !important; z-index: 500; } `}</style>
    </div>
  );
};

export default GameBoard;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);
  const [temporaryView, setTemporaryView] = useState<{ center: Location, zoom: number } | null>(null);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isStartingCamera, setIsStartingCamera] = useState(false);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);
  const [showSavedToast, setShowSavedToast] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;

    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      setCurrentLocation(loc);
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = (err: GeolocationPositionError) => {
      if (err.code === err.TIMEOUT && !currentLocation) {
        navigator.geolocation.getCurrentPosition(success, undefined, { ...options, enableHighAccuracy: false });
      }
    };
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    navigator.geolocation.getCurrentPosition(success, handleError, options);
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, [locationStatus]);

  useEffect(() => {
    if (isCapturing && activeStream && videoRef.current) {
      videoRef.current.srcObject = activeStream;
      videoRef.current.play().catch(err => console.error("Video play failed:", err));
    }
  }, [isCapturing, activeStream]);

  const stopCamera = useCallback(() => {
    if (activeStream) {
      activeStream.getTracks().forEach(track => track.stop());
      setActiveStream(null);
    }
    setIsCapturing(false);
    setIsStartingCamera(false);
  }, [activeStream]);

  const startCamera = async () => {
    if (cameraStatus === 'denied') { setError(strings.creator.cameraError); return; }
    setError(null);
    setIsStartingCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1920 } } });
      setActiveStream(stream);
      setIsCapturing(true);
      setIsStartingCamera(false);
    } catch (err) {
      setError(strings.creator.cameraError);
      setIsStartingCamera(false);
      setIsCapturing(false);
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, w, h);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}
        if (source !== 'IMAGE') source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;
    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
    } else {
      setQuestions(prev => [...prev, { id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
    }
    setPendingQuestion(null);
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const newQuestions = [...questions];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newQuestions.length) return;

    const temp = newQuestions[index];
    newQuestions[index] = newQuestions[targetIndex];
    newQuestions[targetIndex] = temp;
    setQuestions(newQuestions);
  };

  const handleDeleteSpot = (id: string) => {
    setQuestions(prev => prev.filter(q => q.id !== id));
    setConfirmDelete(null);
  };

  const handleSaveView = () => {
    if (temporaryView) {
      setStartingView(temporaryView);
      setShowSavedToast(true);
      setTimeout(() => {
        setShowSavedToast(false);
        setIsSettingView(false);
      }, 1000);
    } else {
      setIsSettingView(false);
    }
  };

  if (isSettingView) {
    const viewCenter = startingView?.center || (questions.length > 0 ? questions[0].location : { lat: 51.505, lng: -0.09 });
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col overflow-hidden">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5 z-10">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">Set Starting View</h2>
          <button onClick={() => setIsSettingView(false)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest">{strings.common.back}</button>
        </header>
        <main className="flex-1 relative">
           <Map center={viewCenter} zoom={startingView?.zoom || 12} onViewChange={setTemporaryView} />
           <div className="absolute inset-0 pointer-events-none flex items-center justify-center z-[1100]">
              <div className="w-10 h-10 border-2 border-[#2d4239] rounded-full flex items-center justify-center bg-white/40 backdrop-blur-sm">
                 <div className="w-2 h-2 bg-[#2d4239] rounded-full"></div>
              </div>
           </div>
           {showSavedToast && (
             <div className="absolute top-10 inset-x-0 flex justify-center z-[3000]">
                <div className="bg-[#10b981] text-white px-8 py-4 rounded-full font-black uppercase tracking-widest shadow-2xl animate-in fade-in zoom-in duration-300">
                  View Saved!
                </div>
             </div>
           )}
           <div className="absolute bottom-10 inset-x-0 flex justify-center p-6 z-[2500]">
              <button onClick={handleSaveView} className="w-full max-w-[240px] py-4 btn-sleek btn-sleek-pine !bg-[#2d4239] shadow-2xl !text-[10px]">
                Set Current View as Start
              </button>
           </div>
        </main>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">{pendingQuestion.editingId ? strings.creator.editSpot : strings.creator.tagSpot}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest px-4 py-2">{strings.common.back}</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-24 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-6 flex items-center justify-center bg-[#2d4239]/5">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map center={pendingQuestion.location} zoom={17} onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} markers={[{ position: pendingQuestion.location, icon: 'target' }]} />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !bg-[#2d4239] !text-lg !tracking-widest">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#0f1a16] flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] animate-flash pointer-events-none"></div>}
        <div className="absolute top-8 left-0 right-0 px-8 flex justify-center z-[120]">
           <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
        </div>
        <div className="absolute inset-x-0 bottom-0 p-12 flex justify-between items-center bg-gradient-to-t from-black/80 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-white/30 shadow-2xl active:scale-95 transition-all flex items-center justify-center disabled:opacity-50">{isProcessing ? <div className="w-10 h-10 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-[#f9fbfa]"></div>}</button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      <PermissionBanner onCheck={onRequestPermissions} />
      <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
        <div className="max-w-4xl mx-auto flex justify-between items-start">
          <div className="flex-1 mr-4">
            <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
            <div className="flex items-center space-x-4 mt-2">
               <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em]">{strings.creator.spotsInTrail(questions.length)}</p>
               <div className="w-1 h-1 rounded-full bg-[#0f1a16]/10" />
               <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
            </div>
          </div>
          <button onClick={() => hasChanges ? setShowExitConfirm(true) : onCancel()} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm text-[#0f1a16]">{strings.common.cancel}</button>
        </div>
      </header>

      <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-6 overflow-y-auto pb-40 scroll-smooth-touch">
        {showExitConfirm && (
          <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
            <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
              <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
              <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
              <div className="flex gap-4">
                <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
                <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
              </div>
            </div>
          </div>
        )}
        {confirmDelete && (
          <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
            <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
              <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
              <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
              <div className="flex gap-4">
                <button onClick={() => setConfirmDelete(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
