export default QuizCreator;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface ScoreboardProps {
  players: Player[];
  isLastRound: boolean;
  onAnimationComplete: () => void;
  isHost?: boolean;
}

const Scoreboard: React.FC<ScoreboardProps> = ({ players, isLastRound, onAnimationComplete, isHost }) => {
  const [step, setStep] = useState<'initial' | 'showingPoints' | 'counting' | 'sorting'>('initial');
  const [visibleCount, setVisibleCount] = useState(0); 
  const [displayScores, setDisplayScores] = useState<Record<string, number>>(
    Object.fromEntries(players.map(p => [p.id, p.score - (p.lastPointsGained || 0)]))
  );

  const sortedInitial = useMemo(() => {
    return [...players].sort((a, b) => {
      const scoreA = a.score - (a.lastPointsGained || 0);
      const scoreB = b.score - (b.lastPointsGained || 0);
      return scoreB - scoreA;
    });
  }, [players]);

  const sortedFinal = useMemo(() => {
    return [...players].sort((a, b) => b.score - a.score);
  }, [players]);

  const currentList = step === 'sorting' ? sortedFinal : sortedInitial;

  useEffect(() => {
    if (isLastRound) {
      const interval = setInterval(() => {
        setVisibleCount(prev => {
          if (prev >= players.length) {
            clearInterval(interval);
            onAnimationComplete();
            return prev;
          }
          return prev + 1;
        });
      }, 1500);
      return () => clearInterval(interval);
    } else {
      const timers = [
        setTimeout(() => setStep('showingPoints'), 1000),
        setTimeout(() => setStep('counting'), 2500),
        setTimeout(() => {
          const newScores = Object.fromEntries(players.map(p => [p.id, p.score]));
          setDisplayScores(newScores);
        }, 3000),
        setTimeout(() => setStep('sorting'), 4500),
        setTimeout(() => onAnimationComplete(), 5500)
      ];
      return () => timers.forEach(clearTimeout);
    }
  }, [isLastRound, players, onAnimationComplete]);

  if (isLastRound) {
    const reversedRanking = [...sortedFinal].reverse();
    return (
      <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden animate-in fade-in zoom-in duration-700">
        <h2 className="text-4xl font-black p-12 pb-6 uppercase tracking-tighter text-[#0f1a16] shrink-0 text-center">
          {strings.game.expeditionComplete}
        </h2>
        <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
          <div className="max-w-lg mx-auto space-y-4">
            {reversedRanking.slice(0, visibleCount).reverse().map((p, idx) => {
              const rank = sortedFinal.findIndex(sp => sp.id === p.id) + 1;
              return (
                <div 
                  key={p.id} 
                  className={`flex items-center justify-between p-6 rounded-[2rem] border transition-all duration-700 animate-in slide-in-from-bottom-8 ${rank === 1 ? 'bg-[#ca8a04]/10 border-[#ca8a04]/30 shadow-xl scale-105 mb-4' : 'bg-[#f9fbfa] border-black/5 shadow-sm'}`}
                >
                  <div className="flex items-center space-x-6">
                    <div className={`text-3xl font-black ${rank === 1 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{rank}</div>
                    <div className="w-14 h-14 rounded-[1.5rem] flex items-center justify-center font-black text-2xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                      {p.name.charAt(0)}
                    </div>
                    <div className="font-black uppercase tracking-tight text-[#0f1a16] text-sm md:text-base">{p.name}</div>
                  </div>
                  <div className="text-xl md:text-2xl font-black text-[#2d4239]">{strings.game.points(p.score)}</div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden">
      <h2 className="text-3xl font-black p-10 pb-6 uppercase tracking-tight text-[#0f1a16] shrink-0 text-center">
        {strings.game.roundResults}
      </h2>
      <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
        <div className="max-w-lg mx-auto space-y-4">
          {currentList.map((p, idx) => {
            const isGaining = step === 'showingPoints';
            const points = p.lastPointsGained || 0;

            return (
              <div 
                key={p.id} 
                className="flex items-center justify-between p-5 rounded-[2rem] bg-[#f9fbfa] border border-black/5 shadow-sm transition-all duration-700"
              >
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-[#0f1a16] text-xs md:text-sm">{p.name}</div>
                </div>

                <div className="flex items-center space-x-4">
                  {isGaining && points > 0 && !isHost && (
                    <div className="px-4 py-2 bg-[#10b981] text-white rounded-full font-black text-[10px] uppercase tracking-widest animate-in zoom-in bounce-in duration-500">
                      +{points}
                    </div>
                  )}
                  {isHost && isGaining && points > 0 && (
                    <div className="text-[10px] font-black text-[#10b981] animate-in zoom-in duration-300">+{points}</div>
                  )}
                  <div className="text-xl font-black text-[#2d4239] tabular-nums min-w-[3ch] text-right">
                    {displayScores[p.id]}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onUnlock?: () => void;
  onReveal?: () => void;
  onForceReveal?: () => void;
  onCountdownFinish: () => void;
  onShowScoreboard: () => void;
  onNext: () => void;
  onExit: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ 
  gameState, 
  isHost, 
  currentPlayer, 
  onGuess, 
  onUnlock,
  onReveal,
  onForceReveal,
  onCountdownFinish, 
  onShowScoreboard,
  onNext, 
  onExit 
}) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [isFullscreenImage, setIsFullscreenImage] = useState(false);
  const [imageZoom, setImageZoom] = useState(1);
  const [imageOffset, setImageOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [canProceed, setCanProceed] = useState(false);
  const [showForceRevealConfirm, setShowForceRevealConfirm] = useState(false);

  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isScoreboard = gameState.status === 'SCOREBOARD';
  const isGameFinished = gameState.status === 'FINISHED';
  const isLastRound = gameState.currentQuestionIndex === gameState.questions.length - 1;

  const playerMapConfig = useMemo(() => {
    if (gameState.startingView) return gameState.startingView;

    const lats = gameState.questions.map(q => q.location.lat);
    const lngs = gameState.questions.map(q => q.location.lng);
    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);

    return {
      center: { lat: (minLat + maxLat) / 2, lng: (minLng + maxLng) / 2 },
      zoom: 12
    };
  }, [gameState.startingView, gameState.questions]);

  const matchingPlayer = gameState.players.find(p => p.id === currentPlayer?.id);
  const hasSubmitted = !!matchingPlayer?.hasGuessed;
  const currentTotalScore = matchingPlayer?.score || 0;

  useEffect(() => {
    if (isRoundFinished || isCountingDown || isScoreboard) {
      setIsFullscreenImage(false);
    }
  }, [gameState.status]);

  useEffect(() => {
    setSelectedGuess(null);
    setCountdownValue(3);
    setIsFullscreenImage(false);
    setImageZoom(1);
    setImageOffset({ x: 0, y: 0 });
    setCanProceed(false);
    setShowForceRevealConfirm(false);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (isCountingDown) {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        onCountdownFinish();
      }
    }
    return () => clearTimeout(timer);
  }, [isCountingDown, countdownValue, onCountdownFinish]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
    }
  };

  const markersForMap = isHost 
    ? [
        { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
        ...gameState.players.filter(p => p.hasGuessed && p.lastGuess).map(p => ({
          position: p.lastGuess!,
          label: p.name,
          color: p.color,
          icon: 'user' as const
        }))
      ]
    : [
        ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
        ...(isRoundFinished ? [
            { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
            ...gameState.players.filter(p => p.lastGuess).map(p => ({ 
              position: p.lastGuess!, 
              label: p.id === currentPlayer?.id ? strings.game.yourGuess : `${p.name}'s guess`, 
              icon: 'user' as const, 
              color: p.color 
            }))
        ] : [])
      ];

  const linesForMap = (isHost || isRoundFinished) 
    ? gameState.players.filter(p => p.lastGuess && (isHost || isRoundFinished)).map(p => ({ 
        from: p.lastGuess!, 
        to: currentQ.location, 
        color: p.color 
      })) 
    : [];

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => Math.min(prev + 0.5, 4));
  };
  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => {
      const next = Math.max(prev - 0.5, 1);
      if (next === 1) setImageOffset({ x: 0, y: 0 });
      return next;
    });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (imageZoom === 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - imageOffset.x, y: e.clientY - imageOffset.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setImageOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };
  const handleMouseUp = () => setIsDragging(false);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(45,66,57,0.15)] w-full max-w-md border border-[#2d4239]/10">
          <div className="space-y-6">
            {[...gameState.players].sort((a,b) => b.score - a.score).map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all border ${idx === 0 ? 'bg-[#ca8a04]/5 border-[#ca8a04]/20 shadow-lg scale-105' : 'bg-[#f9fbfa] border-black/5'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md border-2 border-white/20" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-sm text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#2d4239] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button onClick={onExit} className="w-full mt-12 btn-sleek btn-sleek-pine !bg-[#2d4239] !py-6">
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

  if (isHost) {
    const nonGuessedNames = gameState.players.filter(p => !p.hasGuessed).map(p => p.name).join(', ');
    return (
      <div className="h-screen flex flex-col md:flex-row bg-[#f9fbfa] overflow-hidden">
        {showForceRevealConfirm && (
          <div className="fixed inset-0 z-[3000] bg-[#0f1a16]/40 backdrop-blur-md flex items-center justify-center p-6">
            <div className="bg-white p-10 rounded-[3rem] w-full max-sm text-center shadow-2xl border border-black/5 animate-in zoom-in duration-300">
              <h3 className="text-xl font-black mb-4 uppercase tracking-tight">Reveal Results?</h3>
              <p className="text-[#0f1a16]/60 text-sm mb-8 font-medium">
                {nonGuessedNames} haven't locked in yet. They will receive 0 points if you proceed.
              </p>
              <div className="flex gap-4">
                <button onClick={() => setShowForceRevealConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:bg-black/5">Wait</button>
                <button onClick={() => { setShowForceRevealConfirm(false); onForceReveal?.(); }} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest transition-all hover:opacity-90">Reveal Now</button>
              </div>
            </div>
          </div>
        )}
        <div className="w-full md:w-80 h-1/2 md:h-full bg-white border-r border-[#2d4239]/5 p-8 flex flex-col overflow-y-auto z-20">
          <div className="mb-6">
             <div className="flex items-center justify-between mb-2">
                <span className="text-[10px] font-black uppercase tracking-[0.5em] text-[#8c6b4f]">
                   {strings.lobby.host} <span className="opacity-30 ml-2 tracking-widest">#{gameState.id}</span>
                </span>
             </div>
             <h2 className="text-2xl font-black uppercase tracking-tight">{isRoundFinished ? strings.game.roundResults : isScoreboard ? "Standings" : "In Progress"}</h2>
          </div>
          <div className="space-y-4 flex-1">
             <label className="text-[9px] font-black uppercase tracking-widest text-[#0f1a16]/40">{strings.lobby.playersJoined(gameState.players.length)}</label>
             {gameState.players.map(p => (
               <div key={p.id} className="p-4 bg-[#f9fbfa] rounded-2xl border border-black/5 flex items-center justify-between space-x-4">
                 <div className="flex items-center space-x-3 overflow-hidden flex-1">
                    <div className="w-8 h-8 rounded-lg flex items-center justify-center font-black text-white text-xs shrink-0" style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                    <div className="flex items-center space-x-2 truncate">
                       <span className="font-black text-xs uppercase tracking-tight truncate">{p.name}</span>
                       {p.hasGuessed && p.lastDistance !== undefined && !isScoreboard && (
                          <span className="text-[10px] font-black text-[#8c6b4f] whitespace-nowrap">
                             {formatDistance(p.lastDistance)}
                          </span>
                       )}
                    </div>
                 </div>
                 <div className="shrink-0">
                    {p.hasGuessed ? (
                      <div className="w-5 h-5 bg-[#10b981] rounded-full flex items-center justify-center text-white">
                         <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                      </div>
                    ) : (
                      <div className="w-5 h-5 border-2 border-dashed border-[#0f1a16]/10 rounded-full"></div>
                    )}
                 </div>
               </div>
             ))}
          </div>
          <div className="pt-8 border-t border-black/5 mt-auto space-y-3 pb-6">
             {(!isRoundFinished && !isCountingDown && !isScoreboard) ? (
               <button 
                onClick={() => {
                  const nonGuessed = gameState.players.filter(p => !p.hasGuessed);
                  if (nonGuessed.length > 0) setShowForceRevealConfirm(true); else onReveal?.();
                }}
                disabled={gameState.players.length === 0}
                className={`w-full py-5 btn-sleek !text-sm ${gameState.players.length > 0 ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none cursor-not-allowed'}`}
               >
                 {strings.game.revealResults}
               </button>
             ) : isRoundFinished ? (
               <button onClick={onShowScoreboard} className="w-full py-5 btn-sleek btn-sleek-pine !text-sm">View Scoreboard</button>
             ) : (
               <button 
                disabled={!canProceed && !isGameFinished}
                onClick={onNext} 
                className={`w-full py-5 btn-sleek !text-sm ${canProceed ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none'}`}
               >
                 {isLastRound ? "Finish Expedition" : "Start Next Location"}
               </button>
             )}
          </div>
          <div className="mt-2 p-3 bg-[#f9fbfa] rounded-[2rem] border border-black/5 shadow-inner shrink-0">
             <button onClick={() => setIsFullscreenImage(true)} className="w-full relative group">
                <img src={currentQ.imageUrl} className="w-full aspect-square object-cover rounded-[1.5rem] border border-black/5 shadow-sm" />
                <div className="absolute inset-0 bg-black/30 opacity-0 group-hover:opacity-100 transition-opacity rounded-[1.5rem] flex items-center justify-center backdrop-blur-[2px]">
                   <span className="bg-white text-[#0f1a16] px-4 py-2 rounded-full font-black text-[9px] uppercase tracking-widest">{strings.common.expand}</span>
                </div>
             </button>
             <p className="mt-3 text-[10px] font-black uppercase tracking-[0.4em] text-[#8c6b4f] text-center">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</p>
          </div>
        </div>
        <div className="flex-1 relative bg-[#f9fbfa] p-8">
           {isScoreboard ? (
             <Scoreboard players={gameState.players} isLastRound={isLastRound} isHost onAnimationComplete={() => setCanProceed(true)} />
           ) : (
             <Map center={currentQ.location} zoom={14} markers={markersForMap} lines={linesForMap} roundIndex={gameState.currentQuestionIndex} />
           )}
        </div>
        {isFullscreenImage && (
          <div className="fixed inset-0 z-[2000] bg-black/95 flex items-center justify-center p-0 animate-in fade-in zoom-in duration-300 overflow-hidden" 
               onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp}>
             <div className="absolute top-8 right-8 z-[2010] flex space-x-4">
                <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-1 flex items-center border border-white/10">
                   <button onClick={handleZoomOut} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg></button>
                   <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                   <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
                </div>
                <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl hover:scale-110 transition-transform"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
             </div>
             <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
                <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
             </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="h-screen flex flex-col bg-[#f9fbfa] overflow-hidden selection:bg-[#8c6b4f]/20">
      {isCountingDown && (
        <div className="fixed inset-0 z-[2500] bg-[#0f1a16]/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white animate-in fade-in duration-500">
           <p className="text-white/40 font-black uppercase tracking-[1em] text-[10px] mb-8">{strings.game.countdownTitle}</p>
           <div className="text-[12rem] font-black animate-bounce tracking-tighter">{countdownValue}</div>
        </div>
      )}

      {/* Permanent Location Counter Header */}
      <div className="bg-white/70 backdrop-blur-xl rounded-b-[2rem] p-5 shadow-sm border-b border-[#2d4239]/5 flex justify-between items-center z-[100] shrink-0">
          <div className="font-black text-[10px] uppercase tracking-[0.4em] text-[#8c6b4f]">{strings.game.locationCounter(gameState.currentQuestionIndex + 1, gameState.questions.length)}</div>
          <div className="flex items-center space-x-6">
             <div className="flex -space-x-3">
                {gameState.players.map(p => (
                  <div key={p.id} className={`w-8 h-8 rounded-full border-2 border-white flex items-center justify-center text-[10px] font-black text-white shadow-sm transition-all ${p.hasGuessed ? 'scale-110 opacity-100 ring-4 ring-[#10b981]/20' : 'scale-90 opacity-20'}`} style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                ))}
             </div>
             <div className="font-black text-[#2d4239] text-sm uppercase tracking-tight tabular-nums">{strings.game.points(currentTotalScore)}</div>
          </div>
      </div>

      <div className="flex-1 flex flex-col relative overflow-hidden">
        {isScoreboard ? (
          /* Full Screen Scoreboard (occupies flex-1 space below header) */
          <div className="absolute inset-0 z-[200] p-6 bg-[#f9fbfa] animate-in slide-in-from-bottom duration-500 overflow-hidden flex flex-col">
            <Scoreboard players={gameState.players} isLastRound={isLastRound} onAnimationComplete={() => {}} />
          </div>
        ) : (
          /* Main Game / Results Layout */
          <>
            <div className="w-full h-1/2 flex flex-col p-6 pb-3 space-y-4 overflow-hidden shrink-0">
              {isRoundFinished ? (
                /* Top half scrollable distances (Results) - NO GLOSSY BOX */
