                 <span className="text-white/40 text-[10px] font-black uppercase tracking-widest px-2">{imageZoom.toFixed(1)}x</span>
                 <button onClick={handleZoomIn} className="p-4 text-white hover:text-[#8c6b4f] transition-colors"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg></button>
              </div>
              <button onClick={() => setIsFullscreenImage(false)} className="p-4 bg-white text-[#0f1a16] rounded-full shadow-2xl"><svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
           </div>
           <div className={`w-full h-full flex items-center justify-center ${imageZoom > 1 ? 'cursor-grab active:cursor-grabbing' : ''}`} onMouseDown={handleMouseDown}>
              <img src={currentQ.imageUrl} className="max-w-full max-h-full object-contain shadow-2xl transition-transform duration-100 ease-out" style={{ transform: `translate(${imageOffset.x}px, ${imageOffset.y}px) scale(${imageZoom})`, pointerEvents: 'none' }} />
           </div>
        </div>
      )}
      <style>{` .leaflet-control-container { display: ${isCountingDown ? 'none' : 'block'} !important; z-index: 500; } `}</style>
    </div>
  );
};

export default GameBoard;

import { useEffect, useRef } from 'react';
import L from 'leaflet';
import { Location } from '../types';

interface MarkerData {
  position: Location;
  label?: string;
  icon?: 'default' | 'target' | 'user';
  color?: string;
}

interface LineData {
  from: Location;
  to: Location;
  color?: string;
}

const isValid = (loc?: Location): boolean => 
  !!loc && typeof loc.lat === 'number' && !isNaN(loc.lat) && typeof loc.lng === 'number' && !isNaN(loc.lng);

export const useMapLayers = (
  map: L.Map | null,
  markers: MarkerData[],
  lines: LineData[],
  onLocationSelect?: (loc: Location) => void
) => {
  const layerGroupRef = useRef<L.LayerGroup | null>(null);

  // Initialize LayerGroup once map is ready
  useEffect(() => {
    if (!map) return;
    layerGroupRef.current = L.layerGroup().addTo(map);
    return () => {
      layerGroupRef.current?.remove();
      layerGroupRef.current = null;
    };
  }, [map]);

  // Sync Markers and Lines
  useEffect(() => {
    const layerGroup = layerGroupRef.current;
    if (!map || !layerGroup) return;

    layerGroup.clearLayers();

    const bounds = L.latLngBounds([]);

    markers.forEach((m) => {
      if (!isValid(m.position)) return;

      const bgColor = m.color || (m.icon === 'target' ? '#ef4444' : m.icon === 'user' ? '#3b82f6' : '#6366f1');

      const icon = L.divIcon({
        className: 'custom-div-icon',
        html: `<div class="w-8 h-8 rounded-full border-2 border-white shadow-lg flex items-center justify-center transition-all duration-300" style="background-color: ${bgColor}">
          <div class="w-2.5 h-2.5 rounded-full bg-white/80"></div>
        </div>`,
        iconSize: [32, 32],
        iconAnchor: [16, 16],
      });

      const marker = L.marker([m.position.lat, m.position.lng], { 
        icon, 
        draggable: !!onLocationSelect 
      }).addTo(layerGroup);

      if (onLocationSelect) {
        marker.on('dragend', (event) => {
          const { lat, lng } = event.target.getLatLng();
          onLocationSelect({ lat, lng });
        });
      }

      if (m.label) {
        marker.bindTooltip(m.label, { 
          permanent: false, 
          direction: 'top', 
          className: 'nordic-tooltip',
          offset: [0, -10]
        });
      }

      bounds.extend([m.position.lat, m.position.lng]);
    });

    lines.forEach((line) => {
      if (!isValid(line.from) || !isValid(line.to)) return;

      L.polyline(
        [[line.from.lat, line.from.lng], [line.to.lat, line.to.lng]],
        { 
          color: line.color || '#6366f1', 
          weight: 4, 
          dashArray: '10, 15',
          opacity: 0.8,
          lineCap: 'round'
        }
      ).addTo(layerGroup);

      bounds.extend([line.from.lat, line.from.lng]);
      bounds.extend([line.to.lat, line.to.lng]);
    });

    // Fit bounds if we have significant map data (Host seeing guesses or Results screen)
    if (bounds.isValid() && (markers.length > 1 || lines.length > 0)) {
      // Force a slight delay to ensure UI transitions have settled
      setTimeout(() => {
        map.invalidateSize();
        map.fitBounds(bounds, { 
          padding: [80, 80], 
          maxZoom: 15, 
          animate: true,
          duration: 1.0
        });
      }, 50);
    }
  }, [map, markers, lines, onLocationSelect]);
};

import { useState, useEffect, useCallback } from 'react';

export type PermissionState = 'granted' | 'denied' | 'prompt' | 'unknown';

export const usePermissions = () => {
  const [cameraStatus, setCameraStatus] = useState<PermissionState>('unknown');
  const [locationStatus, setLocationStatus] = useState<PermissionState>('unknown');

  const checkPermissions = useCallback(async () => {
    try {
      if (!('permissions' in navigator)) {
        setLocationStatus('prompt');
        setCameraStatus('prompt');
        return;
      }

      // Check Geolocation
      const geoPermission = await navigator.permissions.query({ name: 'geolocation' as any });
      setLocationStatus(geoPermission.state as PermissionState);
      geoPermission.onchange = () => setLocationStatus(geoPermission.state as PermissionState);

      // Camera permission query
      try {
        const camPermission = await navigator.permissions.query({ name: 'camera' as any });
        setCameraStatus(camPermission.state as PermissionState);
        camPermission.onchange = () => setCameraStatus(camPermission.state as PermissionState);
      } catch (e) {
        if (cameraStatus === 'unknown') setCameraStatus('prompt');
      }
    } catch (err) {
      console.warn('Permission query not supported or failed', err);
      setLocationStatus(prev => prev === 'unknown' ? 'prompt' : prev);
      setCameraStatus(prev => prev === 'unknown' ? 'prompt' : prev);
    }
  }, [cameraStatus]);

  const requestPermissions = useCallback(async () => {
    // Fresh check before requesting
    await checkPermissions();

    // Attempt camera
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      stream.getTracks().forEach(t => t.stop());
      setCameraStatus('granted');
    } catch (e) {
      console.error("Camera request failed:", e);
      setCameraStatus('denied');
    }

    // Attempt location
    return new Promise<void>((resolve) => {
      if (!navigator.geolocation) {
        setLocationStatus('denied');
        resolve();
        return;
      }

      navigator.geolocation.getCurrentPosition(
        () => {
          setLocationStatus('granted');
          resolve();
        },
        (err) => {
          console.error("Location request failed:", err);
          setLocationStatus('denied');
          resolve();
        },
        { enableHighAccuracy: true, timeout: 5000 }
      );
    }).then(() => {
      checkPermissions();
    });
  }, [checkPermissions]);

  useEffect(() => {
    checkPermissions();
  }, [checkPermissions]);

  return { cameraStatus, locationStatus, checkPermissions, requestPermissions };
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);
  const [temporaryView, setTemporaryView] = useState<{ center: Location, zoom: number } | null>(null);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isStartingCamera, setIsStartingCamera] = useState(false);
  const [activeStream, setActiveStream] = useState<MediaStream | null>(null);

  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [error, setError] = useState<string | null>(null);
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);
  const [showSavedToast, setShowSavedToast] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const videoRef = useRef<HTMLVideoElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;

    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      const loc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      setCurrentLocation(loc);
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = (err: GeolocationPositionError) => {
      if (err.code === err.TIMEOUT && !currentLocation) {
        navigator.geolocation.getCurrentPosition(success, undefined, { ...options, enableHighAccuracy: false });
      }
    };
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    navigator.geolocation.getCurrentPosition(success, handleError, options);
    return () => {
      if (watchId.current !== null) {
        navigator.geolocation.clearWatch(watchId.current);
        watchId.current = null;
      }
    };
  }, [locationStatus]);

  useEffect(() => {
    if (isCapturing && activeStream && videoRef.current) {
      videoRef.current.srcObject = activeStream;
      videoRef.current.play().catch(err => console.error("Video play failed:", err));
    }
  }, [isCapturing, activeStream]);

  const stopCamera = useCallback(() => {
    if (activeStream) {
      activeStream.getTracks().forEach(track => track.stop());
      setActiveStream(null);
    }
    setIsCapturing(false);
    setIsStartingCamera(false);
  }, [activeStream]);

  const startCamera = async () => {
    if (cameraStatus === 'denied') { setError(strings.creator.cameraError); return; }
    setError(null);
    setIsStartingCamera(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width: { ideal: 1920 } } });
      setActiveStream(stream);
      setIsCapturing(true);
      setIsStartingCamera(false);
    } catch (err) {
      setError(strings.creator.cameraError);
      setIsStartingCamera(false);
      setIsCapturing(false);
    }
  };

  const capturePhoto = async () => {
    const video = videoRef.current;
    if (!video || video.readyState < 2) return;
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const w = video.videoWidth || 1280;
      const h = video.videoHeight || 720;
      const canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0, w, h);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        const loc = currentLocation || { lat: 51.505, lng: -0.09 };
        const source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        setPendingQuestion({ imageUrl: compressedUrl, location: loc, originalLocation: loc, source });
      }
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      stopCamera();
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    setError(null);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}
        if (source !== 'IMAGE') source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 51.505, lng: -0.09 });
        setPendingQuestion({ imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;
    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
    } else {
      setQuestions(prev => [...prev, { id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
    }
    setPendingQuestion(null);
  };

  const moveQuestion = (index: number, direction: 'up' | 'down') => {
    const newQuestions = [...questions];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newQuestions.length) return;

    const temp = newQuestions[index];
    newQuestions[index] = newQuestions[targetIndex];
    newQuestions[targetIndex] = temp;
    setQuestions(newQuestions);
  };

  const handleDeleteSpot = (id: string) => {
    setQuestions(prev => prev.filter(q => q.id !== id));
    setConfirmDelete(null);
  };

  const handleSaveView = () => {
    if (temporaryView) {
      setStartingView(temporaryView);
      setShowSavedToast(true);
      setTimeout(() => {
        setShowSavedToast(false);
        setIsSettingView(false);
      }, 1000);
    } else {
      setIsSettingView(false);
    }
  };

  if (isSettingView) {
    const viewCenter = startingView?.center || (questions.length > 0 ? questions[0].location : { lat: 51.505, lng: -0.09 });
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col overflow-hidden">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5 z-[300]">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">Set Starting View</h2>
          <button onClick={() => setIsSettingView(false)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest">{strings.common.back}</button>
        </header>
        <main className="flex-1 relative">
           <Map center={viewCenter} zoom={startingView?.zoom || 12} onViewChange={setTemporaryView} />

           {/* Center crosshair with high z-index */}
           <div className="absolute inset-0 pointer-events-none flex items-center justify-center z-[2000]">
              <div className="w-10 h-10 border-2 border-[#2d4239] rounded-full flex items-center justify-center bg-white/40 backdrop-blur-sm shadow-xl">
                 <div className="w-2 h-2 bg-[#2d4239] rounded-full"></div>
              </div>
           </div>

           {showSavedToast && (
             <div className="absolute top-10 inset-x-0 flex justify-center z-[5000]">
                <div className="bg-[#10b981] text-white px-8 py-4 rounded-full font-black uppercase tracking-widest shadow-2xl animate-in fade-in zoom-in duration-300">
                  View Saved!
                </div>
             </div>
           )}

           {/* Smaller button with highest z-index to avoid map control overlap or flashing */}
           <div className="absolute bottom-10 inset-x-0 flex justify-center p-6 z-[4000] pointer-events-none">
              <button 
                onClick={handleSaveView} 
                className="pointer-events-auto px-8 py-3.5 btn-sleek btn-sleek-pine !bg-[#2d4239] shadow-[0_20px_50px_rgba(15,26,22,0.4)] !text-[10px] !tracking-widest"
              >
                Set Current View as Start
              </button>
           </div>
        </main>
      </div>
    );
  }

  if (pendingQuestion) {
    return (
      <div className="fixed inset-0 z-[200] bg-[#f9fbfa] flex flex-col">
        <header className="p-6 flex justify-between items-center bg-white/70 backdrop-blur-xl border-b border-[#2d4239]/5">
          <h2 className="text-lg font-black uppercase tracking-[0.2em] text-[#0f1a16]">{pendingQuestion.editingId ? strings.creator.editSpot : strings.creator.tagSpot}</h2>
          <button onClick={() => setPendingQuestion(null)} className="text-[#8c6b4f] font-bold uppercase text-[10px] tracking-widest px-4 py-2">{strings.common.back}</button>
        </header>
        <main className="flex-1 flex flex-col md:flex-row overflow-y-auto pb-24 scroll-smooth-touch">
          <div className="w-full md:w-1/2 p-6 flex items-center justify-center bg-[#2d4239]/5">
            <img src={pendingQuestion.imageUrl} className="max-h-full max-w-full rounded-[2.5rem] shadow-2xl object-contain border-4 border-white" />
          </div>
          <div className="w-full md:w-1/2 p-6 md:p-10 flex flex-col space-y-6">
             <div className="h-[350px] md:flex-1 rounded-[2.5rem] overflow-hidden border border-black/5 shadow-xl relative">
               <Map center={pendingQuestion.location} zoom={17} onLocationSelect={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} markers={[{ position: pendingQuestion.location, icon: 'target' }]} />
             </div>
             <button onClick={confirmPending} className="w-full py-6 btn-sleek btn-sleek-pine !bg-[#2d4239] !text-lg !tracking-widest">Confirm Marker</button>
          </div>
        </main>
      </div>
    );
  }

  if (isCapturing) {
    return (
      <div className="fixed inset-0 z-[100] bg-[#0f1a16] flex flex-col overflow-hidden">
        <video ref={videoRef} autoPlay playsInline muted className="flex-1 w-full h-full object-cover" />
        {isFlashing && <div className="fixed inset-0 bg-white z-[110] animate-flash pointer-events-none"></div>}
        <div className="absolute top-8 left-0 right-0 px-8 flex justify-center z-[120]">
           <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
        </div>
        <div className="absolute inset-x-0 bottom-0 p-12 flex justify-between items-center bg-gradient-to-t from-black/80 via-black/20 to-transparent">
          <button onClick={stopCamera} className="w-16 h-16 rounded-full bg-white/10 flex items-center justify-center border border-white/20 active:scale-90 transition-transform"><svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg></button>
          <button onClick={capturePhoto} disabled={isProcessing} className="w-24 h-24 rounded-full bg-white border-[8px] border-white/30 shadow-2xl active:scale-95 transition-all flex items-center justify-center disabled:opacity-50">{isProcessing ? <div className="w-10 h-10 border-4 border-[#0f1a16] border-t-transparent rounded-full animate-spin"></div> : <div className="w-14 h-14 rounded-full border-4 border-[#f9fbfa]"></div>}</button>
          <div className="w-16 h-16" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      <PermissionBanner onCheck={onRequestPermissions} />
      <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
        <div className="max-w-4xl mx-auto flex justify-between items-start">
          <div className="flex-1 mr-4">
            <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
            <div className="flex items-center space-x-4 mt-2">
               <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em]">{strings.creator.spotsInTrail(questions.length)}</p>
               <div className="w-1 h-1 rounded-full bg-[#0f1a16]/10" />
               <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
