export default QuizCreator;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { GameState, Player, Location } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';

interface ScoreboardProps {
  players: Player[];
  isLastRound: boolean;
  onAnimationComplete: () => void;
  isHost?: boolean;
}

const Scoreboard: React.FC<ScoreboardProps> = ({ players, isLastRound, onAnimationComplete, isHost }) => {
  const [step, setStep] = useState<'initial' | 'showingPoints' | 'counting' | 'sorting'>('initial');
  const [visibleCount, setVisibleCount] = useState(0); 
  const [displayScores, setDisplayScores] = useState<Record<string, number>>(
    Object.fromEntries(players.map(p => [p.id, p.score - (p.lastPointsGained || 0)]))
  );

  const sortedFinal = useMemo(() => {
    return [...players].sort((a, b) => b.score - a.score);
  }, [players]);

  const rankingFromLastToFirst = useMemo(() => {
    return [...sortedFinal].reverse();
  }, [sortedFinal]);

  const sortedInitial = useMemo(() => {
    return [...players].sort((a, b) => {
      const scoreA = a.score - (a.lastPointsGained || 0);
      const scoreB = b.score - (b.lastPointsGained || 0);
      return scoreB - scoreA;
    });
  }, [players]);

  const currentList = step === 'sorting' || isLastRound ? sortedFinal : sortedInitial;

  useEffect(() => {
    if (isLastRound) {
      // Tension-building animation for the finale: reveal from last place to first
      const interval = setInterval(() => {
        setVisibleCount(prev => {
          if (prev >= players.length) {
            clearInterval(interval);
            onAnimationComplete();
            return prev;
          }
          return prev + 1;
        });
      }, 1800);
      return () => clearInterval(interval);
    } else {
      const timers = [
        setTimeout(() => setStep('showingPoints'), 1000),
        setTimeout(() => setStep('counting'), 2500),
        setTimeout(() => {
          const newScores = Object.fromEntries(players.map(p => [p.id, p.score]));
          setDisplayScores(newScores);
        }, 3000),
        setTimeout(() => setStep('sorting'), 4500),
        setTimeout(() => onAnimationComplete(), 5500)
      ];
      return () => timers.forEach(clearTimeout);
    }
  }, [isLastRound, players, onAnimationComplete]);

  if (isLastRound) {
    // Determine which players to show based on visibleCount (last place first)
    const revealedPlayers = rankingFromLastToFirst.slice(0, visibleCount).reverse();

    return (
      <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden animate-in fade-in duration-700">
        <div className="p-10 md:p-12 pb-6 text-center shrink-0">
          <p className="text-[10px] font-black text-[#8c6b4f] uppercase tracking-[0.5em] mb-4 animate-pulse">Final Standings</p>
          <h2 className="text-4xl md:text-5xl font-black uppercase tracking-tighter text-[#0f1a16] leading-none">
            {strings.game.expeditionComplete}
          </h2>
        </div>
        <div className="flex-1 w-full overflow-y-auto px-6 pb-20 scroll-smooth-touch">
          <div className="max-w-lg mx-auto space-y-6 pt-4">
            {revealedPlayers.map((p) => {
              const rank = sortedFinal.findIndex(sp => sp.id === p.id) + 1;
              const isWinner = rank === 1;
              return (
                <div 
                  key={p.id} 
                  className={`flex items-center justify-between p-6 md:p-8 rounded-[2.5rem] border transition-all duration-1000 animate-in zoom-in slide-in-from-bottom-12 ${isWinner ? 'bg-[#ca8a04] text-white border-transparent shadow-[0_30px_60px_-15px_rgba(202,138,4,0.4)] scale-105 mb-10 mt-4' : 'bg-[#f9fbfa] border-black/5 shadow-sm'}`}
                >
                  <div className="flex items-center space-x-6">
                    <div className={`text-3xl md:text-4xl font-black ${isWinner ? 'text-white' : 'opacity-10 text-[#0f1a16]'}`}>#{rank}</div>
                    <div className={`w-14 h-14 md:w-16 md:h-16 rounded-[1.8rem] flex items-center justify-center font-black text-2xl md:text-3xl shadow-xl ${isWinner ? 'bg-white text-[#ca8a04]' : 'text-white'}`} style={{ backgroundColor: isWinner ? undefined : p.color }}>
                      {p.name.charAt(0)}
                    </div>
                    <div>
                      <div className={`font-black uppercase tracking-tight text-base md:text-lg ${isWinner ? 'text-white' : 'text-[#0f1a16]'}`}>{p.name}</div>
                      {isWinner && visibleCount === players.length && <div className="text-[10px] font-black uppercase tracking-[0.3em] opacity-80">Expedition Leader</div>}
                    </div>
                  </div>
                  <div className={`text-2xl md:text-3xl font-black tracking-tighter ${isWinner ? 'text-white' : 'text-[#2d4239]'}`}>{strings.game.points(p.score)}</div>
                </div>
              );
            })}
            {visibleCount < players.length && (
               <div className="py-10 flex justify-center">
                  <div className="flex space-x-2">
                     <div className="w-2 h-2 bg-[#8c6b4f] rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                     <div className="w-2 h-2 bg-[#8c6b4f] rounded-full animate-bounce" style={{ animationDelay: '200ms' }} />
                     <div className="w-2 h-2 bg-[#8c6b4f] rounded-full animate-bounce" style={{ animationDelay: '400ms' }} />
                  </div>
               </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 w-full h-full flex flex-col items-center bg-white rounded-[3.5rem] shadow-2xl border border-black/5 overflow-hidden">
      <h2 className="text-3xl font-black p-10 pb-6 uppercase tracking-tight text-[#0f1a16] shrink-0 text-center">
        {strings.game.roundResults}
      </h2>
      <div className="flex-1 w-full overflow-y-auto px-6 pb-12 scroll-smooth-touch">
        <div className="max-w-lg mx-auto space-y-4">
          {currentList.map((p) => {
            const isGaining = step === 'showingPoints';
            const points = p.lastPointsGained || 0;

            return (
              <div 
                key={p.id} 
                className="flex items-center justify-between p-5 rounded-[2rem] bg-[#f9fbfa] border border-black/5 shadow-sm transition-all duration-700"
              >
                <div className="flex items-center space-x-5">
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-xl text-white shadow-md" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-[#0f1a16] text-xs md:text-sm">{p.name}</div>
                </div>

                <div className="flex items-center space-x-4">
                  {isGaining && points > 0 && !isHost && (
                    <div className="px-4 py-2 bg-[#10b981] text-white rounded-full font-black text-[10px] uppercase tracking-widest animate-in zoom-in bounce-in duration-500">
                      +{points}
                    </div>
                  )}
                  {isHost && isGaining && points > 0 && (
                    <div className="text-[10px] font-black text-[#10b981] animate-in zoom-in duration-300">+{points}</div>
                  )}
                  <div className="text-xl font-black text-[#2d4239] tabular-nums min-w-[3ch] text-right">
                    {displayScores[p.id]}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onUnlock?: () => void;
  onReveal?: () => void;
  onForceReveal?: () => void;
  onCountdownFinish: () => void;
  onShowScoreboard: () => void;
  onNext: () => void;
  onExit: () => void;
}

const GameBoard: React.FC<GameBoardProps> = ({ 
  gameState, 
  isHost, 
  currentPlayer, 
  onGuess, 
  onUnlock,
  onReveal,
  onForceReveal,
  onCountdownFinish, 
  onShowScoreboard,
  onNext, 
  onExit 
}) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [isFullscreenImage, setIsFullscreenImage] = useState(false);
  const [imageZoom, setImageZoom] = useState(1);
  const [imageOffset, setImageOffset] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const [canProceed, setCanProceed] = useState(false);
  const [showForceRevealConfirm, setShowForceRevealConfirm] = useState(false);

  const [countdownValue, setCountdownValue] = useState(3);
  const currentQ = gameState.questions[gameState.currentQuestionIndex];

  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isScoreboard = gameState.status === 'SCOREBOARD';
  const isGameFinished = gameState.status === 'FINISHED';
  const isLastRound = gameState.currentQuestionIndex === gameState.questions.length - 1;

  const isValidLoc = (loc?: Location): boolean => 
    !!loc && typeof loc.lat === 'number' && !isNaN(loc.lat) && typeof loc.lng === 'number' && !isNaN(loc.lng);

  const playerMapConfig = useMemo(() => {
    if (gameState.startingView && isValidLoc(gameState.startingView.center)) return gameState.startingView;

    const validQuestions = gameState.questions.filter(q => isValidLoc(q.location));
    if (validQuestions.length === 0) return { center: { lat: 51.505, lng: -0.09 }, zoom: 12 };

    const lats = validQuestions.map(q => q.location.lat);
    const lngs = validQuestions.map(q => q.location.lng);
    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);

    return {
      center: { lat: (minLat + maxLat) / 2, lng: (minLng + maxLng) / 2 },
      zoom: 12
    };
  }, [gameState.startingView, gameState.questions]);

  const matchingPlayer = gameState.players.find(p => p.id === currentPlayer?.id);
  const hasSubmitted = !!matchingPlayer?.hasGuessed;
  const currentTotalScore = matchingPlayer?.score || 0;

  useEffect(() => {
    if (isRoundFinished || isCountingDown || isScoreboard) {
      setIsFullscreenImage(false);
    }
  }, [gameState.status]);

  useEffect(() => {
    setSelectedGuess(null);
    setCountdownValue(3);
    setIsFullscreenImage(false);
    setImageZoom(1);
    setImageOffset({ x: 0, y: 0 });
    setCanProceed(false);
    setShowForceRevealConfirm(false);
  }, [gameState.currentQuestionIndex]);

  useEffect(() => {
    let timer: number;
    if (isCountingDown) {
      if (countdownValue > 0) {
        timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
      } else {
        // If last round, skip round results (distances) and go straight to tension scoreboard
        if (isLastRound && isHost) {
          onShowScoreboard();
        } else {
          onCountdownFinish();
        }
      }
    }
    return () => clearTimeout(timer);
  }, [isCountingDown, countdownValue, onCountdownFinish, onShowScoreboard, isLastRound, isHost]);

  const handleGuessSubmit = () => {
    if (selectedGuess) {
      onGuess(selectedGuess);
    }
  };

  const markersForMap = isHost 
    ? [
        { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
        ...gameState.players.filter(p => p.hasGuessed && p.lastGuess).map(p => ({
          position: p.lastGuess!,
          label: p.name,
          color: p.color,
          icon: 'user' as const
        }))
      ]
    : [
        ...(selectedGuess && !isRoundFinished ? [{ position: selectedGuess, label: strings.game.yourGuess, icon: 'user' as const, color: currentPlayer?.color }] : []),
        ...(isRoundFinished ? [
            { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
            ...gameState.players.filter(p => p.lastGuess).map(p => ({ 
              position: p.lastGuess!, 
              label: p.id === currentPlayer?.id ? strings.game.yourGuess : `${p.name}'s guess`, 
              icon: 'user' as const, 
              color: p.color 
            }))
        ] : [])
      ];

  const linesForMap = (isHost || isRoundFinished) 
    ? gameState.players.filter(p => p.lastGuess && (isHost || isRoundFinished)).map(p => ({ 
        from: p.lastGuess!, 
        to: currentQ.location, 
        color: p.color 
      })) 
    : [];

  const handleZoomIn = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => Math.min(prev + 0.5, 4));
  };
  const handleZoomOut = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImageZoom(prev => {
      const next = Math.max(prev - 0.5, 1);
      if (next === 1) setImageOffset({ x: 0, y: 0 });
      return next;
    });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (imageZoom === 1) return;
    setIsDragging(true);
    setDragStart({ x: e.clientX - imageOffset.x, y: e.clientY - imageOffset.y });
  };
  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDragging) return;
    setImageOffset({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };
  const handleMouseUp = () => setIsDragging(false);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(45,66,57,0.15)] w-full max-w-md border border-[#2d4239]/10">
          <div className="space-y-6">
            {[...gameState.players].sort((a,b) => b.score - a.score).map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all border ${idx === 0 ? 'bg-[#ca8a04]/5 border-[#ca8a04]/20 shadow-lg scale-105' : 'bg-[#f9fbfa] border-black/5'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md border-2 border-white/20" style={{ backgroundColor: p.color }}>
                    {p.name.charAt(0)}
                  </div>
                  <div className="font-black uppercase tracking-tight text-sm text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#2d4239] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button onClick={onExit} className="w-full mt-12 btn-sleek btn-sleek-pine !bg-[#2d4239] !py-6">
            {strings.game.playAgain}
          </button>
        </div>
      </div>
    );
  }

