/**
 * Modern non-blocking image compression using Web Workers.
 * Prevents main-thread jank and handles memory more efficiently.
 */
let worker: Worker | null = null;
let nextMessageId = 0;
const pendingRequests = new Map<number, (value: string) => void>();

export const compressImage = async (dataUrl: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
  if (!worker) {
    worker = new Worker(new URL('./compression.worker.ts', import.meta.url));
    worker.onmessage = (e) => {
      const { id, dataUrl, error } = e.data;
      const resolve = pendingRequests.get(id);
      if (resolve) {
        if (error) console.error("Worker error:", error);
        resolve(dataUrl);
        pendingRequests.delete(id);
      }
    };
  }

  return new Promise(async (resolve) => {
    const id = nextMessageId++;
    pendingRequests.set(id, resolve);

    // Convert dataURL to Blob for structured cloning to the worker
    const response = await fetch(dataUrl);
    const blob = await response.blob();

    worker?.postMessage({ id, blob, maxWidth, quality });
  });
};

import { useEffect, useCallback, useRef } from 'react';
import { GameState, Player, Location } from './types';
import { getLeanState } from './utils';

const CHANNEL_NAME = 'locateit_sync_v2';

export type GameSyncMessage = 
  | { type: 'STATE_FULL'; state: GameState }
  | { type: 'STATE_DYNAMIC'; state: Partial<GameState> }
  | { type: 'REQUEST_SYNC' }
  | { type: 'PLAYER_JOIN_REQUEST'; player: Player }
  | { type: 'PLAYER_GUESS_REQUEST'; playerId: string; guess: Location; distance: number }
  | { type: 'PLAYER_UNLOCK_REQUEST'; playerId: string }
  | { type: 'HOST_REVEAL_REQUEST' }
  | { type: 'FORCE_REVEAL' }
  | { type: 'TERMINATE_SESSION' };

export const useGameSync = (
  onStateUpdate: (state: GameState) => void, 
  onActionRequest: (action: any) => void,
  isHost: boolean, 
  gameState: GameState | null
) => {
  const channelRef = useRef<BroadcastChannel | null>(null);
  const questionsCache = useRef<GameState['questions'] | null>(null);

  const clearCache = useCallback(() => {
    questionsCache.current = null;
  }, []);

  const broadcast = useCallback((state: GameState, full = false) => {
    if (!channelRef.current) return;

    if (full) {
      channelRef.current.postMessage({ type: 'STATE_FULL', state });
    } else {
      const lean = getLeanState(state);
      channelRef.current.postMessage({ type: 'STATE_DYNAMIC', state: lean });
    }
  }, []);

  const sendAction = useCallback((message: GameSyncMessage) => {
    if (channelRef.current) {
      channelRef.current.postMessage(message);
    }
  }, []);

  const requestSync = useCallback(() => {
    if (channelRef.current) {
      channelRef.current.postMessage({ type: 'REQUEST_SYNC' });
    }
  }, []);

  useEffect(() => {
    const channel = new BroadcastChannel(CHANNEL_NAME);
    channelRef.current = channel;

    channel.onmessage = (event) => {
      const data = event.data as GameSyncMessage;

      if (data.type === 'STATE_FULL') {
        if (!isHost) {
          questionsCache.current = data.state.questions;
          onStateUpdate(data.state);
        }
      } else if (data.type === 'STATE_DYNAMIC') {
        if (!isHost && questionsCache.current) {
          const reconstructedState = { 
            ...data.state, 
            questions: questionsCache.current 
          } as GameState;
          onStateUpdate(reconstructedState);
        }
      } else if (data.type === 'TERMINATE_SESSION') {
        if (!isHost) clearCache();
      } else if (data.type === 'REQUEST_SYNC') {
        if (isHost && gameState) broadcast(gameState, true);
      } else if (data.type === 'PLAYER_JOIN_REQUEST') {
        if (isHost) onActionRequest({ type: 'JOIN_PLAYER', payload: data.player });
      } else if (data.type === 'PLAYER_GUESS_REQUEST') {
        if (isHost) onActionRequest({ type: 'SUBMIT_GUESS', payload: { playerId: data.playerId, guess: data.guess, distance: data.distance } });
      } else if (data.type === 'PLAYER_UNLOCK_REQUEST') {
        if (isHost) onActionRequest({ type: 'UNLOCK_GUESS', payload: data.playerId });
      } else if (data.type === 'HOST_REVEAL_REQUEST') {
        if (isHost) onActionRequest({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
      } else if (data.type === 'FORCE_REVEAL') {
        if (isHost) onActionRequest({ type: 'FORCE_REVEAL' });
      }
    };

    return () => {
      channel.close();
      channelRef.current = null;
    };
  }, [onStateUpdate, onActionRequest, isHost, gameState, broadcast, clearCache]);

  return { broadcast, sendAction, requestSync, clearCache };
};

import { useState, useEffect, useCallback } from 'react';
import { Trail, Question, Location, User } from '../types';
import { generateId } from '../utils';
import { strings } from '../i18n';

export const useTrails = (user: User | null) => {
  const [trails, setTrails] = useState<Trail[]>([]);

  const loadTrails = useCallback(() => {
    if (!user) return;
    const saved = localStorage.getItem(`trails_${user.id}`);
    if (saved) {
      setTrails(JSON.parse(saved).sort((a: Trail, b: Trail) => b.lastUpdated - a.lastUpdated));
    } else {
      setTrails([]);
    }
  }, [user]);

  useEffect(() => {
    loadTrails();
  }, [loadTrails]);

  const saveTrail = (questions: Question[], name: string, startingView?: { center: Location, zoom: number }, editingId?: string) => {
    if (!user) return null;

    const trailToSave: Trail = {
      id: editingId || generateId(),
      name: name || `Trail ${new Date().toLocaleDateString()}`,
      questions,
      creatorId: user.id,
      lastUpdated: Date.now(),
      startingView
    };

    const key = `trails_${user.id}`;
    const saved = localStorage.getItem(key);
    let currentTrails: Trail[] = saved ? JSON.parse(saved) : [];

    const idx = currentTrails.findIndex(t => t.id === trailToSave.id);
    if (idx > -1) currentTrails[idx] = trailToSave;
    else currentTrails.push(trailToSave);

    try {
      localStorage.setItem(key, JSON.stringify(currentTrails));
      loadTrails();
      return trailToSave;
    } catch (e) {
      if (e instanceof DOMException && e.name === 'QuotaExceededError') {
        alert(strings.storage.limitReached);
      } else {
        console.error("Storage error:", e);
      }
      return null;
    }
  };

  const deleteTrail = (id: string) => {
    if (!user) return;
    const updated = trails.filter(t => t.id !== id);
    localStorage.setItem(`trails_${user.id}`, JSON.stringify(updated));
    setTrails(updated);
  };

  return { trails, saveTrail, deleteTrail, reloadTrails: loadTrails };
};

import React, { useState, useEffect, useReducer, useCallback, useRef } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import { gameReducer } from './gameReducer';
import { useGameSync } from './useGameSync';
import { useTrails } from './hooks/useTrails';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import Home from './components/Home';
import JoinGame from './components/JoinGame';
import { PermissionModal } from './components/PermissionGate';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [showPermissionModal, setShowPermissionModal] = useState(false);
  const [joinError, setJoinError] = useState<string | null>(null);
  const [isJoining, setIsJoining] = useState(false);
  const joinTimeoutRef = useRef<number | null>(null);

  const prevStatusRef = useRef<GameState['status'] | null>(null);
  const prevIndexRef = useRef<number>(-1);

  const { trails, saveTrail, deleteTrail } = useTrails(user);
  const [gameState, dispatch] = useReducer(gameReducer, null);

  const { broadcast, sendAction, requestSync, clearCache } = useGameSync(
    useCallback((state) => dispatch({ type: 'SYNC_STATE', payload: state }), []),
    useCallback((action) => dispatch(action), []),
    isHost,
    gameState
  );

  // Optimized Broadcasting: Full sync only on major transitions
  useEffect(() => {
    if (isHost && gameState) {
      localStorage.setItem('locateit_active_host_state', JSON.stringify(gameState));

      const isStatusChange = gameState.status !== prevStatusRef.current;
      const isIndexChange = gameState.currentQuestionIndex !== prevIndexRef.current;
      const isNewGame = prevStatusRef.current === null;

      const needsFullSync = isStatusChange || isIndexChange || isNewGame;
      broadcast(gameState, needsFullSync);

      prevStatusRef.current = gameState.status;
      prevIndexRef.current = gameState.currentQuestionIndex;
    }
  }, [gameState, isHost, broadcast]);

  useEffect(() => {
    if (view === 'JOIN' && !gameState) {
      requestSync();
      const interval = setInterval(requestSync, 2000);
      return () => clearInterval(interval);
    }
  }, [view, gameState, requestSync]);

  useEffect(() => {
    if (gameState && (isHost || currentPlayer)) {
      const inGameStatus = ['PLAYING', 'COUNTDOWN', 'RESULTS', 'SCOREBOARD', 'FINISHED'];
      if (inGameStatus.includes(gameState.status) && view !== 'PLAYING') {
        setView('PLAYING');
      }

      if (currentPlayer && !isHost && !isJoining) {
        const isPresent = gameState.players.some(p => p.id === currentPlayer.id);
        if (!isPresent && (view === 'LOBBY' || view === 'PLAYING')) {
           alert(strings.lobby.kickedDesc);
           handleExitGame();
        }
      }
    }
  }, [gameState, currentPlayer, isHost, view, isJoining]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  const handleCompleteTrail = (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => {
    saveTrail(questions, name, startingView, editingTrail?.id);
    setEditingTrail(null);
    setView('DASHBOARD');
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); 
    const newGameId = generateId();
    dispatch({ type: 'INIT_LOBBY', payload: { id: newGameId, questions: trail.questions, hostId: user.id, startingView: trail.startingView } });
    setView('LOBBY');
  };

  const handleResumeHost = () => {
    const saved = localStorage.getItem('locateit_active_host_state');
    if (saved) {
      const state = JSON.parse(saved) as GameState;
      setIsHost(true);
      setCurrentPlayer(null);
      dispatch({ type: 'SYNC_STATE', payload: state });
      setView(state.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
    }
  };

  const handleJoinGame = (gameCode: string, name: string, color: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();

    if (!gameState || gameState.id !== code) {
      setJoinError(`Expedition ${code} not found. Ensure the code is correct.`);
      requestSync();
      return;
    }

    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);

    if (existingById) {
      setCurrentPlayer(existingById);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    const existingByName = gameState.players.find(p => p.name.toLowerCase() === name.toLowerCase());
    if (existingByName) {
      setCurrentPlayer(existingByName);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', existingByName.id);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    const newPlayer: Player = { id: generateId(), name, color, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    setIsJoining(true);

    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 5000);

    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  const handleExitGame = () => {
    if (isHost) {
      localStorage.removeItem('locateit_active_host_state');
      sendAction({ type: 'TERMINATE_SESSION' });
    }
    clearCache();
    dispatch({ type: 'EXIT_GAME' });
    setCurrentPlayer(null);
    setView(isHost ? 'DASHBOARD' : 'HOME');
  };

  return (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}

      {view === 'HOME' && <Home onJoin={() => setView('JOIN')} onDesign={() => user ? setView('DASHBOARD') : setView('AUTH')} />}

      {view === 'JOIN' && (
        <JoinGame 
          onBack={() => setView('HOME')} 
          onJoin={handleJoinGame} 
          isSearching={!gameState} 
          error={joinError} 
        />
      )}

      {view === 'AUTH' && (
        <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />
      )}

      {view === 'DASHBOARD' && user && (
        <Dashboard 
          user={user} 
          onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} 
          onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} 
          onHostTrail={handleHostTrail} 
          onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }}
          onResumeHost={localStorage.getItem('locateit_active_host_state') ? handleResumeHost : undefined}
        />
      )}

      {view === 'CREATE' && (
        <QuizCreator 
          initialTrail={editingTrail || undefined} 
          onComplete={handleCompleteTrail} 
          onCancel={() => setView('DASHBOARD')} 
          onRequestPermissions={() => setShowPermissionModal(true)}
        />
      )}

      {view === 'LOBBY' && gameState && (
        <Lobby 
          gameState={gameState} 
          isHost={isHost} 
          onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} 
          currentPlayer={currentPlayer} 
          onBack={handleExitGame} 
          onKick={(id) => dispatch({ type: 'KICK_PLAYER', payload: id })} 
        />
      )}

      {view === 'PLAYING' && gameState && (
        <GameBoard 
          gameState={gameState} 
          isHost={isHost} 
          currentPlayer={currentPlayer} 
          onGuess={(guess) => {
            if (!currentPlayer) return;
            const currentQ = gameState.questions[gameState.currentQuestionIndex];
            const dist = calculateDistance(guess, currentQ.location);
            sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
            if (isHost) dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
          }} 
          onUnlock={() => {
            if (!currentPlayer) return;
            sendAction({ type: 'PLAYER_UNLOCK_REQUEST', playerId: currentPlayer.id });
            if (isHost) dispatch({ type: 'UNLOCK_GUESS', payload: currentPlayer.id });
          }}
          onReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
            sendAction({ type: 'HOST_REVEAL_REQUEST' });
          }}
          onForceReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'FORCE_REVEAL' });
            sendAction({ type: 'FORCE_REVEAL' });
          }}
          onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
          onShowScoreboard={() => isHost && dispatch({ type: 'CALCULATE_SCORES' })}
          onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
          onExit={handleExitGame}
        />
      )}
    </>
  );
};

export default App;

import { Location, GameState } from './types';

export const calculateDistance = (loc1: Location, loc2: Location): number => {
  const R = 6371;
  const dLat = (loc2.lat - loc1.lat) * Math.PI / 180;
  const dLng = (loc2.lng - loc1.lng) * Math.PI / 180;
  const a = 
    Math.sin(dLat/2) * Math.sin(dLat/2) +
    Math.cos(loc1.lat * Math.PI / 180) * Math.cos(loc2.lat * Math.PI / 180) * 
    Math.sin(dLng/2) * Math.sin(dLng/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
  return R * c;
};

export const formatDistance = (km: number): string => {
  if (km < 1) return `${(km * 1000).toFixed(0)}m`;
  return `${km.toFixed(2)}km`;
};

export const generateId = () => Math.random().toString(36).substr(2, 6).toUpperCase();

export const getLeanState = (state: GameState): Partial<GameState> => {
  const { questions, ...leanState } = state;
  return leanState;
};

/**
 * Modern non-blocking image compression using Web Workers.
 * Prevents main-thread jank and handles memory more efficiently.
 * Inlined via Blob to ensure compatibility across all environments.
 */
let worker: Worker | null = null;
let nextMessageId = 0;
const pendingRequests = new Map<number, (value: string) => void>();

const createWorker = () => {
  const workerCode = `
    self.onmessage = async (e) => {
      const { id, blob, maxWidth, quality } = e.data;
      try {
        const img = await createImageBitmap(blob);
        let width = img.width;
        let height = img.height;
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }
        const canvas = new OffscreenCanvas(width, height);
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('Failed to get 2D context');
        ctx.drawImage(img, 0, 0, width, height);
        const compressedBlob = await canvas.convertToBlob({ type: 'image/jpeg', quality });
        const reader = new FileReader();
        reader.onloadend = () => self.postMessage({ id, dataUrl: reader.result });
        reader.readAsDataURL(compressedBlob);
        img.close();
      } catch (error) {
        self.postMessage({ id, error: error instanceof Error ? error.message : 'Unknown error' });
      }
    };
  `;
  const blob = new Blob([workerCode], { type: 'application/javascript' });
  const url = URL.createObjectURL(blob);
  return new Worker(url);
};

export const compressImage = async (dataUrl: string, maxWidth = 1024, quality = 0.7): Promise<string> => {
  if (!worker) {
    try {
      worker = createWorker();
      worker.onmessage = (e) => {
        const { id, dataUrl, error } = e.data;
        const resolve = pendingRequests.get(id);
        if (resolve) {
          if (error) console.error("Worker error:", error);
          resolve(dataUrl);
          pendingRequests.delete(id);
        }
      };
    } catch (err) {
      console.error("Worker creation failed:", err);
      return dataUrl;
    }
  }

  return new Promise(async (resolve) => {
    const id = nextMessageId++;
    pendingRequests.set(id, resolve);

    try {
      const response = await fetch(dataUrl);
      const blob = await response.blob();
      worker?.postMessage({ id, blob, maxWidth, quality });
    } catch (err) {
      console.error("Image processing request failed:", err);
      resolve(dataUrl);
      pendingRequests.delete(id);
    }
  });
};

import { GameState, Player, Location, Question } from './types';

export type GameAction = 
  | { type: 'SYNC_STATE'; payload: GameState }
  | { type: 'INIT_LOBBY'; payload: { id: string, questions: Question[], hostId: string, startingView?: { center: Location, zoom: number } } }
  | { type: 'JOIN_PLAYER'; payload: Player }
  | { type: 'KICK_PLAYER'; payload: string }
  | { type: 'SET_STATUS'; payload: GameState['status'] }
  | { type: 'SUBMIT_GUESS'; payload: { playerId: string, guess: Location, distance: number } }
  | { type: 'UNLOCK_GUESS'; payload: string }
  | { type: 'FORCE_REVEAL' }
  | { type: 'CALCULATE_SCORES' }
  | { type: 'NEXT_ROUND' }
  | { type: 'EXIT_GAME' };

export const gameReducer = (state: GameState | null, action: GameAction): GameState | null => {
  switch (action.type) {
    case 'SYNC_STATE':
      return action.payload;

    case 'INIT_LOBBY':
      return {
        id: action.payload.id,
        status: 'LOBBY',
        questions: action.payload.questions,
        currentQuestionIndex: 0,
        players: [],
        hostId: action.payload.hostId,
        startingView: action.payload.startingView,
      };

    case 'JOIN_PLAYER':
      if (!state) return null;
      if (state.players.find(p => p.id === action.payload.id)) return state;
      return { ...state, players: [...state.players, action.payload] };

    case 'KICK_PLAYER':
      if (!state) return null;
      return { ...state, players: state.players.filter(p => p.id !== action.payload) };

    case 'SET_STATUS':
      if (!state) return null;
      return { ...state, status: action.payload };

    case 'SUBMIT_GUESS':
      if (!state) return null;
      const updatedPlayers = state.players.map(p => 
        p.id === action.payload.playerId 
          ? { ...p, hasGuessed: true, lastGuess: action.payload.guess, lastDistance: action.payload.distance } 
          : p
      );
      return { ...state, players: updatedPlayers };

    case 'UNLOCK_GUESS':
      if (!state) return null;
      return { 
        ...state, 
        players: state.players.map(p => 
          p.id === action.payload 
            ? { ...p, hasGuessed: false, lastGuess: undefined, lastDistance: undefined } 
            : p
        )
      };

    case 'FORCE_REVEAL':
      if (!state) return null;
      return {
        ...state,
        status: 'COUNTDOWN',
        players: state.players.map(p => 
          !p.hasGuessed 
            ? { ...p, hasGuessed: true, lastDistance: 20000, lastGuess: undefined } // Penalty: 20,000 km away
            : p
        )
      };

    case 'CALCULATE_SCORES':
      if (!state) return null;
      const sortedByDistance = [...state.players].sort((a, b) => (a.lastDistance || Infinity) - (b.lastDistance || Infinity));
      const playersWithCalculatedScores = state.players.map(p => {
        const rank = sortedByDistance.findIndex(sp => sp.id === p.id);
        const pointsGained = (p.lastDistance !== undefined && p.lastDistance < 19000) 
          ? Math.max(0, state.players.length - rank) 
          : 0;
        return { 
          ...p, 
          lastPointsGained: pointsGained,
          score: p.score + pointsGained 
        };
      });
      const isLastRound = state.currentQuestionIndex === state.questions.length - 1;
      return { 
        ...state, 
        players: playersWithCalculatedScores, 
        status: isLastRound ? 'FINISHED' : 'SCOREBOARD' 
      };

    case 'NEXT_ROUND':
      if (!state) return null;
      const isLastQuestion = state.currentQuestionIndex === state.questions.length - 1;

      if (isLastQuestion) return { ...state, status: 'FINISHED' };

      const resetPlayers = state.players.map(p => ({
        ...p,
        hasGuessed: false,
        lastGuess: undefined,
        lastDistance: undefined,
        lastPointsGained: 0
      }));

      return {
        ...state,
        players: resetPlayers,
        currentQuestionIndex: state.currentQuestionIndex + 1,
        status: 'PLAYING'
      };

    case 'EXIT_GAME':
      return null;

    default:
      return state;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { GameState, Player, Location } from '../types';
import { strings } from '../i18n';
import HostBoard from './HostBoard';
import PlayerBoard from './PlayerBoard';

interface GameBoardProps {
  gameState: GameState;
  isHost: boolean;
  currentPlayer: Player | null;
  onGuess: (loc: Location) => void;
  onUnlock: () => void;
  onReveal?: () => void;
  onForceReveal?: () => void;
  onCountdownFinish: () => void;
  onShowScoreboard: () => void;
  onNext: () => void;
  onExit: () => void;
}

const isValidLoc = (loc?: Location): boolean => 
  !!loc && typeof loc.lat === 'number' && !isNaN(loc.lat) && typeof loc.lng === 'number' && !isNaN(loc.lng);

const GameBoard: React.FC<GameBoardProps> = ({ 
  gameState, 
  isHost, 
  currentPlayer, 
  onGuess, 
  onUnlock,
  onReveal,
  onForceReveal,
  onCountdownFinish, 
  onShowScoreboard,
  onNext, 
  onExit 
}) => {
  const [canProceed, setCanProceed] = useState(false);
  const [countdownValue, setCountdownValue] = useState(3);

  const currentQ = gameState.questions[gameState.currentQuestionIndex];
  const isCountingDown = gameState.status === 'COUNTDOWN';
  const isRoundFinished = gameState.status === 'RESULTS';
  const isScoreboard = gameState.status === 'SCOREBOARD';
  const isGameFinished = gameState.status === 'FINISHED';
  const isLastRound = gameState.currentQuestionIndex === gameState.questions.length - 1;

  const playerMapConfig = useMemo(() => {
    if (gameState.startingView && isValidLoc(gameState.startingView.center)) return gameState.startingView;
    const validQuestions = gameState.questions.filter(q => isValidLoc(q.location));
    if (validQuestions.length === 0) return { center: { lat: 51.505, lng: -0.09 }, zoom: 12 };

    const lats = validQuestions.map(q => q.location.lat);
    const lngs = validQuestions.map(q => q.location.lng);
    return {
      center: { lat: (Math.min(...lats) + Math.max(...lats)) / 2, lng: (Math.min(...lngs) + Math.max(...lngs)) / 2 },
      zoom: 12
    };
  }, [gameState.startingView, gameState.questions]);

  useEffect(() => {
    if (isCountingDown) {
      if (countdownValue > 0) {
        const timer = window.setTimeout(() => setCountdownValue(v => v - 1), 1000);
        return () => clearTimeout(timer);
      } else {
        // Always go to results first to show map distances, even on the last round.
        onCountdownFinish();
      }
    }
  }, [isCountingDown, countdownValue, onCountdownFinish]);

  useEffect(() => {
    setCountdownValue(3);
    setCanProceed(false);
  }, [gameState.currentQuestionIndex]);

  if (isGameFinished) {
    return (
      <div className="min-h-screen bg-[#f9fbfa] p-6 flex flex-col items-center justify-center text-[#0f1a16]">
        <h1 className="text-4xl font-black mb-12 uppercase tracking-tight text-[#0f1a16]">{strings.game.expeditionComplete}</h1>
        <div className="bg-white rounded-[3.5rem] p-10 shadow-[0_60px_100px_-20px_rgba(45,66,57,0.15)] w-full max-w-md border border-[#2d4239]/10">
          <div className="space-y-6">
            {[...gameState.players].sort((a,b) => b.score - a.score).map((p, idx) => (
              <div key={p.id} className={`flex items-center justify-between p-5 rounded-[2rem] transition-all border ${idx === 0 ? 'bg-[#ca8a04]/5 border-[#ca8a04]/20 shadow-lg scale-105' : 'bg-[#f9fbfa] border-black/5'}`}>
                <div className="flex items-center space-x-5">
                  <div className={`text-2xl font-black ${idx === 0 ? 'text-[#ca8a04]' : 'opacity-10'}`}>#{idx + 1}</div>
                  <div className="w-12 h-12 rounded-[1.25rem] flex items-center justify-center font-black text-white shadow-md border-2 border-white/20" style={{ backgroundColor: p.color }}>{p.name.charAt(0)}</div>
                  <div className="font-black uppercase tracking-tight text-sm text-[#0f1a16]">{p.name}</div>
                </div>
                <div className="text-lg font-black text-[#2d4239] tracking-tight">{strings.game.points(p.score)}</div>
              </div>
            ))}
          </div>
          <button onClick={onExit} className="w-full mt-12 btn-sleek btn-sleek-pine !bg-[#2d4239] !py-6">{strings.game.playAgain}</button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen bg-[#f9fbfa] overflow-hidden">
      {isCountingDown && (
        <div className="fixed inset-0 z-[2500] bg-[#0f1a16]/95 backdrop-blur-3xl flex flex-col items-center justify-center text-white animate-in fade-in duration-500">
           <p className="text-white/40 font-black uppercase tracking-[1em] text-[10px] mb-8">{strings.game.countdownTitle}</p>
           <div className="text-[12rem] font-black animate-bounce tracking-tighter">{countdownValue}</div>
        </div>
      )}

      {isHost ? (
        <HostBoard 
          gameState={gameState} 
          currentQ={currentQ} 
          isRoundFinished={isRoundFinished} 
          isScoreboard={isScoreboard} 
          isLastRound={isLastRound}
          canProceed={canProceed}
          onReveal={onReveal}
          onForceReveal={onForceReveal}
          onShowScoreboard={onShowScoreboard}
          onNext={onNext}
          onSetCanProceed={setCanProceed}
        />
      ) : (
        <PlayerBoard 
          gameState={gameState} 
          currentPlayer={currentPlayer} 
          currentQ={currentQ} 
          isRoundFinished={isRoundFinished} 
          isScoreboard={isScoreboard} 
          isLastRound={isLastRound}
          playerMapConfig={playerMapConfig}
          onGuess={onGuess}
          onUnlock={onUnlock}
        />
      )}
      <style>{` .leaflet-control-container { display: ${isCountingDown ? 'none' : 'block'} !important; z-index: 500; } `}</style>
    </div>
  );
};

export default GameBoard;

import React, { useState, useMemo, useEffect } from 'react';
import { GameState, Player, Location, Question } from '../types';
import { formatDistance } from '../utils';
import { strings } from '../i18n';
import Map from './Map';
import Scoreboard from './Scoreboard';
import ImageOverlay from './ImageOverlay';

interface PlayerBoardProps {
  gameState: GameState;
  currentPlayer: Player | null;
  currentQ: Question;
  isRoundFinished: boolean;
  isScoreboard: boolean;
  isLastRound: boolean;
  playerMapConfig: { center: Location, zoom: number };
  onGuess: (loc: Location) => void;
  onUnlock: () => void;
}

const PlayerBoard: React.FC<PlayerBoardProps> = ({ 
  gameState, 
  currentPlayer, 
  currentQ, 
  isRoundFinished, 
  isScoreboard, 
  isLastRound,
  playerMapConfig,
  onGuess, 
  onUnlock 
}) => {
  const [selectedGuess, setSelectedGuess] = useState<Location | null>(null);
  const [isFullscreenImage, setIsFullscreenImage] = useState(false);

  // Clear local marker when the round changes
  useEffect(() => {
    setSelectedGuess(null);
  }, [gameState.currentQuestionIndex]);

  const matchingPlayer = gameState.players.find(p => p.id === currentPlayer?.id);
  const hasSubmitted = !!matchingPlayer?.hasGuessed;
  const currentTotalScore = matchingPlayer?.score || 0;

  const markers = isRoundFinished ? [
    { position: currentQ.location, label: strings.game.actualLocation, icon: 'target' as const },
