import { useState, useEffect, useCallback } from 'react';
import { Trail, Question, Location, User } from '../types';
import { generateId } from '../utils';
import { strings } from '../i18n';
import { supabase } from '../lib/supabase';

export const useTrails = (user: User | null) => {
  const [trails, setTrails] = useState<Trail[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const loadTrails = useCallback(async () => {
    if (!user) return;
    setIsLoading(true);
    try {
      const { data: trailsData, error: trailsError } = await supabase
        .from('trails')
        .select(`
          *,
          questions (*)
        `)
        .eq('creator_id', user.id)
        .order('created_at', { ascending: false });

      if (trailsError) throw trailsError;

      const formattedTrails: Trail[] = (trailsData || []).map(t => ({
        id: t.id,
        name: t.name,
        creatorId: t.creator_id,
        lastUpdated: new Date(t.created_at).getTime(),
        startingView: t.starting_view,
        questions: (t.questions || []).sort((a: any, b: any) => a.position_order - b.position_order).map((q: any) => ({
          id: q.id,
          imageUrl: q.image_url,
          location: q.location,
          title: q.title,
          locationSource: q.location_source,
          trailId: q.trail_id
        }))
      }));

      setTrails(formattedTrails);
    } catch (err) {
      console.error("Error loading trails:", err);
    } finally {
      setIsLoading(false);
    }
  }, [user]);

  useEffect(() => {
    loadTrails();
  }, [loadTrails]);

  const saveTrail = async (questions: Question[], name: string, startingView?: { center: Location, zoom: number }, editingId?: string) => {
    if (!user) return null;

    try {
      const trailData = {
        name: name || `Trail ${new Date().toLocaleDateString()}`,
        creator_id: user.id,
        starting_view: startingView,
        updated_at: new Date().toISOString()
      };

      let trailId = editingId;
      if (editingId) {
        const { error } = await supabase.from('trails').update(trailData).eq('id', editingId);
        if (error) throw error;
        // Delete existing questions to rebuild
        await supabase.from('questions').delete().eq('trail_id', editingId);
      } else {
        const { data, error } = await supabase.from('trails').insert([trailData]).select().single();
        if (error) throw error;
        trailId = data.id;
      }

      // Insert new questions
      const questionsData = questions.map((q, idx) => ({
        trail_id: trailId,
        image_url: q.imageUrl,
        location: q.location,
        title: q.title,
        position_order: idx,
        location_source: q.locationSource || 'MANUAL'
      }));

      const { error: qError } = await supabase.from('questions').insert(questionsData);
      if (qError) throw qError;

      await loadTrails();
      return trailId;
    } catch (err) {
      console.error("Error saving trail:", err);
      return null;
    }
  };

  const deleteTrail = async (id: string) => {
    if (!user) return;
    try {
      const { error } = await supabase.from('trails').delete().eq('id', id);
      if (error) throw error;
      setTrails(prev => prev.filter(t => t.id !== id));
    } catch (err) {
      console.error("Error deleting trail:", err);
    }
  };

  return { trails, saveTrail, deleteTrail, reloadTrails: loadTrails, isLoading };
};

import { useEffect, useCallback, useRef } from 'react';
import { GameState, Player, Location } from './types';
import { getLeanState } from './utils';
import { supabase } from './lib/supabase';

export type GameSyncMessage = 
  | { type: 'STATE_FULL'; state: GameState }
  | { type: 'STATE_DYNAMIC'; state: Partial<GameState> }
  | { type: 'REQUEST_SYNC' }
  | { type: 'PLAYER_JOIN_REQUEST'; player: Player }
  | { type: 'PLAYER_GUESS_REQUEST'; playerId: string; guess: Location; distance: number }
  | { type: 'PLAYER_UNLOCK_REQUEST'; playerId: string }
  | { type: 'HOST_REVEAL_REQUEST' }
  | { type: 'FORCE_REVEAL' }
  | { type: 'TERMINATE_SESSION' };

export const useGameSync = (
  onStateUpdate: (state: GameState) => void, 
  onActionRequest: (action: any) => void,
  isHost: boolean, 
  gameState: GameState | null
) => {
  const channelRef = useRef<any>(null);
  const questionsCache = useRef<GameState['questions'] | null>(null);

  const clearCache = useCallback(() => {
    questionsCache.current = null;
  }, []);

  const broadcast = useCallback((state: GameState, full = false) => {
    if (!channelRef.current) return;

    if (full) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_FULL', state }
      });
    } else {
      const lean = getLeanState(state);
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_DYNAMIC', state: lean }
      });
    }
  }, []);

  const sendAction = useCallback((message: GameSyncMessage) => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: message
      });
    }
  }, []);

  const requestSync = useCallback(() => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'REQUEST_SYNC' }
      });
    }
  }, []);

  useEffect(() => {
    if (!gameState?.id) return;

    const channel = supabase.channel(`game_${gameState.id}`, {
      config: {
        broadcast: { self: false }
      }
    });

    channel.on('broadcast', { event: 'sync' }, ({ payload }) => {
      const data = payload as GameSyncMessage;

      if (data.type === 'STATE_FULL') {
        if (!isHost) {
          questionsCache.current = data.state.questions;
          onStateUpdate(data.state);
        }
      } else if (data.type === 'STATE_DYNAMIC') {
        if (!isHost && questionsCache.current) {
          const reconstructedState = { 
            ...data.state, 
            questions: questionsCache.current 
          } as GameState;
          onStateUpdate(reconstructedState);
        }
      } else if (data.type === 'TERMINATE_SESSION') {
        if (!isHost) clearCache();
      } else if (data.type === 'REQUEST_SYNC') {
        if (isHost && gameState) broadcast(gameState, true);
      } else if (data.type === 'PLAYER_JOIN_REQUEST') {
        if (isHost) onActionRequest({ type: 'JOIN_PLAYER', payload: data.player });
      } else if (data.type === 'PLAYER_GUESS_REQUEST') {
        if (isHost) onActionRequest({ type: 'SUBMIT_GUESS', payload: { playerId: data.playerId, guess: data.guess, distance: data.distance } });
      } else if (data.type === 'PLAYER_UNLOCK_REQUEST') {
        if (isHost) onActionRequest({ type: 'UNLOCK_GUESS', payload: data.playerId });
      } else if (data.type === 'HOST_REVEAL_REQUEST') {
        if (isHost) onActionRequest({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
      } else if (data.type === 'FORCE_REVEAL') {
        if (isHost) onActionRequest({ type: 'FORCE_REVEAL' });
      }
    });

    channel.subscribe((status) => {
      if (status === 'SUBSCRIBED') {
        channelRef.current = channel;
        if (!isHost) requestSync();
      }
    });

    return () => {
      channel.unsubscribe();
      channelRef.current = null;
    };
  }, [gameState?.id, isHost, onStateUpdate, onActionRequest, broadcast, clearCache, requestSync]);

  return { broadcast, sendAction, requestSync, clearCache };
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
import CameraView from './CameraView';
import SpotEditor from './SpotEditor';
import StartingViewEditor from './StartingViewEditor';
import SpotList from './SpotList';
import { supabase } from '../lib/supabase';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
}

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    imageUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;
    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = () => {};
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [locationStatus]);

  const uploadImageToStorage = async (dataUrl: string): Promise<string> => {
    const base64 = dataUrl.split(',')[1];
    const byteCharacters = atob(base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: 'image/jpeg' });

    const fileName = `${generateId()}.jpg`;
    const { data, error } = await supabase.storage
      .from('trail-images')
      .upload(fileName, blob);

    if (error) throw error;

    const { data: { publicUrl } } = supabase.storage
      .from('trail-images')
      .getPublicUrl(fileName);

    return publicUrl;
  };

  const handleCapture = async (video: HTMLVideoElement) => {
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth; 
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        const finalUrl = await uploadImageToStorage(compressedUrl);
        const loc = currentLocation || { lat: 0, lng: 0 };
        setPendingQuestion({ 
          imageUrl: finalUrl, 
          location: loc, 
          originalLocation: loc, 
          source: (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT' 
        });
      }
    } catch (err) {
      console.error("Capture failed:", err);
      alert(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
      setIsCapturing(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);
        const finalUrl = await uploadImageToStorage(imageUrl);
        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}
        if (source !== 'IMAGE') source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 0, lng: 0 });
        setPendingQuestion({ imageUrl: finalUrl, location: finalLoc, originalLocation: finalLoc, source });
      } catch (err) {
        console.error("Upload failed:", err);
        alert(strings.creator.uploadError);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = () => {
    if (!pendingQuestion) return;
    const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                    Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
    const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;
    if (pendingQuestion.editingId) {
      setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: pendingQuestion.imageUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
    } else {
      setQuestions(prev => [...prev, { id: generateId(), imageUrl: pendingQuestion.imageUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
    }
    setPendingQuestion(null);
  };

  if (isSettingView) {
    return (
      <StartingViewEditor 
        initialView={startingView} 
        questions={questions} 
        onSave={(view) => { setStartingView(view); setIsSettingView(false); }} 
        onCancel={() => setIsSettingView(false)} 
      />
    );
  }

  if (pendingQuestion) {
    return (
      <SpotEditor 
        pendingQuestion={pendingQuestion} 
        onUpdateLocation={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} 
        onConfirm={confirmPending} 
        onCancel={() => setPendingQuestion(null)} 
      />
    );
  }

  if (isCapturing) {
    return (
      <CameraView 
        onCapture={handleCapture} 
        onClose={() => setIsCapturing(false)} 
        gpsAccuracy={gpsAccuracy} 
        locationStatus={locationStatus} 
        isProcessing={isProcessing} 
        isFlashing={isFlashing} 
      />
    );
  }

  return (
