  ]
}

import { createClient } from '@supabase/supabase-js';

// Priority: Local Storage (for interactive setup) > Environment Variables
const getSupabaseConfig = () => {
  const localUrl = localStorage.getItem('HERE_THERE_SUPABASE_URL');
  const localKey = localStorage.getItem('HERE_THERE_SUPABASE_KEY');

  return {
    url: localUrl || process.env.SUPABASE_URL || '',
    key: localKey || process.env.SUPABASE_ANON_KEY || ''
  };
};

const config = getSupabaseConfig();

export const isSupabaseConfigured = !!(config.url && config.key && config.url.startsWith('https://'));

/**
 * Initialize the Supabase client.
 * If not configured, we use a placeholder to allow the app to boot, 
 * but our hooks will guard against making actual network calls.
 */
export const supabase = createClient(
  isSupabaseConfigured ? config.url : 'https://placeholder.supabase.co',
  isSupabaseConfigured ? config.key : 'placeholder'
);

/**
 * Helper to update configuration at runtime
 */
export const updateSupabaseConfig = (url: string, key: string) => {
  localStorage.setItem('HERE_THERE_SUPABASE_URL', url);
  localStorage.setItem('HERE_THERE_SUPABASE_KEY', key);
  window.location.reload(); // Reload to re-initialize client
};

import React, { useState, useEffect, useReducer, useCallback, useRef } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
