import { useState, useEffect, useCallback } from 'react';

export type PermissionState = 'granted' | 'denied' | 'prompt' | 'unknown';

export const usePermissions = () => {
  const [cameraStatus, setCameraStatus] = useState<PermissionState>('unknown');
  const [locationStatus, setLocationStatus] = useState<PermissionState>('unknown');

  const checkPermissions = useCallback(async () => {
    try {
      if (!('permissions' in navigator)) {
        setLocationStatus('prompt');
        setCameraStatus('prompt');
        return;
      }

      // Check Geolocation
      const geoPermission = await navigator.permissions.query({ name: 'geolocation' as any });
      setLocationStatus(geoPermission.state as PermissionState);
      geoPermission.onchange = () => setLocationStatus(geoPermission.state as PermissionState);

      // Camera permission query (Note: Not all browsers support querying 'camera')
      try {
        const camPermission = await navigator.permissions.query({ name: 'camera' as any });
        setCameraStatus(camPermission.state as PermissionState);
        camPermission.onchange = () => setCameraStatus(camPermission.state as PermissionState);
      } catch (e) {
        // Fallback for browsers that don't support camera permission query
        if (cameraStatus === 'unknown') setCameraStatus('prompt');
      }
    } catch (err) {
      console.warn('Permission query failed:', err);
      setLocationStatus(prev => prev === 'unknown' ? 'prompt' : prev);
      setCameraStatus(prev => prev === 'unknown' ? 'prompt' : prev);
    }
  }, [cameraStatus]);

  const requestPermissions = useCallback(async () => {
    // Attempt camera
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      stream.getTracks().forEach(t => t.stop());
      setCameraStatus('granted');
    } catch (e: any) {
      if (e.name === 'NotAllowedError' || e.name === 'SecurityError') {
        console.warn("Camera access denied by user or environment policy.");
      } else {
        console.error("Camera request error:", e);
      }
      setCameraStatus('denied');
    }

    // Attempt location
    return new Promise<void>((resolve) => {
      if (!navigator.geolocation) {
        setLocationStatus('denied');
        resolve();
        return;
      }

      navigator.geolocation.getCurrentPosition(
        () => {
          setLocationStatus('granted');
          resolve();
        },
        (err) => {
          console.warn("Location access denied or failed:", err.message);
          setLocationStatus('denied');
          resolve();
        },
        { enableHighAccuracy: true, timeout: 5000 }
      );
    }).then(() => {
      checkPermissions();
    });
  }, [checkPermissions]);

  useEffect(() => {
    checkPermissions();
  }, [checkPermissions]);

  return { cameraStatus, locationStatus, checkPermissions, requestPermissions };
};

import { useState, useEffect, useCallback } from 'react';
import { Trail, Question, Location, User } from '../types';
import { generateId } from '../utils';
import { strings } from '../i18n';
import { supabase, isSupabaseConfigured } from '../lib/supabase';

export const useTrails = (user: User | null) => {
  const [trails, setTrails] = useState<Trail[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const loadTrails = useCallback(async () => {
    if (!user || !isSupabaseConfigured) return;
    setIsLoading(true);
    try {
      const { data: trailsData, error: trailsError } = await supabase
        .from('trails')
        .select(`
          *,
          questions (*)
        `)
        .eq('creator_id', user.id)
        .order('created_at', { ascending: false });

      if (trailsError) throw trailsError;

      const formattedTrails: Trail[] = (trailsData || []).map(t => ({
        id: t.id,
        name: t.name,
        creatorId: t.creator_id,
        lastUpdated: new Date(t.created_at).getTime(),
        startingView: t.starting_view,
        questions: (t.questions || []).sort((a: any, b: any) => a.position_order - b.position_order).map((q: any) => ({
          id: q.id,
          imageUrl: q.image_url,
          location: q.location,
          title: q.title,
          locationSource: q.location_source,
          trailId: q.trail_id
        }))
      }));

      setTrails(formattedTrails);
    } catch (err) {
      console.error("Error loading trails:", err);
    } finally {
      setIsLoading(false);
    }
  }, [user]);

  useEffect(() => {
    loadTrails();
  }, [loadTrails]);

  const saveTrail = async (questions: Question[], name: string, startingView?: { center: Location, zoom: number }, editingId?: string) => {
    if (!user || !isSupabaseConfigured) return null;

    try {
      const trailData = {
        name: name || `Trail ${new Date().toLocaleDateString()}`,
        creator_id: user.id,
        starting_view: startingView,
        updated_at: new Date().toISOString()
      };

      let trailId = editingId;
      if (editingId) {
        const { error } = await supabase.from('trails').update(trailData).eq('id', editingId);
        if (error) throw error;
        // Delete existing questions to rebuild
        await supabase.from('questions').delete().eq('trail_id', editingId);
      } else {
        const { data, error } = await supabase.from('trails').insert([trailData]).select().single();
        if (error) throw error;
        trailId = data.id;
      }

      // Insert new questions
      const questionsData = questions.map((q, idx) => ({
        trail_id: trailId,
        image_url: q.imageUrl,
        location: q.location,
        title: q.title,
        position_order: idx,
        location_source: q.locationSource || 'MANUAL'
      }));

      const { error: qError } = await supabase.from('questions').insert(questionsData);
      if (qError) throw qError;

      await loadTrails();
      return trailId;
    } catch (err) {
      console.error("Error saving trail:", err);
      return null;
    }
  };

  const deleteTrail = async (id: string) => {
    if (!user || !isSupabaseConfigured) return;
    try {
      // 1. Get all image URLs for this trail before deleting the database records
      const { data: questions } = await supabase
        .from('questions')
        .select('image_url')
        .eq('trail_id', id);

      if (questions && questions.length > 0) {
        const fileNames = questions
          .map(q => q.image_url.split('/').pop())
          .filter(Boolean) as string[];

        if (fileNames.length > 0) {
          // Remove from Supabase Storage
          await supabase.storage.from('trail-images').remove(fileNames);
        }
      }

      // 2. Delete trail from database (cascade handles questions if setup, else handled by manual delete policy)
      const { error } = await supabase.from('trails').delete().eq('id', id);
      if (error) throw error;

      setTrails(prev => prev.filter(t => t.id !== id));
    } catch (err) {
      console.error("Error deleting trail:", err);
    }
  };

  return { trails, saveTrail, deleteTrail, reloadTrails: loadTrails, isLoading };
};

