import React, { useState, useEffect, useReducer, useCallback, useRef } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import { gameReducer } from './gameReducer';
import { useGameSync } from './useGameSync';
import { useTrails } from './hooks/useTrails';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import Home from './components/Home';
import JoinGame from './components/JoinGame';
import { PermissionModal } from './components/PermissionGate';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [showPermissionModal, setShowPermissionModal] = useState(false);
  const [joinError, setJoinError] = useState<string | null>(null);
  const [isJoining, setIsJoining] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const joinTimeoutRef = useRef<number | null>(null);

  const prevStatusRef = useRef<GameState['status'] | null>(null);
  const prevIndexRef = useRef<number>(-1);

  const { trails, saveTrail, deleteTrail, isLoading: isTrailsLoading } = useTrails(user);
  const [gameState, dispatch] = useReducer(gameReducer, null);

  const { broadcast, sendAction, requestSync, clearCache } = useGameSync(
    useCallback((state) => dispatch({ type: 'SYNC_STATE', payload: state }), []),
    useCallback((action) => dispatch(action), []),
    isHost,
    gameState
  );

  useEffect(() => {
    if (isHost && gameState) {
      localStorage.setItem('locateit_active_host_state', JSON.stringify(gameState));
      const isStatusChange = gameState.status !== prevStatusRef.current;
      const isIndexChange = gameState.currentQuestionIndex !== prevIndexRef.current;
      const isNewGame = prevStatusRef.current === null;
      const needsFullSync = isStatusChange || isIndexChange || isNewGame;
      broadcast(gameState, needsFullSync);
      prevStatusRef.current = gameState.status;
      prevIndexRef.current = gameState.currentQuestionIndex;
    }
  }, [gameState, isHost, broadcast]);

  useEffect(() => {
    if (view === 'JOIN' && !gameState) {
      requestSync();
      const interval = setInterval(requestSync, 2000);
      return () => clearInterval(interval);
    }
  }, [view, gameState, requestSync]);

  useEffect(() => {
    if (gameState && (isHost || currentPlayer)) {
      const inGameStatus = ['PLAYING', 'COUNTDOWN', 'RESULTS', 'SCOREBOARD', 'FINISHED'];
      if (inGameStatus.includes(gameState.status) && view !== 'PLAYING') {
        setView('PLAYING');
      }
      if (currentPlayer && !isHost && !isJoining) {
        const isPresent = gameState.players.some(p => p.id === currentPlayer.id);
        if (!isPresent && (view === 'LOBBY' || view === 'PLAYING')) {
           alert(strings.lobby.kickedDesc);
           handleExitGame();
        }
      }
    }
  }, [gameState, currentPlayer, isHost, view, isJoining]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) setUser(JSON.parse(savedUser));
  }, []);

  const handleCompleteTrail = async (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => {
    if (isSaving) return;
    setIsSaving(true);
    try {
      const successId = await saveTrail(questions, name, startingView, editingTrail?.id);
      if (successId) {
        setEditingTrail(null);
        setView('DASHBOARD');
      } else {
        alert("Expedition log failed to save. Please ensure you are connected to the network and try again.");
      }
    } catch (e) {
      console.error("Save failed in App.tsx:", e);
      alert("An unexpected error occurred while saving. Please try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); 
    const newGameId = generateId();
    dispatch({ type: 'INIT_LOBBY', payload: { id: newGameId, questions: trail.questions, hostId: user.id, startingView: trail.startingView } });
    setView('LOBBY');
  };

  const handleResumeHost = () => {
    const saved = localStorage.getItem('locateit_active_host_state');
    if (saved) {
      const state = JSON.parse(saved) as GameState;
      setIsHost(true);
      setCurrentPlayer(null);
      dispatch({ type: 'SYNC_STATE', payload: state });
      setView(state.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
    }
  };

  const handleJoinGame = (gameCode: string, name: string, color: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();
    if (!gameState || gameState.id !== code) {
      setJoinError(`Expedition ${code} not found. Ensure the code is correct.`);
      requestSync();
      return;
    }
    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);
    if (existingById) {
      setCurrentPlayer(existingById);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }
    const existingByName = gameState.players.find(p => p.name.toLowerCase() === name.toLowerCase());
    if (existingByName) {
      setCurrentPlayer(existingByName);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', existingByName.id);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }
    const newPlayer: Player = { id: generateId(), name, color, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    setIsJoining(true);
    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 5000);
    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  const handleExitGame = () => {
    if (isHost) {
      localStorage.removeItem('locateit_active_host_state');
      sendAction({ type: 'TERMINATE_SESSION' });
    }
    clearCache();
    dispatch({ type: 'EXIT_GAME' });
    setCurrentPlayer(null);
    setView(isHost ? 'DASHBOARD' : 'HOME');
  };

  return (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
      {view === 'HOME' && <Home onJoin={() => setView('JOIN')} onDesign={() => user ? setView('DASHBOARD') : setView('AUTH')} />}
      {view === 'JOIN' && <JoinGame onBack={() => setView('HOME')} onJoin={handleJoinGame} isSearching={!gameState} error={joinError} />}
      {view === 'AUTH' && <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />}
      {view === 'DASHBOARD' && user && (
        <Dashboard 
          user={user} 
          trails={trails}
          isLoading={isTrailsLoading}
          onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} 
          onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} 
          onHostTrail={handleHostTrail} 
          onDeleteTrail={deleteTrail}
          onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }}
          onResumeHost={localStorage.getItem('locateit_active_host_state') ? handleResumeHost : undefined}
        />
      )}
      {view === 'CREATE' && (
        <QuizCreator 
          initialTrail={editingTrail || undefined} 
          onComplete={handleCompleteTrail} 
          onCancel={() => setView('DASHBOARD')} 
          onRequestPermissions={() => setShowPermissionModal(true)}
          isSaving={isSaving}
        />
      )}
      {view === 'LOBBY' && gameState && (
        <Lobby 
          gameState={gameState} 
          isHost={isHost} 
          onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} 
          currentPlayer={currentPlayer} 
          onBack={handleExitGame} 
          onKick={(id) => dispatch({ type: 'KICK_PLAYER', payload: id })} 
        />
      )}
      {view === 'PLAYING' && gameState && (
        <GameBoard 
          gameState={gameState} 
          isHost={isHost} 
          currentPlayer={currentPlayer} 
          onGuess={(guess) => {
            if (!currentPlayer) return;
            const currentQ = gameState.questions[gameState.currentQuestionIndex];
            const dist = calculateDistance(guess, currentQ.location);
            sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
            if (isHost) dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
          }} 
          onUnlock={() => {
            if (!currentPlayer) return;
            sendAction({ type: 'PLAYER_UNLOCK_REQUEST', playerId: currentPlayer.id });
            if (isHost) dispatch({ type: 'UNLOCK_GUESS', payload: currentPlayer.id });
          }}
          onReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
            sendAction({ type: 'HOST_REVEAL_REQUEST' });
          }}
          onForceReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'FORCE_REVEAL' });
            sendAction({ type: 'FORCE_REVEAL' });
          }}
          onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
          onShowScoreboard={() => isHost && dispatch({ type: 'CALCULATE_SCORES' })}
          onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
          onExit={handleExitGame}
        />
      )}
    </>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { Location } from '../types';
import { useMapLayers } from '../hooks/useMapLayers';

interface MapProps {
  onLocationSelect?: (loc: Location) => void;
  onViewChange?: (view: { center: Location, zoom: number }) => void;
  markers?: { position: Location; label?: string; icon?: 'default' | 'target' | 'user'; color?: string }[];
  center?: Location;
  zoom?: number;
  lines?: { from: Location; to: Location; color?: string }[];
  roundIndex?: number;
}

const isValid = (loc?: Location): boolean => {
  return !!loc && typeof loc.lat === 'number' && typeof loc.lng === 'number' && !isNaN(loc.lat) && !isNaN(loc.lng);
};

const Map: React.FC<MapProps> = ({ 
  onLocationSelect, 
  onViewChange,
  markers = [], 
  center, 
  zoom = 13, 
  lines = [],
  roundIndex = 0
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const [map, setMap] = useState<L.Map | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current || map) return;

    const startPos: [number, number] = isValid(center) ? [center!.lat, center!.lng] : [59.3293, 18.0686];

    const instance = L.map(mapContainerRef.current, {
      zoomControl: false,
      attributionControl: false,
      scrollWheelZoom: true,
      fadeAnimation: false,
      markerZoomAnimation: true
    }).setView(startPos, zoom);

    L.control.zoom({ position: 'bottomright' }).addTo(instance);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
    }).addTo(instance);

    instance.on('click', (e) => {
      if (onLocationSelect) {
        onLocationSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
      }
    });

    instance.on('moveend', () => {
      if (onViewChange) {
        const c = instance.getCenter();
        onViewChange({ center: { lat: c.lat, lng: c.lng }, zoom: instance.getZoom() });
      }
    });

    setMap(instance);

    const resizeObserver = new ResizeObserver(() => {
      instance.invalidateSize();
    });
    resizeObserver.observe(mapContainerRef.current);

    // CRITICAL: Fix for marker offset. Leaflet needs a re-calc once the container is fully rendered.
    const timer = setTimeout(() => {
      instance.invalidateSize();
    }, 200);

    return () => {
      clearTimeout(timer);
      resizeObserver.disconnect();
      instance.off();
      instance.remove();
      setMap(null);
    };
  }, []);

  useEffect(() => {
    if (map && isValid(center)) {
      map.setView([center!.lat, center!.lng], zoom);
      // Re-invalidate size when center changes, helps with view transitions
      setTimeout(() => map.invalidateSize(), 100);
    }
  }, [map, center, zoom, roundIndex]);

  useMapLayers(map, markers, lines, onLocationSelect);

  return (
    <div className="w-full h-full relative group bg-white">
      <div ref={mapContainerRef} className="w-full h-full" />
      <style>{`
        .nordic-tooltip {
          background: #ffffff;
          border: 1px solid rgba(45, 66, 57, 0.1);
          border-radius: 12px;
          padding: 6px 12px;
          font-family: 'Space Grotesk', sans-serif;
          font-weight: 700;
          font-size: 10px;
          text-transform: uppercase;
          letter-spacing: 0.1em;
          box-shadow: 0 10px 20px -5px rgba(15, 26, 22, 0.1);
          color: #0f1a16;
        }
        .nordic-tooltip:before {
          border-top-color: #ffffff;
        }
        .leaflet-bottom.leaflet-right {
          bottom: 24px !important;
          right: 24px !important;
          z-index: 1000 !important;
        }
        .leaflet-bar {
          border: none !important;
          box-shadow: 0 10px 20px -5px rgba(15, 26, 22, 0.2) !important;
        }
        .leaflet-bar a {
          background-color: #ffffff !important;
          color: #0f1a16 !important;
          border: 1px solid rgba(15, 26, 22, 0.05) !important;
          border-radius: 12px !important;
          margin-bottom: 8px !important;
          width: 44px !important;
          height: 44px !important;
          line-height: 44px !important;
          font-weight: bold !important;
          font-size: 18px !important;
        }
        .leaflet-bar a:hover {
          background-color: #f9fbfa !important;
        }
      `}</style>
    </div>
  );
};

export default Map;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
import CameraView from './CameraView';
import SpotEditor from './SpotEditor';
import StartingViewEditor from './StartingViewEditor';
import SpotList from './SpotList';
import { supabase } from '../lib/supabase';
// @ts-ignore
import ExifReader from 'exifreader';

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
  isSaving?: boolean;
}

const LoadingOverlay: React.FC<{ message: string }> = ({ message }) => (
  <div className="fixed inset-0 z-[1000] bg-white/80 backdrop-blur-xl flex flex-col items-center justify-center animate-in fade-in duration-300">
    <div className="w-16 h-16 border-4 border-[#2d4239] border-t-transparent rounded-full animate-spin mb-6"></div>
    <p className="font-black uppercase tracking-[0.3em] text-[#2d4239] text-xs text-center px-6">{message}</p>
  </div>
);

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail, isSaving }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingMessage, setProcessingMessage] = useState('');
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);

  // pendingQuestion now stores a localDataUrl to avoid flash and speed up UI
  const [pendingQuestion, setPendingQuestion] = useState<{ 
    localDataUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;
    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = () => {};
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [locationStatus]);

  const uploadImageToStorage = async (dataUrl: string): Promise<string> => {
    const base64 = dataUrl.split(',')[1];
    const byteCharacters = atob(base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: 'image/jpeg' });

    const fileName = `${generateId()}.jpg`;
    const { error } = await supabase.storage
      .from('trail-images')
      .upload(fileName, blob);

    if (error) throw error;

    const { data: { publicUrl } } = supabase.storage
      .from('trail-images')
      .getPublicUrl(fileName);

    return publicUrl;
  };

  const deleteImageFromStorage = async (url: string) => {
    try {
      if (url.startsWith('data:')) return; // Don't try to delete local previews
      const fileName = url.split('/').pop();
      if (fileName) {
        await supabase.storage.from('trail-images').remove([fileName]);
      }
    } catch (err) {
      console.error("Failed to cleanup image:", err);
    }
  };

  const handleCapture = async (video: HTMLVideoElement) => {
    // We stay in the camera view while processing locally
    setProcessingMessage(strings.creator.processing);
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth; 
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        // We set local data URL here - upload happens later
        const loc = currentLocation || { lat: 0, lng: 0 };
        setPendingQuestion({ 
          localDataUrl: compressedUrl, 
          location: loc, 
          originalLocation: loc, 
          source: (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT' 
        });
        setIsCapturing(false); 
      }
    } catch (err) {
      console.error("Capture failed:", err);
      alert(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setProcessingMessage(strings.creator.processing);
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);

        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}
        if (source !== 'IMAGE') source = (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT';
        const finalLoc = (lat !== null && lng !== null) ? { lat, lng } : (currentLocation || { lat: 0, lng: 0 });

        setPendingQuestion({ localDataUrl: imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      } catch (err) {
        console.error("Upload failed:", err);
        alert(strings.creator.uploadError);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = async () => {
    if (!pendingQuestion) return;

    setProcessingMessage("Finalizing spot data...");
    setIsProcessing(true);

    try {
      // NOW we upload the image
      const finalUrl = await uploadImageToStorage(pendingQuestion.localDataUrl);

      const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                      Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
      const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

      if (pendingQuestion.editingId) {
        setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: finalUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
      } else {
        setQuestions(prev => [...prev, { id: generateId(), imageUrl: finalUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
      }
      setPendingQuestion(null);
    } catch (err) {
      console.error("Failed to confirm spot:", err);
      alert("Could not save the photo to the cloud. Please check your connection.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDeleteSpot = async () => {
    if (confirmDeleteId) {
      const q = questions.find(question => question.id === confirmDeleteId);
      if (q) {
        await deleteImageFromStorage(q.imageUrl);
      }
      setQuestions(prev => prev.filter(q => q.id !== confirmDeleteId));
      setConfirmDeleteId(null);
    }
  };

  if (isSettingView) {
    return (
      <StartingViewEditor 
        initialView={startingView} 
        questions={questions} 
        onSave={(view) => { setStartingView(view); setIsSettingView(false); }} 
        onCancel={() => setIsSettingView(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      {(isProcessing || isSaving) && <LoadingOverlay message={isSaving ? "Publishing your trail..." : processingMessage} />}

      {pendingQuestion ? (
        <SpotEditor 
          pendingQuestion={{
            imageUrl: pendingQuestion.localDataUrl,
            location: pendingQuestion.location,
            editingId: pendingQuestion.editingId
          }} 
          onUpdateLocation={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} 
          onConfirm={confirmPending} 
          onCancel={() => setPendingQuestion(null)} 
        />
      ) : isCapturing ? (
        <CameraView 
          onCapture={handleCapture} 
          onClose={() => setIsCapturing(false)} 
          gpsAccuracy={gpsAccuracy} 
          locationStatus={locationStatus} 
          isProcessing={isProcessing} 
          isFlashing={isFlashing} 
        />
      ) : (
        <>
          <PermissionBanner onCheck={onRequestPermissions} />
          <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
            <div className="max-w-4xl mx-auto flex justify-between items-start">
              <div className="flex-1 mr-4">
                <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
                <div className="flex items-center space-x-4 mt-2">
                   <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em]">{strings.creator.spotsInTrail(questions.length)}</p>
                   <div className="w-1 h-1 rounded-full bg-[#0f1a16]/10" />
                   <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
                </div>
              </div>
              <button onClick={() => hasChanges ? setShowExitConfirm(true) : onCancel()} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm text-[#0f1a16]">{strings.common.cancel}</button>
