export default QuizCreator;

import { useState, useEffect, useCallback } from 'react';
import { Trail, Question, Location, User } from '../types';
import { supabase, isSupabaseConfigured } from '../lib/supabase';

export const useTrails = (user: User | null) => {
  const [trails, setTrails] = useState<Trail[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  const loadTrails = useCallback(async () => {
    if (!user || !isSupabaseConfigured) return;

    setIsLoading(true);
    try {
      const { data: trailsData, error: trailsError } = await supabase
        .from('trails')
        .select(`
          *,
          questions (*)
        `)
        .eq('creator_id', user.id)
        .order('created_at', { ascending: false });

      if (trailsError) throw trailsError;

      const formattedTrails: Trail[] = (trailsData || []).map(t => ({
        id: t.id,
        name: t.name,
        creatorId: t.creator_id,
        lastUpdated: new Date(t.created_at || Date.now()).getTime(),
        startingView: t.starting_view,
        questions: (t.questions || []).sort((a: any, b: any) => (a.position_order || 0) - (b.position_order || 0)).map((q: any) => ({
          id: q.id,
          imageUrl: q.image_url,
          location: q.location,
          title: q.title,
          locationSource: q.location_source,
          trailId: q.trail_id
        }))
      }));

      setTrails(formattedTrails);
    } catch (err) {
      console.error("Error loading trails:", err);
    } finally {
      setIsLoading(false);
    }
  }, [user]);

  useEffect(() => {
    if (user) {
      loadTrails();
    }
  }, [loadTrails, user]);

  const saveTrail = async (questions: Question[], name: string, startingView?: { center: Location, zoom: number }, editingId?: string): Promise<{ success: boolean; id?: string; error?: string }> => {
    if (!isSupabaseConfigured) return { success: false, error: "Supabase not configured" };

    try {
      console.log("Starting save sequence...", { questionsCount: questions.length, name });

      const { data: { session } } = await supabase.auth.getSession();
      if (!session) return { success: false, error: "No active session. Please re-login." };

      const sessionUserId = session.user.id;
      console.log("Authenticated User ID:", sessionUserId);

      const trailData = {
        name: name || `Trail ${new Date().toLocaleDateString()}`,
        creator_id: sessionUserId,
        starting_view: startingView || null,
        updated_at: new Date().toISOString()
      };

      let trailId = editingId;
      if (editingId) {
        console.log("Updating existing trail:", editingId);
        const { error: updateError } = await supabase.from('trails').update(trailData).eq('id', editingId);
        if (updateError) return { success: false, error: `Trail Update Error: ${updateError.message}` };

        console.log("Cleaning old questions for trail...");
        const { error: deleteError } = await supabase.from('questions').delete().eq('trail_id', editingId);
        if (deleteError) return { success: false, error: `Question Cleanup Error: ${deleteError.message}` };
      } else {
        console.log("Inserting new trail record...");
        const { data: insertedData, error: insertError } = await supabase
          .from('trails')
          .insert([trailData])
          .select('id');

        if (insertError) {
          console.error("Insert Error Object:", insertError);
          return { success: false, error: `Trail Insert Error: ${insertError.message}` };
        }
        if (!insertedData || insertedData.length === 0) {
          return { success: false, error: "Insert succeeded but no record ID returned. Check RLS Policies." };
        }

        trailId = insertedData[0].id;
        console.log("Trail Record Created:", trailId);
      }

      if (!trailId) return { success: false, error: "Failed to resolve trail ID." };

      const questionsData = questions.map((q, idx) => ({
        trail_id: trailId,
        image_url: q.imageUrl,
        location: {
          lat: Number(q.location.lat),
          lng: Number(q.location.lng)
        },
        title: q.title || `Spot ${idx + 1}`,
        position_order: idx,
        location_source: q.locationSource || 'MANUAL'
      }));

      console.log("Inserting questions...", questionsData.length);
      const { error: qError } = await supabase.from('questions').insert(questionsData);
      if (qError) {
        console.error("Questions Insert Error Object:", qError);
        return { success: false, error: `Questions Insert Error: ${qError.message}` };
      }

      console.log("Save successful. Reloading trails...");
      await loadTrails();
      return { success: true, id: trailId };
    } catch (err: any) {
      console.error("CRITICAL EXCEPTION IN SAVETRAIL:", err);
      return { success: false, error: err.message || "An unexpected error occurred" };
    }
  };

  const deleteTrail = async (id: string) => {
    if (!user || !isSupabaseConfigured) return;
    try {
      const { data: questionsData } = await supabase
        .from('questions')
        .select('image_url')
        .eq('trail_id', id);

      if (questionsData && questionsData.length > 0) {
        const fileNames = questionsData
          .map(q => q.image_url.split('/').pop())
          .filter(Boolean) as string[];

        if (fileNames.length > 0) {
          await supabase.storage.from('trail-images').remove(fileNames);
        }
      }

      const { error } = await supabase.from('trails').delete().eq('id', id);
      if (error) throw error;

      setTrails(prev => prev.filter(t => t.id !== id));
    } catch (err) {
      console.error("Error deleting trail:", err);
    }
  };

  return { trails, saveTrail, deleteTrail, reloadTrails: loadTrails, isLoading };
};

