      if (qError) {
        console.error("Questions Insert Failure:", qError);
        return { success: false, error: `Questions Table Error: ${qError.message}` };
      }

      console.log("Trail saved successfully!");
      await loadTrails();
      return { success: true, id: trailId };
    } catch (err: any) {
      console.error("CRITICAL APP ERROR:", err);
      return { success: false, error: err.message || "An unexpected error occurred" };
    }
  };

  const deleteTrail = async (id: string) => {
    if (!user || !isSupabaseConfigured) return;
    try {
      const { data: questionsData } = await supabase
        .from('questions')
        .select('image_url')
        .eq('trail_id', id);

      if (questionsData && questionsData.length > 0) {
        const fileNames = questionsData
          .map(q => q.image_url.split('/').pop())
          .filter(Boolean) as string[];

        if (fileNames.length > 0) {
          await supabase.storage.from('trail-images').remove(fileNames);
        }
      }

      await supabase.from('trails').delete().eq('id', id);
      setTrails(prev => prev.filter(t => t.id !== id));
    } catch (err) {
      console.error("Error deleting trail:", err);
    }
  };

  return { trails, saveTrail, deleteTrail, reloadTrails: loadTrails, isLoading };
};

import React, { useEffect, useRef, useState } from 'react';
import L from 'leaflet';
import { Location } from '../types';
import { useMapLayers } from '../hooks/useMapLayers';

interface MapProps {
  onLocationSelect?: (loc: Location) => void;
  onViewChange?: (view: { center: Location, zoom: number }) => void;
  markers?: { position: Location; label?: string; icon?: 'default' | 'target' | 'user'; color?: string }[];
  center?: Location;
  zoom?: number;
  lines?: { from: Location; to: Location; color?: string }[];
  roundIndex?: number;
}

const isValid = (loc?: Location): boolean => {
  return !!loc && typeof loc.lat === 'number' && typeof loc.lng === 'number' && !isNaN(loc.lat) && !isNaN(loc.lng);
};

const Map: React.FC<MapProps> = ({ 
  onLocationSelect, 
  onViewChange,
  markers = [], 
  center, 
  zoom = 13, 
  lines = [],
  roundIndex = 0
}) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const [map, setMap] = useState<L.Map | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current || map) return;

    const startPos: [number, number] = isValid(center) ? [center!.lat, center!.lng] : [59.3293, 18.0686];

    const instance = L.map(mapContainerRef.current, {
      zoomControl: false,
      attributionControl: false,
      scrollWheelZoom: true,
      fadeAnimation: false,
      markerZoomAnimation: true,
      tap: false,
      trackResize: true
    }).setView(startPos, zoom);

    L.control.zoom({ position: 'bottomright' }).addTo(instance);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
    }).addTo(instance);

    instance.on('click', (e) => {
      // Force refresh on every click as a safety measure for mobile browsers
      instance.invalidateSize();
      if (onLocationSelect) {
        onLocationSelect({ lat: e.latlng.lat, lng: e.latlng.lng });
      }
    });

    instance.on('moveend', () => {
      if (onViewChange) {
        const c = instance.getCenter();
        onViewChange({ center: { lat: c.lat, lng: c.lng }, zoom: instance.getZoom() });
      }
    });

    // Use ResizeObserver to ensure map is valid whenever container changes size
    // This is the most reliable way to fix "first marker offset" in flexible layouts
    const resizeObserver = new ResizeObserver(() => {
      instance.invalidateSize();
    });
    resizeObserver.observe(mapContainerRef.current);

    setMap(instance);

    // Explicitly pulse invalidateSize to handle any entering transitions
    const pulses = [50, 250, 500, 1000];
    pulses.forEach(delay => {
      setTimeout(() => instance.invalidateSize(), delay);
    });

    return () => {
      resizeObserver.disconnect();
      instance.off();
      instance.remove();
      setMap(null);
    };
  }, []);

  useEffect(() => {
    if (map && isValid(center)) {
      map.setView([center!.lat, center!.lng], zoom);
      setTimeout(() => map.invalidateSize(), 50);
    }
  }, [map, center, zoom, roundIndex]);

  useMapLayers(map, markers, lines, onLocationSelect);

  return (
    <div className="w-full h-full relative group bg-white">
      <div ref={mapContainerRef} className="w-full h-full" />
      <style>{`
        .nordic-tooltip {
          background: #ffffff;
          border: 1px solid rgba(45, 66, 57, 0.1);
          border-radius: 12px;
          padding: 6px 12px;
          font-family: 'Space Grotesk', sans-serif;
          font-weight: 700;
          font-size: 10px;
          text-transform: uppercase;
          letter-spacing: 0.1em;
          box-shadow: 0 10px 20px -5px rgba(15, 26, 22, 0.1);
          color: #0f1a16;
        }
        .nordic-tooltip:before {
          border-top-color: #ffffff;
        }
        .leaflet-bottom.leaflet-right {
          bottom: 24px !important;
          right: 24px !important;
          z-index: 1000 !important;
        }
        .leaflet-bar {
          border: none !important;
          box-shadow: 0 10px 20px -5px rgba(15, 26, 22, 0.2) !important;
        }
        .leaflet-bar a {
          background-color: #ffffff !important;
          color: #0f1a16 !important;
          border: 1px solid rgba(15, 26, 22, 0.05) !important;
          border-radius: 12px !important;
          margin-bottom: 8px !important;
          width: 44px !important;
          height: 44px !important;
          line-height: 44px !important;
          font-weight: bold !important;
          font-size: 18px !important;
        }
        .leaflet-bar a:hover {
          background-color: #f9fbfa !important;
        }
      `}</style>
    </div>
  );
};

export default Map;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
import CameraView from './CameraView';
import SpotEditor from './SpotEditor';
import StartingViewEditor from './StartingViewEditor';
import SpotList from './SpotList';
import { supabase } from '../lib/supabase';
// @ts-ignore
import ExifReader from 'exifreader';

const STOCKHOLM: Location = { lat: 59.3293, lng: 18.0686 };

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
  isSaving?: boolean;
}

const LoadingOverlay: React.FC<{ message: string }> = ({ message }) => (
  <div className="fixed inset-0 z-[1000] bg-white/80 backdrop-blur-xl flex flex-col items-center justify-center animate-in fade-in duration-300">
    <div className="w-16 h-16 border-4 border-[#2d4239] border-t-transparent rounded-full animate-spin mb-6"></div>
    <p className="font-black uppercase tracking-[0.3em] text-[#2d4239] text-xs text-center px-6">{message}</p>
  </div>
);

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail, isSaving }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingMessage, setProcessingMessage] = useState('');
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    localDataUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;
    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = () => {};
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [locationStatus]);

  const uploadImageToStorage = async (dataUrl: string): Promise<string> => {
    const base64 = dataUrl.split(',')[1];
    const byteCharacters = atob(base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: 'image/jpeg' });

    const fileName = `${generateId()}.jpg`;
    const { error } = await supabase.storage
      .from('trail-images')
      .upload(fileName, blob);

    if (error) throw error;

    const { data: { publicUrl } } = supabase.storage
      .from('trail-images')
      .getPublicUrl(fileName);

    return publicUrl;
  };

  const deleteImageFromStorage = async (url: string) => {
    try {
      if (url.startsWith('data:')) return;
      const fileName = url.split('/').pop();
      if (fileName) {
        await supabase.storage.from('trail-images').remove([fileName]);
      }
    } catch (err) {
      console.error("Failed to cleanup image:", err);
    }
  };

  const handleCapture = async (video: HTMLVideoElement) => {
    setProcessingMessage(strings.creator.processing);
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth; 
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);
        // Prioritize Live GPS, fallback to Stockholm
        const loc = currentLocation || STOCKHOLM;
        setPendingQuestion({ 
          localDataUrl: compressedUrl, 
          location: loc, 
          originalLocation: loc, 
          source: (currentLocation && locationStatus === 'granted') ? 'GPS' : 'DEFAULT' 
        });
        setIsCapturing(false); 
      }
    } catch (err) {
      console.error("Capture failed:", err);
      alert(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setProcessingMessage(strings.creator.processing);
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);

        let lat: number | null = null, lng: number | null = null, source: any = 'GPS';
        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            lat = parseFloat(tags.GPSLatitude.description);
            lng = parseFloat(tags.GPSLongitude.description);
            if (!isNaN(lat) && !isNaN(lng)) source = 'IMAGE';
          }
        } catch (exifErr) {}

        // Final coordinate resolution
        let finalLoc = STOCKHOLM;

        if (lat !== null && lng !== null) {
          finalLoc = { lat, lng };
          source = 'IMAGE';
        } else {
          // Attempt to get fresh location if watchPosition hasn't fired yet
          if (locationStatus === 'granted') {
             try {
                const pos = await new Promise<GeolocationPosition>((resolve, reject) => {
                   navigator.geolocation.getCurrentPosition(resolve, reject, { 
                      enableHighAccuracy: true, 
                      timeout: 5000 
                   });
                });
                finalLoc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
                source = 'GPS';
             } catch (geoErr) {
                // If fresh check fails, use last known current location or Stockholm
                finalLoc = currentLocation || STOCKHOLM;
                source = currentLocation ? 'GPS' : 'DEFAULT';
             }
          } else {
             finalLoc = STOCKHOLM;
             source = 'DEFAULT';
          }
        }

        setPendingQuestion({ localDataUrl: imageUrl, location: finalLoc, originalLocation: finalLoc, source });
      } catch (err) {
        console.error("Upload failed:", err);
        alert(strings.creator.uploadError);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = async () => {
    if (!pendingQuestion) return;
    setProcessingMessage("Finalizing spot data...");
    setIsProcessing(true);
    try {
      const finalUrl = await uploadImageToStorage(pendingQuestion.localDataUrl);
      const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                      Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
      const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

      if (pendingQuestion.editingId) {
        setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: finalUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
      } else {
        setQuestions(prev => [...prev, { id: generateId(), imageUrl: finalUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
      }
      setPendingQuestion(null);
    } catch (err) {
      console.error("Failed to confirm spot:", err);
      alert("Could not save photo. Cloud sync failed.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDeleteSpot = async () => {
    if (confirmDeleteId) {
      const q = questions.find(question => question.id === confirmDeleteId);
      if (q) await deleteImageFromStorage(q.imageUrl);
      setQuestions(prev => prev.filter(q => q.id !== confirmDeleteId));
      setConfirmDeleteId(null);
    }
  };

  if (isSettingView) {
    return (
      <StartingViewEditor 
        initialView={startingView} 
        questions={questions} 
        onSave={(view) => { setStartingView(view); setIsSettingView(false); }} 
        onCancel={() => setIsSettingView(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      {(isProcessing || isSaving) && <LoadingOverlay message={isSaving ? "Publishing your trail..." : processingMessage} />}

      {pendingQuestion ? (
        <SpotEditor 
          pendingQuestion={{
            imageUrl: pendingQuestion.localDataUrl,
            location: pendingQuestion.location,
            editingId: pendingQuestion.editingId
          }} 
          onUpdateLocation={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} 
          onConfirm={confirmPending} 
          onCancel={() => setPendingQuestion(null)} 
        />
      ) : isCapturing ? (
        <CameraView 
          onCapture={handleCapture} 
          onClose={() => setIsCapturing(false)} 
          gpsAccuracy={gpsAccuracy} 
          locationStatus={locationStatus} 
          isProcessing={isProcessing} 
          isFlashing={isFlashing} 
        />
      ) : (
        <>
          <PermissionBanner onCheck={onRequestPermissions} />
          <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
            <div className="max-w-4xl mx-auto flex justify-between items-start">
              <div className="flex-1 mr-4">
                <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
                <div className="flex items-center space-x-4 mt-2">
                   <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em]">{strings.creator.spotsInTrail(questions.length)}</p>
                   <div className="w-1 h-1 rounded-full bg-[#0f1a16]/10" />
                   <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
                </div>
              </div>
              <button onClick={() => hasChanges ? setShowExitConfirm(true) : onCancel()} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm text-[#0f1a16]">{strings.common.cancel}</button>
            </div>
          </header>

          <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-6 overflow-y-auto pb-40 scroll-smooth-touch">
            {showExitConfirm && (
              <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
                <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
                  <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
                  <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
                  <div className="flex gap-4">
                    <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
                    <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
                  </div>
                </div>
              </div>
            )}
            {confirmDeleteId && (
              <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
                <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
                  <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
                  <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
                  <div className="flex gap-4">
                    <button onClick={() => setConfirmDeleteId(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
                    <button onClick={handleDeleteSpot} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
                  </div>
                </div>
              </div>
            )}

            <div className="grid grid-cols-2 gap-6">
              <button disabled={isProcessing || cameraStatus === 'denied'} onClick={() => setIsCapturing(true)} className={`flex flex-col items-center justify-center space-y-4 bg-white border border-[#2d4239]/5 py-10 rounded-[3rem] transition-all group shadow-sm ${cameraStatus === 'denied' ? 'opacity-20 grayscale' : ''}`}>
                <div className="p-4 bg-[#2d4239]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
                <span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#2d4239]">{strings.creator.takePhoto}</span>
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-4 bg-white border border-[#8c6b4f]/5 py-10 rounded-[3rem] transition-all group shadow-sm"><div className="p-4 bg-[#8c6b4f]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#8c6b4f]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div><span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#8c6b4f]">{strings.creator.uploadImage}</span><input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} /></button>
            </div>

            <button onClick={() => setIsSettingView(true)} className="w-full p-6 bg-white border border-[#2d4239]/10 rounded-[2rem] flex items-center justify-between hover:bg-[#2d4239]/5 transition-all group">
               <div className="flex items-center space-x-4">
                  <div className="w-10 h-10 bg-[#2d4239]/5 rounded-xl flex items-center justify-center"><svg className="w-5 h-5 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg></div>
                  <div className="text-left">
                     <p className="text-[10px] font-black uppercase tracking-widest text-[#2d4239]">Starting Map View</p>
                     <p className="text-[9px] text-[#2d4239]/40 uppercase font-bold">{startingView ? "Custom View Set" : "Auto-calculated from spots"}</p>
                  </div>
               </div>
               <svg className="w-5 h-5 opacity-20 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
            </button>

            <SpotList 
              questions={questions} 
              onUpdateQuestion={(id, updates) => setQuestions(prev => prev.map(q => q.id === id ? { ...q, ...updates } : q))}
              onEditLocation={(q) => {
                 setPendingQuestion({ 
                   localDataUrl: q.imageUrl, 
                   location: q.location, 
                   originalLocation: q.location, 
                   editingId: q.id, 
                   title: q.title, 
                   source: q.locationSource || 'MANUAL' 
                 });
              }}
              onMove={(index, direction) => {
                const newQuestions = [...questions];
                const target = direction === 'up' ? index - 1 : index + 1;
                [newQuestions[index], newQuestions[target]] = [newQuestions[target], newQuestions[index]];
                setQuestions(newQuestions);
              }}
              onDelete={setConfirmDeleteId}
            />
          </main>

          <footer className="fixed bottom-0 left-0 right-0 p-8 bg-white/70 backdrop-blur-xl border-t border-[#2d4239]/5 z-40">
            <button 
              disabled={questions.length === 0 || isSaving} 
              onClick={() => onComplete(questions, trailName, startingView)} 
              className={`w-full max-w-4xl mx-auto flex items-center justify-center py-6 btn-sleek !text-xl !tracking-[0.2em] ${questions.length > 0 && !isSaving ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none cursor-not-allowed'}`}
            >
              {isSaving ? (
                <div className="flex items-center space-x-4">
                  <div className="w-6 h-6 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
                  <span>Saving...</span>
                </div>
              ) : "Finalize Trail"}
            </button>
          </footer>
        </>
      )}
    </div>
  );
};

export default QuizCreator;

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Question, Location, Trail } from '../types';
import { generateId, compressImage } from '../utils';
import { strings } from '../i18n';
import GpsIndicator from './GpsIndicator';
import { usePermissions } from '../hooks/usePermissions';
import { PermissionBanner } from './PermissionGate';
import CameraView from './CameraView';
import SpotEditor from './SpotEditor';
import StartingViewEditor from './StartingViewEditor';
import SpotList from './SpotList';
import { supabase } from '../lib/supabase';
// @ts-ignore
import ExifReader from 'exifreader';

const STOCKHOLM: Location = { lat: 59.3293, lng: 18.0686 };

interface QuizCreatorProps {
  onComplete: (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => void;
  onCancel: () => void;
  onRequestPermissions: () => void;
  initialTrail?: Trail;
  isSaving?: boolean;
}

const LoadingOverlay: React.FC<{ message: string }> = ({ message }) => (
  <div className="fixed inset-0 z-[1000] bg-white/80 backdrop-blur-xl flex flex-col items-center justify-center animate-in fade-in duration-300">
    <div className="w-16 h-16 border-4 border-[#2d4239] border-t-transparent rounded-full animate-spin mb-6"></div>
    <p className="font-black uppercase tracking-[0.3em] text-[#2d4239] text-xs text-center px-6">{message}</p>
  </div>
);

const QuizCreator: React.FC<QuizCreatorProps> = ({ onComplete, onCancel, onRequestPermissions, initialTrail, isSaving }) => {
  const { cameraStatus, locationStatus } = usePermissions();
  const [questions, setQuestions] = useState<Question[]>(initialTrail?.questions || []);
  const [trailName, setTrailName] = useState(initialTrail?.name || '');
  const [startingView, setStartingView] = useState<{ center: Location, zoom: number } | undefined>(initialTrail?.startingView);

  const [isCapturing, setIsCapturing] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingMessage, setProcessingMessage] = useState('');
  const [isFlashing, setIsFlashing] = useState(false);

  const [currentLocation, setCurrentLocation] = useState<Location | null>(null);
  const [gpsAccuracy, setGpsAccuracy] = useState<number | null>(null);

  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [showExitConfirm, setShowExitConfirm] = useState(false);
  const [isSettingView, setIsSettingView] = useState(false);

  const [pendingQuestion, setPendingQuestion] = useState<{ 
    localDataUrl: string, 
    location: Location, 
    originalLocation: Location,
    source: 'IMAGE' | 'GPS' | 'DEFAULT' | 'MANUAL',
    editingId?: string,
    title?: string 
  } | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const watchId = useRef<number | null>(null);

  const hasChanges = useMemo(() => {
    const initialQuestions = initialTrail?.questions || [];
    const initialName = initialTrail?.name || '';
    if (trailName !== initialName) return true;
    if (questions.length !== initialQuestions.length) return true;
    return questions.some((q, idx) => {
      const iq = initialQuestions[idx];
      return !iq || q.id !== iq.id || q.title !== iq.title || 
             q.location.lat !== iq.location.lat || q.location.lng !== iq.location.lng;
    });
  }, [questions, trailName, initialTrail]);

  // Continuously watch position to have it ready
  useEffect(() => {
    if (!navigator.geolocation || locationStatus === 'denied') return;
    const options = { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 };
    const success = (pos: GeolocationPosition) => {
      setCurrentLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      setGpsAccuracy(pos.coords.accuracy);
    };
    const handleError = (err: any) => {
      console.warn("GPS Watch Error:", err.message);
    };
    watchId.current = navigator.geolocation.watchPosition(success, handleError, options);
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [locationStatus]);

  // Helper to get the most reliable live location available right now
  const getBestLiveLocation = async (): Promise<{ loc: Location, source: 'GPS' | 'DEFAULT' }> => {
    // 1. Check if our background watcher already has a lock
    if (currentLocation) {
      console.log("Using cached watch location:", currentLocation);
      return { loc: currentLocation, source: 'GPS' };
    }

    // 2. If granted but no lock, try a one-time high-accuracy burst (3s timeout)
    if (locationStatus === 'granted') {
      console.log("No watch lock yet, attempting high-accuracy burst...");
      try {
        const pos = await new Promise<GeolocationPosition>((resolve, reject) => {
          navigator.geolocation.getCurrentPosition(resolve, reject, { 
            enableHighAccuracy: true, 
            timeout: 3000,
            maximumAge: 0
          });
        });
        const liveLoc = { lat: pos.coords.latitude, lng: pos.coords.longitude };
        setCurrentLocation(liveLoc); // Update cache for next time
        setGpsAccuracy(pos.coords.accuracy);
        return { loc: liveLoc, source: 'GPS' };
      } catch (err) {
        console.warn("High-accuracy burst failed, falling back to Stockholm.");
      }
    }

    // 3. Last resort: Stockholm
    return { loc: STOCKHOLM, source: 'DEFAULT' };
  };

  const uploadImageToStorage = async (dataUrl: string): Promise<string> => {
    const base64 = dataUrl.split(',')[1];
    const byteCharacters = atob(base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: 'image/jpeg' });

    const fileName = `${generateId()}.jpg`;
    const { error } = await supabase.storage
      .from('trail-images')
      .upload(fileName, blob);

    if (error) throw error;

    const { data: { publicUrl } } = supabase.storage
      .from('trail-images')
      .getPublicUrl(fileName);

    return publicUrl;
  };

  const deleteImageFromStorage = async (url: string) => {
    try {
      if (url.startsWith('data:')) return;
      const fileName = url.split('/').pop();
      if (fileName) {
        await supabase.storage.from('trail-images').remove([fileName]);
      }
    } catch (err) {
      console.error("Failed to cleanup image:", err);
    }
  };

  const handleCapture = async (video: HTMLVideoElement) => {
    setProcessingMessage(strings.creator.processing);
    setIsProcessing(true);
    setIsFlashing(true);
    try {
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth; 
      canvas.height = video.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(video, 0, 0);
        const rawUrl = canvas.toDataURL('image/jpeg', 0.9);
        const compressedUrl = await compressImage(rawUrl);

        // Use our robust location helper
        const { loc, source } = await getBestLiveLocation();

        setPendingQuestion({ 
          localDataUrl: compressedUrl, 
          location: loc, 
          originalLocation: loc, 
          source: source
        });
        setIsCapturing(false); 
      }
    } catch (err) {
      console.error("Capture failed:", err);
      alert(strings.creator.processingError);
    } finally {
      setIsFlashing(false);
      setIsProcessing(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setProcessingMessage(strings.creator.processing);
    setIsProcessing(true);
    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const rawUrl = event.target?.result as string;
        const imageUrl = await compressImage(rawUrl);

        let exifLat: number | null = null;
        let exifLng: number | null = null;

        try {
          const tags = await ExifReader.load(file);
          if (tags.GPSLatitude && tags.GPSLongitude) {
            exifLat = parseFloat(tags.GPSLatitude.description);
            exifLng = parseFloat(tags.GPSLongitude.description);
          }
        } catch (exifErr) {
          console.warn("Exif read failed or no GPS data in image.");
        }

        let finalLoc = STOCKHOLM;
        let finalSource: 'IMAGE' | 'GPS' | 'DEFAULT' = 'DEFAULT';

        // 1. Priority: EXIF data from the file itself
        if (exifLat !== null && exifLng !== null && !isNaN(exifLat) && !isNaN(exifLng)) {
          finalLoc = { lat: exifLat, lng: exifLng };
          finalSource = 'IMAGE';
          console.log("Using EXIF location from file:", finalLoc);
        } else {
          // 2. Priority: Live GPS location
          const { loc, source } = await getBestLiveLocation();
          finalLoc = loc;
          finalSource = source;
          console.log(`Using ${source} location for file upload.`);
        }

        setPendingQuestion({ 
          localDataUrl: imageUrl, 
          location: finalLoc, 
          originalLocation: finalLoc, 
          source: finalSource 
        });
      } catch (err) {
        console.error("Upload process failed:", err);
        alert(strings.creator.uploadError);
      } finally {
        setIsProcessing(false);
      }
    };
    reader.readAsDataURL(file);
  };

  const confirmPending = async () => {
    if (!pendingQuestion) return;
    setProcessingMessage("Finalizing spot data...");
    setIsProcessing(true);
    try {
      const finalUrl = await uploadImageToStorage(pendingQuestion.localDataUrl);
      const isMoved = Math.abs(pendingQuestion.location.lat - pendingQuestion.originalLocation.lat) > 0.000001 || 
                      Math.abs(pendingQuestion.location.lng - pendingQuestion.originalLocation.lng) > 0.000001;
      const finalSource = isMoved ? 'MANUAL' : pendingQuestion.source;

      if (pendingQuestion.editingId) {
        setQuestions(prev => prev.map(q => q.id === pendingQuestion.editingId ? { ...q, location: pendingQuestion.location, imageUrl: finalUrl, locationSource: finalSource, title: pendingQuestion.title || q.title } : q));
      } else {
        setQuestions(prev => [...prev, { id: generateId(), imageUrl: finalUrl, location: pendingQuestion.location, locationSource: finalSource, title: strings.creator.spotPlaceholder(prev.length + 1) }]);
      }
      setPendingQuestion(null);
    } catch (err) {
      console.error("Failed to confirm spot:", err);
      alert("Could not save photo. Cloud sync failed.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleDeleteSpot = async () => {
    if (confirmDeleteId) {
      const q = questions.find(question => question.id === confirmDeleteId);
      if (q) await deleteImageFromStorage(q.imageUrl);
      setQuestions(prev => prev.filter(q => q.id !== confirmDeleteId));
      setConfirmDeleteId(null);
    }
  };

  if (isSettingView) {
    return (
      <StartingViewEditor 
        initialView={startingView} 
        questions={questions} 
        onSave={(view) => { setStartingView(view); setIsSettingView(false); }} 
        onCancel={() => setIsSettingView(false)} 
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#f9fbfa] flex flex-col text-[#0f1a16] selection:bg-[#8c6b4f]/20">
      {(isProcessing || isSaving) && <LoadingOverlay message={isSaving ? "Publishing your trail..." : processingMessage} />}

      {pendingQuestion ? (
        <SpotEditor 
          pendingQuestion={{
            imageUrl: pendingQuestion.localDataUrl,
            location: pendingQuestion.location,
            editingId: pendingQuestion.editingId
          }} 
          onUpdateLocation={(loc) => setPendingQuestion(prev => prev ? { ...prev, location: loc } : null)} 
          onConfirm={confirmPending} 
          onCancel={() => setPendingQuestion(null)} 
        />
      ) : isCapturing ? (
        <CameraView 
          onCapture={handleCapture} 
          onClose={() => setIsCapturing(false)} 
          gpsAccuracy={gpsAccuracy} 
          locationStatus={locationStatus} 
          isProcessing={isProcessing} 
          isFlashing={isFlashing} 
        />
      ) : (
        <>
          <PermissionBanner onCheck={onRequestPermissions} />
          <header className="px-6 pt-12 pb-8 shrink-0 bg-white/70 backdrop-blur-xl sticky top-0 z-30 border-b border-[#2d4239]/5">
            <div className="max-w-4xl mx-auto flex justify-between items-start">
              <div className="flex-1 mr-4">
                <input type="text" placeholder={strings.creator.trailNamePlaceholder} value={trailName} onChange={(e) => setTrailName(e.target.value)} className="bg-transparent border-none text-3xl font-black focus:ring-0 p-0 w-full placeholder-[#0f1a16]/10 tracking-tight uppercase text-[#0f1a16]" />
                <div className="flex items-center space-x-4 mt-2">
                   <p className="text-[#8c6b4f] font-black uppercase text-[9px] tracking-[0.4em]">{strings.creator.spotsInTrail(questions.length)}</p>
                   <div className="w-1 h-1 rounded-full bg-[#0f1a16]/10" />
                   <GpsIndicator accuracy={gpsAccuracy} isDisabled={locationStatus === 'denied'} />
                </div>
              </div>
              <button onClick={() => hasChanges ? setShowExitConfirm(true) : onCancel()} className="px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 hover:bg-white transition-all shadow-sm text-[#0f1a16]">{strings.common.cancel}</button>
            </div>
          </header>

          <main className="flex-1 max-w-4xl w-full mx-auto p-6 space-y-6 overflow-y-auto pb-40 scroll-smooth-touch">
            {showExitConfirm && (
              <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
                <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
                  <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.unsavedChangesTitle}</h3>
                  <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.unsavedChangesDesc}</p>
                  <div className="flex gap-4">
                    <button onClick={() => setShowExitConfirm(false)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.creator.keepEditing}</button>
                    <button onClick={onCancel} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.discard}</button>
                  </div>
                </div>
              </div>
            )}
            {confirmDeleteId && (
              <div className="fixed inset-0 z-[400] bg-[#2d4239]/40 backdrop-blur-md flex items-center justify-center p-6 text-center">
                <div className="bg-white border border-black/5 p-8 rounded-[3rem] w-full max-w-sm shadow-2xl">
                  <h3 className="text-xl font-black mb-2 uppercase tracking-tight">{strings.creator.deleteSpotTitle}</h3>
                  <p className="text-[#0f1a16]/40 text-sm mb-8 font-medium">{strings.creator.deleteSpotDesc}</p>
                  <div className="flex gap-4">
                    <button onClick={() => setConfirmDeleteId(null)} className="flex-1 py-4 bg-[#f9fbfa] rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.cancel}</button>
                    <button onClick={handleDeleteSpot} className="flex-1 py-4 bg-[#7c2d12] text-white rounded-2xl font-bold text-xs uppercase tracking-widest">{strings.common.delete}</button>
                  </div>
                </div>
              </div>
            )}

            <div className="grid grid-cols-2 gap-6">
              <button disabled={isProcessing || cameraStatus === 'denied'} onClick={() => setIsCapturing(true)} className={`flex flex-col items-center justify-center space-y-4 bg-white border border-[#2d4239]/5 py-10 rounded-[3rem] transition-all group shadow-sm ${cameraStatus === 'denied' ? 'opacity-20 grayscale' : ''}`}>
                <div className="p-4 bg-[#2d4239]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" /></svg></div>
                <span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#2d4239]">{strings.creator.takePhoto}</span>
              </button>
              <button onClick={() => fileInputRef.current?.click()} className="flex flex-col items-center justify-center space-y-4 bg-white border border-[#8c6b4f]/5 py-10 rounded-[3rem] transition-all group shadow-sm"><div className="p-4 bg-[#8c6b4f]/5 rounded-3xl group-hover:scale-110 transition-transform"><svg className="w-8 h-8 text-[#8c6b4f]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg></div><span className="font-black text-[10px] uppercase tracking-[0.3em] text-[#8c6b4f]">{strings.creator.uploadImage}</span><input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} /></button>
            </div>

            <button onClick={() => setIsSettingView(true)} className="w-full p-6 bg-white border border-[#2d4239]/10 rounded-[2rem] flex items-center justify-between hover:bg-[#2d4239]/5 transition-all group">
               <div className="flex items-center space-x-4">
                  <div className="w-10 h-10 bg-[#2d4239]/5 rounded-xl flex items-center justify-center"><svg className="w-5 h-5 text-[#2d4239]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 20l-5.447-2.724A1 1 0 013 16.382V5.618a1 1 0 011.447-.894L9 7m0 13l6-3m-6 3V7m6 10l4.553 2.276A1 1 0 0021 18.382V7.618a1 1 0 00-.553-.894L15 4m0 13V4m0 0L9 7" /></svg></div>
                  <div className="text-left">
                     <p className="text-[10px] font-black uppercase tracking-widest text-[#2d4239]">Starting Map View</p>
                     <p className="text-[9px] text-[#2d4239]/40 uppercase font-bold">{startingView ? "Custom View Set" : "Auto-calculated from spots"}</p>
                  </div>
               </div>
               <svg className="w-5 h-5 opacity-20 group-hover:opacity-100 transition-opacity" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg>
            </button>

            <SpotList 
              questions={questions} 
              onUpdateQuestion={(id, updates) => setQuestions(prev => prev.map(q => q.id === id ? { ...q, ...updates } : q))}
              onEditLocation={(q) => {
                 setPendingQuestion({ 
                   localDataUrl: q.imageUrl, 
                   location: q.location, 
                   originalLocation: q.location, 
                   editingId: q.id, 
                   title: q.title, 
                   source: q.locationSource || 'MANUAL' 
                 });
              }}
              onMove={(index, direction) => {
                const newQuestions = [...questions];
                const target = direction === 'up' ? index - 1 : index + 1;
                [newQuestions[index], newQuestions[target]] = [newQuestions[target], newQuestions[index]];
                setQuestions(newQuestions);
              }}
              onDelete={setConfirmDeleteId}
            />
          </main>

          <footer className="fixed bottom-0 left-0 right-0 p-8 bg-white/70 backdrop-blur-xl border-t border-[#2d4239]/5 z-40">
            <button 
              disabled={questions.length === 0 || isSaving} 
              onClick={() => onComplete(questions, trailName, startingView)} 
              className={`w-full max-w-4xl mx-auto flex items-center justify-center py-6 btn-sleek !text-xl !tracking-[0.2em] ${questions.length > 0 && !isSaving ? 'btn-sleek-pine !bg-[#2d4239]' : 'bg-[#f9fbfa] text-[#0f1a16]/10 shadow-none cursor-not-allowed'}`}
            >
              {isSaving ? (
                <div className="flex items-center space-x-4">
                  <div className="w-6 h-6 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
                  <span>Saving...</span>
                </div>
              ) : "Finalize Trail"}
            </button>
          </footer>
        </>
      )}
    </div>
  );
};

export default QuizCreator;

import { useEffect, useCallback, useRef } from 'react';
import { GameState, Player, Location } from './types';
import { getLeanState } from './utils';
import { supabase } from './lib/supabase';

export type GameSyncMessage = 
  | { type: 'STATE_FULL'; state: GameState }
  | { type: 'STATE_DYNAMIC'; state: Partial<GameState> }
  | { type: 'REQUEST_SYNC' }
  | { type: 'PLAYER_JOIN_REQUEST'; player: Player }
  | { type: 'PLAYER_GUESS_REQUEST'; playerId: string; guess: Location; distance: number }
  | { type: 'PLAYER_UNLOCK_REQUEST'; playerId: string }
  | { type: 'HOST_REVEAL_REQUEST' }
  | { type: 'FORCE_REVEAL' }
  | { type: 'TERMINATE_SESSION' };

export const useGameSync = (
  onStateUpdate: (state: GameState) => void, 
  onActionRequest: (action: any) => void,
  isHost: boolean, 
  gameState: GameState | null,
  roomId?: string | null // NEW: Allow connecting via raw ID
) => {
  const channelRef = useRef<any>(null);
  const questionsCache = useRef<GameState['questions'] | null>(null);

  const clearCache = useCallback(() => {
    questionsCache.current = null;
  }, []);

  const broadcast = useCallback((state: GameState, full = false) => {
    if (!channelRef.current) return;

    if (full) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_FULL', state }
      });
    } else {
      const lean = getLeanState(state);
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_DYNAMIC', state: lean }
      });
    }
  }, []);

  const sendAction = useCallback((message: GameSyncMessage) => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: message
      });
    }
  }, []);

  const requestSync = useCallback(() => {
    if (channelRef.current) {
      console.log("Requesting sync from host...");
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'REQUEST_SYNC' }
      });
    }
  }, []);

  // Determine which ID to use for the channel
  const activeChannelId = gameState?.id || roomId;

  useEffect(() => {
    if (!activeChannelId) return;

    console.log(`Subscribing to channel: game_${activeChannelId}`);
    const channel = supabase.channel(`game_${activeChannelId}`, {
      config: {
        broadcast: { self: false }
      }
    });

    channel.on('broadcast', { event: 'sync' }, ({ payload }) => {
      const data = payload as GameSyncMessage;

      if (data.type === 'STATE_FULL') {
        if (!isHost) {
          console.log("Received full state from host");
          questionsCache.current = data.state.questions;
          onStateUpdate(data.state);
        }
      } else if (data.type === 'STATE_DYNAMIC') {
        if (!isHost && questionsCache.current) {
          const reconstructedState = { 
            ...data.state, 
            questions: questionsCache.current 
          } as GameState;
          onStateUpdate(reconstructedState);
        }
      } else if (data.type === 'TERMINATE_SESSION') {
        if (!isHost) clearCache();
      } else if (data.type === 'REQUEST_SYNC') {
        if (isHost && gameState) {
          console.log("Player requested sync. Sending full state...");
          broadcast(gameState, true);
        }
      } else if (data.type === 'PLAYER_JOIN_REQUEST') {
        if (isHost) onActionRequest({ type: 'JOIN_PLAYER', payload: data.player });
      } else if (data.type === 'PLAYER_GUESS_REQUEST') {
        if (isHost) onActionRequest({ type: 'SUBMIT_GUESS', payload: { playerId: data.playerId, guess: data.guess, distance: data.distance } });
      } else if (data.type === 'PLAYER_UNLOCK_REQUEST') {
        if (isHost) onActionRequest({ type: 'UNLOCK_GUESS', payload: data.playerId });
      } else if (data.type === 'HOST_REVEAL_REQUEST') {
        if (isHost) onActionRequest({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
      } else if (data.type === 'FORCE_REVEAL') {
        if (isHost) onActionRequest({ type: 'FORCE_REVEAL' });
      }
    });

    channel.subscribe((status) => {
      if (status === 'SUBSCRIBED') {
        channelRef.current = channel;
        // If we are a player looking for a game, ask for state immediately
        if (!isHost) requestSync();
      }
    });

    return () => {
      console.log(`Unsubscribing from channel: game_${activeChannelId}`);
      channel.unsubscribe();
      channelRef.current = null;
    };
  }, [activeChannelId, isHost, gameState?.status, onStateUpdate, onActionRequest, broadcast, clearCache, requestSync]);

  return { broadcast, sendAction, requestSync, clearCache };
};

import React, { useState, useEffect, useReducer, useCallback, useRef } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import { gameReducer } from './gameReducer';
import { useGameSync } from './useGameSync';
import { useTrails } from './hooks/useTrails';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import Home from './components/Home';
import JoinGame from './components/JoinGame';
import { PermissionModal } from './components/PermissionGate';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [showPermissionModal, setShowPermissionModal] = useState(false);
  const [joinError, setJoinError] = useState<string | null>(null);
  const [joinCode, setJoinCode] = useState<string | null>(null); // NEW: Track the code being typed
  const [isJoining, setIsJoining] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const joinTimeoutRef = useRef<number | null>(null);

  const prevStatusRef = useRef<GameState['status'] | null>(null);
  const prevIndexRef = useRef<number>(-1);

  const { trails, saveTrail, deleteTrail, isLoading: isTrailsLoading } = useTrails(user);
  const [gameState, dispatch] = useReducer(gameReducer, null);

  const { broadcast, sendAction, requestSync, clearCache } = useGameSync(
    useCallback((state) => dispatch({ type: 'SYNC_STATE', payload: state }), []),
    useCallback((action) => dispatch(action), []),
    isHost,
    gameState,
    joinCode // Pass the typed code to sync hook
  );

  useEffect(() => {
    if (isHost && gameState) {
      localStorage.setItem('locateit_active_host_state', JSON.stringify(gameState));
      const isStatusChange = gameState.status !== prevStatusRef.current;
      const isIndexChange = gameState.currentQuestionIndex !== prevIndexRef.current;
      const isNewGame = prevStatusRef.current === null;
      const needsFullSync = isStatusChange || isIndexChange || isNewGame;
      broadcast(gameState, needsFullSync);
      prevStatusRef.current = gameState.status;
      prevIndexRef.current = gameState.currentQuestionIndex;
    }
  }, [gameState, isHost, broadcast]);

  useEffect(() => {
    if (view === 'JOIN' && !gameState && joinCode) {
      requestSync();
      const interval = setInterval(requestSync, 2000);
      return () => clearInterval(interval);
    }
  }, [view, gameState, requestSync, joinCode]);

  useEffect(() => {
    if (gameState && (isHost || currentPlayer)) {
      const inGameStatus = ['PLAYING', 'COUNTDOWN', 'RESULTS', 'SCOREBOARD', 'FINISHED'];
      if (inGameStatus.includes(gameState.status) && view !== 'PLAYING') {
        setView('PLAYING');
      }
      if (currentPlayer && !isHost && !isJoining) {
        const isPresent = gameState.players.some(p => p.id === currentPlayer.id);
        if (!isPresent && (view === 'LOBBY' || view === 'PLAYING')) {
           alert(strings.lobby.kickedDesc);
           handleExitGame();
        }
      }
    }
  }, [gameState, currentPlayer, isHost, view, isJoining]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) setUser(JSON.parse(savedUser));
  }, []);

  const handleCompleteTrail = async (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => {
    if (isSaving) return;
    setIsSaving(true);
    try {
      const result = await saveTrail(questions, name, startingView, editingTrail?.id);
      if (result.success) {
        setEditingTrail(null);
        setView('DASHBOARD');
      } else {
        alert(`Save Failed: ${result.error}. Ensure your Supabase tables (profiles, trails, questions) are set up correctly.`);
      }
    } catch (e: any) {
      console.error("Save failed in App.tsx:", e);
      alert(`Unexpected Error: ${e.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); 
    const newGameId = generateId();
    dispatch({ type: 'INIT_LOBBY', payload: { id: newGameId, questions: trail.questions, hostId: user.id, startingView: trail.startingView } });
    setView('LOBBY');
  };

  const handleResumeHost = () => {
    const saved = localStorage.getItem('locateit_active_host_state');
    if (saved) {
      const state = JSON.parse(saved) as GameState;
      setIsHost(true);
      setCurrentPlayer(null);
      dispatch({ type: 'SYNC_STATE', payload: state });
      setView(state.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
    }
  };

  const handleJoinGame = (gameCode: string, name: string, color: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();

    // We only proceed if we've successfully received the state from the host
    if (!gameState || gameState.id !== code) {
      setJoinError(`Searching for Expedition ${code}... Ensure the host has started the lobby.`);
      requestSync();
      return;
    }

    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);
    if (existingById) {
      setCurrentPlayer(existingById);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }
    const existingByName = gameState.players.find(p => p.name.toLowerCase() === name.toLowerCase());
    if (existingByName) {
      setCurrentPlayer(existingByName);
      setIsHost(false);
      localStorage.setItem('locateit_last_player_id', existingByName.id);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }
    const newPlayer: Player = { id: generateId(), name, color, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    setIsJoining(true);
    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 5000);
    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  const handleExitGame = () => {
    if (isHost) {
      localStorage.removeItem('locateit_active_host_state');
      sendAction({ type: 'TERMINATE_SESSION' });
    }
    clearCache();
    dispatch({ type: 'EXIT_GAME' });
    setCurrentPlayer(null);
    setJoinCode(null);
    setView(isHost ? 'DASHBOARD' : 'HOME');
  };

  return (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
      {view === 'HOME' && <Home onJoin={() => setView('JOIN')} onDesign={() => user ? setView('DASHBOARD') : setView('AUTH')} />}
      {view === 'JOIN' && <JoinGame onBack={() => setView('HOME')} onJoin={handleJoinGame} onCodeChange={setJoinCode} isSearching={!gameState && !!joinCode} error={joinError} />}
      {view === 'AUTH' && <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />}
      {view === 'DASHBOARD' && user && (
        <Dashboard 
          user={user} 
          trails={trails}
          isLoading={isTrailsLoading}
          onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} 
          onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} 
          onHostTrail={handleHostTrail} 
          onDeleteTrail={deleteTrail}
          onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }}
          onResumeHost={localStorage.getItem('locateit_active_host_state') ? handleResumeHost : undefined}
        />
      )}
      {view === 'CREATE' && (
        <QuizCreator 
          initialTrail={editingTrail || undefined} 
          onComplete={handleCompleteTrail} 
          onCancel={() => setView('DASHBOARD')} 
          onRequestPermissions={() => setShowPermissionModal(true)}
          isSaving={isSaving}
        />
      )}
      {view === 'LOBBY' && gameState && (
        <Lobby 
          gameState={gameState} 
          isHost={isHost} 
          onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} 
          currentPlayer={currentPlayer} 
          onBack={handleExitGame} 
          onKick={(id) => dispatch({ type: 'KICK_PLAYER', payload: id })} 
        />
      )}
      {view === 'PLAYING' && gameState && (
        <GameBoard 
          gameState={gameState} 
          isHost={isHost} 
          currentPlayer={currentPlayer} 
          onGuess={(guess) => {
            if (!currentPlayer) return;
            const currentQ = gameState.questions[gameState.currentQuestionIndex];
            const dist = calculateDistance(guess, currentQ.location);
            sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
            if (isHost) dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
          }} 
          onUnlock={() => {
            if (!currentPlayer) return;
            sendAction({ type: 'PLAYER_UNLOCK_REQUEST', playerId: currentPlayer.id });
            if (isHost) dispatch({ type: 'UNLOCK_GUESS', payload: currentPlayer.id });
          }}
          onReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
            sendAction({ type: 'HOST_REVEAL_REQUEST' });
          }}
          onForceReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'FORCE_REVEAL' });
            sendAction({ type: 'FORCE_REVEAL' });
          }}
          onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
          onShowScoreboard={() => isHost && dispatch({ type: 'CALCULATE_SCORES' })}
          onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
          onExit={handleExitGame}
        />
      )}
    </>
  );
};

export default App;

