      const isStatusChange = gameState.status !== prevStatusRef.current;
      const isIndexChange = gameState.currentQuestionIndex !== prevIndexRef.current;
      const isNewGame = prevStatusRef.current === null;
      const needsFullSync = isStatusChange || isIndexChange || isNewGame;

      broadcast(gameState, needsFullSync);

      prevStatusRef.current = gameState.status;
      prevIndexRef.current = gameState.currentQuestionIndex;
    }
  }, [gameState, isHost, broadcast]);

  // Player: Sync loop when waiting for game data
  useEffect(() => {
    if ((view === 'JOIN' || view === 'LOBBY') && !isHost && joinCode) {
      const interval = setInterval(requestSync, 3000);
      return () => clearInterval(interval);
    }
  }, [view, isHost, requestSync, joinCode]);

  // View Transition Watchdog
  useEffect(() => {
    if (gameState && (isHost || currentPlayer)) {
      const inGameStatus = ['PLAYING', 'COUNTDOWN', 'RESULTS', 'SCOREBOARD', 'FINISHED'];

      // Auto-transition to board if game is active
      if (inGameStatus.includes(gameState.status) && view !== 'PLAYING') {
        setView('PLAYING');
      }

      // Player-side logic: Detect if we've been accepted or kicked
      if (currentPlayer && !isHost) {
        const isPresent = gameState.players.some(p => p.id === currentPlayer.id);

        if (isPresent) {
          // Reset missing counter since we found ourselves
          missingPresenceCountRef.current = 0;

          if (!hasBeenAccepted) {
            setHasBeenAccepted(true);
            setIsJoining(false);
            if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
          }
        } else {
          // Not found in the current state update. 
          // Are we waiting to join or were we already in?
          if (hasBeenAccepted && !isJoining) {
            missingPresenceCountRef.current++;
            // Only kick if we are missing for multiple consecutive updates (~9-12s)
            // to survive network jitters or out-of-order broadcasts.
            if (missingPresenceCountRef.current > 3) {
               alert(strings.lobby.kickedDesc);
               handleExitGame();
            }
          }

          // Timeout Check: We requested to join but never appeared in the host's list
          if (!isJoining && !hasBeenAccepted && view === 'LOBBY') {
             setJoinError("Connection timeout. Host did not acknowledge join request within 30s.");
             handleExitGame();
          }
        }
      }
    }
  }, [gameState?.players, gameState?.status, currentPlayer, isHost, view, isJoining, hasBeenAccepted]);

