      setJoinError(`Searching for Expedition ${code}... Ensure the host has started the lobby.`);
      requestSync();
      return;
    }

    // Check if we are rejoining an existing session
    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);

    if (existingById) {
      setCurrentPlayer(existingById);
      // We don't set hasBeenAccepted to true immediately.
      // We set isJoining to true so the watchdog confirms presence 
      // from the current broadcast before letting us "in".
      setIsJoining(true);
      setHasBeenAccepted(false);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');

      if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
      joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 30000);
      return;
    }

