import { useEffect, useCallback, useRef } from 'react';
import { GameState, Player, Location } from './types';
import { getLeanState } from './utils';
import { supabase } from './lib/supabase';

export type GameSyncMessage = 
  | { type: 'STATE_FULL'; state: GameState }
  | { type: 'STATE_DYNAMIC'; state: Partial<GameState> }
  | { type: 'REQUEST_SYNC' }
  | { type: 'PLAYER_JOIN_REQUEST'; player: Player }
  | { type: 'PLAYER_GUESS_REQUEST'; playerId: string; guess: Location; distance: number }
  | { type: 'PLAYER_UNLOCK_REQUEST'; playerId: string }
  | { type: 'PLAYER_LEAVE'; playerId: string }
  | { type: 'PLAYER_KICKED'; playerId: string }
  | { type: 'HOST_REVEAL_REQUEST' }
  | { type: 'FORCE_REVEAL' }
  | { type: 'TERMINATE_SESSION' };

export const useGameSync = (
  onStateUpdate: (state: GameState) => void, 
  onActionRequest: (action: any) => void,
  isHost: boolean, 
  gameState: GameState | null,
  roomId?: string | null,
  onKicked?: () => void,
  onSessionEnded?: () => void
) => {
  const channelRef = useRef<any>(null);
  const questionsCache = useRef<GameState['questions'] | null>(null);

  const clearCache = useCallback(() => {
    questionsCache.current = null;
  }, []);

  const broadcast = useCallback((state: GameState, full = false) => {
    if (!channelRef.current) return;

    if (full) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_FULL', state }
      });
    } else {
      const lean = getLeanState(state);
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_DYNAMIC', state: lean }
      });
    }
  }, []);

  const sendAction = useCallback((message: GameSyncMessage) => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: message
      });
    }
  }, []);

  const requestSync = useCallback(() => {
    if (channelRef.current) {
      console.log("Requesting sync from host...");
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'REQUEST_SYNC' }
      });
    }
  }, []);

  const activeChannelId = gameState?.id || roomId;

  useEffect(() => {
    if (!activeChannelId) return;

    const channel = supabase.channel(`game_${activeChannelId}`, {
      config: { broadcast: { self: false } }
    });

    channel.on('broadcast', { event: 'sync' }, ({ payload }) => {
      const data = payload as GameSyncMessage;

      if (data.type === 'STATE_FULL') {
        if (!isHost) {
          questionsCache.current = data.state.questions;
          onStateUpdate(data.state);
        }
      } else if (data.type === 'STATE_DYNAMIC') {
        if (!isHost && questionsCache.current) {
          const reconstructedState = { 
            ...data.state, 
            questions: questionsCache.current 
          } as GameState;
          onStateUpdate(reconstructedState);
        }
      } else if (data.type === 'TERMINATE_SESSION') {
        if (!isHost) {
          clearCache();
          onSessionEnded?.();
        }
      } else if (data.type === 'PLAYER_KICKED') {
        if (!isHost) {
          // If the message is targeted at us, trigger the kick callback
          // Note: App.tsx will handle checking if the ID matches its local player
          onKicked?.();
          // We pass data so the caller can check the ID, but here we just notify
          // The App.tsx listener handles the ID check more reliably
        }
      } else if (data.type === 'PLAYER_LEAVE') {
        if (isHost) onActionRequest({ type: 'KICK_PLAYER', payload: data.playerId });
      } else if (data.type === 'REQUEST_SYNC') {
        if (isHost && gameState) broadcast(gameState, true);
      } else if (data.type === 'PLAYER_JOIN_REQUEST') {
        if (isHost) onActionRequest({ type: 'JOIN_PLAYER', payload: data.player });
      } else if (data.type === 'PLAYER_GUESS_REQUEST') {
        if (isHost) onActionRequest({ type: 'SUBMIT_GUESS', payload: { playerId: data.playerId, guess: data.guess, distance: data.distance } });
      } else if (data.type === 'PLAYER_UNLOCK_REQUEST') {
        if (isHost) onActionRequest({ type: 'UNLOCK_GUESS', payload: data.playerId });
      } else if (data.type === 'HOST_REVEAL_REQUEST') {
        if (isHost) onActionRequest({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
      } else if (data.type === 'FORCE_REVEAL') {
        if (isHost) onActionRequest({ type: 'FORCE_REVEAL' });
      }
    });

    channel.subscribe((status) => {
      if (status === 'SUBSCRIBED') {
        channelRef.current = channel;
        if (!isHost) requestSync();
      }
    });

    return () => {
      channel.unsubscribe();
      channelRef.current = null;
    };
  }, [activeChannelId, isHost, onStateUpdate, onActionRequest, broadcast, clearCache, requestSync, onSessionEnded]);

  return { broadcast, sendAction, requestSync, clearCache };
};

import React, { useState, useEffect, useReducer, useCallback, useRef } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import { gameReducer } from './gameReducer';
import { useGameSync } from './useGameSync';
import { useTrails } from './hooks/useTrails';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import Home from './components/Home';
import JoinGame from './components/JoinGame';
import { PermissionModal } from './components/PermissionGate';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [showPermissionModal, setShowPermissionModal] = useState(false);
  const [joinError, setJoinError] = useState<string | null>(null);
  const [joinCode, setJoinCode] = useState<string | null>(null); 
  const [isJoining, setIsJoining] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const joinTimeoutRef = useRef<number | null>(null);
  const prevStatusRef = useRef<GameState['status'] | null>(null);
  const prevIndexRef = useRef<number>(-1);

  const { trails, saveTrail, deleteTrail, isLoading: isTrailsLoading } = useTrails(user);
  const [gameState, dispatch] = useReducer(gameReducer, null);

  // Define exit game first so it can be used in callbacks
  const handleExitGame = useCallback((silent = false) => {
    if (isHost) {
      localStorage.removeItem('locateit_active_host_state');
      sendAction({ type: 'TERMINATE_SESSION' });
    } else if (currentPlayer) {
      // Notify host that we are leaving so they remove us from the list
      sendAction({ type: 'PLAYER_LEAVE', playerId: currentPlayer.id });
    }

    clearCache();
    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);

    dispatch({ type: 'EXIT_GAME' });
    setCurrentPlayer(null);
    setIsJoining(false);
    setJoinCode(null);
    setView(isHost ? 'DASHBOARD' : 'HOME');
  }, [isHost, currentPlayer]);

  const { broadcast, sendAction, requestSync, clearCache } = useGameSync(
    useCallback((state) => dispatch({ type: 'SYNC_STATE', payload: state }), []),
    useCallback((action) => dispatch(action), []),
    isHost,
    gameState,
    joinCode,
    useCallback(() => {
      // onKicked: We verify if we are the ones kicked inside the message listener
      // but let's do it safely here if we can get the payload? 
      // Actually, we'll handle the alert in useGameSync or specific broadcast listener
    }, []),
    useCallback(() => {
      // onSessionEnded: Host disconnected
      handleExitGame(true);
    }, [handleExitGame])
  );

  // Subscribe to explicit kick events via the channel if not host
  useEffect(() => {
    if (!isHost && joinCode && currentPlayer) {
      const channel = useGameSync.prototype.channelRef?.current; // This is a bit hacky, better use onActionRequest approach
      // Instead of hack, we rely on the STATE_DYNAMIC updates from the host.
      // If the host kicks us, they broadcast a new state where we are missing.
      // We removed the watchdog to prevent false positives, but we still need 
      // to know if we were INTENTIONALLY kicked.
    }
  }, [isHost, joinCode, currentPlayer]);

  // Handle Join Deep Link
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const codeFromUrl = params.get('join');
    if (codeFromUrl) {
      const cleanCode = codeFromUrl.trim().toUpperCase();
      setJoinCode(cleanCode);
      setView('JOIN');
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  // Host: Broadcast changes
  useEffect(() => {
    if (isHost && gameState) {
      localStorage.setItem('locateit_active_host_state', JSON.stringify(gameState));
      const isStatusChange = gameState.status !== prevStatusRef.current;
      const isIndexChange = gameState.currentQuestionIndex !== prevIndexRef.current;
      const isNewGame = prevStatusRef.current === null;
      const needsFullSync = isStatusChange || isIndexChange || isNewGame;

      broadcast(gameState, needsFullSync);

      prevStatusRef.current = gameState.status;
      prevIndexRef.current = gameState.currentQuestionIndex;
    }
  }, [gameState, isHost, broadcast]);

  // Player: Sync loop when waiting for game data
  useEffect(() => {
    if ((view === 'JOIN' || view === 'LOBBY') && !isHost && joinCode) {
      const interval = setInterval(requestSync, 4000);
      return () => clearInterval(interval);
    }
  }, [view, isHost, requestSync, joinCode]);

  // View Transition Watchdog
  useEffect(() => {
    if (gameState && (isHost || currentPlayer)) {
      const inGameStatus = ['PLAYING', 'COUNTDOWN', 'RESULTS', 'SCOREBOARD', 'FINISHED'];

      // Auto-transition to board if game is active
      if (inGameStatus.includes(gameState.status) && view !== 'PLAYING') {
        setView('PLAYING');
      }

      // If we see ourselves in the host list, we stop the "Joining" spinner
      if (currentPlayer && !isHost && isJoining) {
        const isPresent = gameState.players.some(p => p.id === currentPlayer.id);
        if (isPresent) {
          setIsJoining(false);
          if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
        }
      }
    }
  }, [gameState?.players, gameState?.status, currentPlayer, isHost, view, isJoining]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) setUser(JSON.parse(savedUser));
  }, []);

  const handleCompleteTrail = async (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => {
    if (isSaving) return;
    setIsSaving(true);
    try {
      const result = await saveTrail(questions, name, startingView, editingTrail?.id);
      if (result.success) {
        setEditingTrail(null);
        setView('DASHBOARD');
      } else {
        alert(`Save Failed: ${result.error}.`);
      }
    } catch (e: any) {
      alert(`Unexpected Error: ${e.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); 
    const newGameId = generateId();
    dispatch({ type: 'INIT_LOBBY', payload: { id: newGameId, questions: trail.questions, hostId: user.id, startingView: trail.startingView } });
    setJoinCode(newGameId);
    setView('LOBBY');
  };

  const handleResumeHost = () => {
    const saved = localStorage.getItem('locateit_active_host_state');
    if (saved) {
      const state = JSON.parse(saved) as GameState;
      setIsHost(true);
      setCurrentPlayer(null);
      setJoinCode(state.id);
      dispatch({ type: 'SYNC_STATE', payload: state });
      setView(state.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
    }
  };

  const handleJoinGame = (gameCode: string, name: string, color: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();

    if (!gameState || gameState.id !== code) {
      setJoinError(`Searching for Expedition ${code}... Ensure the host has started the lobby.`);
      requestSync();
      return;
    }

    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);

    if (existingById) {
      setCurrentPlayer(existingById);
      setIsJoining(false);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    const newPlayer: Player = { id: generateId(), name, color, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    setIsJoining(true);

    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 20000);

    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  return (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
      {view === 'HOME' && <Home onJoin={() => setView('JOIN')} onDesign={() => user ? setView('DASHBOARD') : setView('AUTH')} />}
      {view === 'JOIN' && <JoinGame prefilledCode={joinCode || ''} onBack={() => setView('HOME')} onJoin={handleJoinGame} onCodeChange={setJoinCode} isSearching={!gameState && !!joinCode} error={joinError} />}
      {view === 'AUTH' && <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />}
      {view === 'DASHBOARD' && user && (
        <Dashboard 
          user={user} 
          trails={trails}
          isLoading={isTrailsLoading}
          onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} 
          onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} 
          onHostTrail={handleHostTrail} 
          onDeleteTrail={deleteTrail}
          onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }}
          onResumeHost={localStorage.getItem('locateit_active_host_state') ? handleResumeHost : undefined}
        />
      )}
      {view === 'CREATE' && (
        <QuizCreator 
          initialTrail={editingTrail || undefined} 
          onComplete={handleCompleteTrail} 
          onCancel={() => setView('DASHBOARD')} 
          onRequestPermissions={() => setShowPermissionModal(true)}
          isSaving={isSaving}
        />
      )}
      {view === 'LOBBY' && gameState && (
        <Lobby 
          gameState={gameState} 
          isHost={isHost} 
          onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} 
          currentPlayer={currentPlayer} 
          onBack={handleExitGame} 
          onKick={(id) => {
            // Host kicks: 1. Remove locally 2. Broadcast the kick
            dispatch({ type: 'KICK_PLAYER', payload: id });
            sendAction({ type: 'PLAYER_KICKED', playerId: id });
          }} 
        />
      )}
      {view === 'PLAYING' && gameState && (
        <GameBoard 
          gameState={gameState} 
          isHost={isHost} 
          currentPlayer={currentPlayer} 
          onGuess={(guess) => {
            if (!currentPlayer) return;
            const currentQ = gameState.questions[gameState.currentQuestionIndex];
            const dist = calculateDistance(guess, currentQ.location);
            sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
            if (isHost) dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
          }} 
          onUnlock={() => {
            if (!currentPlayer) return;
            sendAction({ type: 'PLAYER_UNLOCK_REQUEST', playerId: currentPlayer.id });
            if (isHost) dispatch({ type: 'UNLOCK_GUESS', payload: currentPlayer.id });
          }}
          onReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
            sendAction({ type: 'HOST_REVEAL_REQUEST' });
          }}
          onForceReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'FORCE_REVEAL' });
            sendAction({ type: 'FORCE_REVEAL' });
          }}
          onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
          onShowScoreboard={() => isHost && dispatch({ type: 'CALCULATE_SCORES' })}
          onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
          onExit={handleExitGame}
        />
      )}
    </>
  );
};

export default App;

import { useEffect, useCallback, useRef } from 'react';
import { GameState, Player, Location } from './types';
import { getLeanState } from './utils';
import { supabase } from './lib/supabase';

export type GameSyncMessage = 
  | { type: 'STATE_FULL'; state: GameState }
  | { type: 'STATE_DYNAMIC'; state: Partial<GameState> }
  | { type: 'REQUEST_SYNC' }
  | { type: 'PLAYER_JOIN_REQUEST'; player: Player }
  | { type: 'PLAYER_GUESS_REQUEST'; playerId: string; guess: Location; distance: number }
  | { type: 'PLAYER_UNLOCK_REQUEST'; playerId: string }
  | { type: 'PLAYER_LEAVE'; playerId: string }
  | { type: 'PLAYER_KICKED'; targetId: string }
  | { type: 'HOST_REVEAL_REQUEST' }
  | { type: 'FORCE_REVEAL' }
  | { type: 'TERMINATE_SESSION' };

export const useGameSync = (
  onStateUpdate: (state: GameState) => void, 
  onActionRequest: (action: any) => void,
  isHost: boolean, 
  gameState: GameState | null,
  roomId?: string | null,
  onKicked?: (targetId: string) => void,
  onSessionEnded?: () => void
) => {
  const channelRef = useRef<any>(null);
  const questionsCache = useRef<GameState['questions'] | null>(null);

  const clearCache = useCallback(() => {
    questionsCache.current = null;
  }, []);

  const broadcast = useCallback((state: GameState, full = false) => {
    if (!channelRef.current) return;

    if (full) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_FULL', state }
      });
    } else {
      const lean = getLeanState(state);
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'STATE_DYNAMIC', state: lean }
      });
    }
  }, []);

  const sendAction = useCallback((message: GameSyncMessage) => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: message
      });
    }
  }, []);

  const requestSync = useCallback(() => {
    if (channelRef.current) {
      channelRef.current.send({
        type: 'broadcast',
        event: 'sync',
        payload: { type: 'REQUEST_SYNC' }
      });
    }
  }, []);

  const activeChannelId = gameState?.id || roomId;

  useEffect(() => {
    if (!activeChannelId) return;

    const channel = supabase.channel(`game_${activeChannelId}`, {
      config: { broadcast: { self: false } }
    });

    channel.on('broadcast', { event: 'sync' }, ({ payload }) => {
      const data = payload as GameSyncMessage;

      if (data.type === 'STATE_FULL') {
        if (!isHost) {
          questionsCache.current = data.state.questions;
          onStateUpdate(data.state);
        }
      } else if (data.type === 'STATE_DYNAMIC') {
        if (!isHost && questionsCache.current) {
          const reconstructedState = { 
            ...data.state, 
            questions: questionsCache.current 
          } as GameState;
          onStateUpdate(reconstructedState);
        }
      } else if (data.type === 'TERMINATE_SESSION') {
        if (!isHost) {
          onSessionEnded?.();
        }
      } else if (data.type === 'PLAYER_KICKED') {
        if (!isHost) {
          onKicked?.(data.targetId);
        }
      } else if (data.type === 'PLAYER_LEAVE') {
        // Host receives a notification that someone left voluntarily
        if (isHost) onActionRequest({ type: 'KICK_PLAYER', payload: data.playerId });
      } else if (data.type === 'REQUEST_SYNC') {
        if (isHost && gameState) broadcast(gameState, true);
      } else if (data.type === 'PLAYER_JOIN_REQUEST') {
        if (isHost) onActionRequest({ type: 'JOIN_PLAYER', payload: data.player });
      } else if (data.type === 'PLAYER_GUESS_REQUEST') {
        if (isHost) onActionRequest({ type: 'SUBMIT_GUESS', payload: { playerId: data.playerId, guess: data.guess, distance: data.distance } });
      } else if (data.type === 'PLAYER_UNLOCK_REQUEST') {
        if (isHost) onActionRequest({ type: 'UNLOCK_GUESS', payload: data.playerId });
      } else if (data.type === 'HOST_REVEAL_REQUEST') {
        if (isHost) onActionRequest({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
      } else if (data.type === 'FORCE_REVEAL') {
        if (isHost) onActionRequest({ type: 'FORCE_REVEAL' });
      }
    });

    channel.subscribe((status) => {
      if (status === 'SUBSCRIBED') {
        channelRef.current = channel;
        if (!isHost) requestSync();
      }
    });

    return () => {
      channel.unsubscribe();
      channelRef.current = null;
    };
  }, [activeChannelId, isHost, onStateUpdate, onActionRequest, broadcast, requestSync, onSessionEnded, onKicked]);

  return { broadcast, sendAction, requestSync, clearCache };
};

import React, { useState, useEffect, useReducer, useCallback, useRef } from 'react';
import { GameState, Player, Question, Location, User, AppView, Trail } from './types';
import { generateId, calculateDistance } from './utils';
import { strings } from './i18n';
import { gameReducer } from './gameReducer';
import { useGameSync } from './useGameSync';
import { useTrails } from './hooks/useTrails';
import QuizCreator from './components/QuizCreator';
import Lobby from './components/Lobby';
import GameBoard from './components/GameBoard';
import Auth from './components/Auth';
import Dashboard from './components/Dashboard';
import Home from './components/Home';
import JoinGame from './components/JoinGame';
import { PermissionModal } from './components/PermissionGate';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>('HOME');
  const [user, setUser] = useState<User | null>(null);
  const [isHost, setIsHost] = useState(false);
  const [editingTrail, setEditingTrail] = useState<Trail | null>(null);
  const [currentPlayer, setCurrentPlayer] = useState<Player | null>(null);
  const [showPermissionModal, setShowPermissionModal] = useState(false);
  const [joinError, setJoinError] = useState<string | null>(null);
  const [joinCode, setJoinCode] = useState<string | null>(null); 
  const [isJoining, setIsJoining] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  const joinTimeoutRef = useRef<number | null>(null);
  const prevStatusRef = useRef<GameState['status'] | null>(null);
  const prevIndexRef = useRef<number>(-1);

  const { trails, saveTrail, deleteTrail, isLoading: isTrailsLoading } = useTrails(user);
  const [gameState, dispatch] = useReducer(gameReducer, null);

  const handleExitGame = useCallback((silent = false) => {
    // 1. Snapshot the player identity before clearing
    const pId = currentPlayer?.id;
    const wasHost = isHost;

    // 2. Clear state immediately to stop watchers and callbacks
    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    setCurrentPlayer(null);
    setIsJoining(false);
    setJoinCode(null);
    dispatch({ type: 'EXIT_GAME' });

    // 3. Notify the network
    if (wasHost) {
      localStorage.removeItem('locateit_active_host_state');
      sendAction({ type: 'TERMINATE_SESSION' });
    } else if (pId) {
      sendAction({ type: 'PLAYER_LEAVE', playerId: pId });
    }

    // 4. Update view
    setView(wasHost ? 'DASHBOARD' : 'HOME');
  }, [isHost, currentPlayer, sendAction]);

  const { broadcast, sendAction, requestSync, clearCache } = useGameSync(
    useCallback((state) => dispatch({ type: 'SYNC_STATE', payload: state }), []),
    useCallback((action) => dispatch(action), []),
    isHost,
    gameState,
    joinCode,
    useCallback((targetId) => {
      // Targeted Kick: only alert if WE are the target
      if (currentPlayer && targetId === currentPlayer.id) {
        alert(strings.lobby.kickedDesc);
        handleExitGame(true);
      }
    }, [currentPlayer, handleExitGame]),
    useCallback(() => {
      // Session Ended: Host disconnected explicitly
      handleExitGame(true);
    }, [handleExitGame])
  );

  // Handle Join Deep Link
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const codeFromUrl = params.get('join');
    if (codeFromUrl) {
      const cleanCode = codeFromUrl.trim().toUpperCase();
      setJoinCode(cleanCode);
      setView('JOIN');
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  // Host: Broadcast changes
  useEffect(() => {
    if (isHost && gameState) {
      // Accidental refresh protection: save host state to local storage
      localStorage.setItem('locateit_active_host_state', JSON.stringify(gameState));

      const isStatusChange = gameState.status !== prevStatusRef.current;
      const isIndexChange = gameState.currentQuestionIndex !== prevIndexRef.current;
      const isNewGame = prevStatusRef.current === null;
      const needsFullSync = isStatusChange || isIndexChange || isNewGame;

      broadcast(gameState, needsFullSync);

      prevStatusRef.current = gameState.status;
      prevIndexRef.current = gameState.currentQuestionIndex;
    }
  }, [gameState, isHost, broadcast]);

  // Player: Sync loop when waiting for game data
  useEffect(() => {
    if ((view === 'JOIN' || view === 'LOBBY') && !isHost && joinCode) {
      const interval = setInterval(requestSync, 4000);
      return () => clearInterval(interval);
    }
  }, [view, isHost, requestSync, joinCode]);

  // Join Watchdog (Purely for the spinner)
  useEffect(() => {
    if (gameState && currentPlayer && !isHost && isJoining) {
      const isPresent = gameState.players.some(p => p.id === currentPlayer.id);
      if (isPresent) {
        setIsJoining(false);
        if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
      }
    }
  }, [gameState?.players, currentPlayer, isHost, isJoining]);

  useEffect(() => {
    const savedUser = localStorage.getItem('locateit_user');
    if (savedUser) setUser(JSON.parse(savedUser));
  }, []);

  const handleCompleteTrail = async (questions: Question[], name: string, startingView?: { center: Location, zoom: number }) => {
    if (isSaving) return;
    setIsSaving(true);
    try {
      const result = await saveTrail(questions, name, startingView, editingTrail?.id);
      if (result.success) {
        setEditingTrail(null);
        setView('DASHBOARD');
      } else {
        alert(`Save Failed: ${result.error}.`);
      }
    } catch (e: any) {
      alert(`Unexpected Error: ${e.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  const handleHostTrail = (trail: Trail) => {
    if (!user) return;
    setIsHost(true);
    setCurrentPlayer(null); 
    const newGameId = generateId();
    dispatch({ type: 'INIT_LOBBY', payload: { id: newGameId, questions: trail.questions, hostId: user.id, startingView: trail.startingView } });
    setJoinCode(newGameId);
    setView('LOBBY');
  };

  const handleResumeHost = () => {
    const saved = localStorage.getItem('locateit_active_host_state');
    if (saved) {
      const state = JSON.parse(saved) as GameState;
      setIsHost(true);
      setCurrentPlayer(null);
      setJoinCode(state.id);
      dispatch({ type: 'SYNC_STATE', payload: state });
      setView(state.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
    }
  };

  const handleJoinGame = (gameCode: string, name: string, color: string) => {
    setJoinError(null);
    const code = gameCode.trim().toUpperCase();

    if (!gameState || gameState.id !== code) {
      setJoinError(`Searching for Expedition ${code}... Ensure the host has started the lobby.`);
      requestSync();
      return;
    }

    const savedId = localStorage.getItem('locateit_last_player_id');
    const existingById = gameState.players.find(p => p.id === savedId);

    if (existingById) {
      setCurrentPlayer(existingById);
      setIsJoining(false);
      setIsHost(false);
      setView(gameState.status === 'LOBBY' ? 'LOBBY' : 'PLAYING');
      return;
    }

    const newPlayer: Player = { id: generateId(), name, color, score: 0, hasGuessed: false };
    setCurrentPlayer(newPlayer);
    setIsHost(false);
    setIsJoining(true);

    if (joinTimeoutRef.current) clearTimeout(joinTimeoutRef.current);
    joinTimeoutRef.current = window.setTimeout(() => setIsJoining(false), 20000);

    localStorage.setItem('locateit_last_player_id', newPlayer.id);
    sendAction({ type: 'PLAYER_JOIN_REQUEST', player: newPlayer });
    setView('LOBBY');
  };

  return (
    <>
      {showPermissionModal && <PermissionModal onClose={() => setShowPermissionModal(false)} />}
      {view === 'HOME' && <Home onJoin={() => setView('JOIN')} onDesign={() => user ? setView('DASHBOARD') : setView('AUTH')} />}
      {view === 'JOIN' && <JoinGame prefilledCode={joinCode || ''} onBack={() => setView('HOME')} onJoin={handleJoinGame} onCodeChange={setJoinCode} isSearching={!gameState && !!joinCode} error={joinError} />}
      {view === 'AUTH' && <Auth onAuthSuccess={(u) => { setUser(u); setView('DASHBOARD'); }} onBack={() => setView('HOME')} />}
      {view === 'DASHBOARD' && user && (
        <Dashboard 
          user={user} 
          trails={trails}
          isLoading={isTrailsLoading}
          onNewTrail={() => { setEditingTrail(null); setView('CREATE'); }} 
          onEditTrail={(t) => { setEditingTrail(t); setView('CREATE'); }} 
          onHostTrail={handleHostTrail} 
          onDeleteTrail={deleteTrail}
          onLogout={() => { localStorage.removeItem('locateit_user'); setUser(null); setView('HOME'); }}
          onResumeHost={localStorage.getItem('locateit_active_host_state') ? handleResumeHost : undefined}
        />
      )}
      {view === 'CREATE' && (
        <QuizCreator 
          initialTrail={editingTrail || undefined} 
          onComplete={handleCompleteTrail} 
          onCancel={() => setView('DASHBOARD')} 
          onRequestPermissions={() => setShowPermissionModal(true)}
          isSaving={isSaving}
        />
      )}
      {view === 'LOBBY' && gameState && (
        <Lobby 
          gameState={gameState} 
          isHost={isHost} 
          onStart={() => dispatch({ type: 'SET_STATUS', payload: 'PLAYING' })} 
          currentPlayer={currentPlayer} 
          onBack={() => handleExitGame()} 
          onKick={(id) => {
            dispatch({ type: 'KICK_PLAYER', payload: id });
            sendAction({ type: 'PLAYER_KICKED', targetId: id });
          }} 
        />
      )}
      {view === 'PLAYING' && gameState && (
        <GameBoard 
          gameState={gameState} 
          isHost={isHost} 
          currentPlayer={currentPlayer} 
          onGuess={(guess) => {
            if (!currentPlayer) return;
            const currentQ = gameState.questions[gameState.currentQuestionIndex];
            const dist = calculateDistance(guess, currentQ.location);
            sendAction({ type: 'PLAYER_GUESS_REQUEST', playerId: currentPlayer.id, guess, distance: dist });
            if (isHost) dispatch({ type: 'SUBMIT_GUESS', payload: { playerId: currentPlayer.id, guess, distance: dist } });
          }} 
          onUnlock={() => {
            if (!currentPlayer) return;
            sendAction({ type: 'PLAYER_UNLOCK_REQUEST', playerId: currentPlayer.id });
            if (isHost) dispatch({ type: 'UNLOCK_GUESS', payload: currentPlayer.id });
          }}
          onReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'SET_STATUS', payload: 'COUNTDOWN' });
            sendAction({ type: 'HOST_REVEAL_REQUEST' });
          }}
          onForceReveal={() => {
            if (!isHost) return;
            dispatch({ type: 'FORCE_REVEAL' });
            sendAction({ type: 'FORCE_REVEAL' });
          }}
          onCountdownFinish={() => isHost && dispatch({ type: 'SET_STATUS', payload: 'RESULTS' })}
          onShowScoreboard={() => isHost && dispatch({ type: 'CALCULATE_SCORES' })}
          onNext={() => isHost && dispatch({ type: 'NEXT_ROUND' })} 
          onExit={() => handleExitGame()}
        />
      )}
    </>
  );
};

export default App;

